CCRCDataCtrl::~CCRCDataCtrl()
{
	if (m_pKSCE_USD03 != NULL) { delete m_pKSCE_USD03;			m_pKSCE_USD03 = NULL; }
	if (m_pJTG_D62_04 != NULL) { delete m_pJTG_D62_04;			m_pJTG_D62_04 = NULL; }
	if (m_pKSCE_USD05 != NULL) { delete m_pKSCE_USD05;			m_pKSCE_USD05 = NULL; }
	if (m_pLoadRating != NULL) { delete m_pLoadRating;			m_pLoadRating = NULL; }
	if (m_pRatingKS05 != NULL) { delete m_pRatingKS05;			m_pRatingKS05 = NULL; }
	if (m_pPlateGirder != NULL) { delete m_pPlateGirder;		m_pPlateGirder = NULL; }
	if (m_pPscDataCtrl != NULL) { delete m_pPscDataCtrl;		m_pPscDataCtrl = NULL; }
	if (m_pCsgDataCtrl != NULL) { delete m_pCsgDataCtrl;		m_pCsgDataCtrl = NULL; }
	if (m_pStlRatingDataCtrl != NULL) { delete m_pStlRatingDataCtrl;		m_pStlRatingDataCtrl = NULL; }
	if (m_pRCRatingDataCtrl != NULL) { delete m_pRCRatingDataCtrl;		m_pRCRatingDataCtrl = NULL; }
	if (m_pRusStlCompDataCtrl != NULL) { delete m_pRusStlCompDataCtrl;		m_pRusStlCompDataCtrl = NULL; }
	if (m_pSodDataCtrl != NULL) { delete m_pSodDataCtrl;		m_pSodDataCtrl = NULL; }
	//
	if (m_pDesignForceResult != NULL) { delete m_pDesignForceResult; m_pDesignForceResult = NULL; }
	if (m_pDgnResultFileCtrl != NULL) { delete m_pDgnResultFileCtrl; m_pDgnResultFileCtrl = NULL; }

	CDBDoc::GetDocPoint()->SetDesignStatus(0);	// Initialize.
}

