BOOL CCRCDataCtrl::Get_ConMatd(T_MATD_D& MatdD, BOOL bCompositeSect)
{
	if (MatdD.Type == _T("SRC"))	MatdD.Data1 = MatdD.Data2;
	bCompositeSect = m_pPostCtrl->IsPSCCompositeSect();

	// 거더 재료 정보
	// Concrete.
	if (MatdD.Data1.CodeName == _T("") || MatdD.Data1.CodeName == _T("None"))
	{
		T_MATL_CONCRETE ConcD;
		CString CodeName;
		CMatlDB MatlDB(m_pDoc);
		CString strCode = _T(""), strSubCode = _T(""), strMatName = _T("");
		CDBLib::GetDefaultConMatl(strCode, strSubCode, strMatName);
		m_pDoc->m_pMatlDB->GetConcreteDataNew(strCode, strSubCode, strMatName, ConcD);
		ConcD.Initialize();
		if (MatdD.Data1.Design.C_fc <= 0.0)	MatdD.Data1.Design.C_fc = ConcD.C_fc;
		if (MatdD.Data1.Design.C_fci <= 0.0)	MatdD.Data1.Design.C_fci = ConcD.C_fci;
		if (MatdD.Data1.Analysis.Density <= 0.0)	MatdD.Data1.Analysis.Density = ConcD.Density;
		if (MatdD.Data1.Analysis.Elast <= 0.0)	MatdD.Data1.Analysis.Elast = ConcD.Elast;
		if (MatdD.Data1.Analysis.Poisson <= 0.0)	MatdD.Data1.Analysis.Poisson = ConcD.Poisson;
		if (MatdD.Data1.Analysis.Thermal <= 0.0)	MatdD.Data1.Analysis.Thermal = ConcD.Thermal;

		if (CDBLib::IsPscCodeAASHTO(m_iCivilCode))
		{
			CodeName = MATLCODE_CON_ASTM;
			MatdD.Data1.CodeName = CodeName;
			MatdD.Data1.Analysis.Elast = MatlDB.Get_Ec(MatdD.Data1.CodeName, MatdD.Data1.CodeMatlName, MatdD.Data1.Design.C_fc * 1000);
			MatdD.Data1.Analysis.Elast /= 1000;    //AASHTO LRFD 단위 변환(lb/in2 -> Kips/in2)
			if (bCompositeSect)
			{
				MatdD.Data2.CodeName = CodeName;
				MatdD.Data2.Analysis.Elast = MatlDB.Get_Ec(MatdD.Data2.CodeName, MatdD.Data2.CodeMatlName, MatdD.Data2.Design.C_fc * 1000);
				MatdD.Data2.Analysis.Elast /= 1000;    //AASHTO LRFD 단위 변환(lb/in2 -> Kips/in2)
			}
		}
	}

	// Rebar.
	if (MatdD.Rebar_CodeName == _T("") || MatdD.Rebar_CodeName == _T("None"))
	{
		CString strCode = _T(""), strRebarName = _T("");
		CDBLib::GetDefaultConRbar(strCode, strRebarName);

		T_MATL_REBAR RbarD;
		RbarD.Initialize();
		if (!m_pDoc->m_pMatlDB->GetRebarData(strCode, strRebarName, RbarD))	return FALSE;
		MatdD.Rebar_CodeName = strCode;
		// Save Main Rebar Data.
		if (MatdD.MainRebar_RebarName == _T(""))	        MatdD.MainRebar_RebarName = strRebarName;	// SD40.
		if (MatdD.MainRebarData.B_Density <= 0.0)	MatdD.MainRebarData.B_Density = RbarD.B_Density;
		if (MatdD.MainRebarData.B_Elast <= 0.0)	MatdD.MainRebarData.B_Elast = RbarD.B_Elast;
		if (MatdD.MainRebarData.B_fy <= 0.0)	MatdD.MainRebarData.B_fy = RbarD.B_fy;

		// Save Sub Rebar Data.
		if (MatdD.SubRebar_RebarName == _T(""))					MatdD.SubRebar_RebarName = strRebarName;	// SD40.
		if (MatdD.SubRebarData.B_Density <= 0.0)		MatdD.SubRebarData.B_Density = RbarD.B_Density;
		if (MatdD.SubRebarData.B_Elast <= 0.0)		MatdD.SubRebarData.B_Elast = RbarD.B_Elast;
		if (MatdD.SubRebarData.B_fy <= 0.0)		MatdD.SubRebarData.B_fy = RbarD.B_fy;
	}
	else if (MatdD.Rebar_CodeName == MATLCODE_CON_IRC || MatdD.Rebar_CodeName == MATLCODE_CON_IRS)
	{

		T_MATL_REBAR rData;
		rData.Initialize();
		if (!m_pDoc->m_pMatlDB->GetRebarData(MatdD.Rebar_CodeName, MatdD.MainRebar_RebarName, rData))	return FALSE;
		if (MatdD.MainRebarData.B_Elast / rData.B_Elast <= 1.0)  MatdD.MainRebarData.B_Elast = rData.B_Elast;
		if (MatdD.SubRebarData.B_Elast / rData.B_Elast <= 1.0)  MatdD.SubRebarData.B_Elast = rData.B_Elast;
		if (MatdD.MainRebarData2.B_Elast / rData.B_Elast <= 1.0)  MatdD.MainRebarData2.B_Elast = rData.B_Elast;
		if (MatdD.SubRebarData2.B_Elast / rData.B_Elast <= 1.0)  MatdD.SubRebarData2.B_Elast = rData.B_Elast;

		if (MatdD.MainRebarData.B_Density / rData.B_Density <= 1.0)  MatdD.MainRebarData.B_Density = rData.B_Density;
		if (MatdD.SubRebarData.B_Density / rData.B_Density <= 1.0)  MatdD.SubRebarData.B_Density = rData.B_Density;
		if (MatdD.MainRebarData2.B_Density / rData.B_Density <= 1.0)  MatdD.MainRebarData2.B_Density = rData.B_Density;
		if (MatdD.SubRebarData2.B_Density / rData.B_Density <= 1.0)  MatdD.SubRebarData2.B_Density = rData.B_Density;
	}
	// Add by ZINU.('04.09.09). Always fci=0.7*fc.
	MatdD.Data1.Design.C_fci = 0.7 * MatdD.Data1.Design.C_fc;

	T_MATL_CONCRETE cData;
	BOOL bCheck = m_pDoc->m_pMatlDB->GetConcreteData(MatdD.Data1.CodeName, MatdD.Data1.CodeMatlName, cData);
	if (bCheck)
	{
		MatdD.Data1.Analysis.Elast = cData.Elast;
	}

	// PSC Composite 일 경우 슬래브 재료 정보
	BOOL bPscComposite = m_pPostCtrl->IsPSCCompositeSect();
	if (bPscComposite)
	{
		// Concrete.
		if (MatdD.Data2.CodeName == _T("") || MatdD.Data2.CodeName == _T("None"))
		{
			T_MATL_CONCRETE ConcD;
			CString strCode = _T(""), strSubCode = _T(""), strMatName = _T("");
			CDBLib::GetDefaultConMatl(strCode, strSubCode, strMatName);
			m_pDoc->m_pMatlDB->GetConcreteDataNew(strCode, strSubCode, strMatName, ConcD);
			// If not exist, Set Default Data (Design).
			if (MatdD.Data2.Design.C_fc <= 0.0)	MatdD.Data2.Design.C_fc = ConcD.C_fc;
			if (MatdD.Data2.Design.C_fci <= 0.0)	MatdD.Data2.Design.C_fci = ConcD.C_fci;
			// If not exist, Set Default Data (Analysis).
			if (MatdD.Data2.Analysis.Density <= 0.0)	MatdD.Data2.Analysis.Density = ConcD.Density;
			if (MatdD.Data2.Analysis.Elast <= 0.0)	MatdD.Data2.Analysis.Elast = ConcD.Elast;
			if (MatdD.Data2.Analysis.Poisson <= 0.0)	MatdD.Data2.Analysis.Poisson = ConcD.Poisson;
			if (MatdD.Data2.Analysis.Thermal <= 0.0)	MatdD.Data2.Analysis.Thermal = ConcD.Thermal;
		}
		// Rebar.
		if (MatdD.Rebar_CodeName2 == _T("") || MatdD.Rebar_CodeName2 == _T("None"))
		{
			CString strCode = _T(""), strRebarName = _T("");
			CDBLib::GetDefaultConRbar(strCode, strRebarName);

			T_MATL_REBAR RbarD;
			RbarD.Initialize();
			if (!m_pDoc->m_pMatlDB->GetRebarData(strCode, strRebarName, RbarD))	return FALSE;
			MatdD.Rebar_CodeName = strCode;
			// Save Main Rebar Data.
			if (MatdD.MainRebar_RebarName2 == _T(""))	      MatdD.MainRebar_RebarName2 = strRebarName;	// SD40.
			if (MatdD.MainRebarData2.B_Density <= 0.0)	MatdD.MainRebarData2.B_Density = RbarD.B_Density;
			if (MatdD.MainRebarData2.B_Elast <= 0.0)	MatdD.MainRebarData2.B_Elast = RbarD.B_Elast;
			if (MatdD.MainRebarData2.B_fy <= 0.0)	MatdD.MainRebarData2.B_fy = RbarD.B_fy;

			// Save Sub Rebar Data.
			if (MatdD.SubRebar_RebarName2 == _T(""))					MatdD.SubRebar_RebarName2 = strRebarName;	// SD40.
			if (MatdD.SubRebarData2.B_Density <= 0.0)	MatdD.SubRebarData2.B_Density = RbarD.B_Density;
			if (MatdD.SubRebarData2.B_Elast <= 0.0)	MatdD.SubRebarData2.B_Elast = RbarD.B_Elast;
			if (MatdD.SubRebarData2.B_fy <= 0.0)	MatdD.SubRebarData2.B_fy = RbarD.B_fy;
		}
		// Add by ZINU.('04.09.09). Always fci=0.7*fc.

		MatdD.Data2.Design.C_fci = 0.7 * MatdD.Data2.Design.C_fc;

		T_MATL_CONCRETE cDataSl;
		BOOL bCheck = m_pDoc->m_pMatlDB->GetConcreteData(MatdD.Data2.CodeName, MatdD.Data2.CodeMatlName, cDataSl);
		if (bCheck)
		{
			MatdD.Data2.Analysis.Elast = cDataSl.Elast;
			MatdD.Data2.Analysis.Density = cDataSl.Density;
		}
	}

	if (MatdD.Type == _T("C") || MatdD.Type == _T("SRC"))	return TRUE;
	else																			return FALSE;
}

