BOOL CCRCDataCtrl::Get_RbarMatl(BOOL bMbar, T_MATD_D& MatlD)
{
	if (m_iCivilCode != JSCE02) { ASSERT(0); return FALSE; }	// Only JSCE02.

	if (bMbar)	MatlD.CRC.MbarMatl.Initialize();	// Main Rbar.
	else			MatlD.CRC.SbarMatl.Initialize();	// Sub Rbar.
	CString strMatl = (bMbar ? MatlD.MainRebar_RebarName : MatlD.SubRebar_RebarName);

	CRC_T_MATD_RBAR RbarMatl;
	RbarMatl.Initialize();
	// Only JIS.
	if (MatlD.Rebar_CodeName != MATLCODE_CON_JIS_CIVIL) { ASSERT(0); return FALSE; }
	// Unit(Stress) = N/mm^2.
	if (strMatl == _T("SR235"))
	{
		RbarMatl.dRebar_AFu = 380.0;
		RbarMatl.dRebar_AFt_D = 80.0;
		RbarMatl.dRebar_AFt_T = 140.0;
		RbarMatl.dRebar_AFt_EQ = 140.0;
		RbarMatl.dRebar_AFv = 120.0;
		RbarMatl.dRebar_Es = 2.0E+5;
	}
	else if (strMatl == _T("SR295") || strMatl == _T("SD295A") || strMatl == _T("SD295B"))
	{
		RbarMatl.dRebar_AFu = 440.0;
		RbarMatl.dRebar_AFt_D = 100.0;
		RbarMatl.dRebar_AFt_T = 180.0;
		RbarMatl.dRebar_AFt_EQ = 180.0;
		RbarMatl.dRebar_AFv = 120.0;
		RbarMatl.dRebar_Es = 2.0E+5;
	}
	else if (strMatl == _T("SD345"))
	{
		RbarMatl.dRebar_AFu = 490.0;
		RbarMatl.dRebar_AFt_D = 100.0;
		RbarMatl.dRebar_AFt_T = 180.0;
		RbarMatl.dRebar_AFt_EQ = 200.0;
		RbarMatl.dRebar_AFv = 120.0;
		RbarMatl.dRebar_Es = 2.0E+5;
	}
	else if (strMatl == _T("SD390"))
	{
		RbarMatl.dRebar_AFu = 490.0;
		RbarMatl.dRebar_AFt_D = 100.0;
		RbarMatl.dRebar_AFt_T = 180.0;
		RbarMatl.dRebar_AFt_EQ = 230.0;
		RbarMatl.dRebar_AFv = 120.0;
		RbarMatl.dRebar_Es = 2.0E+5;
	}
	else if (strMatl == _T("SD490"))
	{
		RbarMatl.dRebar_AFu = 490.0;
		RbarMatl.dRebar_AFt_D = 100.0;
		RbarMatl.dRebar_AFt_T = 180.0;
		RbarMatl.dRebar_AFt_EQ = 290.0;
		RbarMatl.dRebar_AFv = 120.0;
		RbarMatl.dRebar_Es = 2.0E+5;
	}
	else { ASSERT(0); return FALSE; }

	// Calculate Factor for Changing Unit.
	T_UNIT_INDEX CngUnit, CurUnit;
	CngUnit.nBase_Force = D_UNITSYS_FORCE_INDEX_N;
	CngUnit.nBase_Length = D_UNITSYS_LENGTH_INDEX_MM;
	m_pUnitCtrl->GetUnitIndexCurrent(CurUnit);	// Current Unit.
	double dFfor = CSectUtil::Cng_Ffor(CngUnit.nBase_Force, CurUnit.nBase_Force);
	double dFlen = CSectUtil::Cng_Flen(CngUnit.nBase_Length, CurUnit.nBase_Length);
	double dFstr = (dFlen == 0.0 ? 0.0 : dFfor / pow(dFlen, 2));
	// Change Unit (Code(N/mm^2) -> Current).
	(bMbar ? MatlD.CRC.MbarMatl.dRebar_AFu : MatlD.CRC.SbarMatl.dRebar_AFu) = RbarMatl.dRebar_AFu    * dFstr;
	(bMbar ? MatlD.CRC.MbarMatl.dRebar_AFt_D : MatlD.CRC.SbarMatl.dRebar_AFt_D) = RbarMatl.dRebar_AFt_D  * dFstr;
	(bMbar ? MatlD.CRC.MbarMatl.dRebar_AFt_T : MatlD.CRC.SbarMatl.dRebar_AFt_T) = RbarMatl.dRebar_AFt_T  * dFstr;
	(bMbar ? MatlD.CRC.MbarMatl.dRebar_AFt_EQ : MatlD.CRC.SbarMatl.dRebar_AFt_EQ) = RbarMatl.dRebar_AFt_EQ * dFstr;
	(bMbar ? MatlD.CRC.MbarMatl.dRebar_AFv : MatlD.CRC.SbarMatl.dRebar_AFv) = RbarMatl.dRebar_AFv    * dFstr;
	(bMbar ? MatlD.CRC.MbarMatl.dRebar_Es : MatlD.CRC.SbarMatl.dRebar_Es) = RbarMatl.dRebar_Es     * dFstr;

	return TRUE;
}

BOOL CCRCDataCtrl::Cal_TdgrDataForDesignAll()
{
	m_amTdnaK.RemoveAll();
	m_amTdgrK.RemoveAll();

	_DGN_TDGR_CRC TdgrCrc;
	T_TDGR_K TdgrK; T_TDGR_D TdgrD;
	T_TDNA_K TdnaK; T_TDNA_D TdnaD;

	CArray<T_TDNA_K, T_TDNA_K> arTdnaK;
	arTdnaK.RemoveAll();
	m_pAttrCtrl->GetTdnaKeyList(arTdnaK);

	CMap<T_TDGR_K, T_TDGR_K, _DGN_TDGR_CRC, _DGN_TDGR_CRC&> amDgnTdgrD;
	amDgnTdgrD.RemoveAll();
	CMap<T_TDGR_K, T_TDGR_K, T_TDGR_K, T_TDGR_K> amOrgTdgrK;
	amOrgTdgrK.RemoveAll();
	int iGrupNo = 1;
	for (int i = 0; i < arTdnaK.GetSize(); ++i)
	{
		TdgrCrc.Initialize();
		TdnaK = arTdnaK.GetAt(i);
		TdnaD.Initialize();
		if (!m_pAttrCtrl->GetTdna(TdnaK, TdnaD))	continue;
		TdgrK = TdnaD.GroupKey;
		if (TdgrK == 0)
		{
			TdgrCrc.DgnTdgrK = iGrupNo;
			TdgrCrc.TdnaK = TdnaK;
			TdgrCrc.strTdgrNa = _T("S_") + TdnaD.TendonName;
			m_amTdgrK.SetAt(TdgrCrc.DgnTdgrK, TdgrCrc);
			iGrupNo++;
		}
		else
		{
			if (!m_pAttrCtrl->GetTdgr(TdgrK, TdgrD))	continue;
			T_TDGR_K rTdgrK;
			if (amOrgTdgrK.Lookup(TdgrK, rTdgrK) == 0)
			{
				TdgrCrc.DgnTdgrK = iGrupNo;
				TdgrCrc.OrgTdgrK = TdgrK;
				TdgrCrc.strTdgrNa = TdgrD.GroupName;

				amOrgTdgrK.SetAt(TdgrK, TdgrK);
				amDgnTdgrD.SetAt(TdgrK, TdgrCrc);
				m_amTdgrK.SetAt(TdgrCrc.DgnTdgrK, TdgrCrc);
				iGrupNo++;
			}
			else
			{
				if (!amDgnTdgrD.Lookup(TdgrK, TdgrCrc)) continue;
			}
		}
		m_amTdnaK.SetAt(TdnaK, TdgrCrc);
	}
	return TRUE;
}

BOOL CCRCDataCtrl::Get_CrcSpscTdgr(ElemPairK ElemK, BOOL bPosI, double dMuyMax, double dMuyMin, _DGN_TDGR_CRC& TdgrCrc, T_SPSC_TNDN& SpscTndn)
{
	SpscTndn.Initialize();
	if (TdgrCrc.OrgTdgrK == 0)
	{
		if (!CSectUtil::GetPscTndnSngl(TRUE, ElemK, TdgrCrc.TdnaK, bPosI, dMuyMax, dMuyMin, SpscTndn))	return FALSE;
	}
	else
	{
		if (!CSectUtil::GetPscTndnGrup(TRUE, ElemK, TdgrCrc.OrgTdgrK, bPosI, dMuyMax, dMuyMin, SpscTndn))	return FALSE;
	}
	return TRUE;
}

BOOL CCRCDataCtrl::Get_ServMaxMinMoment(ElemPairK ElemK, double& dMuyMaxI, double& dMuyMinI, double& dMuyMaxJ, double& dMuyMinJ)
{
	dMuyMaxI = 0.0;
	dMuyMinI = 0.0;
	dMuyMaxJ = 0.0;
	dMuyMinJ = 0.0;

	int i = 0;
	/////////////////////////////////////////
	// Get Major Moment by Moving Load.
	CArray<UINT, UINT> aTotMvldK;
	aTotMvldK.RemoveAll();
	// Get Moving Load.
	// General.
	CArray<T_MVLD_K, T_MVLD_K> aMvldK;
	aMvldK.RemoveAll();
	m_pAttrCtrl->GetMvldKeyList(aMvldK);
	aTotMvldK.Append(aMvldK);
	// British Standard.
	CArray<T_MVLDbs_K, T_MVLDbs_K> aMvldbsK;
	aMvldbsK.RemoveAll();
	m_pAttrCtrl->GetMvldbsKeyList(aMvldbsK);
	aTotMvldK.Append(aMvldbsK);
	// France
	CArray<T_MVLDfr_K, T_MVLDfr_K> aMvldfrK;
	aMvldfrK.RemoveAll();
	m_pAttrCtrl->GetMvldfrKeyList(aMvldfrK);
	aTotMvldK.Append(aMvldfrK);
	// China.
	CArray<T_MVLDch_K, T_MVLDch_K> aMvldchK;
	aMvldchK.RemoveAll();
	m_pAttrCtrl->GetMvldchKeyList(aMvldchK);
	aTotMvldK.Append(aMvldchK);
	// India.
	CArray<T_MVLDid_K, T_MVLDid_K> aMvldidK;
	aMvldidK.RemoveAll();
	m_pAttrCtrl->GetMvldidKeyList(aMvldidK);
	aTotMvldK.Append(aMvldidK);
	// Japan.
	CArray<T_MVLDjp_K, T_MVLDjp_K> aMvldjpK;
	aMvldjpK.RemoveAll();
	m_pAttrCtrl->GetMvldjpKeyList(aMvldjpK);
	aTotMvldK.Append(aMvldjpK);

	int nForType = 0; //부재력 받아옴.
	BOOL bCalcStss = FALSE;
	for (i = 0; i < aTotMvldK.GetSize(); ++i)
	{
		UINT MvldK = aTotMvldK.GetAt(i);
		CArray<_DGN_FORC_CRC, _DGN_FORC_CRC&> aForceLcase;
		CString strLcaseNa = _T("");
		if (!m_ForceCtrl.Get_Mvld(ElemK, MvldK, nForType, bCalcStss, strLcaseNa, aForceLcase, TRUE)) { ASSERT(0); return FALSE; }
		dMuyMaxI += aForceLcase[8].dMuy[0];	// MY-MAX.
		dMuyMaxJ += aForceLcase[8].dMuy[1];	// MY-MAX.
		dMuyMinI += aForceLcase[9].dMuy[0];	// MY-MIN.
		dMuyMinJ += aForceLcase[9].dMuy[1];	// MY-MIN.
	}
	/////////////////////////////////////////
	// Get Major Moment by Grid Influence Load.

	CArray<T_GILC_K, T_GILC_K> aGilcK;
	m_pAttrCtrl->GetGilcKeyList(aGilcK);
	for (i = 0; i < aGilcK.GetSize(); ++i)
	{
		T_GILC_K GilcK = aGilcK.GetAt(i);
		// Get Load Case Type.
		T_GILC_D GilcD;
		GilcD.Initialize();
		if (!m_pAttrCtrl->GetGilc(GilcK, GilcD))	continue;
		int iLcaseType = GilcD.nLoadCaseType;
		if (iLcaseType == 0 || iLcaseType == 1)	continue;	// Only Live Load.

		CArray<_DGN_FORC_CRC, _DGN_FORC_CRC&> aForceLcase;		aForceLcase.RemoveAll();
		CString strLcaseNa = _T("");
		if (!m_ForceCtrl.Get_Gilc(ElemK, GilcK, nForType, bCalcStss, iLcaseType, strLcaseNa, aForceLcase)) { ASSERT(0); return FALSE; }
		dMuyMaxI += aForceLcase[8].dMuy[0];	// MY-MAX.
		dMuyMaxJ += aForceLcase[8].dMuy[1];	// MY-MAX.
		dMuyMinI += aForceLcase[9].dMuy[0];	// MY-MIN.
		dMuyMinJ += aForceLcase[9].dMuy[1];	// MY-MIN.
	}
	return TRUE;
}

BOOL CCRCDataCtrl::Get_CrcElemListForDgn(BOOL bShowMsg, ArrElemPairKey& aElemK, BOOL bSkip2nd)
{
	// Change by ZINU.('04.08.13). Check Reason if All Elements are NG.
	aElemK.RemoveAll();

	int i = 0, j = 0;
	ArrElemPairKey aSelElemK;
	// Change by ZINU.('04.04.27). Design by All Elem.
	//	m_pDoc->m_pViewCtrl->GetAllSelectedElem(aSelElemK);
	if (aSelElemK.GetSize() == 0)	// All Design.
	{
		int iTotElemNum = m_pAttrCtrl->GetCountElem();
		for (i = 0; i < iTotElemNum; ++i)
		{
			ElemPairK ElemK(m_pPostCtrl->GetOriginElem(i + 1), EN_EL_BEAM);
			// Change by ZINU.('05.04.08). All Elem Only if JSCE02.
			T_POSC_D PoscD;
			BOOL bIncludeElem = (m_iCivilCode == JSCE02 ? TRUE : Get_CrcPosc(ElemK, PoscD));
			if (bIncludeElem)	aSelElemK.Add(ElemK);
		}
	}

	CArray<T_VBEM_K, T_VBEM_K> aVbeamKList;
	m_pDoc->m_pAttrCtrl2->GetVbemKeyList(aVbeamKList);
	for (i = 0; i < aVbeamKList.GetSize(); ++i)
	{
		ElemPairK ElemK(aVbeamKList[i], EN_EL_VBEAM);
		T_POSC_D PoscD; PoscD.Initialize();
		BOOL bIncludeElem = Get_CrcPosc(ElemK, PoscD);
		if (bIncludeElem)	aSelElemK.Add(ElemK);
	}


	int iTotOK = 0, iTotNG = 0;
	int iCountNG[9] = { 0,0,0,0,0,0,0,0,0 };
	if (bShowMsg)
	{
		if (bSkip2nd) ASSERT(0); // bShowMsg=TRUE 일경우는 bSkip2nd=TRUE로 하지 마세요.
		for (i = 0; i < aSelElemK.GetSize(); ++i)
		{
			ElemPairK ElemK = aSelElemK.GetAt(i);
			BOOL bpErr[9] = { FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE, FALSE };
			if (!bSkip2nd)
			{
				if (CDBLib::IsPscDgnFor2nd(ElemK, bpErr))	iTotOK++;
				else
				{
					iTotNG++;
					if (bpErr[0])	iCountNG[0]++;
					if (bpErr[1])	iCountNG[1]++;
					if (bpErr[2])	iCountNG[2]++;
					if (bpErr[3])	iCountNG[3]++;
					if (bpErr[4])	iCountNG[4]++;
					if (bpErr[5])	iCountNG[5]++;
					if (bpErr[6])  iCountNG[6]++;
					if (bpErr[7])  iCountNG[7]++;
					if (bpErr[8])  iCountNG[8]++;
				}
			}
		}
		int iLcomNum = m_pAttrCtrl->GetCountLcom(D_LCOMTYPE_CONCRETE);
		int iStagNum = m_pAttrCtrl->GetCountStag();
		CString strMsg = _T("");
		if (iLcomNum == 0 || iStagNum == 0 || iTotOK == 0)	GActiveAnalysisViewer();
		if (iLcomNum == 0)
		{
			strMsg.Format(_T("%s%s"), _LS(IDS_RCS_NO_LCOM_GOOD), _LS(IDS_RCS_DGN));
			GSaveHistoryFormatNF(strMsg);
		}
		if (!(m_iCivilCode == SNiP_20503_84_PSC || m_iCivilCode == SP_35_13330_11_PSC || m_iCivilCode == SNiP_20503_84_PSC_MKS || m_iCivilCode == SP_35_13330_11_PSC_MKS))
		{
			if (iStagNum == 0)
			{
				strMsg.Format(_T("%s%s"), _LS(IDS_RCS_NO_STAG_GOOD), _LS(IDS_RCS_DGN));
				GSaveHistoryFormatNF(strMsg);
			}
		}
		if (iTotOK == 0)
		{
			if (iTotNG == iCountNG[0])
			{
				strMsg.Format(_T("%s%s"), _LS(IDS_RCSC_NG_ELEM_TYPE), _LS(IDS_RCS_DGN));
				GSaveHistoryFormatNF(strMsg);
			}
			if (iTotNG == iCountNG[1])
			{
				strMsg.Format(_T("%s%s"), _LS(IDS_RCSC_NG_MEMB_TYPE), _LS(IDS_RCS_DGN));
				GSaveHistoryFormatNF(strMsg);
			}
			if (iTotNG == iCountNG[2])
			{
				strMsg.Format(_T("%s%s"), _LS(IDS_RCSC_NG_MATL_TYPE), _LS(IDS_RCS_DGN));
				GSaveHistoryFormatNF(strMsg);
			}
			if (iTotNG == iCountNG[3])
			{
				strMsg.Format(_T("%s%s"), _LS(IDS_RCSC_NG_RBAR_DATA), _LS(IDS_RCS_DGN));
				GSaveHistoryFormatNF(strMsg);
			}
			if (iTotNG == iCountNG[4])
			{
				strMsg.Format(_T("%s%s"), _LS(IDS_RCSC_NG_TNDN_DATA), _LS(IDS_RCS_DGN));
				GSaveHistoryFormatNF(strMsg);
			}
			if (iTotNG == iCountNG[5])
			{
				strMsg.Format(_T("%s%s"), _LS(IDS_RCSC_NG_SECT_TYPE), _LS(IDS_RCS_DGN));
				GSaveHistoryFormatNF(strMsg);
			}
			if (iTotNG == iCountNG[7])
			{
				strMsg.Format(_T("%s%s"), _LS(IDS_RCSC_NG_SECT_TYPE), _LS(IDS_RCS_DGN));
				GSaveHistoryFormatNF(strMsg);
			}
		}
	}

	for (i = 0; i < aSelElemK.GetSize(); ++i)
	{
		ElemPairK ElemK = aSelElemK.GetAt(i);
		if (!CDBLib::IsPscDgnFor1st(ElemK, FALSE))	continue;
		BOOL bpErr[9] = { FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE };
		if (!bSkip2nd)
		{
			if (!CDBLib::IsPscDgnFor2nd(ElemK, bpErr))
			{
				// Change by ZINU.('05.02.04). ShowMsg by Checking Posc.
				T_POSC_D PoscD;
				PoscD.Initialize();
				BOOL bGetPosc = Get_CrcPosc(ElemK, PoscD);
				if (bShowMsg && bGetPosc)
				{
					CString strErr = _T("");
					if (bpErr[0]) { strErr.Format(_LS(IDS_RCSC_SKIP_ELEM_TYPE), ElemK); GSaveHistoryNF(strErr); }
					if (bpErr[1]) { strErr.Format(_LS(IDS_RCSC_SKIP_MEMB_TYPE), ElemK); GSaveHistoryNF(strErr); }
					if (bpErr[2]) { strErr.Format(_LS(IDS_RCSC_SKIP_MATL_TYPE), ElemK); GSaveHistoryNF(strErr); }
					if (bpErr[3]) { strErr.Format(_LS(IDS_RCSC_SKIP_RBAR_DATA), ElemK); GSaveHistoryNF(strErr); }
					if (bpErr[4]) { strErr.Format(_LS(IDS_RCSC_SKIP_TNDN_DATA), ElemK); GSaveHistoryNF(strErr); }
					if (bpErr[5]) { strErr.Format(_LS(IDS_RCSC_SKIP_SECT_TYPE), ElemK); GSaveHistoryNF(strErr); }
					if (bpErr[6]) { strErr.Format(_LS(IDS_RCSC_SKIP_NO_TNDN), ElemK); GSaveHistoryNF(strErr); }
					if (bpErr[7])
					{
						strErr.Format(_LS(IDS_DB_ERROR_PSC_SECT_G_PART), ElemK); GSaveHistoryFormatNF(strErr);
						strErr.Format(_LS(IDS_RCSC_SKIP_SECT_TYPE), ElemK); GSaveHistoryNF(strErr);
					}
					if (bpErr[8]) { strErr.Format(_LS(IDS_RCSC_SKIP_PSC_COMPOSITE_LICENCE), ElemK); GSaveHistoryNF(strErr); }
				}
				continue;
			}
		}
		aElemK.Add(ElemK);
	}
	if (bShowMsg)	GSaveHistoryNF(_T(""));
	if (aElemK.GetSize() > 0)	return TRUE;
	else											return FALSE;
}

BOOL CCRCDataCtrl::Get_ElemListForJtgFypc(ArrElemPairKey& arElemK, ArrElemPairKey& arTnElemK)
{
	int i, j, k;
	// 텐던이 있는 전체 요소
	arTnElemK.RemoveAll();

	if (m_iCivilCode == JTG_D62_04 || m_iCivilCode == CJJ_11_2011)
	{
		CArray<T_TDNA_K, T_TDNA_K> arTdnaK;
		m_pAttrCtrl->GetTdnaKeyList(arTdnaK);

		for (i = 0; i < arTdnaK.GetSize(); ++i)
		{
			T_TDNA_K TdnaK = arTdnaK[i];
			T_TENDON_INFO TndnInfo;
			TndnInfo.Initialize();
			if (!m_pTendonInfo->GetTendonInfo(TdnaK, TndnInfo))	return FALSE;
			// Tendon Profile.
			T_TDNA_D TdnaD;
			TdnaD.Initialize();
			if (!m_pAttrCtrl->GetTdna(TdnaK, TdnaD))	return FALSE;

			int iTndnElemNum = TndnInfo.aTendonInfoElem.GetSize();
			for (j = 0; j < iTndnElemNum; ++j)
			{
				T_TENDON_INFO_ELEM &TndnInfoElem = TndnInfo.aTendonInfoElem.GetAt(j);
				T_ELEM_K TnElemK = TndnInfoElem.KeyElem;
				ElemPairK TnEPairK(TnElemK, EN_EL_BEAM);
				if (i == 0)
				{
					arTnElemK.Add(TnEPairK);
				}
				else
				{
					int iEqualElem = 0;
					for (k = 0; k < arTnElemK.GetSize(); k++)
					{
						if (arTnElemK[k] == TnEPairK)
						{
							iEqualElem++;
							break;
						}
					}
					if (arTnElemK.GetSize() > 0 && iEqualElem == 0)
						arTnElemK.Add(TnEPairK);
				}
			}
		}
	}

	// 설계 대상요소중 빠진 요소가 있으면 Add
	for (i = 0; i < arElemK.GetSize(); ++i)
	{
		int iEqualElem = 0;
		ElemPairK ElemK = arElemK[i];
		for (j = 0; j < arTnElemK.GetSize(); ++j)
		{
			if (arTnElemK[j] == ElemK)
			{
				iEqualElem++;
				break;
			}
		}
		if (arTnElemK.GetSize() > 0 && iEqualElem == 0)
			arTnElemK.Add(ElemK);
	}

	//qsort(arTnElemK.GetData(), arTnElemK.GetSize(), sizeof(UINT), CCompFunc::UINTAsc);

	return TRUE;
}

// Bridge Load Rating
BOOL CCRCDataCtrl::Get_ElemListForBlrDgn(BOOL bShowMsg, ArrElemPairKey& arElemK)
{
	arElemK.RemoveAll();

	ArrElemPairKey arTotalElem; arTotalElem.RemoveAll();
	if (!CDBLib::GetElemforBridgeLoadRating(arTotalElem)) return FALSE;

	int i = 0;

	int iTotOK = 0, iTotNG = 0;
	int iCountNG[8] = { 0,0,0,0,0,0,0,0 };
	if (bShowMsg)
	{
		for (i = 0; i < arTotalElem.GetSize(); ++i)
		{
			ElemPairK ElemK = arTotalElem.GetAt(i);
			BOOL bpErr[8] = { FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE };
			if (CDBLib::IsElementForBlrDgn(ElemK, bpErr))	iTotOK++;
			else
			{
				iTotNG++;
				if (bpErr[0])	iCountNG[0]++;
				if (bpErr[1])	iCountNG[1]++;
				if (bpErr[2])	iCountNG[2]++;
				if (bpErr[3])	iCountNG[3]++;
				if (bpErr[4])	iCountNG[4]++;
				if (bpErr[5])	iCountNG[5]++;
				if (bpErr[6])  iCountNG[6]++;
				if (bpErr[7])  iCountNG[7]++;
			}
		}

		int iRatingCaseNum = 0;

		switch (m_iCivilCode)
		{
		case AASHTO_LRFD05_PSC_RATING:
		case AASHTO_LRFD12_PSC_RATING:
		case AASHTO_LRFD19_PSC_RATING:
			iRatingCaseNum = m_pAttrCtrl->GetCountBlrc();
			break;
		case KSCE_USD05_RATING:
		case KSCE_USD10_RATING:
		case KSCE_RAIL_USD11_RATING:
		case KSCE_LSD15_RATING:
			iRatingCaseNum = m_pAttrCtrl->GetCountRklc();
			break;
		case CS_454_20_PSC_RATING:
			iRatingCaseNum = m_pAttrCtrl2->GetCountAlcs();
			break;
		case KSCE_USD10_RC_RATING:
		case KSCE_RAIL_USD11_RC_RATING:
		case KSCE_LSD15_RC_RATING:
			iRatingCaseNum = m_pAttrCtrl->GetCountRklc();
			break;
		case STL_KSCE_ASD05:
		case STL_KSCE_ASD10:
		case STL_KSCE_RAIL_ASD04:
		case STL_KSCE_RAIL_ASD11:
		case STL_AASHTO_LRFD12:
		case STL_AASHTO_LRFD19:
		case STL_KSCE_LSD15:
			iRatingCaseNum = m_pAttrCtrl2->GetCountRlcs();
			break;
		default:
			ASSERT(0);
			break;
		}

		CString strMsg = _T("");
		if (iRatingCaseNum == 0 || iTotOK == 0)	GActiveAnalysisViewer();
		if (iRatingCaseNum == 0)
		{
			strMsg.Format(_T("%s%s"), _T("Rating Case가 존재하지 않습니다."), _LS(IDS_RCS_DGN));
			GSaveHistoryFormatNF(strMsg);
		}
		if (iTotOK == 0)
		{
			if (iTotNG == iCountNG[0])
			{
				strMsg.Format(_T("%s%s"), _LS(IDS_RCSC_NG_ELEM_TYPE), _LS(IDS_RCS_DGN));
				GSaveHistoryFormatNF(strMsg);
			}
			if (iTotNG == iCountNG[1])
			{
				strMsg.Format(_T("%s%s"), _LS(IDS_RCSC_NG_MEMB_TYPE), _LS(IDS_RCS_DGN));
				GSaveHistoryFormatNF(strMsg);
			}
			if (iTotNG == iCountNG[2])
			{
				strMsg.Format(_T("%s%s"), _LS(IDS_RCSC_NG_MATL_TYPE), _LS(IDS_RCS_DGN));
				GSaveHistoryFormatNF(strMsg);
			}
			if (iTotNG == iCountNG[3])
			{
				strMsg.Format(_T("%s%s"), _LS(IDS_RCSC_NG_RBAR_DATA), _LS(IDS_RCS_DGN));
				GSaveHistoryFormatNF(strMsg);
			}
			if (iTotNG == iCountNG[4])
			{
				strMsg.Format(_T("%s%s"), _LS(IDS_RCSC_NG_TNDN_DATA), _LS(IDS_RCS_DGN));
				GSaveHistoryFormatNF(strMsg);
			}
			if (iTotNG == iCountNG[5])
			{
				strMsg.Format(_T("%s%s"), _LS(IDS_RCSC_NG_SECT_TYPE), _LS(IDS_RCS_DGN));
				GSaveHistoryFormatNF(strMsg);
			}
		}
	}

	for (i = 0; i < arTotalElem.GetSize(); ++i)
	{
		auto ElemK = arTotalElem.GetAt(i);
		if (!CDBLib::IsPscDgnFor1st(ElemK, FALSE))	continue;
		BOOL bpErr[8] = { FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE,FALSE };
		if (!CDBLib::IsElementForBlrDgn(ElemK, bpErr))
		{
			if (bShowMsg)
			{
				CString strErr = _T("");
				if (bpErr[0]) { strErr.Format(_LS(IDS_RCSC_SKIP_ELEM_TYPE), ElemK.first); GSaveHistoryNF(strErr); }
				if (bpErr[1]) { strErr.Format(_LS(IDS_RCSC_SKIP_MEMB_TYPE), ElemK.first); GSaveHistoryNF(strErr); }
				if (bpErr[2]) { strErr.Format(_LS(IDS_RCSC_SKIP_MATL_TYPE), ElemK.first); GSaveHistoryNF(strErr); }
				if (bpErr[3]) { strErr.Format(_LS(IDS_RCSC_SKIP_RBAR_DATA), ElemK.first); GSaveHistoryNF(strErr); }
				if (bpErr[4]) { strErr.Format(_LS(IDS_RCSC_SKIP_TNDN_DATA), ElemK.first); GSaveHistoryNF(strErr); }
				if (bpErr[5]) { strErr.Format(_LS(IDS_RCSC_SKIP_SECT_TYPE), ElemK.first); GSaveHistoryNF(strErr); }
				if (bpErr[6]) { strErr.Format(_LS(IDS_RCSC_SKIP_NO_TNDN), ElemK.first); GSaveHistoryNF(strErr); }
				if (bpErr[7]) { strErr.Format(_LS(IDS_RCSC_SKIP_PSC_COMPOSITE_LICENCE), ElemK.first); GSaveHistoryNF(strErr); }
			}
			continue;
		}
		arElemK.Add(ElemK);
	}
	if (bShowMsg)	GSaveHistoryNF(_T(""));
	if (arElemK.GetSize() > 0)	return TRUE;
	else											return FALSE;
}

