BOOL CCRCDataCtrl::Cal_LcomDataForDesignAll(ArrElemPairKey& aElemK)
{
	if (aElemK.GetSize() < 1) return FALSE;

	BOOL bBinary = TRUE;

	m_arCheckElemK.Copy(aElemK);
	m_iDgnElemNum = m_arCheckElemK.GetSize();
	Set_SerialCheckElemData();

	BOOL bExistStage = m_pDoc->m_pStagCtrl->ExistStag();
	T_STAG_K CurStagK = m_pDoc->m_pStagCtrl->GetCurStag();
	BOOL bPostCS = m_pDoc->m_pStagCtrl->IsFinalStagKey(CurStagK);
	if (bExistStage && !bPostCS)
	{
		m_pDoc->m_pStagCtrl->SetFinalStagWithoutUpdateNotify();
	}

	int i = 0, j = 0;
	m_amLcbaD.clear();

	m_ForceCtrl.m_arForcElemInTP.clear();
	m_ForceCtrl.m_arForcElemExTP.clear();
	m_ForceCtrl.m_arForcTnprData.clear();
	m_ForceCtrl.m_arForcTnscData.clear();
	m_ForceCtrl.m_arCrckForcData.clear();	// SetAt at CCRCForceCtrl::Set_CrackJtg().
	m_ForceCtrl.m_arStrsAddData.clear();	// For Beam Section Temperature.
	m_ForceCtrl.m_arForcElemLTerm.clear();
	m_ForceCtrl.m_arForcElemLTermExTP.clear();
	m_ForceCtrl.m_arForcForJtgTndnStress.clear();
	// Stress.
	m_ForceCtrl.m_arStressElemInTP.clear();
	m_ForceCtrl.m_arStressElemExTP.clear();
	m_ForceCtrl.m_arStressTnprData.clear();
	m_ForceCtrl.m_arStressTnscData.clear();
	m_ForceCtrl.m_arStressElemLTerm.clear();
	m_ForceCtrl.m_arStressElemLTermExTP.clear();
	// Principle.
	m_ForceCtrl.m_arStssElemShrs.clear();

	if (m_ForceCtrl.Get_Write5PositionDgnForce())
	{
		m_ForceCtrl.m_arForcElemInTP_EX.clear();
		m_ForceCtrl.m_arForcElemExTP_EX.clear();
		m_ForceCtrl.m_arForcTnprData_EX.clear();
		m_ForceCtrl.m_arForcTnscData_EX.clear();
		m_ForceCtrl.m_arCrckForcData_EX.clear();	// SetAt at CCRCForceCtrl::Set_CrackJtg().
		m_ForceCtrl.m_arStrsAddData_EX.clear();	// For Beam Section Temperature.
		m_ForceCtrl.m_arForcElemLTerm_EX.clear();
		m_ForceCtrl.m_arForcElemLTermExTP_EX.clear();
		m_ForceCtrl.m_arForcForJtgTndnStress_EX.clear();
		// Stress.
		m_ForceCtrl.m_arStressElemInTP_EX.clear();
		m_ForceCtrl.m_arStressElemExTP_EX.clear();
		m_ForceCtrl.m_arStressTnprData_EX.clear();
		m_ForceCtrl.m_arStressTnscData_EX.clear();
		m_ForceCtrl.m_arStressElemLTerm_EX.clear();
		m_ForceCtrl.m_arStressElemLTermExTP_EX.clear();
		// Principle.
		m_ForceCtrl.m_arStssElemShrs_EX.clear();
	}

	//
	m_ForceCtrl.Set_DataCtrl(this);
	m_ForceCtrl.Set_LcomForElem(aElemK);

	if (bBinary)
	{
		/// Write Data 
		if (!m_ForceCtrl.CreatDesignForceStressFile())
			return FALSE;
	}

	ADGNFORCE aForceLcomInTP;
	ADGNFORCE aForceTnpr;
	ADGNFORCE aForceTnsc;
	ADGNSTRSADD aStressAdd;
	ADGNFORCE aForceLTerm;
	ADGNFORCE aForceJtgTndn;
	_DGN_FORC_CRC_ELEM ForceLcomInTP;
	_DGN_FORC_CRC_ELEM ForceLcomExTP;
	_DGN_FORC_CRC_ELEM ForceTnpr;
	_DGN_FORC_CRC_ELEM ForceTnsc;
	_DGN_STRS_ADD_ELEM StressAdd;
	_DGN_FORC_CRC_ELEM ForceLTerm;
	_DGN_FORC_CRC_ELEM ForceLTermExTP;
	_DGN_FORC_CRC_ELEM ForceJtgTndn;
	// Stress.
	ADGNSTRESS aStressLcomInTP;
	ADGNSTRESS aStressTnpr;
	ADGNSTRESS aStressTnsc;
	ADGNSTRESS aStressLTerm;
	_DGN_STRS_CRC_ELEM StressLcomInTP;
	_DGN_STRS_CRC_ELEM StressLcomExTP;
	_DGN_STRS_CRC_ELEM StressTnpr;
	_DGN_STRS_CRC_ELEM StressTnsc;
	_DGN_STRS_CRC_ELEM StressLTerm;
	_DGN_STRS_CRC_ELEM StressLTermExTP;
	// Principle.
	ADGNSHRSADD aStssLcom;
	_DGN_SHRS_ADD_ELEM StssLcom;

	// Expansion Position Force & Stress Data (2 Position -> 5 Position)
	ADGNFORCE_EX aForceLcomInTP_EX;
	ADGNFORCE_EX aForceTnpr_EX;
	ADGNFORCE_EX aForceTnsc_EX;
	ADGNSTRSADD_EX aStressAdd_EX;
	ADGNFORCE_EX aForceLTerm_EX;
	ADGNFORCE_EX aForceJtgTndn_EX;
	_DGN_FORC_CRC_EX_ELEM ForceLcomInTP_EX;
	_DGN_FORC_CRC_EX_ELEM ForceLcomExTP_EX;
	_DGN_FORC_CRC_EX_ELEM ForceTnpr_EX;
	_DGN_FORC_CRC_EX_ELEM ForceTnsc_EX;
	_DGN_STRS_ADD_EX_ELEM StressAdd_EX;
	_DGN_FORC_CRC_EX_ELEM ForceLTerm_EX;
	_DGN_FORC_CRC_EX_ELEM ForceLTermExTP_EX;
	_DGN_FORC_CRC_EX_ELEM ForceJtgTndn_EX;
	// Stress.
	ADGNSTRESS_EX aStressLcomInTP_EX;
	ADGNSTRESS_EX aStressTnpr_EX;
	ADGNSTRESS_EX aStressTnsc_EX;
	ADGNSTRESS_EX aStressLTerm_EX;
	_DGN_STRS_CRC_EX_ELEM StressLcomInTP_EX;
	_DGN_STRS_CRC_EX_ELEM StressLcomExTP_EX;
	_DGN_STRS_CRC_EX_ELEM StressTnpr_EX;
	_DGN_STRS_CRC_EX_ELEM StressTnsc_EX;
	_DGN_STRS_CRC_EX_ELEM StressLTerm_EX;
	_DGN_STRS_CRC_EX_ELEM StressLTermExTP_EX;
	// Principle.
	ADGNSHRSADD_EX aStssLcom_EX;
	_DGN_SHRS_ADD_EX_ELEM StssLcom_EX;

	for (i = 0; i < aElemK.GetSize(); ++i)
	{
		ElemPairK ElemK = aElemK.GetAt(i);
		aForceLcomInTP.RemoveAll();
		aForceTnpr.RemoveAll();
		aForceTnsc.RemoveAll();
		aStressAdd.RemoveAll();
		aForceLTerm.RemoveAll();
		// Stress.
		aStressLcomInTP.RemoveAll();
		aStressTnpr.RemoveAll();
		aStressTnsc.RemoveAll();
		aStressLTerm.RemoveAll();
		// Principle.
		aStssLcom.RemoveAll();
		if (bBinary)
		{
			m_ForceCtrl.Get_LcomDataForDesignBinary(ElemK, TRUE, FALSE);
		}
		else
		{
			m_ForceCtrl.Get_LcomDataForStress(ElemK, TRUE, FALSE, aForceLcomInTP, aForceTnpr, aForceTnsc, aStressAdd, aForceLTerm, aForceJtgTndn,
				aStressLcomInTP, aStressTnpr, aStressTnsc, aStressLTerm, aStssLcom);
			// Add by ZINU.('04.12.30). ForceLcom -> Include TP, Exclude TP.
			// Lcom Forces (Include TP).
			ForceLcomInTP.Initialize();
			ForceLcomInTP.aForceLcom.Copy(aForceLcomInTP);
			m_ForceCtrl.m_arForcElemInTP.insert({ElemK, ForceLcomInTP});
			// Tendon Primary Forces.
			ForceTnpr.Initialize();
			ForceTnpr.aForceLcom.Copy(aForceTnpr);
			m_ForceCtrl.m_arForcTnprData.insert({ElemK, ForceTnpr});
			// Tendon Secondary Forces.
			ForceTnsc.Initialize();
			ForceTnsc.aForceLcom.Copy(aForceTnsc);
			m_ForceCtrl.m_arForcTnscData.insert({ElemK, ForceTnsc});
			// Lcom Forces (Exclude TP).
			ForceLcomExTP.Initialize();
			ForceLcomExTP += ForceLcomInTP;
			ForceLcomExTP -= ForceTnpr;
			m_ForceCtrl.m_arForcElemExTP.insert({ElemK, ForceLcomExTP});
			// Add by ZINU.('05.01.04). Stress For Beam Section Temperature.
			StressAdd.Initialize();
			StressAdd.aStressAdd.Copy(aStressAdd);
			m_ForceCtrl.m_arStrsAddData.insert({ElemK, StressAdd});
			// Add by Jaeoh. ('05.08.16)
			// LTerm Force. For JTG D62-04.
			ForceLTerm.Initialize();
			ForceLTerm.aForceLcom.Copy(aForceLTerm);
			m_ForceCtrl.m_arForcElemLTerm.insert({ElemK, ForceLTerm});
			// LTerm Force (Exclude TP)
			ForceLTermExTP.Initialize();
			ForceLTermExTP += ForceLTerm;
			ForceLTermExTP -= ForceTnpr;
			m_ForceCtrl.m_arForcElemLTermExTP.insert({ElemK, ForceLTermExTP});
			// Add by Jaeoh. ('06.09.18)
			// For JTG, Tendon Stress
			ForceJtgTndn.Initialize();
			ForceJtgTndn.aForceLcom.Copy(aForceJtgTndn);
			m_ForceCtrl.m_arForcForJtgTndnStress.insert({ElemK, ForceJtgTndn});

			// Stress.
			// Lcom Stress (Include TP).
			StressLcomInTP.Initialize();
			StressLcomInTP.aStressLcom.Copy(aStressLcomInTP);
			m_ForceCtrl.m_arStressElemInTP.insert({ElemK, StressLcomInTP});
			// Tendon Primary Stress.
			StressTnpr.Initialize();
			StressTnpr.aStressLcom.Copy(aStressTnpr);
			m_ForceCtrl.m_arStressTnprData.insert({ElemK, StressTnpr});
			// Tendon Secondary Stress.
			StressTnsc.Initialize();
			StressTnsc.aStressLcom.Copy(aStressTnsc);
			m_ForceCtrl.m_arStressTnscData.insert({ElemK, StressTnsc});
			// Lcom Stress. (Exclude TP).
			StressLcomExTP.Initialize();
			StressLcomExTP += StressLcomInTP;
			StressLcomExTP -= StressTnpr;
			m_ForceCtrl.m_arStressElemExTP.insert({ElemK, StressLcomExTP});
			// LTerm Stress. For JTG D62-04.
			StressLTerm.Initialize();
			StressLTerm.aStressLcom.Copy(aStressLTerm);
			m_ForceCtrl.m_arStressElemLTerm.insert({ElemK, StressLTerm});
			// LTerm Stress. (Exclude TP)
			StressLTermExTP.Initialize();
			StressLTermExTP += StressLTerm;
			StressLTermExTP -= StressTnpr;
			m_ForceCtrl.m_arStressElemLTermExTP.insert({ElemK, StressLTermExTP});

			// Principle.
			StssLcom.Initialize();
			StssLcom.aStressAdd.Copy(aStssLcom);
			m_ForceCtrl.m_arStssElemShrs.insert({ElemK, StssLcom});

			if (m_ForceCtrl.Get_Write5PositionDgnForce())
			{
				m_ForceCtrl.Get_LcomDataForStress_EX(ElemK, TRUE, FALSE, aForceLcomInTP_EX, aForceTnpr_EX, aForceTnsc_EX,
					aStressAdd_EX, aForceLTerm_EX, aForceJtgTndn_EX, aStressLcomInTP_EX,
					aStressTnpr_EX, aStressTnsc_EX, aStressLTerm_EX, aStssLcom_EX);
				// Add by ZINU.('04.12.30). ForceLcom -> Include TP, Exclude TP.
				// Lcom Forces (Include TP).
				ForceLcomInTP_EX.Initialize();
				ForceLcomInTP_EX.aForceLcom.Copy(aForceLcomInTP_EX);
				m_ForceCtrl.m_arForcElemInTP_EX.insert({ElemK, ForceLcomInTP_EX});

				// Tendon Primary Forces.
				ForceTnpr_EX.Initialize();
				ForceTnpr_EX.aForceLcom.Copy(aForceTnpr_EX);
				m_ForceCtrl.m_arForcTnprData_EX.insert({ElemK, ForceTnpr_EX});

				// Tendon Secondary Forces.
				ForceTnsc_EX.Initialize();
				ForceTnsc_EX.aForceLcom.Copy(aForceTnsc_EX);
				m_ForceCtrl.m_arForcTnscData_EX.insert({ElemK, ForceTnsc_EX});

				// Lcom Forces (Exclude TP).
				ForceLcomExTP_EX.Initialize();
				ForceLcomExTP_EX += ForceLcomInTP_EX;
				ForceLcomExTP_EX -= ForceTnpr_EX;
				m_ForceCtrl.m_arForcElemExTP_EX.insert({ElemK, ForceLcomExTP_EX});

				// Add by ZINU.('05.01.04). Stress For Beam Section Temperature.
				StressAdd_EX.Initialize();
				StressAdd_EX.aStressAdd.Copy(aStressAdd_EX);
				m_ForceCtrl.m_arStrsAddData_EX.insert({ElemK, StressAdd_EX});

				// Add by Jaeoh. ('05.08.16)
				// LTerm Force. For JTG D62-04.
				ForceLTerm_EX.Initialize();
				ForceLTerm_EX.aForceLcom.Copy(aForceLTerm_EX);
				m_ForceCtrl.m_arForcElemLTerm_EX.insert({ElemK, ForceLTerm_EX});

				// LTerm Force (Exclude TP)
				ForceLTermExTP_EX.Initialize();
				ForceLTermExTP_EX += ForceLTerm_EX;
				ForceLTermExTP_EX -= ForceTnpr_EX;
				m_ForceCtrl.m_arForcElemLTermExTP_EX.insert({ElemK, ForceLTermExTP_EX});

				// Add by Jaeoh. ('06.09.18)
				// For JTG, Tendon Stress
				ForceJtgTndn_EX.Initialize();
				ForceJtgTndn_EX.aForceLcom.Copy(aForceJtgTndn_EX);
				m_ForceCtrl.m_arForcForJtgTndnStress_EX.insert({ElemK, ForceJtgTndn_EX});

				// Stress.
				// Lcom Stress (Include TP).
				StressLcomInTP_EX.Initialize();
				StressLcomInTP_EX.aStressLcom.Copy(aStressLcomInTP_EX);
				m_ForceCtrl.m_arStressElemInTP_EX.insert({ElemK, StressLcomInTP_EX});

				// Tendon Primary Stress.
				StressTnpr_EX.Initialize();
				StressTnpr_EX.aStressLcom.Copy(aStressTnpr_EX);
				m_ForceCtrl.m_arStressTnprData_EX.insert({ElemK, StressTnpr_EX});

				// Tendon Secondary Stress.
				StressTnsc_EX.Initialize();
				StressTnsc_EX.aStressLcom.Copy(aStressTnsc_EX);
				m_ForceCtrl.m_arStressTnscData_EX.insert({ElemK, StressTnsc_EX});

				// Lcom Stress. (Exclude TP).
				StressLcomExTP_EX.Initialize();
				StressLcomExTP_EX += StressLcomInTP_EX;
				StressLcomExTP_EX -= StressTnpr_EX;
				m_ForceCtrl.m_arStressElemExTP_EX.insert({ElemK, StressLcomExTP_EX});

				// LTerm Stress. For JTG D62-04.
				StressLTerm_EX.Initialize();
				StressLTerm_EX.aStressLcom.Copy(aStressLTerm_EX);
				m_ForceCtrl.m_arStressElemLTerm_EX.insert({ElemK, StressLTerm_EX});

				// LTerm Stress. (Exclude TP)
				StressLTermExTP_EX.Initialize();
				StressLTermExTP_EX += StressLTerm_EX;
				StressLTermExTP_EX -= StressTnpr_EX;
				m_ForceCtrl.m_arStressElemLTermExTP_EX.insert({ElemK, StressLTermExTP_EX});

				// Principle.
				StssLcom_EX.Initialize();
				StssLcom_EX.aStressAdd.Copy(aStssLcom_EX);
				m_ForceCtrl.m_arStssElemShrs_EX.insert({ElemK, StssLcom_EX});
			}
		}
	}

	if (bExistStage && !bPostCS) m_pDoc->m_pStagCtrl->SetCurStagWithoutUpdateNotify(CurStagK);

	if (bBinary)
	{
		m_ForceCtrl.CloseDgnForceFile();

		if (!CheckDesignForceData()) return FALSE;
	}

	return TRUE;
}

void CCRCDataCtrl::Set_SerialCheckElemData()
{
	for (int i = 0; i < m_arCheckElemK.GetSize(); ++i)
	{
		m_mapSerialElemK.insert({ m_arCheckElemK[i], i + 1 });
	}
}

UINT CCRCDataCtrl::Get_SerialCheckElemData(ElemPairK ElemK)
{
	UINT iSerialKey = 0;
	const auto& iter = m_mapSerialElemK.find(ElemK);
	if (iter != m_mapSerialElemK.end())
	{
		iSerialKey = iter->second;
	}

	return iSerialKey;
}

BOOL CCRCDataCtrl::Get_LcomDataMap(CMap<T_LCOM_K, T_LCOM_K, T_LCOM_K, T_LCOM_K>& aLcomK)
{
	return m_ForceCtrl.Get_LcomDataMap(aLcomK);
}

BOOL CCRCDataCtrl::Get_ForcDataMap(CMap<_CRC_COMF_K, _CRC_COMF_K, _CRC_COMF_D, _CRC_COMF_D&>& aForcD, CMapEx<int, int, _CRC_COMF_K, _CRC_COMF_K&>& mComfKey)
{
	aForcD.RemoveAll();
	ArrElemPairKey aElemK;
	if (!Get_CrcElemListForDgn(FALSE, aElemK))	return FALSE;
	_CRC_COMF_K ComfK;
	_CRC_COMF_D ComfD;
	int i = 0, j = 0, k = 0;
	int iLcomNum = m_ForceCtrl.Get_LcomDataCount();
	int nSerialK = 1;
	for (i = 0; i < aElemK.GetSize(); ++i)
	{
		auto ElemK = aElemK.GetAt(i);
		ADGNFORCE aForceLcom;
		if (!m_ForceCtrl.Get_LcomDataForDesign(ElemK, 0, TRUE, FALSE, aForceLcom, iLcomNum))	continue;	// TRUE=Include Tendon Primary.
		for (j = 0; j < aForceLcom.GetSize(); ++j)
		{
			_DGN_FORC_CRC &ForceLcom = aForceLcom.GetAt(j);
			int iDgnLcomNo = j + 1;
			CString strOrgLcomNa = _T("");
			int iOrgLcomNo = 0, iOrgLccomCount = 0;
			int iMaxMinType = 0;
			if (!m_ForceCtrl.Get_LcomType(iDgnLcomNo, strOrgLcomNa, iOrgLcomNo, iOrgLccomCount, iMaxMinType)) continue;
			int iDgnLcomKind = m_ForceCtrl.Get_LcomKind(iDgnLcomNo);
			for (k = 0; k < 2; k++)	// I,J.
			{
				ComfK.Initialize();
				ComfK.ElemK = ElemK.first;
				ComfK.DgnLcomK = iDgnLcomNo;
				ComfK.nPos = k;
				ComfD.Initialize();
				ComfD.OrgLcomK = iOrgLcomNo;
				ComfD.iKind = iDgnLcomKind;
				ComfD.iMax = iMaxMinType;
				ComfD.dFxx = ForceLcom.dFxx[k];
				ComfD.dFyy = ForceLcom.dFyy[k];
				ComfD.dFzz = ForceLcom.dFzz[k];
				ComfD.dMux = ForceLcom.dMux[k];
				ComfD.dMuy = ForceLcom.dMuy[k];
				ComfD.dMuz = ForceLcom.dMuz[k];
				aForcD.SetAt(ComfK, ComfD);
				mComfKey.SetAt(nSerialK++, ComfK);
			}
		}
	}
	return TRUE;
}

