BOOL CCRCDataCtrl::Get_CrcCums(ElemPairK ElemK, T_CUMS_D& CumsD)
{
	CumsD.Initialize();
	// Add by ZINU.('04.08.25). Check Calculating Item.
	if (!Is_CalcItem(ElemK, FALSE))  return FALSE;
	// Add by ZINU.('05.09.05).	PSC-Design/Strs(5), PSC-Design/Strn(6).
	int iDgnStatus = m_pDoc->GetDesignStatus();
	m_pDoc->SetDesignStatus(6);

	int iLcomNum = m_ForceCtrl.Get_LcomDataCount();
	ADGNFORCE aForceLcom;
	if (!m_ForceCtrl.Get_LcomDataForDesign(ElemK, 0, FALSE, FALSE, aForceLcom, iLcomNum))	return FALSE;
	if (m_ForceCtrl.Get_LcomNumForStrn() == 0)	return FALSE;

	m_ForceCtrl.Debug_PrintOpt(10);	// For DEBUG.
	double dTol = 1. / pow(m_dZero, 40);
	double dFzMax[2] = { -dTol,-dTol }, dFzMin[2] = { +dTol,+dTol };
	double dMxMax[2] = { -dTol,-dTol }, dMxMin[2] = { +dTol,+dTol };
	int iMaxDgnLcom[2] = { 0,0 }, iMinDgnLcom[2] = { 0,0 };
	int i = 0, j = 0;
	for (i = 0; i < aForceLcom.GetSize(); ++i)
	{
		if (!m_ForceCtrl.Is_LcomForStrn(i + 1))	continue;	// Only 종국시.
		_DGN_FORC_CRC &ForceCrc = aForceLcom.GetAt(i);
		for (j = 0; j < 2; ++j)	// I,J.
		{
			if (ForceCrc.dFzz[j] > dFzMax[j]) { dFzMax[j] = ForceCrc.dFzz[j]; dMxMax[j] = ForceCrc.dMux[j]; iMaxDgnLcom[j] = i + 1; }
			if (ForceCrc.dFzz[j] < dFzMin[j]) { dFzMin[j] = ForceCrc.dFzz[j]; dMxMin[j] = ForceCrc.dMux[j]; iMinDgnLcom[j] = i + 1; }
		}
	}
	for (i = 0; i < 4; ++i)
	{
		// 0=I-MAX, 1=I-MIN, 2=J-MAX, 3=J-MIN.
		int iDgnLcomNo = (i % 2 == 0 ? iMaxDgnLcom[i / 2] : iMinDgnLcom[i / 2]);
		CString strOrgLcomNa = _T("");
		int iMaxMinType = 0;
		if (!m_ForceCtrl.Get_LcomType(iDgnLcomNo, strOrgLcomNa, iMaxMinType))	ASSERT(0);
		double dFzz = (i % 2 == 0 ? dFzMax[i / 2] : dFzMin[i / 2]);
		double dMux = (i % 2 == 0 ? dMxMax[i / 2] : dMxMin[i / 2]);

		CumsD.CumsBase[i].bCHK = Get_ChkFlag(ElemK, i / 2, FALSE);
		CumsD.CumsBase[i].LcomK = iDgnLcomNo;
		CumsD.CumsBase[i].iKind = m_ForceCtrl.Get_LcomKind(iDgnLcomNo);
		CumsD.CumsBase[i].iMax = iMaxMinType;
		CumsD.CumsBase[i].dQU = dFzz;
		CumsD.CumsBase[i].dQR = 0.0;	// From CRC.
		CumsD.CumsBase[i].dTU = dMux;
		CumsD.CumsBase[i].dTR = 0.0;	// From CRC.
	}
	return TRUE;
}

