BOOL CCRCDataCtrl::Get_CrcFsmt(ElemPairK ElemK, T_FSMT_D& FsmtD)
{
	FsmtD.Initialize();
	// Add by ZINU.('04.08.25). Check Calculating Item.
	if (!Is_CalcItem(ElemK, FALSE))  return FALSE;
	// Add by ZINU.('05.09.05).	PSC-Design/Strs(5), PSC-Design/Strn(6).
	int iDgnStatus = m_pDoc->GetDesignStatus();
	m_pDoc->SetDesignStatus(5);

	_DGN_SHRS_CRC ShrsMax;
	_DGN_SHRS_CRC ShrsMin;

	m_ForceCtrl.Debug_PrintOpt(12);	// For DEBUG.
	if (!m_ForceCtrl.Get_ShrsByLcom(ElemK, ShrsMax, ShrsMin, 6, FALSE))	return FALSE;	// 2=Only Torsion.
	// Set Data.
	int i = 0;
	for (i = 0; i < 4; ++i)
	{
		// 0=I-MAX, 1=I-MIN, 2=J-MAX, 3=J-MIN.
		_DGN_SHRS_CRC &ShrsCrc = (i % 2 == 0 ? ShrsMax : ShrsMin);
		// Change by ZINU.('06.06.01). ShrsCrc.dSxi[i/2][1]==0.0.
		if (ShrsCrc.dSsh[i / 2][1] == 0.0 && ShrsCrc.dSst[i / 2][1] == 0.0 && ShrsCrc.dSxi[i / 2][1] == 0.0)	continue;

		int iDgnLcomNo = ShrsCrc.iRefNo[i / 2];
		CString strOrgLcomNa = _T("");
		int iMaxMinType = 0;
		if (!m_ForceCtrl.Get_LcomType(iDgnLcomNo, strOrgLcomNa, iMaxMinType))	ASSERT(0);

		FsmtD.FsmtBase[i].bCHK = Get_ChkFlag(ElemK, i / 2, FALSE);
		FsmtD.FsmtBase[i].LcomK = iDgnLcomNo;
		FsmtD.FsmtBase[i].iKind = m_ForceCtrl.Get_LcomKind(iDgnLcomNo);
		FsmtD.FsmtBase[i].iMax = iMaxMinType;
		FsmtD.FsmtBase[i].dFS1 = ShrsCrc.dSsh[i / 2][0];
		FsmtD.FsmtBase[i].dFSG = ShrsCrc.dSsh[i / 2][1];
		FsmtD.FsmtBase[i].dFS3 = ShrsCrc.dSsh[i / 2][2];
		FsmtD.FsmtBase[i].dAFS = 0.0;	// From CRC.
		FsmtD.FsmtBase[i].dFST1 = ShrsCrc.dSst[i / 2][0];
		FsmtD.FsmtBase[i].dFSTG = ShrsCrc.dSst[i / 2][1];
		FsmtD.FsmtBase[i].dFST3 = ShrsCrc.dSst[i / 2][2];
		FsmtD.FsmtBase[i].dAFST = 0.0;	// From CRC.
	}

	if (m_iCivilCode == KSCE_USD03)
	{
		if (!m_pKSCE_USD03->Get_KsceFsmt(ElemK, FsmtD)) return FALSE;
	}
	else if (m_iCivilCode == KSCE_USD05 || m_iCivilCode == KSCE_USD05 || m_iCivilCode == KSCE_USD10 ||
		m_iCivilCode == KSCE_RAIL_USD04 || m_iCivilCode == KSCE_RAIL_USD11)
	{
		if (!m_pKSCE_USD05->Get_KsceFsmt(ElemK, FsmtD)) return FALSE;
	}

	return TRUE;
}

