		FpmtJtg.FpmtBase[i].dFP6 = ShrsJtg.dSsp[i / 2][5];
		FpmtJtg.FpmtBase[i].dFP7 = ShrsJtg.dSsp[i / 2][6];
		FpmtJtg.FpmtBase[i].dFP8 = ShrsJtg.dSsp[i / 2][7];
		FpmtJtg.FpmtBase[i].dFP9 = ShrsJtg.dSsp[i / 2][8];
