BOOL CCRCDataCtrl::Get_JtgTbar(ElemPairK ElemK, T_TBAR_JTG& TbarJtg, T_DETAIL_STR& RptInfo)
{
	TbarJtg.Initialize();
	if (!Is_CalcItem(ElemK, TRUE))  return FALSE;
	// Add by ZINU.('05.09.05).	PSC-Design/Strs(5), PSC-Design/Strn(6).
	int iDgnStatus = m_pDoc->GetDesignStatus();
	m_pDoc->SetDesignStatus(6);

	int iLcomNum = m_ForceCtrl.Get_LcomDataCount();
	/*
	ADGNFORCE aForceLcom;
	ADGNFORCE aForceTnpr;
	ADGNFORCE aForceTnsc;
	ADGNFORCE aForceLTerm;
	ADGNSHRSADD aStssLcom;
	if(!m_ForceCtrl.Get_LcomDataForDesign(ElemK, FALSE, FALSE, aForceLcom, aForceTnpr, aForceTnsc, aForceLTerm, aStssLcom)) return FALSE;
	*/
	if (m_ForceCtrl.Get_LcomNumForStrn() == 0)	return FALSE;
	//if(aForceLcom.GetSize()!=aForceTnpr.GetSize())	{ASSERT(0); return FALSE;}

	double dTol = 1. / pow(m_dZero, 40);
	double dMyMax[2] = { -dTol,-dTol }, dMyMin[2] = { +dTol,+dTol };
	int iMaxDgnLcom[2] = { 0,0 }, iMinDgnLcom[2] = { 0,0 };
	int i = 0, j = 0;
	for (i = 0; i < iLcomNum; ++i)
	{
		int iSerialLcom = i + 1;
		if (!m_ForceCtrl.Is_LcomForStrn(i + 1))	continue;	// Only 종국시.
		_DGN_FORC_CRC ForcLcom;
		GetDesignForceResult()->GetForceLcomExTpResult(ElemK, iSerialLcom, ForcLcom);
		//
		_DGN_FORC_CRC ForceTnsc;
		GetDesignForceResult()->GetForceTnscResult(ElemK, iSerialLcom, ForceTnsc);

		_DGN_FORC_CRC ForceCrc;
		for (j = 0; j < 2; ++j)	// I,J.
		{
			ForceCrc.dMuy[j] = ForcLcom.dMuy[j] - ForceTnsc.dMuy[j];

			if (ForceCrc.dMuy[j] > dMyMax[j])
			{
				dMyMax[j] = ForceCrc.dMuy[j];
				iMaxDgnLcom[j] = i + 1;
			}
			if (ForceCrc.dMuy[j] < dMyMin[j])
			{
				dMyMin[j] = ForceCrc.dMuy[j];
				iMinDgnLcom[j] = i + 1;
			}
		}
	}
	for (i = 0; i < 4; ++i)
	{
		// 0=I-TOP_MAX, 1=I-BOT_MAX, 2=J-TOP_MAX, 3=J-BOT_MAX.
		// TOP_MAX=My_MIN, BOT_MAX=My_MAX
		int iDgnLcomNo = (i % 2 == 0 ? iMinDgnLcom[i / 2] : iMaxDgnLcom[i / 2]);
		CString strOrgLcomNa = _T("");
		int iMaxMinType = 0;
		if (!m_ForceCtrl.Get_LcomType(iDgnLcomNo, strOrgLcomNa, iMaxMinType))	ASSERT(0);
		double dMuy = (i % 2 == 0 ? dMyMin[i / 2] : dMyMax[i / 2]);

		TbarJtg.TbarBase[i].bCHK = Get_ChkFlag(ElemK, i / 2, TRUE);
		TbarJtg.TbarBase[i].LcomK = iDgnLcomNo;
		TbarJtg.TbarBase[i].iMax = iMaxMinType;
		TbarJtg.TbarBase[i].dMj = dMuy;
		TbarJtg.TbarBase[i].dREQ = 0.0;
		TbarJtg.TbarBase[i].dUSE = 0.0;
		TbarJtg.TbarBase[i].dMIN = 0.0;
	}

	if (m_iCivilCode == JTG_D62_04 || m_iCivilCode == CJJ_11_2011)
	{
		if (!m_pJTG_D62_04->Get_JtgTbar(ElemK, TbarJtg, RptInfo)) return FALSE;
	}

	return TRUE;
}

BOOL CCRCDataCtrl::Get_JtgTndn(ElemPairK ElemK, T_TNDN_JTG& TndnJtg, T_DETAIL_STR& RptInfo)
{
	TndnJtg.Initialize();
	if (!Is_CalcItem(ElemK, TRUE))  return FALSE;
	// Add by ZINU.('05.09.05).	PSC-Design/Strs(5), PSC-Design/Strn(6).
	int iDgnStatus = m_pDoc->GetDesignStatus();
	m_pDoc->SetDesignStatus(6);

	// Stage
	CArray<T_STAG_K, T_STAG_K> aStagK;
	m_pStageInfo->GetResultSavedStagKeyList(aStagK);
	if (aStagK.GetSize() == 0)	return FALSE;
	int i = 0, j = 0;
	double dTol = 1. / pow(m_dZero, 40);
	double dMgMax[2] = { -dTol,-dTol }, dMgMin[2] = { +dTol,+dTol };
	int iMaxStage[2] = { 0,0 }, iMinStage[2] = { 0,0 };
	for (i = 0; i < aStagK.GetSize(); ++i)
	{
		T_STCT_D StctD; StctD.Initialize();
		m_pAttrCtrl->GetStct(StctD);
		T_STAG_K StagK = aStagK.GetAt(i);
		int iFinalStepNo = 0;
		// Get Last StepNo at Current Stage.
		Get_LastStepInCurStage(StagK, iFinalStepNo);

		_DGN_FORC_CRC ForceLcase;
		_DGN_STRS_CRC StressLcase;
		// DL.
		CString strDL = _LS(IDS_DB_SGLD_DL);
		T_SGLD_K SgldDlK = m_pAttrCtrl->GetSgldKey(strDL);
		T_SGLD_D SgldDlD; SgldDlD.Initialize();
		if (!m_pStageInfo->GetSgldPost(SgldDlK, SgldDlD)) continue;
		_DGN_FORC_CRC ForceLcaseDL;
		_DGN_STRS_CRC StressLcaseDL;
		_DGN_SHRS_ADD StssLcaseDL;
		if (!m_ForceCtrl.Get_Sgld_Expo(ElemK, SgldDlK, SgldDlD, iFinalStepNo, ForceLcaseDL, StressLcaseDL, StssLcaseDL)) continue;
		// EL.
		_DGN_FORC_CRC ForceLcaseEL;
		_DGN_STRS_CRC StressLcaseEL;
		_DGN_SHRS_ADD StssLcaseEL;
		for (INT_PTR Er = 0; Er < StctD.aErection.GetSize(); ++Er)
		{
			T_SGLD_K SgldElK = m_pAttrCtrl->GetSgldKey(StctD.aErection[Er].strErection);
			T_SGLD_D SgldElD; SgldElD.Initialize();
			if (!m_pStageInfo->GetSgldPost(SgldElK, SgldElD)) continue;

			if (CDBLib::IsStldDL(StctD.aErection[Er].LoadCaseType))
			{
				_DGN_FORC_CRC ForceEL;
				_DGN_STRS_CRC StressEL;
				_DGN_SHRS_ADD StssEL;
				if (!m_ForceCtrl.Get_Sgld_Expo(ElemK, SgldElK, SgldElD, iFinalStepNo, ForceEL, StressEL, StssEL)) continue;
				ForceLcaseEL += ForceEL;
				StressLcaseEL += StressEL;
				StssLcaseEL += StssEL;
			}
		}

		double dMuy[2] = { 0, 0 };
		for (j = 0; j < 2; ++j)	// I,J.
		{
			//      ForceLcase.dMuy[j] = ForceLcaseDL.dMuy[j] + ForceLcaseEL.dMuy[j];
			dMuy[j] = ForceLcaseDL.dMuy[j] + ForceLcaseEL.dMuy[j];//by maxiao 2009.12.18      
			if (dMuy[j] > dMgMax[j])
			{
				dMgMax[j] = dMuy[j];
				iMaxStage[j] = StagK;
			}
			if (dMuy[j] < dMgMin[j])
			{
				dMgMin[j] = dMuy[j];
				iMinStage[j] = StagK;
			}
		}
	}

	/*
	ADGNFORCE aForceLcom;
	ADGNFORCE aForceTnpr;
	ADGNFORCE aForceTnsc;
	ADGNFORCE aForceLTerm;
	ADGNSHRSADD aStssLcom;
	if(!m_ForceCtrl.Get_LcomDataForDesign(ElemK, FALSE, FALSE, aForceLcom, aForceTnpr, aForceTnsc, aForceLTerm, aStssLcom)) return FALSE;
	*/
	if (m_ForceCtrl.Get_LcomNumForStrs() == 0 || m_ForceCtrl.Get_LcomNumForStrn() == 0)	return FALSE;
	//if(aForceLcom.GetSize()!=aForceTnpr.GetSize())	{ASSERT(0); return FALSE;}
	//if(aForceLcom.GetSize()!=aForceLTerm.GetSize())	{ASSERT(0); return FALSE;}

	int iLcomNum = m_ForceCtrl.Get_LcomDataCount();
	double dMyMaxServ[2] = { -dTol,-dTol }, dMyMinServ[2] = { +dTol,+dTol };
	int iMaxLcomServ[2] = { 0,0 }, iMinLcomServ[2] = { 0,0 };
	for (i = 0; i < iLcomNum; ++i)
	{
		int iSerialLcom = i + 1;
		if (!m_ForceCtrl.Is_LcomForStrs(i + 1))	continue; // Only 정상사용극한상태.
		//
		_DGN_FORC_CRC ForcLcom;
		GetDesignForceResult()->GetForceLcomExTpResult(ElemK, iSerialLcom, ForcLcom);
		//
		_DGN_FORC_CRC ForceTnsc;
		GetDesignForceResult()->GetForceTnscResult(ElemK, iSerialLcom, ForceTnsc);

		_DGN_FORC_CRC ForceCrc;
		for (j = 0; j < 2; ++j)	// I,J.
		{
			ForceCrc.dMuy[j] = ForcLcom.dMuy[j] - ForceTnsc.dMuy[j];

			if (ForceCrc.dMuy[j] > dMyMaxServ[j])
			{
				dMyMaxServ[j] = ForceCrc.dMuy[j];
				iMaxLcomServ[j] = i + 1;
			}
			if (ForceCrc.dMuy[j] < dMyMinServ[j])
			{
				dMyMinServ[j] = ForceCrc.dMuy[j];
				iMinLcomServ[j] = i + 1;
			}
		}
	}

	// 재하능력극한상태 휨강도
	double dMyMaxStrn[2] = { -dTol,-dTol }, dMyMinStrn[2] = { +dTol,+dTol };
	int iMaxLcomStrn[2] = { 0,0 }, iMinLcomStrn[2] = { 0,0 };
	for (i = 0; i < iLcomNum; ++i)
	{
		int iSerialLcom = i + 1;
		if (!m_ForceCtrl.Is_LcomForStrn(i + 1))	continue;	// Only 재하능력극한상태.

		//
		_DGN_FORC_CRC ForcLcom;
		GetDesignForceResult()->GetForceLcomExTpResult(ElemK, iSerialLcom, ForcLcom);
		//
		_DGN_FORC_CRC ForceTnsc;
		GetDesignForceResult()->GetForceTnscResult(ElemK, iSerialLcom, ForceTnsc);

		_DGN_FORC_CRC ForceCrc;
		for (j = 0; j < 2; ++j)	// I,J.
		{
			ForceCrc.dMuy[j] = ForcLcom.dMuy[j] - ForceTnsc.dMuy[j];

			if (ForceCrc.dMuy[j] > dMyMaxStrn[j])
			{
				dMyMaxStrn[j] = ForceCrc.dMuy[j];
				iMaxLcomStrn[j] = i + 1;
			}
			if (ForceCrc.dMuy[j] < dMyMinStrn[j])
			{
				dMyMinStrn[j] = ForceCrc.dMuy[j];
				iMinLcomStrn[j] = i + 1;
			}
		}
	}
	T_BDCY_JTG bdcyData;
	bdcyData.Initialize();
	auto& it = m_mapResultBDCY_JTG.find(ElemK);
	if (it == m_mapResultBDCY_JTG.end())
	{
		T_DETAIL_STR DetailStr;
		m_pJTG_D62_04->Get_JtgBdcy(ElemK, bdcyData, DetailStr);
	}

	for (i = 0; i < 4; ++i)
	{
		// 0=I-TOP_MAX, 1=I-BOT_MAX, 2=J-TOP_MAX, 3=J-BOT_MAX.
		// TOP_MAX=My_MIN, BOT_MAX=My_MAX
		// Stage
		int iStage = (i % 2 == 0 ? iMinStage[i / 2] : iMaxStage[i / 2]);
		double dMg = (i % 2 == 0 ? dMgMin[i / 2] : dMgMax[i / 2]);

		// 정상사용극한상태. 
		int iDgnLcomNoServ = (i % 2 == 0 ? iMinLcomServ[i / 2] : iMaxLcomServ[i / 2]);
		CString strOrgLcomNaServ = _T("");
		int iMaxMinTypeServ = 0;
		if (!m_ForceCtrl.Get_LcomType(iDgnLcomNoServ, strOrgLcomNaServ, iMaxMinTypeServ))	ASSERT(0);
		double dMsum = (i % 2 == 0 ? dMyMinServ[i / 2] : dMyMaxServ[i / 2]);

		// 재하능력극한상태.
		int iDgnLcomNoStrn = (i % 2 == 0 ? iMinLcomStrn[i / 2] : iMaxLcomStrn[i / 2]);
		CString strOrgLcomNaStrn = _T("");
		int iMaxMinTypeStrn = 0;
		if (!m_ForceCtrl.Get_LcomType(iDgnLcomNoStrn, strOrgLcomNaStrn, iMaxMinTypeStrn))	ASSERT(0);
		double dMj = (i % 2 == 0 ? dMyMinStrn[i / 2] : dMyMaxStrn[i / 2]);
		double dMuy = bdcyData.BdcyBase[i].dMny;

		TndnJtg.TndnBase[i].bCHK = Get_ChkFlag(ElemK, i / 2, TRUE);
		TndnJtg.TndnBase[i].StagK = iStage;
		TndnJtg.TndnBase[i].dMg1 = dMg;
		TndnJtg.TndnBase[i].LcomKSer = iDgnLcomNoServ;  //정상사용극한상태 하중조합.
		TndnJtg.TndnBase[i].iMaxSer = iMaxMinTypeServ;
		TndnJtg.TndnBase[i].dMsum = dMsum;
		TndnJtg.TndnBase[i].LcomK = iDgnLcomNoStrn;  //재하능력극한상태 하중조합.
		TndnJtg.TndnBase[i].iMax = iMaxMinTypeStrn;
		TndnJtg.TndnBase[i].dMj = dMj;
		TndnJtg.TndnBase[i].dMud = dMuy;

		// Etc. From JTG D62-04.
	}

	if (m_iCivilCode == JTG_D62_04 || m_iCivilCode == CJJ_11_2011)
	{
		if (!m_pJTG_D62_04->Get_JtgTndn(ElemK, TndnJtg, RptInfo)) return FALSE;
	}
	else { ASSERT(0); return FALSE; }

	return TRUE;
}

BOOL CCRCDataCtrl::Get_JtgBdcy(ElemPairK ElemK, T_BDCY_JTG& BdcyJtg, T_DETAIL_STR& RptInfo)
{
	BdcyJtg.Initialize();
	// Add by ZINU.('04.08.25). Check Calculating Item.
	if (!Is_CalcItem(ElemK, TRUE))  return FALSE;
	// Add by ZINU.('05.09.05).	PSC-Design/Strs(5), PSC-Design/Strn(6).
	int iDgnStatus = m_pDoc->GetDesignStatus();
	m_pDoc->SetDesignStatus(6);

	//ADGNFORCE aForceLcom;
	//if(!m_ForceCtrl.Get_LcomDataForDesign(ElemK, TRUE, FALSE, aForceLcom))	return FALSE;
	if (m_ForceCtrl.Get_LcomNumForStrn() == 0)	return FALSE;

	int iLcomNum = m_ForceCtrl.Get_LcomDataCount();
	double dTol = 1. / pow(m_dZero, 40);
	double dMyMax[2] = { -dTol,-dTol }, dMyMin[2] = { +dTol,+dTol };
	int iMaxDgnLcom[2] = { 0,0 }, iMinDgnLcom[2] = { 0,0 };
	int i = 0, j = 0;
	for (i = 0; i < iLcomNum; ++i)
	{
		int iSerialLcom = i + 1;
		if (!m_ForceCtrl.Is_LcomForStrn(i + 1))	continue;	// Only 종국시.
		_DGN_FORC_CRC ForceCrc;
		GetDesignForceResult()->GetForceLcomResult(ElemK, iSerialLcom, ForceCrc);
		for (j = 0; j < 2; ++j)	// I,J.
		{
			if (ForceCrc.dMuy[j] > dMyMax[j]) { dMyMax[j] = ForceCrc.dMuy[j]; iMaxDgnLcom[j] = i + 1; }
			if (ForceCrc.dMuy[j] < dMyMin[j]) { dMyMin[j] = ForceCrc.dMuy[j]; iMinDgnLcom[j] = i + 1; }
		}
	}
	for (i = 0; i < 4; ++i)
	{
		// 0=I-MAX, 1=I-MIN, 2=J-MAX, 3=J-MIN.
		int iDgnLcomNo = (i % 2 == 0 ? iMaxDgnLcom[i / 2] : iMinDgnLcom[i / 2]);
		CString strOrgLcomNa = _T("");
		int iMaxMinType = 0;
		if (!m_ForceCtrl.Get_LcomType(iDgnLcomNo, strOrgLcomNa, iMaxMinType))	ASSERT(0);
		double dMuy = (i % 2 == 0 ? dMyMax[i / 2] : dMyMin[i / 2]);

		BdcyJtg.BdcyBase[i].bCHK = Get_ChkFlag(ElemK, i / 2, TRUE);
		BdcyJtg.BdcyBase[i].LcomK = iDgnLcomNo;
		BdcyJtg.BdcyBase[i].iMax = iMaxMinType;
		BdcyJtg.BdcyBase[i].dMuy = dMuy;
		// Etc. From JTG D62-04.
	}

	if (m_iCivilCode == JTG_D62_04 || m_iCivilCode == CJJ_11_2011)
	{
		if (!m_pJTG_D62_04->Get_JtgBdcy(ElemK, BdcyJtg, RptInfo)) return FALSE;
		m_mapResultBDCY_JTG[ElemK] = BdcyJtg;
	}

	return TRUE;
}

BOOL CCRCDataCtrl::Get_JtgCums(ElemPairK ElemK, T_CUMS_JTG& CumsJtg, T_DETAIL_STR& RptInfo)
{
	CumsJtg.Initialize();
	if (!Is_CalcItem(ElemK, FALSE))  return FALSE;
	// Add by ZINU.('05.09.05).	PSC-Design/Strs(5), PSC-Design/Strn(6).
	int iDgnStatus = m_pDoc->GetDesignStatus();
	m_pDoc->SetDesignStatus(6);

	/*
	// Change by Jaeoh.('05.06.13)
	ADGNFORCE aForceLcom;
	ADGNFORCE aForceTnpr;
	//if(!m_ForceCtrl.Get_LcomDataForDesign(ElemK, FALSE, FALSE, aForceLcom))	return FALSE;
	if(!m_ForceCtrl.Get_LcomDataForDesign(ElemK, TRUE, FALSE, aForceLcom, aForceTnpr)) return FALSE;
	if(m_ForceCtrl.Get_LcomNumForStrn()==0)	return FALSE;
	if(aForceLcom.GetSize()!=aForceTnpr.GetSize()) return FALSE;
	*/
	if (m_ForceCtrl.Get_LcomNumForStrn() == 0)	return FALSE;

	int iLcomNum = m_ForceCtrl.Get_LcomDataCount();
	double dTol = 1. / pow(m_dZero, 40);
	double dFzMax[2] = { -dTol,-dTol }, dFzMin[2] = { +dTol,+dTol };
	double dFzMaxMy[2] = { 0,0 }, dFzMinMy[2] = { 0,0 };
	double dFzMaxMyTnpr[2] = { 0.,0. }, dFzMinMyTnpr[2] = { 0.,0. };
	int iMaxDgnLcom[2] = { 0,0 }, iMinDgnLcom[2] = { 0,0 };
	int i = 0, j = 0;
	for (i = 0; i < iLcomNum; ++i)
	{
		int iSerialLcom = i + 1;
		if (!m_ForceCtrl.Is_LcomForStrn(i + 1))	continue;	// Only 종국시.
		//
		_DGN_FORC_CRC ForceCrc;
		GetDesignForceResult()->GetForceLcomResult(ElemK, iSerialLcom, ForceCrc);
		//
		_DGN_FORC_CRC ForceTnpr;
		GetDesignForceResult()->GetForceTnprResult(ElemK, iSerialLcom, ForceTnpr);
		for (j = 0; j < 2; ++j)	// I,J.
		{
			if (ForceCrc.dFzz[j] > dFzMax[j])
			{
				dFzMax[j] = ForceCrc.dFzz[j];
				dFzMaxMy[j] = ForceCrc.dMuy[j];
				iMaxDgnLcom[j] = i + 1;

				dFzMaxMyTnpr[j] = ForceTnpr.dMuy[j];
			}
			if (ForceCrc.dFzz[j] < dFzMin[j])
			{
				dFzMin[j] = ForceCrc.dFzz[j];
				dFzMinMy[j] = ForceCrc.dMuy[j];
				iMinDgnLcom[j] = i + 1;

				dFzMinMyTnpr[j] = ForceTnpr.dMuy[j];
			}
		}
	}
	for (i = 0; i < 4; ++i)
	{
		// 0=I-MAX, 1=I-MIN, 2=J-MAX, 3=J-MIN.
		int iDgnLcomNo = (i % 2 == 0 ? iMaxDgnLcom[i / 2] : iMinDgnLcom[i / 2]);
		CString strOrgLcomNa = _T("");
		int iMaxMinType = 0;
		if (!m_ForceCtrl.Get_LcomType(iDgnLcomNo, strOrgLcomNa, iMaxMinType))	ASSERT(0);
		double dFzz = (i % 2 == 0 ? dFzMax[i / 2] : dFzMin[i / 2]);
		double dMuy = (i % 2 == 0 ? dFzMaxMy[i / 2] : dFzMinMy[i / 2]);
		double dMuyTnpr = (i % 2 == 0 ? dFzMaxMyTnpr[i / 2] : dFzMinMyTnpr[i / 2]);

		CumsJtg.CumsBase[i].bCHK = Get_ChkFlag(ElemK, i / 2, FALSE);
		CumsJtg.CumsBase[i].LcomK = iDgnLcomNo;
		CumsJtg.CumsBase[i].iMax = iMaxMinType;
		CumsJtg.CumsBase[i].dVu = dFzz;
		CumsJtg.CumsBase[i].dMu = dMuy;
		CumsJtg.CumsBase[i].dMu_P = dMuyTnpr;
		// Etc. From JTG-USD03.
	}
	if (m_iCivilCode == JTG_D62_04 || m_iCivilCode == CJJ_11_2011)
	{
		if (!m_pJTG_D62_04->Get_JtgCums(ElemK, CumsJtg, RptInfo)) return FALSE;
	}
	return TRUE;
}

BOOL CCRCDataCtrl::Get_JtgCrmt(ElemPairK ElemK, T_CRMT_JTG& CrmtJtg, T_DETAIL_STR& RptInfo)
{
	CrmtJtg.Initialize();
	// Add by ZINU.('04.08.25). Check Calculating Item.
	if (!Is_CalcItem(ElemK, FALSE))  return FALSE;
	// Add by ZINU.('05.09.05).	PSC-Design/Strs(5), PSC-Design/Strn(6).
	int iDgnStatus = m_pDoc->GetDesignStatus();
	m_pDoc->SetDesignStatus(6);

	/*
	// Change by Jaeoh.('05.06.13)
	ADGNFORCE aForceLcom;
	ADGNFORCE aForceTnpr;
	//if(!m_ForceCtrl.Get_LcomDataForDesign(ElemK, FALSE, FALSE, aForceLcom))	return FALSE;
	if(!m_ForceCtrl.Get_LcomDataForDesign(ElemK, TRUE, FALSE, aForceLcom, aForceTnpr)) return FALSE;
	if(m_ForceCtrl.Get_LcomNumForStrn()==0)	return FALSE;
	if(aForceLcom.GetSize()!=aForceTnpr.GetSize()) return FALSE;
	*/
	if (m_ForceCtrl.Get_LcomNumForStrn() == 0)	return FALSE;

	int iLcomNum = m_ForceCtrl.Get_LcomDataCount();
	double dTol = 1. / pow(m_dZero, 40);
	double dMxMaxT[2] = { 0.,0. }, dMxMaxV[2] = { 0.,0. };
	double dFzMaxT[2] = { 0.,0. }, dFzMaxV[2] = { -dTol,-dTol };
	double dFzMinT[2] = { 0.,0. }, dFzMinV[2] = { +dTol,+dTol };
	double dFzMaxMy[2] = { 0,0 }, dFzMinMy[2] = { 0,0 }, dMxMaxMy[2] = { 0.0 };
	double dFzMaxMyTnpr[2] = { 0,0 }, dFzMinMyTnpr[2] = { 0,0 }, dMxMaxMyTnpr[2] = { 0.0 };
	int iMxMaxDgnLcom[2] = { 0,0 }, iFzMaxDgnLcom[2] = { 0,0 }, iFzMinDgnLcom[2] = { 0,0 };
	int i = 0, j = 0;
	for (i = 0; i < iLcomNum; ++i)
	{
		int iSerialLcom = i + 1;
		if (!m_ForceCtrl.Is_LcomForStrn(i + 1))	continue;	// Only 종국시.
		//
		_DGN_FORC_CRC ForceCrc;
		GetDesignForceResult()->GetForceLcomResult(ElemK, iSerialLcom, ForceCrc);
		//
		_DGN_FORC_CRC ForceTnpr;
		GetDesignForceResult()->GetForceTnprResult(ElemK, iSerialLcom, ForceTnpr);

		for (j = 0; j < 2; ++j)	// I,J.
		{
			if (ForceCrc.dFzz[j] >= dFzMaxV[j])
			{
				dFzMaxT[j] = ForceCrc.dMux[j];
				dFzMaxV[j] = ForceCrc.dFzz[j];
				dFzMaxMy[j] = ForceCrc.dMuy[j];
				iFzMaxDgnLcom[j] = i + 1;

				dFzMaxMyTnpr[j] = ForceTnpr.dMuy[j];
			}
			if (ForceCrc.dFzz[j] <= dFzMinV[j])
			{
				dFzMinT[j] = ForceCrc.dMux[j];
				dFzMinV[j] = ForceCrc.dFzz[j];
				dFzMinMy[j] = ForceCrc.dMuy[j];
				iFzMinDgnLcom[j] = i + 1;

				dFzMinMyTnpr[j] = ForceTnpr.dMuy[j];
			}
			if (fabs(ForceCrc.dMux[j]) >= fabs(dMxMaxT[j]))
			{
				dMxMaxT[j] = ForceCrc.dMux[j];
				dMxMaxV[j] = ForceCrc.dFzz[j];
				dMxMaxMy[j] = ForceCrc.dMuy[j];
				iMxMaxDgnLcom[j] = i + 1;

				dMxMaxMyTnpr[j] = ForceTnpr.dMuy[j];
			}
		}
	}
	for (i = 0; i < 6; ++i)
	{
		// 0=I-V-MAX, 1=I-V-MIN, 2=I-T-MAX, 3=J-V-MAX, 4=J-V-MIN, 5=J-T-MAX.
		int iDgnLcomNo = 0;
		double dMux = 0.0, dFzz = 0.0, dMuy = 0.0, dMuyTnpr = 0.0;
		if (i % 3 == 0) { iDgnLcomNo = iFzMaxDgnLcom[i / 3]; dMux = dFzMaxT[i / 3]; dFzz = dFzMaxV[i / 3]; dMuy = dFzMaxMy[i / 3]; dMuyTnpr = dFzMaxMyTnpr[i / 3]; }
		else if (i % 3 == 1) { iDgnLcomNo = iFzMinDgnLcom[i / 3]; dMux = dFzMinT[i / 3]; dFzz = dFzMinV[i / 3]; dMuy = dFzMinMy[i / 3]; dMuyTnpr = dFzMinMyTnpr[i / 3]; }
		else if (i % 3 == 2) { iDgnLcomNo = iMxMaxDgnLcom[i / 3]; dMux = dMxMaxT[i / 3]; dFzz = dMxMaxV[i / 3]; dMuy = dMxMaxMy[i / 3]; dMuyTnpr = dMxMaxMyTnpr[i / 3]; }
		else	ASSERT(0);

		CString strOrgLcomNa = _T("");
		int iMaxMinType = 0;
		if (!m_ForceCtrl.Get_LcomType(iDgnLcomNo, strOrgLcomNa, iMaxMinType))	ASSERT(0);

		CrmtJtg.CrmtBase[i].bCHK = Get_ChkFlag(ElemK, i / 3, FALSE);
		CrmtJtg.CrmtBase[i].LcomK = iDgnLcomNo;
		CrmtJtg.CrmtBase[i].iMax = iMaxMinType;
		CrmtJtg.CrmtBase[i].dTu = dMux;
		CrmtJtg.CrmtBase[i].dVu = dFzz;
		CrmtJtg.CrmtBase[i].dMu = dMuy;
		CrmtJtg.CrmtBase[i].dMu_P = dMuyTnpr;
	}
	if (m_iCivilCode == JTG_D62_04 || m_iCivilCode == CJJ_11_2011)
	{
		if (!m_pJTG_D62_04->Get_JtgCrmt(ElemK, CrmtJtg, RptInfo)) return FALSE;
	}
	return TRUE;
}

/************************************************************************/
/*compressive stress check at service stage.예箕駱炬 JTG D62-04 5.3     */
/************************************************************************/
BOOL CCRCDataCtrl::Get_JtgCscs(ElemPairK ElemK, T_CSTCS_CH& CscsJtg, T_DETAIL_STR& RptInfo)
{
	CscsJtg.Initialize();
	// Check Calculating Item.
	if (!Is_CalcItem(ElemK, FALSE))  return FALSE;
	// Add by ZINU.('05.09.05).	PSC-Design/Strs(5), PSC-Design/Strn(6).
	int iDgnStatus = m_pDoc->GetDesignStatus();
	m_pDoc->SetDesignStatus(6);

	//get force
	if (m_ForceCtrl.Get_LcomNumForStrn() == 0)	return FALSE;
	int iLcomNum = m_ForceCtrl.Get_LcomDataCount();
	double dTol = 1. / pow(m_dZero, 40);
	double dMyMax[2] = { -dTol,-dTol }, dMyMin[2] = { +dTol,+dTol }, dMyMaxN[2] = { 0.0,0.0 }, dMyMinN[2] = { 0.0,0.0 };
	double dNxMax[2] = { -dTol,-dTol }, dNxMaxMy[2] = { 0.0,0.0 }, dNxMaxMz[2] = { 0.0,0.0 };
	double dNxMin[2] = { +dTol,+dTol }, dNxMinMy[2] = { 0.0,0.0 }, dNxMinMz[2] = { 0.0,0.0 };
	int iMyMaxDgnLcom[2] = { 0,0 }, iMyMinDgnLcom[2] = { 0,0 }, iNxMaxDgnLcom[2] = { 0,0 }, iNxMinDgnLcom[2] = { 0,0 };

	int i = 0, j = 0;
	for (i = 0; i < iLcomNum; ++i)
	{
		int iSerialLcom = i + 1;
		if (!m_ForceCtrl.Is_LcomForStrn(i + 1))	continue;	// Only 종국시.

		_DGN_FORC_CRC ForceCrc;//
		GetDesignForceResult()->GetForceLcomResult(ElemK, iSerialLcom, ForceCrc);

		for (j = 0; j < 2; ++j)	// I,J.
		{
			if (ForceCrc.dMuy[j] > dMyMax[j]) {
				dMyMax[j] = ForceCrc.dMuy[j]; dMyMaxN[j] = ForceCrc.dFxx[j];
				iMyMaxDgnLcom[j] = i + 1;
			}
			if (ForceCrc.dMuy[j] < dMyMin[j]) {
				dMyMin[j] = ForceCrc.dMuy[j]; dMyMinN[j] = ForceCrc.dFxx[j];
				iMyMinDgnLcom[j] = i + 1;
			}
			if (ForceCrc.dFxx[j] > dNxMax[j]) {
				dNxMax[j] = ForceCrc.dFxx[j]; dNxMaxMy[j] = ForceCrc.dMuy[j];
				dNxMaxMz[j] = ForceCrc.dMuz[j];  iNxMaxDgnLcom[j] = i + 1;
			}
			if (ForceCrc.dFxx[j] < dNxMin[j]) {
				dNxMin[j] = ForceCrc.dFxx[j]; dNxMinMy[j] = ForceCrc.dMuy[j];
				dNxMinMz[j] = ForceCrc.dMuz[j];  iNxMinDgnLcom[j] = i + 1;
			}
		}
	}
	for (i = 0; i < 10; ++i)
	{
		// 0=I-V-MAX, 1=I-V-MIN, 2=I-T-MAX, 3=J-V-MAX, 4=J-V-MIN, 5=J-T-MAX.
		int iDgnLcomNo = 0, iMax = 0;
		double dNd = 0.0, dMd = 0.0;
		if (i % 5 == 0) { dNd = dNxMin[i / 5]; iDgnLcomNo = iNxMinDgnLcom[i / 5]; iMax = 2; }//2:Fx-Min; 
		if (i % 5 == 1) { dNd = dNxMin[i / 5]; iDgnLcomNo = iNxMinDgnLcom[i / 5]; iMax = 2; dMd = dNxMinMy[i / 5]; }//2:Fx-Min;
		if (i % 5 == 2) { dNd = dNxMin[i / 5]; iDgnLcomNo = iNxMinDgnLcom[i / 5]; iMax = 2; dMd = dNxMinMz[i / 5]; }//2:Fx-Min; 
		if (i % 5 == 3) { dMd = dMyMax[i / 5]; iDgnLcomNo = iMyMaxDgnLcom[i / 5]; iMax = 9; dNd = dMyMaxN[i / 5]; }//9:My-max
		if (i % 5 == 4) { dMd = dMyMin[i / 5]; iDgnLcomNo = iMyMinDgnLcom[i / 5]; iMax = 10; dNd = dMyMinN[i / 5]; }//10:My-min

		CscsJtg.cstcsBase[i].bCHK = Get_ChkFlag(ElemK, i / 5, TRUE);
		CscsJtg.cstcsBase[i].LcomK = iDgnLcomNo;
		CscsJtg.cstcsBase[i].iMax = iMax;
		CscsJtg.cstcsBase[i].dNd = -dNd;//
		CscsJtg.cstcsBase[i].dMd = dMd;
	}
	if (m_iCivilCode == JTG_D62_04 || m_iCivilCode == CJJ_11_2011)
	{
		if (!m_pJTG_D62_04->Get_JtgCscs(ElemK, CscsJtg, RptInfo)) return FALSE;
	}
	return TRUE;
}
//get print option of JTG design
//PrintItem: 0(M) 1(shear) 2(torsion) 3(rebarsM)
BOOL CCRCDataCtrl::Get_JtgRptOption(ElemPairK ElemK, int iPosi, int PrintItem)
{
	T_POSX_D PosxD;  PosxD.Initialize();
	if (ElemK.first == EN_EL_BEAM)
	{
		if (!m_pAttrCtrl->GetPosx(ElemK.first, PosxD))	return  FALSE;	// Default.
	}
	else if (ElemK.first == EN_EL_VBEAM)
	{		
		if (!m_pAttrCtrl->GetPosx(ElemK.first, PosxD))	return  FALSE;	// Default.
	}
	else ASSERT(0);
	
	if (PrintItem == 0)// M 
	{
		if (PosxD.iMomChk[0] == 1 && iPosi == 0)	return TRUE;//M+ I
		if (PosxD.iMomChk[0] == 2 && iPosi == 1)	return TRUE;//M+ J
		if (PosxD.iMomChk[0] == 3)           	return TRUE;//M+ IJ
		if (PosxD.iMomChk[1] == 1 && iPosi == 0)	return TRUE;//M- I
		if (PosxD.iMomChk[1] == 2 && iPosi == 1)	return TRUE;//M- J
		if (PosxD.iMomChk[1] == 3)           	return TRUE;//M- IJ
		return FALSE;
	}
	else if (PrintItem == 1) {//shear
		if (PosxD.iShrChk == 0)									return FALSE;
		else if (PosxD.iShrChk == 1 && iPosi == 1)	return FALSE;
		else if (PosxD.iShrChk == 2 && iPosi == 0)	return FALSE;
		else	return TRUE;
	}
	else if (PrintItem == 2) {//torsion
		if (PosxD.iTorChk == 0)									return FALSE;
		else if (PosxD.iTorChk == 1 && iPosi == 1)	return FALSE;
		else if (PosxD.iTorChk == 2 && iPosi == 0)	return FALSE;
		else	return TRUE;
	}
	else if (PrintItem == 3) {//rebars
		if (PosxD.iBarChk[0] == 1 && iPosi == 0)	return TRUE;//rebarsM+ I
		if (PosxD.iBarChk[0] == 2 && iPosi == 1)	return TRUE;//rebarsM+ J
		if (PosxD.iBarChk[0] == 3)           	return TRUE;//rebarsM+ IJ
		if (PosxD.iBarChk[1] == 1 && iPosi == 0)	return TRUE;//rebarsM- I
		if (PosxD.iBarChk[1] == 2 && iPosi == 1)	return TRUE;//rebarsM- J
		if (PosxD.iBarChk[1] == 3)           	return TRUE;//rebarsM- IJ
		else	return FALSE;
	}
	else return FALSE;
}
//PrintItem: 0(M) 1(shear) 2(torsion) 3(rebarsM)
BOOL CCRCDataCtrl::Get_JtgRptOption(ElemPairK ElemK, int PrintItem)
{
	return (Get_JtgRptOption(ElemK, 0, PrintItem) || Get_JtgRptOption(ElemK, 1, PrintItem));
}
