			FpmsBIRC.dFP8 = ShrsD.dSsp[nIx][7];
			FpmsBIRC.dFP9 = ShrsD.dSsp[nIx][8];
			FpmsBIRC.dFP10 = ShrsD.dSsp[nIx][9];
