BOOL CCRCDataCtrl::Get_BdcwDataPSC(ElemPairK ElemK, PSC_DATA_MEMB &MembInD, T_BDCW_PSC_IRC& rData)
{
	rData.Initialize();
	// Add by ZINU.('04.08.25). Check Calculating Item.
	if (!Is_CalcItem(ElemK, TRUE))  return FALSE;
	// Add by ZINU.('05.09.05).	PSC-Design/Strs(5), PSC-Design/Strn(6).
	int iDgnStatus = m_pDoc->GetDesignStatus();
	m_pDoc->SetDesignStatus(6);

	int i = 0, j = 0;
	double dMyMax[2] = { 0.,0. }, dMyMin[2] = { 0.,0. };
	int iMaxDgnLcom[2] = { 0,0 }, iMinDgnLcom[2] = { 0,0 };
	double dMaxRat[4] = { 0.0 }, dMaxRat_zero[4] = { 0.0 };;
	int iCheckCount[4] = { 0 }, iCheckCount_zero[4] = { 0 };

	BOOL bChkI = Get_ChkFlag(ElemK, 0, TRUE);
	BOOL bChkJ = Get_ChkFlag(ElemK, 1, TRUE);

	T_BDCW_PSC_IRC BdcwD;
	if (CDBLib::IsPscCodeLSD(m_iCivilCode) || CDBLib::IsPscCodeCSA(m_iCivilCode) || m_iCivilCode == IRC_112_2011_PSC || m_iCivilCode == IRS_PSC ||
		m_iCivilCode == IRC_112_2020_PSC)
	{
		int iLcomNum = m_ForceCtrl.Get_LcomDataCount();
		ADGNFORCE aForceLcom;
		if (!m_ForceCtrl.Get_LcomDataForDesign(ElemK, 0, TRUE, FALSE, aForceLcom, iLcomNum))	return FALSE;

		ADGNSTRESS aStressLcom;
		ADGNSTRESS aStressTnpr;
		if (!m_ForceCtrl.Get_LcomDataForStress(ElemK, 0, TRUE, FALSE, aStressLcom, aStressTnpr, iLcomNum)) return FALSE;

		// 전체하중조합을 검토한다.
		int iLcomSize = aForceLcom.GetSize();
		int nStressLcomSize = aStressLcom.GetSize();
		for (i = 0; i < iLcomSize; ++i)
		{
			if (!m_ForceCtrl.Is_LcomForStrs(i + 1))	continue;
			_DGN_FORC_CRC &ForceD = aForceLcom[i];
			_DGN_STRS_CRC &StressD = aStressLcom[i];
			BdcwD.Initialize();

			PSC_BDCW_D BdcwResD;
			int iDgnLcomNo = i + 1;
			CString strOrgLcomNa = _T("");
			int iMaxMinType = 0;
			if (!m_ForceCtrl.Get_LcomType(iDgnLcomNo, strOrgLcomNa, iMaxMinType))	ASSERT(0);

			//  (iKind== 1) (_T("사용하중I"));      - Quasi-permanant
			//  (iKind== 2) (_T("사용하중III/VI")); - Frequent
			//  (iKind== 3) (_T("지속하중"));       - Characteristic
			int iKind = m_ForceCtrl.Get_ServLcomType(iDgnLcomNo);
			if (m_iCivilCode == EUROCODE2_2_05_PSC || m_iCivilCode == IRS_PSC || m_iCivilCode == ABNT_NBR_6118_2023_PSC)
			{
				if (iKind < 1 || iKind >2) continue;
			}
			else if (CDBLib::IsPscCodeLSD_KR(m_iCivilCode))
			{
				if (iKind < 1 || iKind >3) continue;
			}
			else if (m_iCivilCode == IRC_112_2011_PSC || m_iCivilCode == IRC_112_2020_PSC)
			{
				if (iKind != 2) continue; //Check only for Frequent Load COmbinations IRC112 PSC
			}
			else ASSERT(0);

			for (j = 0; j < 4; ++j)
			{
				double dMuy = (j < 2 ? ForceD.dMuy[0] : ForceD.dMuy[1]);
				double dFxx = (j < 2 ? ForceD.dFxx[0] : ForceD.dFxx[1]);
				double dft = (j < 2 ? StressD.dStop[0] : StressD.dStop[1]);
				double dfb = (j < 2 ? StressD.dSbot[0] : StressD.dSbot[1]);
				//if(j%2==1) { dMuy = ( dMuy<0.0 ? 0.0 : dMuy ); } // negative면 Top검토 
				//else       { dMuy = ( dMuy>0.0 ? 0.0 : dMuy ); }

				T_BDCW_PSC_BASE_IRC &BdcwB = BdcwD.BdcwBase[j];
				BdcwB.bCHK = (j / 2 == 0) ? bChkI : bChkJ;
				BdcwB.LcomK = iDgnLcomNo;
				BdcwB.iKind = iKind;
				BdcwB.iLSTerm = m_ForceCtrl.Get_LcomKind(iDgnLcomNo);
				BdcwB.iMax = iMaxMinType;
				BdcwB.dPu = dFxx;
				BdcwB.dMu = dMuy;
				BdcwB.dft = dft;
				BdcwB.dfb = dfb;

				if (CDBLib::IsPscCodeLSD(m_iCivilCode) || m_iCivilCode == IRC_112_2011_PSC || m_iCivilCode == IRS_PSC ||
					m_iCivilCode == IRC_112_2020_PSC)
				{
					T_BDCW_PSC_BASE_IRC &BdcwZeroB = BdcwD.BdcwBaseZero[j];
					BdcwZeroB.bCHK = (j / 2 == 0) ? bChkI : bChkJ;
					BdcwZeroB.LcomK = iDgnLcomNo;
					BdcwZeroB.iKind = iKind;
					BdcwZeroB.iLSTerm = m_ForceCtrl.Get_LcomKind(iDgnLcomNo);
					BdcwZeroB.iMax = iMaxMinType;
					BdcwZeroB.dPu = dFxx;
					BdcwZeroB.dMu = dMuy;
					BdcwZeroB.dft = dft;
					BdcwZeroB.dfb = dfb;
				}
			}
			//
			if (!m_pPscDataCtrl->Get_BdcwData(ElemK, MembInD, BdcwD, BdcwResD)) continue; //return FALSE;

			// 균열
			for (j = 0; j < 4; ++j)
			{
				T_BDCW_PSC_BASE_IRC &BdcwBaseD = BdcwD.BdcwBase[j];
				if (BdcwBaseD.bCHK && BdcwBaseD.bOK_Cr) iCheckCount[j] += 1;
				else continue;

				if (iCheckCount[j] == 1)
				{
					dMaxRat[j] = BdcwBaseD.dRatio;
					rData.BdcwBase[j] = BdcwBaseD;
				}
				else if (iCheckCount[j] > 1)
				{
					if (dMaxRat[j] < BdcwBaseD.dRatio)
					{
						dMaxRat[j] = BdcwBaseD.dRatio;
						rData.BdcwBase[j] = BdcwBaseD;
					}
				}
			}

			// 영응력
			if (CDBLib::IsPscCodeLSD(m_iCivilCode) || m_iCivilCode == IRC_112_2011_PSC || m_iCivilCode == IRS_PSC ||
				m_iCivilCode == IRC_112_2020_PSC)
			{
				for (j = 0; j < 4; ++j)
				{
					T_BDCW_PSC_BASE_IRC &BdcwBaseD = BdcwD.BdcwBaseZero[j];
					if (iCheckCount_zero[j] == 0) // 기본적인 값 채윰
					{
						dMaxRat_zero[j] = BdcwBaseD.dRatio;
						rData.BdcwBaseZero[j] = BdcwBaseD;
					}
					if (BdcwBaseD.bOk_Zero) iCheckCount_zero[j] += 1;
					else continue;

					if (iCheckCount_zero[j] == 1)
					{
						dMaxRat_zero[j] = BdcwBaseD.dRatio;
						rData.BdcwBaseZero[j] = BdcwBaseD;
					}
					else if (iCheckCount_zero[j] > 1)
					{
						if (dMaxRat_zero[j] < BdcwBaseD.dRatio)
						{
							dMaxRat_zero[j] = BdcwBaseD.dRatio;
							rData.BdcwBaseZero[j] = BdcwBaseD;
						}
					}
				}
			}
		} // Lcom
	}
	else
	{
		// 필요한 Force Max/Min 값을 찾음.
		BOOL bStrength = FALSE;
		if (!Get_CheckForceMu_MaxMin(bStrength, ElemK, dMyMax, dMyMin, iMaxDgnLcom, iMinDgnLcom)) return FALSE;

		// Set Data.
		for (i = 0; i < 4; ++i)
		{
			// 0=I-TOP_MAX, 1=I-BOT_MAX, 2=J-TOP_MAX, 3=J-BOT_MAX.
			// 0=I-MAX, 1=I-MIN, 2=J-MAX, 3=J-MIN.
			int iDgnLcomNo = (i % 2 == 1 ? iMaxDgnLcom[i / 2] : iMinDgnLcom[i / 2]); // negative면 Top검토
			CString strOrgLcomNa = _T("");
			int iMaxMinType = 0;
			if (!m_ForceCtrl.Get_LcomType(iDgnLcomNo, strOrgLcomNa, iMaxMinType))	ASSERT(0);
			double dMuy = (i % 2 == 1 ? dMyMax[i / 2] : dMyMin[i / 2]);
			if (i % 2 == 1) { dMuy = (dMuy < 0.0 ? 0.0 : dMuy); } // negative면 Top검토 
			else { dMuy = (dMuy > 0.0 ? 0.0 : dMuy); }

			T_BDCW_PSC_BASE_IRC &BdcwB = rData.BdcwBase[j];
			BdcwB.bCHK = (i / 2 == 0) ? bChkI : bChkJ;
			BdcwB.LcomK = iDgnLcomNo;
			BdcwB.iKind = m_ForceCtrl.Get_ServLcomType(iDgnLcomNo);
			BdcwB.iLSTerm = m_ForceCtrl.Get_LcomKind(iDgnLcomNo);
			BdcwB.iMax = iMaxMinType;
			BdcwB.dMu = dMuy;
			//rData.BdcwBase[i].dFT		= StrsCrc.dStop[i/2];
			//rData.BdcwBase[i].dFB		= StrsCrc.dSbot[i/2];
		}

		PSC_BDCW_D BdcwResD;
		if (m_iCivilCode == BS5400_90_PSC|| m_iCivilCode == TMH07_3_1989)
		{
			if (!m_pPscDataCtrl->Get_BdcwData(ElemK, MembInD, rData, BdcwResD)) return FALSE;
		}
		else ASSERT(0);
	}

	return TRUE;
}

BOOL CCRCDataCtrl::Get_FatgDataPSC(ElemPairK ElemK, PSC_DATA_MEMB &MembInD, T_FATG_PSC_IRC& rData)
{
	rData.Initialize();
	// Add by ZINU.('04.08.25). Check Calculating Item.
	if (!Is_CalcItem(ElemK, TRUE))  return FALSE;
	// Add by ZINU.('05.09.05).	PSC-Design/Strs(5), PSC-Design/Strn(6).
	int iDgnStatus = m_pDoc->GetDesignStatus();
	m_pDoc->SetDesignStatus(6);

	// max : + 값이 가장 큰것, mon : -값이 가장 큰것
	double dSigLcom_max_t[2] = { 0.0 };  // I/J
	double dSigLcom_min_t[2] = { 0.0 };
	double dSigLcom_max_b[2] = { 0.0 };
	double dSigLcom_min_b[2] = { 0.0 };
	double dVuLcom_max[2] = { 0.0 };
	double dVuLcom_min[2] = { 0.0 };

	//OrgLcomNum
	int nMaxSigLcom_t[2] = { 0 };
	int nMaxSigLcom_b[2] = { 0 };
	int nMaxVuLcom[2] = { 0 };

	BOOL bChkI = Get_ChkFlag(ElemK, 0, TRUE);
	BOOL bChkJ = Get_ChkFlag(ElemK, 1, TRUE);

	BOOL bStrengh = FALSE;
	Get_CheckSigma_MaxMin_FatgPsc(bStrengh, ElemK, dSigLcom_max_t, dSigLcom_min_t, nMaxSigLcom_t,
		dSigLcom_max_b, dSigLcom_min_b, nMaxSigLcom_b,
		dVuLcom_max, dVuLcom_min, nMaxVuLcom);

	// (- 압축 + 인장) => (+ 압축 - 인장)변환

	for (int nIJ = 0; nIJ < 2; ++nIJ)
	{
		dSigLcom_max_t[nIJ] *= 1.0;  // I/J
		dSigLcom_min_t[nIJ] *= 1.0;
		dSigLcom_max_b[nIJ] *= 1.0;
		dSigLcom_min_b[nIJ] *= 1.0;
	}

	BOOL bCompositeElem = m_pDoc->m_pPostCtrl->IsElem4CompositePSCSect(ElemK);

	T_CUMS_PSC_IRC       CumsD;	     CumsD.Initialize();
	T_CUMS_PSC_COMP  CumsDComp;	 CumsDComp.Initialize();

	double dVc[4] = { 0.0 };
	if (bCompositeElem)
	{
		if (!m_pDoc->m_pPostCtrl->GetPCDesign()->ReadCums_PSC_Comp(ElemK, CumsDComp))
		{
			CumsDComp.Initialize();
		}

		for (int i = 0; i < 4; i++) 	dVc[i] = CumsDComp.CumsBase[i].dVc;
	}
	else
	{
		if (!m_pDoc->m_pPostCtrl->GetPCDesign()->ReadCums_PSC(ElemK, CumsD))
		{
			CumsD.Initialize();
		}

		for (int i = 0; i < 4; i++) 	dVc[i] = CumsDComp.CumsBase[i].dVc;
	}

	// Set Data.
	for (int i = 0; i < 4; ++i)
	{
		// 0=I-TOP, 1=I-BOT, 2=J-TOP, 3=J-BOT

		int nIJ = (i < 2) ? 0 : 1;   // 0 :I  1:J
		int nTB = (i % 2 == 1) ? 0 : 1;   // 0 :Top  1:Bottom

		T_FATG_PSC_BASE_IRC &FatgB = rData.FatgBase[i];
		FatgB.bCHK = (nIJ == 0) ? bChkI : bChkJ;

		FatgB.LcomK1 = (nTB == 0) ? nMaxSigLcom_t[nIJ] : nMaxSigLcom_b[nIJ];
		FatgB.dSigLcom_max = (nTB == 0) ? dSigLcom_max_t[nIJ] : dSigLcom_max_b[nIJ];
		FatgB.dSigLcom_min = (nTB == 0) ? dSigLcom_min_t[nIJ] : dSigLcom_min_b[nIJ];

		FatgB.LcomK2 = nMaxVuLcom[nIJ];
		FatgB.dVuLcom_max = dVuLcom_max[nIJ];
		FatgB.dVuLcom_min = dVuLcom_min[nIJ];
		FatgB.dVc = dVc[i];
	}

	if (!m_pPscDataCtrl->Get_FatgData(ElemK, MembInD, rData)) return FALSE;

	return TRUE;
}

BOOL CCRCDataCtrl::Get_BdcrDataPSC(ElemPairK ElemK, PSC_DATA_MEMB &MembInD, T_BDCR_PSC_IRC& rData)
{
	rData.Initialize();
	// Add by ZINU.('04.08.25). Check Calculating Item.
	if (!Is_CalcItem(ElemK, TRUE))  return FALSE;
	// Add by ZINU.('05.09.05).	PSC-Design/Strs(5), PSC-Design/Strn(6).
	int iDgnStatus = m_pDoc->GetDesignStatus();
	m_pDoc->SetDesignStatus(6);

	BOOL bComposite = IsCompositePSCSect(ElemK);

	int i;
	double dMyMax[2] = { 0.,0. }, dMyMin[2] = { 0.,0. };
	int iMaxDgnLcom[2] = { 0,0 }, iMinDgnLcom[2] = { 0,0 };

	// 필요한 Force Max/Min 값을 찾음.
	BOOL bStrength = TRUE;
	if (!Get_CheckForceMu_MaxMin(bStrength, ElemK, dMyMax, dMyMin, iMaxDgnLcom, iMinDgnLcom)) return FALSE;

	for (i = 0; i < 4; ++i)
	{
		int nIx = i / 2;
		// 0=I-MAX, 1=I-MIN, 2=J-MAX, 3=J-MIN.
		int iDgnLcomNo = (i % 2 == 0 ? iMaxDgnLcom[nIx] : iMinDgnLcom[nIx]);
		CString strOrgLcomNa = _T("");
		int iMaxMinType = 0;
		if (!m_ForceCtrl.Get_LcomType(iDgnLcomNo, strOrgLcomNa, iMaxMinType))	ASSERT(0);
		double dMuy = (i % 2 == 0 ? dMyMax[nIx] : dMyMin[nIx]);
		if (i % 2 == 0) { dMuy = (dMuy < 0.0 ? 0.0 : dMuy); }
		else { dMuy = (dMuy > 0.0 ? 0.0 : dMuy); }

		T_BDCR_PSC_BASE_IRC &BdcrB = rData.BdcrBase[i];
		BdcrB.bCHK = Get_ChkFlag(ElemK, nIx, TRUE);
		BdcrB.LcomK = iDgnLcomNo;
		BdcrB.iKind = m_ForceCtrl.Get_LcomKind(iDgnLcomNo);
		BdcrB.iMax = iMaxMinType;
		BdcrB.dMu = dMuy;
	}

	if (CDBLib::IsPscCodeLSD(m_iCivilCode) || m_iCivilCode == BS5400_90_PSC || m_iCivilCode == TMH07_3_1989 || m_iCivilCode == IRC_112_2011_PSC || m_iCivilCode == IRS_PSC ||
		m_iCivilCode == IRC_112_2020_PSC)
	{
		if (!m_pPscDataCtrl->Get_BdcrData(ElemK, MembInD, rData)) return FALSE;
	}
	else ASSERT(0);

	CString sBendingErrMsg = _T("");
	for (i = 0; i < 4; ++i)
	{
		if (rData.BdcrBase[i].bCHK)
		{
			CString strIJ = i < 2 ? _T("I") : _T("J");
			if (rData.BdcrBase[i].bOK == D_PSC_FRC_ERR_Iteration_Over)
			{
				CString strPN = i % 2 == 0 ? _T("P") : _T("N"); // Positive/Negative
				CString strPosi;
				strPosi.Format(_T("%d-%s(%s)"), ElemK, strIJ, strPN);
				sBendingErrMsg.Format(_LS(IDS_DGN_WARN_BEND_NEUTRAL_AXIS_Err), strPosi); // [Warning] Midas Civil has failed to find the neutral axis(member no.: xxxx). Please check the PSC Design Calculation sheet for details.
				GSaveHistoryFormatNF(sBendingErrMsg);
			}
		}
	}

	return TRUE;
}

BOOL CCRCDataCtrl::Get_CumsDataPSC(ElemPairK ElemK, PSC_DATA_MEMB &MembInD, T_CUMS_PSC_IRC& rData)
{
	rData.Initialize();
	// Add by ZINU.('04.08.25). Check Calculating Item.
	if (!Is_CalcItem(ElemK, FALSE))  return FALSE;
	// Add by ZINU.('05.09.05).	PSC-Design/Strs(5), PSC-Design/Strn(6).
	int iDgnStatus = m_pDoc->GetDesignStatus();
	m_pDoc->SetDesignStatus(6);

	_DGN_FORC_CRC ForceFzMaxD;
	_DGN_FORC_CRC ForceFzMinD;
	_DGN_STRS_CRC StressFzMaxD;
	_DGN_STRS_CRC StressFzMinD;

	double dFzMax[2] = { 0,0 }, dFzMin[2] = { 0,0 };
	double dFzMaxMy[2] = { 0,0 }, dFzMinMy[2] = { 0,0 };
	double dFzMaxFx[2] = { 0,0 }, dFzMinFx[2] = { 0,0 };
	int iMaxDgnLcom[2] = { 0,0 }, iMinDgnLcom[2] = { 0,0 };
	int i = 0;

	//////////////////////////////////////////////////////////////////////////  
	double dFx_TP[2] = { 0.0, 0.0 };
	double dFz_TP[2] = { 0.0, 0.0 };
	double dft_TP[2] = { 0.0, 0.0 };
	double dfb_TP[2] = { 0.0, 0.0 };
	BOOL bExistStage = m_pDoc->m_pStagCtrl->ExistStag();
	if (bExistStage)
	{
		CString strTP = _LS(IDS_DB_SGLD_TP);
		T_SGLD_K SgldTempK = m_pAttrCtrl->GetSgldKey(strTP);
		T_STEP_K StepK = 0;
		T_LCOM_D LcasD;
		T_STRB_D StrbMax; StrbMax.Initialize();
		m_pPostCtrl->MakeLoadComb(D_LOADCASE_STAGE, SgldTempK, LcasD);
		m_pPostCtrl->SelectLoadCombNew(LcasD, StepK, 2);	// 0=Nonlinear, 1=Pushover, 2=Consruction.	  
		m_pPostCtrl->GetStrbNew(ElemK.first, &StrbMax, NULL, NULL, FALSE, NULL, ElemK.second);
		dFx_TP[0] = StrbMax.dblForce[0][0];
		dFx_TP[1] = StrbMax.dblForce[3][6];
		dFz_TP[0] = StrbMax.dblForce[0][2];
		dFz_TP[1] = StrbMax.dblForce[3][8];
		// MQC 11614 이대근 이사보님 요청, fb 계산할 때 Tendon primary 응력 포함
		dft_TP[0] = StrbMax.dblStress[0][0] + StrbMax.dblStress[0][5];
		dft_TP[1] = StrbMax.dblStress[3][7] + StrbMax.dblStress[3][12];
		dfb_TP[0] = StrbMax.dblStress[0][0] + StrbMax.dblStress[0][6];
		dfb_TP[1] = StrbMax.dblStress[3][7] + StrbMax.dblStress[3][13];
	}
	//////////////////////////////////////////////////////////////////////////  
	if (CDBLib::IsPscCodeLSD_KR(m_iCivilCode))
	{
		if (!Get_CumsForceFz_MaxMin_LSD(ElemK, ForceFzMaxD, ForceFzMinD, StressFzMaxD, StressFzMinD, iMaxDgnLcom, iMinDgnLcom)) return FALSE;
	}
	else
	{
		if (!Get_CumsForceFz_MaxMin(ElemK, ForceFzMaxD, ForceFzMinD, StressFzMaxD, StressFzMinD, iMaxDgnLcom, iMinDgnLcom)) return FALSE;
	}

	for (i = 0; i < 2; ++i)
	{
		dFzMax[i] = ForceFzMaxD.dFzz[i];
		dFzMaxMy[i] = ForceFzMaxD.dMuy[i];
		dFzMaxFx[i] = ForceFzMaxD.dFxx[i];
		//
		dFzMin[i] = ForceFzMinD.dFzz[i];
		dFzMinMy[i] = ForceFzMinD.dMuy[i];
		dFzMinFx[i] = ForceFzMinD.dFxx[i];
	}

	double adMr[4] = { 0.0 };
	T_BDCR_PSC_IRC BdcrD;
	m_pPostCtrl->GetPCDesign()->ReadBdcr_PSC(ElemK, BdcrD);

	for (i = 0; i < 4; ++i)
	{
		int nIx = i / 2;
		// 0=I-MAX, 1=I-MIN, 2=J-MAX, 3=J-MIN.
		int iDgnLcomNo = (i % 2 == 0 ? iMaxDgnLcom[nIx] : iMinDgnLcom[nIx]);
		CString strOrgLcomNa = _T("");
		int iMaxMinType = 0;
		if (!m_ForceCtrl.Get_LcomType(iDgnLcomNo, strOrgLcomNa, iMaxMinType))	ASSERT(0);
		double dFzz = (i % 2 == 0 ? dFzMax[nIx] : dFzMin[nIx]);
		double dMuy = (i % 2 == 0 ? dFzMaxMy[nIx] : dFzMinMy[nIx]);
		double dFxx = (i % 2 == 0 ? dFzMaxFx[nIx] + dFx_TP[nIx] : dFzMinFx[nIx] + dFx_TP[nIx]);
		double dft = (i % 2 == 0 ? StressFzMaxD.dStop[nIx] + dft_TP[nIx] : StressFzMinD.dStop[nIx] + dft_TP[nIx]);
		double dfb = (i % 2 == 0 ? StressFzMaxD.dSbot[nIx] + dfb_TP[nIx] : StressFzMinD.dSbot[nIx] + dfb_TP[nIx]);

		T_CUMS_PSC_BASE_IRC &CumsB = rData.CumsBase[i];
		CumsB.bCHK = Get_ChkFlag(ElemK, i / 2, FALSE);
		CumsB.LcomK = iDgnLcomNo;
		CumsB.iKind = m_ForceCtrl.Get_LcomKind(iDgnLcomNo);
		CumsB.iMax = iMaxMinType;
		CumsB.dPu = dFxx;
		CumsB.dVu = GetVu4TpEx(dFzz, dFz_TP[nIx]);
		CumsB.dVp = dFz_TP[nIx];
		CumsB.dMu = dMuy;
		CumsB.dft = dft;
		CumsB.dfb = dfb;

		if (i < 2)
		{
			adMr[i] = (dMuy < 0.0) ? BdcrD.BdcrBase[1].dphiMn : BdcrD.BdcrBase[0].dphiMn;
		}
		else
		{
			adMr[i] = (dMuy < 0.0) ? BdcrD.BdcrBase[3].dphiMn : BdcrD.BdcrBase[2].dphiMn;
		}
	}

	if (CDBLib::IsPscCodeLSD(m_iCivilCode) || m_iCivilCode == BS5400_90_PSC || m_iCivilCode == TMH07_3_1989 || m_iCivilCode == IRC_112_2011_PSC || m_iCivilCode == IRS_PSC ||
		m_iCivilCode == IRC_112_2020_PSC)
	{
		if (!m_pPscDataCtrl->Get_CumsData(ElemK, MembInD, adMr, rData)) return FALSE;
	}
	else ASSERT(0);

	return TRUE;
}

BOOL CCRCDataCtrl::Get_CrmtDataPSC(ElemPairK ElemK, PSC_DATA_MEMB &MembInD, T_CRMT_PSC_IRC& rData)
{
	rData.Initialize();
	// Add by ZINU.('04.08.25). Check Calculating Item.
	if (!Is_CalcItem(ElemK, FALSE))  return FALSE;
	// Add by ZINU.('05.09.05).	PSC-Design/Strs(5), PSC-Design/Strn(6).
	int iDgnStatus = m_pDoc->GetDesignStatus();
	m_pDoc->SetDesignStatus(6);

	//////////////////////////////////////////////////////////////////////////  
	double dFx_TP_I = 0.0, dFx_TP_J = 0.0;
	double dFz_TP_I = 0.0, dFz_TP_J = 0.0;
	double dft_TP_I = 0.0, dfb_TP_I = 0.0;
	double dft_TP_J = 0.0, dfb_TP_J = 0.0;
	BOOL bExistStage = m_pDoc->m_pStagCtrl->ExistStag();
	if (bExistStage)
	{
		CString strTP = _LS(IDS_DB_SGLD_TP);
		T_SGLD_K SgldTempK = m_pAttrCtrl->GetSgldKey(strTP);
		T_STEP_K StepK = 0;
		T_LCOM_D LcasD;
		T_STRB_D StrbMax; StrbMax.Initialize();
		m_pPostCtrl->MakeLoadComb(D_LOADCASE_STAGE, SgldTempK, LcasD);
		m_pPostCtrl->SelectLoadCombNew(LcasD, StepK, 2);	// 0=Nonlinear, 1=Pushover, 2=Consruction.	  
		m_pPostCtrl->GetStrbNew(ElemK.first, &StrbMax, NULL, NULL, FALSE, NULL, ElemK.second);
		dFx_TP_I = StrbMax.dblForce[0][0];
		dFx_TP_J = StrbMax.dblForce[3][6];
		dFz_TP_I = StrbMax.dblForce[0][2];
		dFz_TP_J = StrbMax.dblForce[3][8];
		// MQC 11614 이대근 이사보님 요청, fb 계산할 때 Tendon primary 응력 포함
		dft_TP_I = StrbMax.dblStress[0][0] + StrbMax.dblStress[0][5];
		dfb_TP_I = StrbMax.dblStress[0][0] + StrbMax.dblStress[0][6];
		dft_TP_J = StrbMax.dblStress[3][7] + StrbMax.dblStress[3][12];
		dfb_TP_J = StrbMax.dblStress[3][7] + StrbMax.dblStress[3][13];
	}
	//////////////////////////////////////////////////////////////////////////  

	_DGN_FORC_CRC ForceMxMaxD;
	_DGN_FORC_CRC ForceFzMaxD;
	_DGN_FORC_CRC ForceFzMinD;

	_DGN_STRS_CRC StressMxMaxD;
	_DGN_STRS_CRC StressFzMaxD;
	_DGN_STRS_CRC StressFzMinD;

	double dMxMaxT[2] = { 0,0 }, dMxMaxV[2] = { 0,0 }, dMxMaxMy[2] = { 0,0 }, dMxMaxFx[2] = { 0,0 };
	double dFzMaxT[2] = { 0,0 }, dFzMaxV[2] = { 0,0 }, dFzMaxMy[2] = { 0,0 }, dFzMaxFx[2] = { 0,0 };
	double dFzMinT[2] = { 0,0 }, dFzMinV[2] = { 0,0 }, dFzMinMy[2] = { 0,0 }, dFzMinFx[2] = { 0,0 };
	int iMxMaxDgnLcom[2] = { 0,0 }, iFzMaxDgnLcom[2] = { 0,0 }, iFzMinDgnLcom[2] = { 0,0 };

	int i = 0;
	if (!Get_CrmtForceMx_MaxMin(ElemK, ForceMxMaxD, ForceFzMaxD, ForceFzMinD, StressMxMaxD, StressFzMaxD, StressFzMinD, iMxMaxDgnLcom, iFzMaxDgnLcom, iFzMinDgnLcom)) return FALSE;

	for (i = 0; i < 2; ++i)
	{
		dMxMaxT[i] = ForceMxMaxD.dMux[i];
		dMxMaxV[i] = ForceMxMaxD.dFzz[i];
		dMxMaxMy[i] = ForceMxMaxD.dMuy[i];
		dMxMaxFx[i] = ForceMxMaxD.dFxx[i];
		//    
		dFzMaxT[i] = ForceFzMaxD.dMux[i];
		dFzMaxV[i] = ForceFzMaxD.dFzz[i];
		dFzMaxMy[i] = ForceFzMaxD.dMuy[i];
		dFzMaxFx[i] = ForceFzMaxD.dFxx[i];
		//
		dFzMinT[i] = ForceFzMinD.dMux[i];
		dFzMinV[i] = ForceFzMinD.dFzz[i];
		dFzMinMy[i] = ForceFzMinD.dMuy[i];
		dFzMinFx[i] = ForceFzMinD.dFxx[i];
	}

	for (i = 0; i < 6; ++i)
	{
		int nIx = i / 3;
		// 0=I-V-MAX, 1=I-V-MIN, 2=I-T-MAX, 3=J-V-MAX, 4=J-V-MIN, 5=J-T-MAX.
		int iDgnLcomNo = 0;
		double dMux = 0.0, dFzz = 0.0, dMuy = 0.0, dFxx = 0.0;
		double dft = 0.0, dfb = 0.0;
		if (i % 3 == 0)
		{
			iDgnLcomNo = iFzMaxDgnLcom[nIx]; dMux = dFzMaxT[nIx]; dFzz = dFzMaxV[nIx]; dMuy = dFzMaxMy[nIx]; dFxx = dFzMaxFx[nIx];
			dft = StressFzMaxD.dStop[nIx];
			dfb = StressFzMaxD.dSbot[nIx];
		}
		else if (i % 3 == 1)
		{
			iDgnLcomNo = iFzMinDgnLcom[nIx]; dMux = dFzMinT[nIx]; dFzz = dFzMinV[nIx]; dMuy = dFzMinMy[nIx]; dFxx = dFzMinFx[nIx];
			dft = StressFzMinD.dStop[nIx];
			dfb = StressFzMinD.dSbot[nIx];
		}
		else if (i % 3 == 2)
		{
			iDgnLcomNo = iMxMaxDgnLcom[nIx]; dMux = dMxMaxT[nIx]; dFzz = dMxMaxV[nIx]; dMuy = dMxMaxMy[nIx]; dFxx = dMxMaxFx[nIx];
			dft = StressMxMaxD.dStop[nIx];
			dfb = StressMxMaxD.dSbot[nIx];
		}
		else	ASSERT(0);
		dFxx += nIx == 0 ? dFx_TP_I : dFx_TP_J;
		double dFz_tp = nIx == 0 ? dFz_TP_I : dFz_TP_J;

		CString strOrgLcomNa = _T("");
		int iMaxMinType = 0;
		if (!m_ForceCtrl.Get_LcomType(iDgnLcomNo, strOrgLcomNa, iMaxMinType))	ASSERT(0);

		T_CRMT_PSC_BASE_IRC	 &CrmtB = rData.CrmtBase[i];
		CrmtB.bCHK = Get_ChkFlag(ElemK, nIx, TRUE);
		CrmtB.LcomK = iDgnLcomNo;
		CrmtB.iKind = m_ForceCtrl.Get_LcomKind(iDgnLcomNo);
		CrmtB.iMax = iMaxMinType;
		CrmtB.dPu = dFxx;
		CrmtB.dTu = dMux;
		CrmtB.dVu = GetVu4TpEx(dFzz, dFz_tp);
		CrmtB.dMu = dMuy;
		CrmtB.dft = dft;
		CrmtB.dfb = dfb;
	}

	if (CDBLib::IsPscCodeLSD(m_iCivilCode) || m_iCivilCode == BS5400_90_PSC || m_iCivilCode == TMH07_3_1989 || m_iCivilCode == IRC_112_2011_PSC || m_iCivilCode == IRS_PSC ||
		m_iCivilCode == IRC_112_2020_PSC)
	{
		if (!m_pPscDataCtrl->Get_CrmtData(ElemK, MembInD, rData)) return FALSE;
	}
	else ASSERT(0);

	return TRUE;
}

