BOOL CCRCDataCtrl::Get_CStageResPSC(ElemPairK ElemK, PSC_DATA_MEMB &MembInD, T_FYSG_PSC_IRS &FysgD, T_FPSG_PSC_IRS &FpsgD)
{
	FysgD.Initialize();
	FpsgD.Initialize();
	// Add by ZINU.('04.08.25). Check Calculating Item.
	if (!Is_CalcItem(ElemK, TRUE))  return FALSE;
	// Add by ZINU.('05.09.05).	PSC-Design/Strs(5), PSC-Design/Strn(6).
	int iDgnStatus = m_pDoc->GetDesignStatus();
	m_pDoc->SetDesignStatus(5);

	_DGN_STRS_CRC StrsMax;
	_DGN_STRS_CRC StrsMin;

	_DGN_SHRS_CRC ShrsMax;
	_DGN_SHRS_CRC ShrsMin;

	CArray<T_STAG_K, T_STAG_K> aStagK;
	m_pStageInfo->GetResultSavedStagKeyList(aStagK);
	if (aStagK.GetSize() == 0)	return FALSE;
	int i = 0, j = 0;

	// Modify, Step이 있으면 Step도 고려할 수 있도록 수정. 
	CString strSgldName = _LS(IDS_DB_SGLD_SUM);	// SUM.
	T_SGLD_K SgldK = m_pAttrCtrl->GetSgldKey(strSgldName);
	for (i = 0; i < aStagK.GetSize(); ++i)
	{
		T_STAG_K StagK = aStagK.GetAt(i);
		// MQC. 4145
		if (!m_pStageInfo->IsActiveElemInTgtStag(StagK, ElemK)) continue;

		T_STAG_STEP_INFO StageInfo; StageInfo.Initialize();
		m_pAttrCtrl->GetStagStepInfo(StagK, StageInfo);
		int iStepSize = StageInfo.aInfo.GetSize();
		if (iStepSize == 0)
		{
			int iFinalStepNo = 0;
			Get_LastStepInCurStage(StagK, iFinalStepNo);
			if (!m_ForceCtrl.Get_StrsBySgld(ElemK, SgldK, StagK, iFinalStepNo, StrsMax, StrsMin))	continue;
			//
			if (!m_ForceCtrl.Get_ShrsBySgld(ElemK, SgldK, StagK, iFinalStepNo, ShrsMax, ShrsMin, 4))	continue;	// 4=Principal.
		}
		else
		{
			for (j = 0; j < iStepSize; ++j)
			{
				int iStep = j + 1;
				int iSerialStep = 0;
				if (m_pStageInfo->GetStepSerialKey(StagK, iStep, iSerialStep))
				{
					if (!m_ForceCtrl.Get_StrsBySgld(ElemK, SgldK, StagK, iSerialStep, StrsMax, StrsMin))	continue;
					//
					if (!m_ForceCtrl.Get_ShrsBySgld(ElemK, SgldK, StagK, iSerialStep, ShrsMax, ShrsMin, 4))	continue;	// 4=Principal.
				}
			}
		}
	}
	// Set Data.
	for (i = 0; i < 4; ++i)
	{
		// 0=I-MAX, 1=I-MIN, 2=J-MAX, 3=J-MIN.
		_DGN_STRS_CRC &StrsCrc = (i % 2 == 0 ? StrsMax : StrsMin);
		int nIx = i / 2;
		if (StrsCrc.dScom[nIx] == 0.0)	continue;

		T_FYSG_PSC_BASE_IRS &FysgB = FysgD.FysgBase[i];
		FysgB.bCHK = Get_ChkFlag(ElemK, nIx, TRUE);
		FysgB.StageK = StrsCrc.iRefNo[nIx];
		FysgB.StepK = StrsCrc.iSerialStep[nIx];
		FysgB.dFT = StrsCrc.dStop[nIx];
		FysgB.dFB = StrsCrc.dSbot[nIx];
		FysgB.dFTL = StrsCrc.dStl[nIx];
		FysgB.dFBL = StrsCrc.dSbl[nIx];
		FysgB.dFTR = StrsCrc.dStr[nIx];
		FysgB.dFBR = StrsCrc.dSbr[nIx];
		FysgB.dFMAX = StrsCrc.dScom[nIx];
		FysgB.dALW = 0.0;	// From CRC.
	}

	for (i = 0; i < 4; ++i)
	{
		// 0=I-MAX, 1=I-MIN, 2=J-MAX, 3=J-MIN.
		_DGN_SHRS_CRC &ShrsD = (i % 2 == 0 ? ShrsMax : ShrsMin);
		int nIx = i / 2;
		if (ShrsD.dSspAbs[nIx] == 0.0)	continue;

		T_FPSG_PSC_BASE_IRS &FpsgB = FpsgD.FpsgBase[i];
		FpsgB.bCHK = Get_ChkFlag(ElemK, nIx, FALSE);
		FpsgB.StageK = ShrsD.iRefNo[nIx]; // LcomK에 Stage Key를 입력한다.     
		FpsgB.StepK = ShrsD.iSerialStep[nIx];
		FpsgB.dFP1 = ShrsD.dSsp[nIx][0];
		FpsgB.dFP2 = ShrsD.dSsp[nIx][1];
		FpsgB.dFP3 = ShrsD.dSsp[nIx][2];
		FpsgB.dFP4 = ShrsD.dSsp[nIx][3];
		FpsgB.dFP5 = ShrsD.dSsp[nIx][4];
		FpsgB.dFP6 = ShrsD.dSsp[nIx][5];
		FpsgB.dFP7 = ShrsD.dSsp[nIx][6];
		FpsgB.dFP8 = ShrsD.dSsp[nIx][7];
		FpsgB.dFP9 = ShrsD.dSsp[nIx][8];
		FpsgB.dFP10 = ShrsD.dSsp[nIx][9];
		FpsgB.dFMAX = ShrsD.dSspAbs[nIx];	//Max,Min
		FpsgB.dAFP = 0.0;	// From JTG D62-04
	}

	switch (m_iCivilCode)
	{
	case EUROCODE2_2_05_PSC:
	case IRC_112_2011_PSC:
	case IRC_112_2020_PSC:
	case TMH07_3_1989:
	case BS5400_90_PSC:
	case KDS_24_14_21_2022_PSC:
	case KSCE_LSD15_PSC:
	case SNiP_20503_84_PSC:
	case SP_35_13330_11_PSC:
	case SNiP_20503_84_PSC_MKS:
	case SP_35_13330_11_PSC_MKS:
	case IRS_PSC:
	case ABNT_NBR_6118_2023_PSC:
	{
		if (!m_pPscDataCtrl->Get_FysgData(ElemK, MembInD, FysgD)) return FALSE;
		//
		if (!m_pPscDataCtrl->Get_FpsgData(ElemK, MembInD, FpsgD)) return FALSE;
		break;
	}
	default: ASSERT(0); break;
	}

	return TRUE;
}

