		double dMaxMomM[2];//0 - I ENd ; 1 - J End
		double dMinMomM[2];//0 - I ENd ; 1 - J End
		//I End
		int iPart = 0; int iKind = 0;	// I.
		dMaxMomM[0] = StrbMax.dblForce[iPart][iKind + 4];
		dMinMomM[0] = StrbMin.dblForce[iPart][iKind + 4];
		//J - End
