//////////////////////////////////////////////////////////////////////////
// PSC Composite
BOOL CCRCDataCtrl::Get_PSCCheckResult(ElemPairK ElemK)
{
	BOOL bComposite = IsCompositePSCSect(ElemK);

	PSC_DATA_MEMB PscMembD;
	if (!m_pPscDataCtrl->Get_PscDataPosi(ElemK, 0, PscMembD.Pos[0], bComposite)) return FALSE;
	if (!m_pPscDataCtrl->Get_PscDataPosi(ElemK, 1, PscMembD.Pos[1], bComposite)) return FALSE;

	double dHeight[2] = { 0.0 };
	dHeight[0] = PscMembD.Pos[0].SectgD.dzDim;
	dHeight[1] = PscMembD.Pos[1].SectgD.dzDim;
	m_ForceCtrl.Set_SectHeight4PscGen(dHeight);

	if (bComposite)
	{
		T_FYSG_PSC_COMP FysgD;
		T_FPSG_PSC_COMP FpsgD;
		Get_CStageResPSC_Comp(ElemK, PscMembD, FysgD, FpsgD);
		m_pPostCtrl->GetPCDesign()->WriteFysg_PSC_Comp(ElemK, FysgD);
		m_pPostCtrl->GetPCDesign()->WriteFpsg_PSC_Comp(ElemK, FpsgD);

		T_FYCM_PSC_COMP FycmD;
		T_FPMS_PSC_COMP FpmsD;
		T_BDCW_PSC_COMP BdcwD;
		Get_FycmDataPSC_Comp(ElemK, PscMembD, FycmD);
		Get_FpmsDataPSC_Comp(ElemK, PscMembD, FpmsD);
		Get_BdcwDataPSC_Comp(ElemK, PscMembD, BdcwD);

		m_pPostCtrl->GetPCDesign()->WriteFycm_PSC_Comp(ElemK, FycmD);
		m_pPostCtrl->GetPCDesign()->WriteFpms_PSC_Comp(ElemK, FpmsD);
		m_pPostCtrl->GetPCDesign()->WriteBdcw_PSC_Comp(ElemK, BdcwD);

		T_BDCR_PSC_COMP BdcrD;
		T_CUMS_PSC_COMP CumsD;
		T_CRMT_PSC_COMP CrmtD;
		Get_BdcrDataPSC_Comp(ElemK, PscMembD, BdcrD);
		m_pPostCtrl->GetPCDesign()->WriteBdcr_PSC_Comp(ElemK, BdcrD); // 설계 후 바로 저장해야 함!

		Get_CumsDataPSC_Comp(ElemK, PscMembD, CumsD);
		m_pPostCtrl->GetPCDesign()->WriteCums_PSC_Comp(ElemK, CumsD);
		//BOOL bConsiderTor=(m_iCivilCode==EUROCODE2_2_05_PSC || m_iCivilCode==IRC_112_2011_PSC)? TRUE:FALSE;

		//if(!bConsiderTor)
		{
			if (Get_CrmtDataPSC_Comp(ElemK, PscMembD, CrmtD))
			{
				m_pPostCtrl->GetPCDesign()->WriteCrmt_PSC_Comp(ElemK, CrmtD);
			}
		}
	}
	else
	{
		if (m_iCivilCode == IRC_112_2011_PSC || m_iCivilCode == IRC_112_2020_PSC)
		{
			T_FYSG_PSC_IRC FysgD;
			T_FPSG_PSC_IRC FpsgD;
			Get_CStageResPSC(ElemK, PscMembD, FysgD, FpsgD);

			m_pPostCtrl->GetPCDesign()->WriteFysg_PSC_IRC(ElemK, FysgD);
			m_pPostCtrl->GetPCDesign()->WriteFpsg_PSC_IRC(ElemK, FpsgD);

			T_FYCM_PSC_IRC FycmD;
			T_FPMS_PSC_IRC FpmsD;
			T_BDCW_PSC_IRC BdcwD;
			Get_FycmDataPSC(ElemK, PscMembD, FycmD);
			Get_FpmsDataPSC(ElemK, PscMembD, FpmsD);
			Get_BdcwDataPSC(ElemK, PscMembD, BdcwD);

			m_pPostCtrl->GetPCDesign()->WriteFycm_PSC_IRC(ElemK, FycmD);
			m_pPostCtrl->GetPCDesign()->WriteFpms_PSC_IRC(ElemK, FpmsD);
			m_pPostCtrl->GetPCDesign()->WriteBdcw_PSC_IRC(ElemK, BdcwD);

			T_BDCR_PSC_IRC BdcrD;
			T_CUMS_PSC_IRC CumsD;
			T_CRMT_PSC_IRC CrmtD;
			Get_BdcrDataPSC(ElemK, PscMembD, BdcrD);
			Get_CumsDataPSC(ElemK, PscMembD, CumsD);
			Get_CrmtDataPSC(ElemK, PscMembD, CrmtD);

			m_pPostCtrl->GetPCDesign()->WriteBdcr_PSC_IRC(ElemK, BdcrD);
			m_pPostCtrl->GetPCDesign()->WriteCums_PSC_IRC(ElemK, CumsD);
			m_pPostCtrl->GetPCDesign()->WriteCrmt_PSC_IRC(ElemK, CrmtD);
		}
		else if (m_iCivilCode == IRS_PSC)
		{
			T_FYSG_PSC_IRS FysgD;
			T_FPSG_PSC_IRS FpsgD;
			Get_CStageResPSC(ElemK, PscMembD, FysgD, FpsgD);

			m_pPostCtrl->GetPCDesign()->WriteFysg_PSC_IRS(ElemK, FysgD);
			m_pPostCtrl->GetPCDesign()->WriteFpsg_PSC_IRS(ElemK, FpsgD);

			T_FYCM_PSC_IRS FycmD;
			T_FPMS_PSC_IRS FpmsD;
			T_BDCW_PSC_IRS BdcwD;
			T_BDCR_PSC_IRS BdcrD;
			Get_FycmDataPSC(ElemK, PscMembD, FycmD);
			Get_FpmsDataPSC(ElemK, PscMembD, FpmsD);
			Get_BdcrDataPSC(ElemK, PscMembD, BdcrD);
			Get_BdcwDataPSC(ElemK, PscMembD, BdcwD);

			m_pPostCtrl->GetPCDesign()->WriteFycm_PSC_IRS(ElemK, FycmD);
			m_pPostCtrl->GetPCDesign()->WriteFpms_PSC_IRS(ElemK, FpmsD);
			m_pPostCtrl->GetPCDesign()->WriteBdcr_PSC_IRS(ElemK, BdcrD);
			m_pPostCtrl->GetPCDesign()->WriteBdcw_PSC_IRS(ElemK, BdcwD);

			T_CUMS_PSC_IRS CumsD;
			T_CRMT_PSC_IRS CrmtD;
			Get_CumsDataPSC(ElemK, PscMembD, CumsD);
			Get_CrmtDataPSC(ElemK, PscMembD, CrmtD);

			m_pPostCtrl->GetPCDesign()->WriteCums_PSC_IRS(ElemK, CumsD);
			m_pPostCtrl->GetPCDesign()->WriteCrmt_PSC_IRS(ElemK, CrmtD);
		}
		else
		{
			T_FYSG_PSC FysgD;
			T_FPSG_PSC FpsgD;
			Get_CStageResPSC(ElemK, PscMembD, FysgD, FpsgD);

			m_pPostCtrl->GetPCDesign()->WriteFysg_PSC(ElemK, FysgD);
			m_pPostCtrl->GetPCDesign()->WriteFpsg_PSC(ElemK, FpsgD);

			T_FYCM_PSC FycmD;
			T_FPMS_PSC FpmsD;
			T_BDCW_PSC BdcwD;
			Get_FycmDataPSC(ElemK, PscMembD, FycmD);
			Get_FpmsDataPSC(ElemK, PscMembD, FpmsD);
			Get_BdcwDataPSC(ElemK, PscMembD, BdcwD);

			m_pPostCtrl->GetPCDesign()->WriteFycm_PSC(ElemK, FycmD);
			m_pPostCtrl->GetPCDesign()->WriteFpms_PSC(ElemK, FpmsD);
			m_pPostCtrl->GetPCDesign()->WriteBdcw_PSC(ElemK, BdcwD);

			T_BDCR_PSC BdcrD;
			T_CUMS_PSC CumsD;
			T_CRMT_PSC CrmtD;
			Get_BdcrDataPSC(ElemK, PscMembD, BdcrD);
			Get_CumsDataPSC(ElemK, PscMembD, CumsD);
			Get_CrmtDataPSC(ElemK, PscMembD, CrmtD);

			m_pPostCtrl->GetPCDesign()->WriteBdcr_PSC(ElemK, BdcrD);
			m_pPostCtrl->GetPCDesign()->WriteCums_PSC(ElemK, CumsD);
			m_pPostCtrl->GetPCDesign()->WriteCrmt_PSC(ElemK, CrmtD);
		}
	}

	T_FATG_PSC FatgD;
	T_FATG_PSC_IRC FatgDIRC;
	T_FATG_PSC_IRS FatgDIRS;
	if (m_iCivilCode == EUROCODE2_2_05_PSC)
	{
		Get_FatgDataPSC(ElemK, PscMembD, FatgD);
		m_pPostCtrl->GetPCDesign()->WriteFatg_PSC(ElemK, FatgD);
	}
	else if (m_iCivilCode == IRC_112_2011_PSC || m_iCivilCode == IRC_112_2020_PSC)
	{
		Get_FatgDataPSC(ElemK, PscMembD, FatgDIRC);
		m_pPostCtrl->GetPCDesign()->WriteFatg_PSC(ElemK, FatgDIRC);
	}
	else if (m_iCivilCode == IRS_PSC)
	{
		Get_FatgDataPSC(ElemK, PscMembD, FatgDIRS);
		m_pPostCtrl->GetPCDesign()->WriteFatg_PSC(ElemK, FatgDIRS);
	}
	return TRUE;
}

BOOL CCRCDataCtrl::Get_CStageResPSC_Comp(ElemPairK ElemK, PSC_DATA_MEMB &MembInD, T_FYSG_PSC_COMP &FysgD, T_FPSG_PSC_COMP &FpsgD)
{
	// Add by ZINU.('04.08.25). Check Calculating Item.
	if (!Is_CalcItem(ElemK, TRUE))  return FALSE;
	// Add by ZINU.('05.09.05).	PSC-Design/Strs(5), PSC-Design/Strn(6).
	int iDgnStatus = m_pDoc->GetDesignStatus();
	m_pDoc->SetDesignStatus(5);

	T_STRS_CPT StrsCpt;
	T_SHRS_CPT ShrsCpt;

	Calc_CStageResCpt(ElemK, MembInD, StrsCpt, ShrsCpt, FysgD, FpsgD);

	return TRUE;
}

BOOL CCRCDataCtrl::Get_FysgDataPSC_Comp(ElemPairK ElemK, PSC_DATA_MEMB &MembInD, T_FYSG_PSC_COMP& rData)
{
	rData.Initialize();
	// Add by ZINU.('04.08.25). Check Calculating Item.
	if (!Is_CalcItem(ElemK, TRUE))  return FALSE;
	// Add by ZINU.('05.09.05).	PSC-Design/Strs(5), PSC-Design/Strn(6).
	int iDgnStatus = m_pDoc->GetDesignStatus();
	m_pDoc->SetDesignStatus(5);

	_DGN_STRS_CRC StrsMaxGr; // 거더
	_DGN_STRS_CRC StrsMinGr;
	_DGN_STRS_CRC StrsMaxSl; // 슬래브
	_DGN_STRS_CRC StrsMinSl;

	CArray<T_STAG_K, T_STAG_K> aStagK;
	m_pStageInfo->GetResultSavedStagKeyList(aStagK);
	if (aStagK.GetSize() == 0)	return FALSE;
	int i = 0, j = 0;
	m_ForceCtrl.Debug_PrintOpt(1);	// For DEBUG.

	T_CONC_AGE_D AgeD;
	if(!GetInitAgesOfConcrete(ElemK, AgeD)) ASSERT(0);
	double dAgeGr = AgeD.dAgeGr;

	// Modify, Step이 있으면 Step도 고려할 수 있도록 수정. 
	CString strSgldName = _LS(IDS_DB_SGLD_SUM);	// SUM.
	T_SGLD_K SgldK = m_pAttrCtrl->GetSgldKey(strSgldName);
	std::vector<double> vDay;

	vDay.push_back(0.0);

	int nStepGr = 0;
	double dFirstStep_Day = 0.0;
	for (i = 0; i < aStagK.GetSize(); ++i)
	{
		T_STAG_K StagK = aStagK.GetAt(i);
		// MQC. 4145
		if (!m_pStageInfo->IsActiveElemInTgtStag(StagK, ElemK)) continue;

		// 0:오류 또는 시공 합성 단면 아님
		// 1:시공 합성 단면 : 합성 전 (Active Stage 이전)
		// 2:시공 합성 단면 : 합성 중 (Active되고 모든 Part가 합성되기 전)
		// 3:시공 합성 단면 : 합성 후 (모든 Part가 합성된 후)
		T_CSCS_D CscsD; CscsD.Initialize();
		int nCompositeType = m_pAttrCtrl->GetElemSectCompositeInfoDgn(ElemK, StagK, CscsD);
		if (nCompositeType == 0 || nCompositeType == 1) continue;

		T_STAG_STEP_INFO StageInfo; StageInfo.Initialize();
		m_pAttrCtrl->GetStagStepInfo(StagK, StageInfo);
		int iStepSize = StageInfo.aInfo.GetSize();
		if (iStepSize == 0)
		{
			int iFinalStepNo = 0;
			Get_LastStepInCurStage(StagK, iFinalStepNo);
			if (nCompositeType == 2)
			{
				if (!m_ForceCtrl.Get_StrsPartBySgld(ElemK, SgldK, StagK, iFinalStepNo, 1, StrsMaxGr, StrsMinGr))	continue;
			}
			else if (nCompositeType >= 3)
			{
				if (!m_ForceCtrl.Get_StrsPartBySgld(ElemK, SgldK, StagK, iFinalStepNo, 1, StrsMaxGr, StrsMinGr))	continue;
				if (!m_ForceCtrl.Get_StrsPartBySgld(ElemK, SgldK, StagK, iFinalStepNo, 2, StrsMaxSl, StrsMinSl))	continue;
			}
			else ASSERT(0);
		}
		else
		{
			for (j = 0; j < iStepSize; ++j)
			{
				int iStep = j + 1;

				double dStep_Day = 0.0;
				double dDay = 0.0;
				
				m_pStageInfo->GetStagStepDay(StagK, iStep, dStep_Day); // Stage에서 각 step의 날짜

				nStepGr++;
				if (nStepGr == 1) dFirstStep_Day = dStep_Day;
				double dCurrStepAge = dStep_Day - dFirstStep_Day;

				int iSerialStep = 0;
				if (m_pStageInfo->GetStepSerialKey(StagK, iStep, iSerialStep))
				{
					if (nCompositeType == 2)
					{
						if (!m_ForceCtrl.Get_StrsPartBySgld(ElemK, SgldK, StagK, iSerialStep, 1, StrsMaxGr, StrsMinGr))	continue;
					}
					else if (nCompositeType >= 3)
					{
						if (!m_ForceCtrl.Get_StrsPartBySgld(ElemK, SgldK, StagK, iSerialStep, 1, StrsMaxGr, StrsMinGr))	continue;
						if (!m_ForceCtrl.Get_StrsPartBySgld(ElemK, SgldK, StagK, iSerialStep, 2, StrsMaxSl, StrsMinSl))	continue;
					}
					else ASSERT(0);

					

					T_ELFM_D dDayActive; dDayActive.Initialize();
					m_pPostCtrl->GetElfmDgn(StagK, ElemK, dDayActive);

					double dCurrAgeGr = dAgeGr + dCurrStepAge;
					dDay = dCurrAgeGr;
					vDay.push_back(dDay);
				}
			}
		}
	}
	// Set Data. 거더
	for (i = 0; i < 4; ++i)
	{
		// 0=I-MAX, 1=I-MIN, 2=J-MAX, 3=J-MIN.
		_DGN_STRS_CRC &StrsCrc = (i % 2 == 0 ? StrsMaxGr : StrsMinGr);
		if (StrsCrc.dScom[i / 2] == 0.0)	continue;
		rData.FysgGrBase[i].bCHK = Get_ChkFlag(ElemK, i / 2, TRUE);
		rData.FysgGrBase[i].StageK = StrsCrc.iRefNo[i / 2];
		rData.FysgGrBase[i].StepK = StrsCrc.iSerialStep[i / 2];
		rData.FysgGrBase[i].dFT = StrsCrc.dStop[i / 2];
		rData.FysgGrBase[i].dFB = StrsCrc.dSbot[i / 2];
		rData.FysgGrBase[i].dFTL = StrsCrc.dStl[i / 2];
		rData.FysgGrBase[i].dFBL = StrsCrc.dSbl[i / 2];
		rData.FysgGrBase[i].dFTR = StrsCrc.dStr[i / 2];
		rData.FysgGrBase[i].dFBR = StrsCrc.dSbr[i / 2];
		rData.FysgGrBase[i].dFMAX = StrsCrc.dScom[i / 2];
		rData.FysgGrBase[i].dALW = 0.0;	// From CRC.
	}

	// Set Data. 슬래브
	for (i = 0; i < 4; ++i)
	{
		// 0=I-MAX, 1=I-MIN, 2=J-MAX, 3=J-MIN.
		_DGN_STRS_CRC &StrsCrc = (i % 2 == 0 ? StrsMaxSl : StrsMinSl);
		if (StrsCrc.dScom[i / 2] == 0.0)	continue;
		rData.FysgSlBase[i].bCHK = Get_ChkFlag(ElemK, i / 2, TRUE);
		rData.FysgSlBase[i].StageK = StrsCrc.iRefNo[i / 2];
		rData.FysgSlBase[i].StepK = StrsCrc.iSerialStep[i / 2];
		rData.FysgSlBase[i].dFT = StrsCrc.dStop[i / 2];
		rData.FysgSlBase[i].dFB = StrsCrc.dSbot[i / 2];
		rData.FysgSlBase[i].dFTL = StrsCrc.dStl[i / 2];
		rData.FysgSlBase[i].dFBL = StrsCrc.dSbl[i / 2];
		rData.FysgSlBase[i].dFTR = StrsCrc.dStr[i / 2];
		rData.FysgSlBase[i].dFBR = StrsCrc.dSbr[i / 2];
		rData.FysgSlBase[i].dFMAX = StrsCrc.dScom[i / 2];
		rData.FysgSlBase[i].dALW = 0.0;	// From CRC.
	}

	switch (m_iCivilCode)
	{
	case KDS_24_14_21_2022_PSC:
	case KSCE_LSD15_PSC:
	case EUROCODE2_2_05_PSC:
	case IRC_112_2011_PSC:
	case IRC_112_2020_PSC:
	case AS_5100_5_17_PSC:
	case IRS_PSC:
	case TMH07_3_1989:
	case BS5400_90_PSC:
	case ABNT_NBR_6118_2023_PSC:
	{
		if (!m_pPscDataCtrl->Get_FysgData_Composite(ElemK, MembInD, rData)) return FALSE;
		break;
	}
	default:
	{ASSERT(0); break; }
	}

	return TRUE;
}

BOOL CCRCDataCtrl::Get_FycmDataPSC_Comp(ElemPairK ElemK, PSC_DATA_MEMB &MembInD, T_FYCM_PSC_COMP& rData)
{
	rData.Initialize();
	// Add by ZINU.('04.08.25). Check Calculating Item.
	if (!Is_CalcItem(ElemK, TRUE))  return FALSE;
	// Add by ZINU.('05.09.05).	PSC-Design/Strs(5), PSC-Design/Strn(6).
	int iDgnStatus = m_pDoc->GetDesignStatus();
	m_pDoc->SetDesignStatus(5);

	_DGN_STRS_CRC StrsMax;
	_DGN_STRS_CRC StrsMin;

	_DGN_STRS_CRC StrsMaxGr;// 거더
	_DGN_STRS_CRC StrsMinGr;
	_DGN_STRS_CRC StrsMaxSl;// 슬래브
	_DGN_STRS_CRC StrsMinSl;

	m_ForceCtrl.Debug_PrintOpt(3);	// For DEBUG.
	int iShortLongTerm = 3;
	if (!m_ForceCtrl.Get_StrsByLcom(ElemK, 0, StrsMax, StrsMin, iShortLongTerm))	return FALSE;

	//////////////////////////////////////////////////////////////////////////
	// 수정해야함!!!
	//////////////////////////////////////////////////////////////////////////
	// Set Data - 거더
	int i = 0;
	for (i = 0; i < 4; ++i)
	{
		// 0=I-MAX, 1=I-MIN, 2=J-MAX, 3=J-MIN.
		_DGN_STRS_CRC &StrsCrc = (i % 2 == 0 ? StrsMax : StrsMin);
		int nIx = i / 2;
		if (StrsCrc.dScom[nIx] == 0.0)	continue;

		T_FYCM_PSC_COMP_BASE &FycmB = rData.FycmGrBase[i];

		int iDgnLcomNo = StrsCrc.iRefNo[nIx];
		CString strOrgLcomNa = _T("");
		int iMaxMinType = 0;
		if (!m_ForceCtrl.Get_LcomType(iDgnLcomNo, strOrgLcomNa, iMaxMinType))	ASSERT(0);

		FycmB.bCHK = Get_ChkFlag(ElemK, nIx, TRUE);
		FycmB.LcomK = iDgnLcomNo;
		FycmB.iKind = m_ForceCtrl.Get_ServLcomType(iDgnLcomNo); //m_ForceCtrl.Get_LcomKind(iDgnLcomNo);
		FycmB.iMax = iMaxMinType;
		FycmB.dFT = StrsCrc.dStop[nIx];
		FycmB.dFB = StrsCrc.dSbot[nIx];
		FycmB.dFTL = StrsCrc.dStl[nIx];
		FycmB.dFBL = StrsCrc.dSbl[nIx];
		FycmB.dFTR = StrsCrc.dStr[nIx];
		FycmB.dFBR = StrsCrc.dSbr[nIx];
		FycmB.dFMAX = StrsCrc.dScom[nIx];
		FycmB.dALW = 0.0;	// From CRC.
	}

	// Set Data - 슬래브
	StrsMax.Initialize();
	StrsMin.Initialize();
	if (!m_ForceCtrl.Get_StrsByLcom(ElemK, 2, StrsMax, StrsMin, iShortLongTerm))	return FALSE;

	for (i = 0; i < 4; ++i)
	{
		// 0=I-MAX, 1=I-MIN, 2=J-MAX, 3=J-MIN.
		_DGN_STRS_CRC &StrsCrc = (i % 2 == 0 ? StrsMax : StrsMin);
		int nIx = i / 2;
		if (StrsCrc.dScom[nIx] == 0.0)	continue;

		T_FYCM_PSC_COMP_BASE &FycmB = rData.FycmSlBase[i];

		int iDgnLcomNo = StrsCrc.iRefNo[i / 2];
		CString strOrgLcomNa = _T("");
		int iMaxMinType = 0;
		if (!m_ForceCtrl.Get_LcomType(iDgnLcomNo, strOrgLcomNa, iMaxMinType))	ASSERT(0);

		FycmB.bCHK = Get_ChkFlag(ElemK, nIx, TRUE);
		FycmB.LcomK = iDgnLcomNo;
		FycmB.iKind = m_ForceCtrl.Get_ServLcomType(iDgnLcomNo); //m_ForceCtrl.Get_LcomKind(iDgnLcomNo);
		FycmB.iMax = iMaxMinType;
		FycmB.dFT = StrsCrc.dStop[nIx];
		FycmB.dFB = StrsCrc.dSbot[nIx];
		FycmB.dFTL = StrsCrc.dStl[nIx];
		FycmB.dFBL = StrsCrc.dSbl[nIx];
		FycmB.dFTR = StrsCrc.dStr[nIx];
		FycmB.dFBR = StrsCrc.dSbr[nIx];
		FycmB.dFMAX = StrsCrc.dScom[nIx];
		FycmB.dALW = 0.0;	// From CRC.
	}

	switch (m_iCivilCode)
	{
	case KDS_24_14_21_2022_PSC:
	case KSCE_LSD15_PSC:
	case EUROCODE2_2_05_PSC:
	case IRC_112_2011_PSC:
	case IRC_112_2020_PSC:
	case AS_5100_5_17_PSC:
	case IRS_PSC:
	case TMH07_3_1989:
	case BS5400_90_PSC:
	case ABNT_NBR_6118_2023_PSC:
	{
		if (!m_pPscDataCtrl->Get_FycmData_Composite(ElemK, MembInD, rData)) return FALSE;
		break;
	}
	default: ASSERT(0); break;
	}

	return TRUE;
}

BOOL CCRCDataCtrl::Get_FpsgDataPSC_Comp(ElemPairK ElemK, PSC_DATA_MEMB &MembInD, T_FPSG_PSC_COMP& rData)
{
	rData.Initialize();
	// Add by ZINU.('04.08.25). Check Calculating Item.
	if (!Is_CalcItem(ElemK, FALSE))  return FALSE;
	// Add by ZINU.('05.09.05).	PSC-Design/Strs(5), PSC-Design/Strn(6).
	int iDgnStatus = m_pDoc->GetDesignStatus();
	m_pDoc->SetDesignStatus(5);

	_DGN_SHRS_CRC ShrsMaxGr;
	_DGN_SHRS_CRC ShrsMinGr;

	_DGN_SHRS_CRC ShrsMaxSl;
	_DGN_SHRS_CRC ShrsMinSl;

	CArray<T_STAG_K, T_STAG_K> aStagK;
	m_pStageInfo->GetResultSavedStagKeyList(aStagK);
	if (aStagK.GetSize() == 0)	return FALSE;
	int i = 0, j = 0;
	m_ForceCtrl.Debug_PrintOpt(7);	// For DEBUG.

	// Modify, Step이 있으면 Step도 고려할 수 있도록 수정. 
	CString strSgldName = _LS(IDS_DB_SGLD_SUM);	// SUM.
	T_SGLD_K SgldK = m_pAttrCtrl->GetSgldKey(strSgldName);

	int nStepGr = 0;
	double dFirstStep_Day = 0.0;
	for (i = 0; i < aStagK.GetSize(); ++i)
	{
		T_STAG_K StagK = aStagK.GetAt(i);

		if (!m_pStageInfo->IsActiveElemInTgtStag(StagK, ElemK)) continue;
		
		// 0:오류 또는 시공 합성 단면 아님
		// 1:시공 합성 단면 : 합성 전 (Active Stage 이전)
		// 2:시공 합성 단면 : 합성 중 (Active되고 모든 Part가 합성되기 전)
		// 3:시공 합성 단면 : 합성 후 (모든 Part가 합성된 후)
		T_CSCS_D CscsD; CscsD.Initialize();
		int nCompositeType = m_pAttrCtrl->GetElemSectCompositeInfoDgn(ElemK, StagK, CscsD);
		if (nCompositeType == 0 || nCompositeType == 1) continue;

		T_STAG_STEP_INFO StageInfo; StageInfo.Initialize();
		m_pAttrCtrl->GetStagStepInfo(StagK, StageInfo);
		int iStepSize = StageInfo.aInfo.GetSize();
		if (iStepSize == 0)
		{
			int iFinalStepNo = 0;
			Get_LastStepInCurStage(StagK, iFinalStepNo);
			if (nCompositeType == 2)
			{
				if (!m_ForceCtrl.Get_ShrsPartBySgld(ElemK, SgldK, StagK, iFinalStepNo, 1, ShrsMaxGr, ShrsMinGr, 4))	continue;	// 4=Principal.
			}
			else if (nCompositeType >= 3)
			{
				if (!m_ForceCtrl.Get_ShrsPartBySgld(ElemK, SgldK, StagK, iFinalStepNo, 1, ShrsMaxGr, ShrsMinGr, 4))	continue;	// 4=Principal.
				if (!m_ForceCtrl.Get_ShrsPartBySgld(ElemK, SgldK, StagK, iFinalStepNo, 2, ShrsMaxSl, ShrsMinSl, 4))	continue;	// 4=Principal.
			}
			else ASSERT(0);
		}
		else
		{
			for (j = 0; j < iStepSize; ++j)
			{
				int iStep = j + 1;
				int iSerialStep = 0;
				if (m_pStageInfo->GetStepSerialKey(StagK, iStep, iSerialStep))
				{
					if (nCompositeType == 2)
					{
						if (!m_ForceCtrl.Get_ShrsPartBySgld(ElemK, SgldK, StagK, iSerialStep, 1, ShrsMaxGr, ShrsMinGr, 4))	continue;	// 4=Principal.
					}
					else if (nCompositeType >= 3)
					{
						if (!m_ForceCtrl.Get_ShrsPartBySgld(ElemK, SgldK, StagK, iSerialStep, 1, ShrsMaxGr, ShrsMinGr, 4))	continue;	// 4=Principal.
						if (!m_ForceCtrl.Get_ShrsPartBySgld(ElemK, SgldK, StagK, iSerialStep, 2, ShrsMaxSl, ShrsMaxSl, 4))	continue;	// 4=Principal.
					}
					else ASSERT(0);
				}
			}
		}
	}

	//////////////////////////////////////////////////////////////////////////
	// 시공단계시 파트별 주응력 - 결과 확인 필요
	//////////////////////////////////////////////////////////////////////////
	// Set Data. - 거더
	for (i = 0; i < 4; ++i)
	{
		// 0=I-MAX, 1=I-MIN, 2=J-MAX, 3=J-MIN.
		_DGN_SHRS_CRC &ShrsD = (i % 2 == 0 ? ShrsMaxGr : ShrsMinGr);
		if (ShrsD.dSspAbs[i / 2] == 0.0)	continue;

		rData.FpsgGrBase[i].bCHK = Get_ChkFlag(ElemK, i / 2, FALSE);
		rData.FpsgGrBase[i].StageK = ShrsD.iRefNo[i / 2]; // LcomK에 Stage Key를 입력한다.     
		rData.FpsgGrBase[i].StepK = ShrsD.iSerialStep[i / 2];
		rData.FpsgGrBase[i].dFP1 = ShrsD.dSsp[i / 2][0];
		rData.FpsgGrBase[i].dFP2 = ShrsD.dSsp[i / 2][1];
		rData.FpsgGrBase[i].dFP3 = ShrsD.dSsp[i / 2][2];
		rData.FpsgGrBase[i].dFP4 = ShrsD.dSsp[i / 2][3];
		rData.FpsgGrBase[i].dFP5 = ShrsD.dSsp[i / 2][4];
		rData.FpsgGrBase[i].dFP6 = ShrsD.dSsp[i / 2][5];
		rData.FpsgGrBase[i].dFP7 = ShrsD.dSsp[i / 2][6];
		rData.FpsgGrBase[i].dFP8 = ShrsD.dSsp[i / 2][7];
		rData.FpsgGrBase[i].dFP9 = ShrsD.dSsp[i / 2][8];
		rData.FpsgGrBase[i].dFP10 = ShrsD.dSsp[i / 2][9];
		rData.FpsgGrBase[i].dFMAX = ShrsD.dSspAbs[i / 2];	//Max,Min
		rData.FpsgGrBase[i].dAFP = 0.0;	// From JTG D62-04
	}

	// Set Data. - 슬래브
	for (i = 0; i < 4; ++i)
	{
		// 0=I-MAX, 1=I-MIN, 2=J-MAX, 3=J-MIN.
		_DGN_SHRS_CRC &ShrsD = (i % 2 == 0 ? ShrsMaxSl : ShrsMinSl);
		if (ShrsD.dSspAbs[i / 2] == 0.0)	continue;

		rData.FpsgSlBase[i].bCHK = Get_ChkFlag(ElemK, i / 2, FALSE);
		rData.FpsgSlBase[i].StageK = ShrsD.iRefNo[i / 2]; // LcomK에 Stage Key를 입력한다.     
		rData.FpsgSlBase[i].StepK = ShrsD.iSerialStep[i / 2];
		rData.FpsgSlBase[i].dFP1 = ShrsD.dSsp[i / 2][0];
		rData.FpsgSlBase[i].dFP2 = ShrsD.dSsp[i / 2][1];
		rData.FpsgSlBase[i].dFP3 = ShrsD.dSsp[i / 2][2];
		rData.FpsgSlBase[i].dFP4 = ShrsD.dSsp[i / 2][3];
		rData.FpsgSlBase[i].dFP5 = ShrsD.dSsp[i / 2][4];
		rData.FpsgSlBase[i].dFP6 = ShrsD.dSsp[i / 2][5];
		rData.FpsgSlBase[i].dFP7 = ShrsD.dSsp[i / 2][6];
		rData.FpsgSlBase[i].dFP8 = ShrsD.dSsp[i / 2][7];
		rData.FpsgSlBase[i].dFP9 = ShrsD.dSsp[i / 2][8];
		rData.FpsgSlBase[i].dFP10 = ShrsD.dSsp[i / 2][9];
		rData.FpsgSlBase[i].dFMAX = ShrsD.dSspAbs[i / 2];	//Max,Min
		rData.FpsgSlBase[i].dAFP = 0.0;	// From JTG D62-04
	}

	switch (m_iCivilCode)
	{
	case KDS_24_14_21_2022_PSC:
	case KSCE_LSD15_PSC:
	case EUROCODE2_2_05_PSC:
	case IRC_112_2011_PSC:
	case IRC_112_2020_PSC:
	case AS_5100_5_17_PSC:
	case IRS_PSC:
	case TMH07_3_1989:
	case BS5400_90_PSC:
	case ABNT_NBR_6118_2023_PSC:
	{
		if (!m_pPscDataCtrl->Get_FpsgData_Composite(ElemK, MembInD, rData)) return FALSE;
		break;
	}
	default: ASSERT(0); break;
	}

	return TRUE;
}

