BOOL CCRCDataCtrl::Get_BdcwDataPSC_Comp(ElemPairK ElemK, PSC_DATA_MEMB &MembInD, T_BDCW_PSC_COMP& rData)
{
	if (m_iCivilCode == IRC_112_2011_PSC || m_iCivilCode == IRC_112_2020_PSC) return Get_BdcwDataPSC_Comp_IRC112(ElemK, MembInD, rData);

	rData.Initialize();
	// Add by ZINU.('04.08.25). Check Calculating Item.
	if (!Is_CalcItem(ElemK, TRUE))  return FALSE;
	// Add by ZINU.('05.09.05).	PSC-Design/Strs(5), PSC-Design/Strn(6).
	int iDgnStatus = m_pDoc->GetDesignStatus();
	m_pDoc->SetDesignStatus(6);

	T_STCT_D StctD; StctD.Initialize();
	m_pDoc->m_pAttrCtrl->GetStct(StctD);

	int i = 0, j = 0, z = 0;
	double dMyMax[2] = { 0.,0. }, dMyMin[2] = { 0.,0. };
	int iMaxDgnLcom[2] = { 0,0 }, iMinDgnLcom[2] = { 0,0 };
	double dMaxRat[4] = { 0.0, 0.0, 0.0, 0.0 }, dMaxRat_zero[4] = { 0.0, 0.0, 0.0, 0.0 }, dMaxRat_Asmin[4] = { 0.0, 0.0, 0.0, 0.0 };
	int iCheckCount[4] = { 0,0,0,0 }, iCheckCount_zero[4] = { 0,0,0,0 }, iCheckCount_Asmin[4] = { 0,0,0,0 };

	T_BDCW_PSC_COMP BdcwD;

	int iLcomNum = m_ForceCtrl.Get_LcomDataCount();
	ADGNFORCE aForceLcom;
	ADGNFORCE aForceTnpr;
	ADGNFORCE aForceTnsc;
	ADGNFORCE aForceLTerm;
	ADGNFORCE aForceSTerm;
	ADGNSHRSADD aStssLcom;
	int nForType = 0; // CIVIL-724 전체의 부재력 받아옴, Total
	if (!m_ForceCtrl.Get_LcomDataForDesign(ElemK, TRUE, TRUE, aForceLcom, aForceTnpr, aForceTnsc, aForceLTerm, aForceSTerm, aStssLcom, iLcomNum)) return FALSE;

	ADGNSTRESS aStressLcom;
	ADGNSTRSADD aStressAdd;
	ADGNSTRESS aStressLterm;
	ADGNSTRESS aStressSterm;
	nForType = 1; // CIVIL-724 거더의 응력 받아옴, Part1
	if (!m_ForceCtrl.Get_LcomDataForStress(ElemK, TRUE, TRUE, aStressLcom, aStressAdd, aStressLterm, aStressSterm, iLcomNum)) return FALSE;

	T_STAG_K nGdLastStagK = 0;
	int nLastStepNo = 0;
	m_ForceCtrl.GetGirderLastStageKey(ElemK, nGdLastStagK, nLastStepNo);

	BOOL bChkI = Get_ChkFlag(ElemK, 0, TRUE);
	BOOL bChkJ = Get_ChkFlag(ElemK, 1, TRUE);

	// 전체하중조합을 검토한다.
	int nChkStrCount[4] = { 0,0,0,0 };
	T_BDCW_PSC_COMP BdcwStressD;
	int iLcomSize = aForceLcom.GetSize();
	int nStressLcomSize = aStressLcom.GetSize();
	for (i = 0; i < iLcomSize; ++i)
	{
		if (!m_ForceCtrl.Is_LcomForStrs(i + 1))	continue;
		_DGN_FORC_CRC &ForceD = aForceLcom[i];
		_DGN_FORC_CRC& TnprForD = aForceTnpr[i];
		_DGN_FORC_CRC& ForSTD = aForceSTerm[i];
		_DGN_STRS_CRC &StressD = aStressLcom[i];
		_DGN_STRS_CRC& StrLTermD = aStressLterm[i];
		_DGN_STRS_CRC& StrSTermD = aStressSterm[i];

		BdcwD.Initialize();

		PSC_BDCW_D BdcwResD;
		int iDgnLcomNo = i + 1;
		CString strOrgLcomNa = _T("");
		int iMaxMinType = 0;
		if (!m_ForceCtrl.Get_LcomType(iDgnLcomNo, strOrgLcomNa, iMaxMinType))	ASSERT(0);

		_DGN_FORC_CRC FcsDL;
		_DGN_STRS_CRC StrP2;
		_DGN_STRS_CRC StrLTP2;
		_DGN_STRS_CRC StrSTP2;
		// 시공중 거더 Force
		int nForceBeforeType = 1;
		m_ForceCtrl.Get_GirderForce4CSLoadOfLCOM(FALSE, StctD, ElemK, nGdLastStagK, nLastStepNo, iDgnLcomNo, nForceBeforeType, FcsDL);
		m_ForceCtrl.GetDgnForce()->GetStressLcomResult_Part2(ElemK, iDgnLcomNo, StrP2);
		m_ForceCtrl.GetDgnForce()->GetStressLcomLTerm_Part2(ElemK, iDgnLcomNo, StrLTP2);
		m_ForceCtrl.GetDgnForce()->GetStressLcomSTerm_Part2(ElemK, iDgnLcomNo, StrSTP2);


		//  (iKind== 1) (_T("사용하중I"));      - Quasi-permanant
		//  (iKind== 2) (_T("사용하중III/VI")); - Frequent
		//  (iKind== 3) (_T("지속하중"));       - Characteristic
		int iKind = m_ForceCtrl.Get_ServLcomType(iDgnLcomNo);

		if (CDBLib::IsPscCodeLSD(m_iCivilCode) || m_iCivilCode == IRC_112_2011_PSC || m_iCivilCode == IRS_PSC ||
			m_iCivilCode == IRC_112_2020_PSC)
		{
			if (iKind < 1 || iKind >3) continue;
		}


		PSC_LCOM_INFO_B       LcomInf[2];
		PSC_LCOM_FOR_B        ForB[2];
		PSC_LCOM_FOR_B        ForP2[2];
		PSC_BDCW_CR_PROP_R CrackP[2];
		for (j = 0; j < 2; ++j)
		{
			LcomInf[j].bCHK = j == 0 ? bChkI : bChkJ;
			LcomInf[j].LcomK = iDgnLcomNo;
			LcomInf[j].nKind = m_ForceCtrl.Get_LcomKind(iDgnLcomNo);
			LcomInf[j].nMax = iMaxMinType;

			ForB[j].dForce[0] = ForceD.dFxx[j] - TnprForD.dFxx[j];
			ForB[j].dForce[1] = ForceD.dFyy[j] - TnprForD.dFyy[j];
			ForB[j].dForce[2] = ForceD.dFzz[j] - TnprForD.dFzz[j];
			ForB[j].dForce[3] = ForceD.dMux[j] - TnprForD.dMux[j];
			ForB[j].dForce[4] = ForceD.dMuy[j] - TnprForD.dMuy[j];
			ForB[j].dForce[5] = ForceD.dMuz[j] - TnprForD.dMuz[j];

			CrackP[j].dPu = FcsDL.dFxx[j];
			CrackP[j].dMu = FcsDL.dMuy[j];
			CrackP[j].dPu_st = ForSTD.dFxx[j];
			CrackP[j].dMu_st = ForSTD.dMuy[j];
			_DGN_FORC_CRC ForLTD;
			ForLTD += ForceD;
			ForLTD -= TnprForD;
			ForLTD -= ForSTD;
			CrackP[j].dPu_lt = ForLTD.dFxx[j];
			CrackP[j].dMu_lt = ForLTD.dMuy[j];
			CrackP[j].dPu_c = ForLTD.dFxx[j] + ForSTD.dFxx[j];
			CrackP[j].dMu_c = ForLTD.dMuy[j] + ForSTD.dMuy[j];

			double dft_PL = StrLTermD.dStop[j]; // DL(Long Term)
			double dfb_PL = StrLTermD.dSbot[j];
			double dft_LL = StrSTermD.dStop[j];
			double dfb_LL = StrSTermD.dSbot[j];

			ForB[j].dFT = StressD.dStop[j];
			ForB[j].dFB = StressD.dSbot[j];
			ForB[j].dft_DL = dft_PL;
			ForB[j].dfb_DL = dfb_PL;
			ForB[j].dft_LL = dft_LL;
			ForB[j].dfb_LL = dfb_LL;
			// bComposite
			ForP2[j].dFT = StrP2.dStop[j];
			ForP2[j].dFB = StrP2.dSbot[j];
			ForP2[j].dft_DL = StrLTP2.dStop[j];
			ForP2[j].dfb_DL = StrLTP2.dSbot[j];
			ForP2[j].dft_LL = StrSTP2.dStop[j];
			ForP2[j].dfb_LL = StrSTP2.dSbot[j];
		}

		for (j = 0; j < 2; ++j)
		{
			BdcwResD.BdcwBase[j].LInf = LcomInf[0];
			BdcwResD.BdcwBase[j].ForB = ForB[0];
			BdcwResD.BdcwBase[j].ForP2 = ForP2[0];
			BdcwResD.BdcwBase[j].CrPropD = CrackP[0];
			BdcwResD.BdcwBase[j + 2].LInf = LcomInf[1];
			BdcwResD.BdcwBase[j + 2].ForB = ForB[1];
			BdcwResD.BdcwBase[j + 2].ForP2 = ForP2[1];
			BdcwResD.BdcwBase[j + 2].CrPropD = CrackP[1];
		}

		for (j = 0; j < 4; ++j)
		{
			double dMuy = (j < 2 ? ForceD.dMuy[0] : ForceD.dMuy[1]);
			double dFxx = (j < 2 ? ForceD.dFxx[0] : ForceD.dFxx[1]);
			double dft = (j < 2 ? StressD.dStop[0] : StressD.dStop[1]);
			double dfb = (j < 2 ? StressD.dSbot[0] : StressD.dSbot[1]);
			//if(j%2==1) { dMuy = ( dMuy<0.0 ? 0.0 : dMuy ); } // negative면 Top검토 
			//else       { dMuy = ( dMuy>0.0 ? 0.0 : dMuy ); }

			T_BDCW_PSC_COMP_BASE &BdcwB = BdcwD.BdcwBase[j];
			BdcwB.bCHK = (j / 2 == 0) ? bChkI : bChkJ;
			BdcwB.LcomK = iDgnLcomNo;
			BdcwB.iKind = iKind;
			BdcwB.iLSTerm = m_ForceCtrl.Get_LcomKind(iDgnLcomNo);
			BdcwB.iMax = iMaxMinType;
			BdcwB.dPu = dFxx;
			BdcwB.dMu = dMuy;
			BdcwB.dft = dft;
			BdcwB.dfb = dfb;

			T_BDCW_PSC_COMP_BASE &BdcwZeroB = BdcwD.BdcwBaseZero[j];
			BdcwZeroB.bCHK = (j / 2 == 0) ? bChkI : bChkJ;
			BdcwZeroB.LcomK = iDgnLcomNo;
			BdcwZeroB.iKind = iKind;
			BdcwZeroB.iLSTerm = m_ForceCtrl.Get_LcomKind(iDgnLcomNo);
			BdcwZeroB.iMax = iMaxMinType;
			BdcwZeroB.dPu = dFxx;
			BdcwZeroB.dMu = dMuy;
			BdcwZeroB.dft = dft;
			BdcwZeroB.dfb = dfb;

			T_BDCW_PSC_COMP_BASE &BdcwAsminB = BdcwD.BdcwBaseAsmin[j];
			BdcwAsminB.bCHK = (j / 2 == 0) ? bChkI : bChkJ;
			BdcwAsminB.LcomK = iDgnLcomNo;
			BdcwAsminB.iKind = iKind;
			BdcwAsminB.iLSTerm = m_ForceCtrl.Get_LcomKind(iDgnLcomNo);
			BdcwAsminB.iMax = iMaxMinType;
			BdcwAsminB.dPu = dFxx;
			BdcwAsminB.dMu = dMuy;
			BdcwAsminB.dft = dft;
			BdcwAsminB.dfb = dfb;
		}
		//
		if (!m_pPscDataCtrl->Get_BdcwData_Composite(ElemK, MembInD, BdcwD, BdcwResD))  continue; //return FALSE;

        // 균열
        for(j=0; j<4; ++j)
        {
            T_BDCW_PSC_COMP_BASE &BdcwBaseD = BdcwD.BdcwBase[j];
            if(BdcwBaseD.bCHK/* && BdcwBaseD.bOK_Cr*/) iCheckCount[j] += 1;
            else continue;

			if (iCheckCount[j] == 1)
			{
				dMaxRat[j] = BdcwBaseD.dRatio;
				rData.BdcwBase[j] = BdcwBaseD;
			}
			else if (iCheckCount[j] > 1)
			{
				if (dMaxRat[j] < BdcwBaseD.dRatio)
				{
					dMaxRat[j] = BdcwBaseD.dRatio;
					rData.BdcwBase[j] = BdcwBaseD;
				}
			}
		}

		// MQC-11615. 이대근 이사보님 요청 20160224
		for (j = 0; j < 4; ++j)
		{
			if (BdcwResD.BdcwBase[j].bCHK == TRUE) // 계산이 된 것만 적용
			{
				if (nChkStrCount[j] == 0)
				{
					BdcwStressD.BdcwBase[j] = BdcwD.BdcwBase[j];
				}
				else
				{
					if (j == 0 || j == 2)
					{
						if (BdcwStressD.BdcwBase[j].dft < BdcwD.BdcwBase[j].dft) BdcwStressD.BdcwBase[j] = BdcwD.BdcwBase[j];
					}
					else
					{
						if (BdcwStressD.BdcwBase[j].dfb < BdcwD.BdcwBase[j].dfb) BdcwStressD.BdcwBase[j] = BdcwD.BdcwBase[j];
					}
				}
				nChkStrCount[j]++;
			}
		}

		// 영응력
		for (j = 0; j < 4; ++j)
		{
			T_BDCW_PSC_COMP_BASE &BdcwBaseD = BdcwD.BdcwBaseZero[j];

			if (BdcwBaseD.bCHK)
			{
				if (iCheckCount_zero[j] == 0)
				{
					dMaxRat_zero[j] = BdcwBaseD.dRatio;
					rData.BdcwBaseZero[j] = BdcwBaseD;
				}
				else if (iCheckCount_zero[j] > 1)
				{
					if (dMaxRat_zero[j] < BdcwBaseD.dRatio)
					{
						dMaxRat_zero[j] = BdcwBaseD.dRatio;
						rData.BdcwBaseZero[j] = BdcwBaseD;
					}
				}
				iCheckCount_zero[j]++;
			}
		}

		// 최소철근량 검토 여부(Characteristic Load Combination)
		for (z = 0; z < 4; ++z)
		{
			T_BDCW_PSC_COMP_BASE &BdcwBaseD = BdcwD.BdcwBaseAsmin[z];
			if (BdcwBaseD.bCHK == TRUE) //Characteristic
			{
				if (iCheckCount_Asmin[z] == 0)
				{
					dMaxRat_Asmin[z] = BdcwBaseD.dRatio;
					rData.BdcwBaseAsmin[z] = BdcwBaseD;
				}
				else
				{
					if (dMaxRat_Asmin[z] < BdcwBaseD.dRatio)
					{
						dMaxRat_Asmin[z] = BdcwBaseD.dRatio;
						rData.BdcwBaseAsmin[z] = BdcwBaseD;
					}
				}
				iCheckCount_Asmin[z]++;
			}
		}
	} // Lcom

	for (int k = 0; k < 4; ++k)
	{
		if (rData.BdcwBase[k].bCHK == TRUE && fabs(rData.BdcwBase[k].dWk) < m_dZero && fabs(rData.BdcwBase[k].dWmax) < m_dZero)
		{
			rData.BdcwBase[k] = BdcwStressD.BdcwBase[k];
		}
	}

	return TRUE;
}

BOOL CCRCDataCtrl::Get_BdcrDataPSC_Comp(ElemPairK ElemK, PSC_DATA_MEMB &MembInD, T_BDCR_PSC_COMP& rData)
{
	rData.Initialize();
	// Add by ZINU.('04.08.25). Check Calculating Item.
	if (!Is_CalcItem(ElemK, TRUE))  return FALSE;
	// Add by ZINU.('05.09.05).	PSC-Design/Strs(5), PSC-Design/Strn(6).
	int iDgnStatus = m_pDoc->GetDesignStatus();
	m_pDoc->SetDesignStatus(6);

	int i;
	double dMyMax[2] = { 0.,0. }, dMyMin[2] = { 0.,0. };
	int iMaxDgnLcom[2] = { 0,0 }, iMinDgnLcom[2] = { 0,0 };

	// 필요한 Force Max/Min 값을 찾음.
	BOOL bStrength = TRUE;
	if (!Get_CheckForceMu_MaxMin(bStrength, ElemK, dMyMax, dMyMin, iMaxDgnLcom, iMinDgnLcom)) return FALSE;

	for (i = 0; i < 4; ++i)
	{
		// 0=I-MAX, 1=I-MIN, 2=J-MAX, 3=J-MIN.
		int iDgnLcomNo = (i % 2 == 0 ? iMaxDgnLcom[i / 2] : iMinDgnLcom[i / 2]);
		CString strOrgLcomNa = _T("");
		int iMaxMinType = 0;
		if (!m_ForceCtrl.Get_LcomType(iDgnLcomNo, strOrgLcomNa, iMaxMinType))	ASSERT(0);
		double dMuy = (i % 2 == 0 ? dMyMax[i / 2] : dMyMin[i / 2]);
		if (i % 2 == 0) { dMuy = (dMuy < 0.0 ? 0.0 : dMuy); }
		else { dMuy = (dMuy > 0.0 ? 0.0 : dMuy); }

		rData.BdcrBase[i].bCHK = Get_ChkFlag(ElemK, i / 2, TRUE);
		rData.BdcrBase[i].LcomK = iDgnLcomNo;
		rData.BdcrBase[i].iKind = m_ForceCtrl.Get_LcomKind(iDgnLcomNo);
		rData.BdcrBase[i].iMax = iMaxMinType;
		rData.BdcrBase[i].dMu = dMuy;
	}

	BOOL bComposite = IsCompositePSCSect(ElemK);
	if (bComposite)
	{
		if (!m_pPscDataCtrl->Get_BdcrData_Composite(ElemK, MembInD, rData)) return FALSE;
	}
	else ASSERT(0);

	CString sBendingErrMsg = _T("");
	for (i = 0; i < 4; ++i)
	{
		if (rData.BdcrBase[i].bCHK)
		{
			CString strIJ = i < 2 ? _T("I") : _T("J");
			if (rData.BdcrBase[i].bOK == D_PSC_FRC_ERR_Iteration_Over)
			{
				CString strPN = i % 2 == 0 ? _T("P") : _T("N"); // Positive/Negative
				CString strPosi;
				strPosi.Format(_T("%d-%s(%s)"), ElemK, strIJ, strPN);
				sBendingErrMsg.Format(_LS(IDS_DGN_WARN_BEND_NEUTRAL_AXIS_Err), strPosi); // [Warning] Midas Civil has failed to find the neutral axis(member no.: xxxx). Please check the PSC Design Calculation sheet for details.
				GSaveHistoryFormatNF(sBendingErrMsg);
			}
		}
	}

	return TRUE;
}

BOOL CCRCDataCtrl::Get_CumsDataPSC_Comp(ElemPairK ElemK, PSC_DATA_MEMB &MembInD, T_CUMS_PSC_COMP& rData)
{
	rData.Initialize();
	// Add by ZINU.('04.08.25). Check Calculating Item.
	if (!Is_CalcItem(ElemK, FALSE))  return FALSE;
	// Add by ZINU.('05.09.05).	PSC-Design/Strs(5), PSC-Design/Strn(6).
	int iDgnStatus = m_pDoc->GetDesignStatus();
	m_pDoc->SetDesignStatus(6);

	_DGN_FORC_CRC ForceFzMaxD;
	_DGN_FORC_CRC ForceFzMinD;
	_DGN_STRS_CRC StressFzMaxD;
	_DGN_STRS_CRC StressFzMinD;

	double dFzMax[2] = { 0,0 }, dFzMin[2] = { 0,0 };
	double dFzMaxMy[2] = { 0,0 }, dFzMinMy[2] = { 0,0 };
	double dFzMaxFx[2] = { 0,0 }, dFzMinFx[2] = { 0,0 };
	int iMaxDgnLcom[2] = { 0,0 }, iMinDgnLcom[2] = { 0,0 };
	int i = 0;

	//////////////////////////////////////////////////////////////////////////  
	double dFx_TP[2] = { 0.0, 0.0 };
	double dFz_TP[2] = { 0.0, 0.0 };
	double dft_TP[2] = { 0.0, 0.0 };
	double dfb_TP[2] = { 0.0, 0.0 };
	BOOL bExistStage = m_pDoc->m_pStagCtrl->ExistStag();
	if (bExistStage)
	{
		CString strTP = _LS(IDS_DB_SGLD_TP);
		T_SGLD_K SgldTempK = m_pAttrCtrl->GetSgldKey(strTP);
		T_STEP_K StepK = 0;
		T_LCOM_D LcasD;
		T_STRB_D StrbMax; StrbMax.Initialize();
		m_pPostCtrl->MakeLoadComb(D_LOADCASE_STAGE, SgldTempK, LcasD);
		m_pPostCtrl->SelectLoadCombNew(LcasD, StepK, 2);	// 0=Nonlinear, 1=Pushover, 2=Consruction.	  
		m_pPostCtrl->GetStrbNew(ElemK.first, &StrbMax, NULL, NULL, FALSE, NULL, ElemK.second);
		dFx_TP[0] = StrbMax.dblForce[0][0];
		dFx_TP[1] = StrbMax.dblForce[3][6];
		dFz_TP[0] = StrbMax.dblForce[0][2];
		dFz_TP[1] = StrbMax.dblForce[3][8];
		// MQC 11614 이대근 이사보님 요청, fb 계산할 때 Tendon primary 응력 포함
		T_STRB_D StrbMaxP; StrbMaxP.Initialize();
		m_pPostCtrl->GetStrbPartNew(ElemK.first, 1, &StrbMaxP, NULL, NULL);
		dft_TP[0] = StrbMaxP.dblStress[0][0] + StrbMaxP.dblStress[0][5];
		dft_TP[1] = StrbMaxP.dblStress[3][7] + StrbMaxP.dblStress[3][12];
		dfb_TP[0] = StrbMaxP.dblStress[0][0] + StrbMaxP.dblStress[0][6];
		dfb_TP[1] = StrbMaxP.dblStress[3][7] + StrbMaxP.dblStress[3][13];
	}
	//////////////////////////////////////////////////////////////////////////  

	// 요소별 합성 직전의 부재력
	CPG_FORC_STAG ForceStage;
	ForceStage.Initialize();
	if (!Get_ForceStageMapData_PSCComposite(ElemK, ForceStage))  ASSERT(0);
	double dM_pre[2] = { 0,0 };
	double dV_pre[2] = { 0,0 };
	for (i = 0; i < 2; ++i)
	{
		double dM_stg01 = fabs(ForceStage.MaxForce.dMuy[i]);
		double dM_stg02 = fabs(ForceStage.MinForce.dMuy[i]);
		dM_pre[i] = max(dM_stg01, dM_stg02);

		double dV_stg01 = fabs(ForceStage.MaxForce.dFzz[i]);
		double dV_stg02 = fabs(ForceStage.MinForce.dFzz[i]);
		dV_pre[i] = max(dV_stg01, dV_stg02);
	}

	//
	if (CDBLib::IsPscCodeLSD_KR(m_iCivilCode))
	{
		if (!Get_CumsForceFz_MaxMin_LSD(ElemK, ForceFzMaxD, ForceFzMinD, StressFzMaxD, StressFzMinD, iMaxDgnLcom, iMinDgnLcom)) return FALSE;
	}
	else
	{
		if (!Get_CumsForceFz_MaxMin(ElemK, ForceFzMaxD, ForceFzMinD, StressFzMaxD, StressFzMinD, iMaxDgnLcom, iMinDgnLcom)) return FALSE;
	}

	// 최대 모멘트
	// 	double dMuMax[2]={0,0}, dMuMin[2]={0,0};
	// 	Get_CumsForce_Mu_MaxMin(ElemK, dMuMax, dMuMin);

	for (i = 0; i < 2; ++i)
	{
		dFzMax[i] = ForceFzMaxD.dFzz[i];
		dFzMaxMy[i] = ForceFzMaxD.dMuy[i];
		dFzMaxFx[i] = ForceFzMaxD.dFxx[i];
		//
		dFzMin[i] = ForceFzMinD.dFzz[i];
		dFzMinMy[i] = ForceFzMinD.dMuy[i];
		dFzMinFx[i] = ForceFzMinD.dFxx[i];
	}

	double adMr[4] = { 0.0 };
	double adZ_sh[4] = { 0.0 };
	double adCc_gr[4] = { 0.0 };    // 거더 압축력
	double adCc_sl[4] = { 0.0 };    // 슬래브 압축력
	double adForce_T[4] = { 0.0 };  // 전체인장응력(Rebar+Tendon)
	double adTst_sl[4] = { 0.0 };   // 슬래브인장응력(Rebar)

	T_BDCR_PSC_COMP BdcrD;
	m_pPostCtrl->GetPCDesign()->ReadBdcr_PSC_Comp(ElemK, BdcrD);

	for (i = 0; i < 4; ++i)
	{
		// 0=I-MAX, 1=I-MIN, 2=J-MAX, 3=J-MIN.
		int nIx = i / 2;
		int iDgnLcomNo = (i % 2 == 0 ? iMaxDgnLcom[nIx] : iMinDgnLcom[nIx]);
		CString strOrgLcomNa = _T("");
		int iMaxMinType = 0;
		if (!m_ForceCtrl.Get_LcomType(iDgnLcomNo, strOrgLcomNa, iMaxMinType))	ASSERT(0);
		//MQC 15168 Tendon Primary 응력 반영 시 Coding Mistake 수정
		//     double dFx_TP_IJ = (i<2 ? dFx_TP_I : dFx_TP_J);
		//     double dft_TP_IJ = (i<2 ? dft_TP_I : dft_TP_J);
		//     double dfb_TP_IJ = (i<2 ? dfb_TP_I : dfb_TP_J);
		//
		//     double dFzz = (i%2==0 ? dFzMax[i/2] : dFzMin[i/2]);
		//     double dMuy = (i%2==0 ? dFzMaxMy[i/2] : dFzMinMy[i/2]);
		//     double dFxx = (i%2==0 ? dFzMaxFx[i/2] + dFx_TP_IJ : dFzMinFx[i/2] + dFx_TP_IJ);
		//     double dft  = (i%2==0 ? StressFzMaxD.dStop[i/2] + dft_TP_IJ : StressFzMinD.dStop[i/2] + dft_TP_IJ);
		//     double dfb  = (i%2==0 ? StressFzMaxD.dSbot[i/2] + dfb_TP_IJ : StressFzMinD.dSbot[i/2] + dfb_TP_IJ);

		double dFzz = (i % 2 == 0 ? dFzMax[nIx] : dFzMin[nIx]);
		double dMuy = (i % 2 == 0 ? dFzMaxMy[nIx] : dFzMinMy[nIx]);
		double dFxx = (i % 2 == 0 ? dFzMaxFx[nIx] + dFx_TP[nIx] : dFzMinFx[nIx] + dFx_TP[nIx]);
		double dft = (i % 2 == 0 ? StressFzMaxD.dStop[nIx] + dft_TP[nIx] : StressFzMinD.dStop[nIx] + dft_TP[nIx]);
		double dfb = (i % 2 == 0 ? StressFzMaxD.dSbot[nIx] + dfb_TP[nIx] : StressFzMinD.dSbot[nIx] + dfb_TP[nIx]);

		rData.CumsBase[i].bCHK = Get_ChkFlag(ElemK, nIx, FALSE);
		rData.CumsBase[i].LcomK = iDgnLcomNo;
		rData.CumsBase[i].iKind = m_ForceCtrl.Get_LcomKind(iDgnLcomNo);
		rData.CumsBase[i].iMax = iMaxMinType;
		rData.CumsBase[i].dPu = dFxx;
		rData.CumsBase[i].dVu = GetVu4TpEx(dFzz, dFz_TP[nIx]);
		rData.CumsBase[i].dMu = dMuy;
		rData.CumsBase[i].dft = dft;   // 상부 응력 - 균열발생여부 검토
		rData.CumsBase[i].dfb = dfb;   // 하부 응력 

		// KSCE-LSD15.
		rData.CumsBase[i].dM_pre = dM_pre[nIx];
		rData.CumsBase[i].dV_pre = dV_pre[nIx];

		if (i < 2)
		{
			adMr[i] = (dMuy < 0.0) ? BdcrD.BdcrBase[1].dphiMn : BdcrD.BdcrBase[0].dphiMn;
			adZ_sh[i] = (dMuy < 0.0) ? BdcrD.BdcrBase[1].dz_sh : BdcrD.BdcrBase[0].dz_sh;
			adCc_gr[i] = (dMuy < 0.0) ? BdcrD.BdcrBase[1].dCc_gr : BdcrD.BdcrBase[0].dCc_gr;
			adCc_sl[i] = (dMuy < 0.0) ? BdcrD.BdcrBase[1].dCc_sl : BdcrD.BdcrBase[0].dCc_sl;
			adForce_T[i] = (dMuy < 0.0) ? BdcrD.BdcrBase[1].dForce_T : BdcrD.BdcrBase[0].dForce_T;
			adTst_sl[i] = (dMuy < 0.0) ? BdcrD.BdcrBase[1].dTst_sl : BdcrD.BdcrBase[0].dTst_sl;
		}
		else
		{
			adMr[i] = (dMuy < 0.0) ? BdcrD.BdcrBase[3].dphiMn : BdcrD.BdcrBase[2].dphiMn;
			adZ_sh[i] = (dMuy < 0.0) ? BdcrD.BdcrBase[3].dz_sh : BdcrD.BdcrBase[2].dz_sh;
			adCc_gr[i] = (dMuy < 0.0) ? BdcrD.BdcrBase[3].dCc_gr : BdcrD.BdcrBase[2].dCc_gr;
			adCc_sl[i] = (dMuy < 0.0) ? BdcrD.BdcrBase[3].dCc_sl : BdcrD.BdcrBase[2].dCc_sl;
			adForce_T[i] = (dMuy < 0.0) ? BdcrD.BdcrBase[3].dForce_T : BdcrD.BdcrBase[2].dForce_T;
			adTst_sl[i] = (dMuy < 0.0) ? BdcrD.BdcrBase[3].dTst_sl : BdcrD.BdcrBase[2].dTst_sl;
		}
	}

	if (CDBLib::IsPscCodeLSD(m_iCivilCode) || m_iCivilCode == IRC_112_2011_PSC || m_iCivilCode == IRS_PSC ||
		m_iCivilCode == IRC_112_2020_PSC)
	{
		if (!m_pPscDataCtrl->Get_CumsData_Composite(ElemK, MembInD, adMr, adZ_sh, adCc_gr, adCc_sl, adForce_T, adTst_sl, rData)) return FALSE;
	}
	else ASSERT(0);

	return TRUE;
}

BOOL CCRCDataCtrl::Get_CrmtDataPSC_Comp(ElemPairK ElemK, PSC_DATA_MEMB &MembInD, T_CRMT_PSC_COMP& rData)
{
	rData.Initialize();
	// Add by ZINU.('04.08.25). Check Calculating Item.
	if (!Is_CalcItem(ElemK, FALSE))  return FALSE;
	// Add by ZINU.('05.09.05).	PSC-Design/Strs(5), PSC-Design/Strn(6).
	int iDgnStatus = m_pDoc->GetDesignStatus();
	m_pDoc->SetDesignStatus(6);

	//////////////////////////////////////////////////////////////////////////  
	double dFx_TP_I = 0.0, dFx_TP_J = 0.0;
	double dFz_TP_I = 0.0, dFz_TP_J = 0.0;
	double dft_TP_I = 0.0, dfb_TP_I = 0.0;
	double dft_TP_J = 0.0, dfb_TP_J = 0.0;
	BOOL bExistStage = m_pDoc->m_pStagCtrl->ExistStag();
	if (bExistStage)
	{
		CString strTP = _LS(IDS_DB_SGLD_TP);
		T_SGLD_K SgldTempK = m_pAttrCtrl->GetSgldKey(strTP);
		T_STEP_K StepK = 0;
		T_LCOM_D LcasD;
		T_STRB_D StrbMax; StrbMax.Initialize();
		m_pPostCtrl->MakeLoadComb(D_LOADCASE_STAGE, SgldTempK, LcasD);
		m_pPostCtrl->SelectLoadCombNew(LcasD, StepK, 2);	// 0=Nonlinear, 1=Pushover, 2=Consruction.	  
		m_pPostCtrl->GetStrbNew(ElemK.first, &StrbMax, NULL, NULL, FALSE, NULL, ElemK.second);
		dFx_TP_I = StrbMax.dblForce[0][0];
		dFx_TP_J = StrbMax.dblForce[3][6];
		dFz_TP_I = StrbMax.dblForce[0][2];
		dFz_TP_J = StrbMax.dblForce[3][8];
		// MQC 11614 이대근 이사보님 요청, fb 계산할 때 Tendon primary 응력 포함
		T_STRB_D StrbMaxP; StrbMaxP.Initialize();
		m_pPostCtrl->GetStrbPartNew(ElemK.first, 1, &StrbMaxP, NULL, NULL);
		dft_TP_I = StrbMaxP.dblStress[0][0] + StrbMaxP.dblStress[0][5];
		dfb_TP_I = StrbMaxP.dblStress[0][0] + StrbMaxP.dblStress[0][6];
		dft_TP_J = StrbMaxP.dblStress[3][7] + StrbMaxP.dblStress[3][12];
		dfb_TP_J = StrbMaxP.dblStress[3][7] + StrbMaxP.dblStress[3][13];
	}
	//////////////////////////////////////////////////////////////////////////  

	_DGN_FORC_CRC ForceMxMaxD;
	_DGN_FORC_CRC ForceFzMaxD;
	_DGN_FORC_CRC ForceFzMinD;

	_DGN_STRS_CRC StressMxMaxD;
	_DGN_STRS_CRC StressFzMaxD;
	_DGN_STRS_CRC StressFzMinD;

	double dMxMaxT[2] = { 0,0 }, dMxMaxV[2] = { 0,0 }, dMxMaxMy[2] = { 0,0 }, dMxMaxFx[2] = { 0,0 };
	double dFzMaxT[2] = { 0,0 }, dFzMaxV[2] = { 0,0 }, dFzMaxMy[2] = { 0,0 }, dFzMaxFx[2] = { 0,0 };
	double dFzMinT[2] = { 0,0 }, dFzMinV[2] = { 0,0 }, dFzMinMy[2] = { 0,0 }, dFzMinFx[2] = { 0,0 };
	int iMxMaxDgnLcom[2] = { 0,0 }, iFzMaxDgnLcom[2] = { 0,0 }, iFzMinDgnLcom[2] = { 0,0 };

	// 요소별 합성 직전의 부재력
	CPG_FORC_STAG ForceStage;
	ForceStage.Initialize();
	if (!Get_ForceStageMapData_PSCComposite(ElemK, ForceStage))  ASSERT(0);
	double dM_pre[2] = { 0,0 };
	double dV_pre[2] = { 0,0 };

	int i = 0;
	for (i = 0; i < 2; ++i)
	{
		double dM_stg01 = fabs(ForceStage.MaxForce.dMuy[i]);
		double dM_stg02 = fabs(ForceStage.MinForce.dMuy[i]);
		dM_pre[i] = max(dM_stg01, dM_stg02);

		double dV_stg01 = fabs(ForceStage.MaxForce.dFzz[i]);
		double dV_stg02 = fabs(ForceStage.MinForce.dFzz[i]);
		dV_pre[i] = max(dV_stg01, dV_stg02);
	}

	double adZ_sh[6] = { 0.0 };
	double adCc_gr[6] = { 0.0 };
	double adCc_sl[6] = { 0.0 };
	T_BDCR_PSC_COMP BdcrD;
	m_pPostCtrl->GetPCDesign()->ReadBdcr_PSC_Comp(ElemK, BdcrD);

	if (!Get_CrmtForceMx_MaxMin(ElemK, ForceMxMaxD, ForceFzMaxD, ForceFzMinD, StressMxMaxD, StressFzMaxD, StressFzMinD, iMxMaxDgnLcom, iFzMaxDgnLcom, iFzMinDgnLcom)) return FALSE;

	for (i = 0; i < 2; ++i)
	{
		dMxMaxT[i] = ForceMxMaxD.dMux[i];
		dMxMaxV[i] = ForceMxMaxD.dFzz[i];
		dMxMaxMy[i] = ForceMxMaxD.dMuy[i];
		dMxMaxFx[i] = ForceMxMaxD.dFxx[i];
		//    
		dFzMaxT[i] = ForceFzMaxD.dMux[i];
		dFzMaxV[i] = ForceFzMaxD.dFzz[i];
		dFzMaxMy[i] = ForceFzMaxD.dMuy[i];
		dFzMaxFx[i] = ForceFzMaxD.dFxx[i];
		//
		dFzMinT[i] = ForceFzMinD.dMux[i];
		dFzMinV[i] = ForceFzMinD.dFzz[i];
		dFzMinMy[i] = ForceFzMinD.dMuy[i];
		dFzMinFx[i] = ForceFzMinD.dFxx[i];
	}

	for (i = 0; i < 6; ++i)
	{
		// 0=I-V-MAX, 1=I-V-MIN, 2=I-T-MAX, 3=J-V-MAX, 4=J-V-MIN, 5=J-T-MAX.
		int nIx = i / 3;
		int iDgnLcomNo = 0;
		double dMux = 0.0, dFzz = 0.0, dMuy = 0.0, dFxx = 0.0;
		double dft = 0.0, dfb = 0.0;
		if (i % 3 == 0)
		{
			iDgnLcomNo = iFzMaxDgnLcom[nIx]; dMux = dFzMaxT[nIx]; dFzz = dFzMaxV[nIx]; dMuy = dFzMaxMy[nIx]; dFxx = dFzMaxFx[nIx];
			dft = StressFzMaxD.dStop[nIx];
			dfb = StressFzMaxD.dSbot[nIx];
		}
		else if (i % 3 == 1)
		{
			iDgnLcomNo = iFzMinDgnLcom[nIx]; dMux = dFzMinT[nIx]; dFzz = dFzMinV[nIx]; dMuy = dFzMinMy[nIx]; dFxx = dFzMinFx[nIx];
			dft = StressFzMinD.dStop[nIx];
			dfb = StressFzMinD.dSbot[nIx];
		}
		else if (i % 3 == 2)
		{
			iDgnLcomNo = iMxMaxDgnLcom[nIx]; dMux = dMxMaxT[nIx]; dFzz = dMxMaxV[nIx]; dMuy = dMxMaxMy[nIx]; dFxx = dMxMaxFx[nIx];
			dft = StressMxMaxD.dStop[nIx];
			dfb = StressMxMaxD.dSbot[nIx];
		}
		else	ASSERT(0);
		dFxx += nIx == 0 ? dFx_TP_I : dFx_TP_J;
		dft += nIx == 0 ? dft_TP_I : dft_TP_J;
		dfb += nIx == 0 ? dfb_TP_I : dfb_TP_J;
		double dFz_tp = nIx == 0 ? dFz_TP_I : dFz_TP_J;

		CString strOrgLcomNa = _T("");
		int iMaxMinType = 0;
		if (!m_ForceCtrl.Get_LcomType(iDgnLcomNo, strOrgLcomNa, iMaxMinType))	ASSERT(0);

		rData.CrmtBase[i].bCHK = Get_ChkFlag(ElemK, nIx, TRUE);
		rData.CrmtBase[i].LcomK = iDgnLcomNo;
		rData.CrmtBase[i].iKind = m_ForceCtrl.Get_LcomKind(iDgnLcomNo);
		rData.CrmtBase[i].iMax = iMaxMinType;
		rData.CrmtBase[i].dPu = dFxx;
		rData.CrmtBase[i].dTu = dMux;
		rData.CrmtBase[i].dVu = GetVu4TpEx(dFzz, dFz_tp);
		rData.CrmtBase[i].dMu = dMuy;
		rData.CrmtBase[i].dft = dft;
		rData.CrmtBase[i].dfb = dfb;

		// KSCE-LSD15.
		rData.CrmtBase[i].dM_pre = dM_pre[nIx];
		rData.CrmtBase[i].dV_pre = dV_pre[nIx];

		if (i < 3) // I
		{
			adZ_sh[i] = (dMuy < 0.0) ? BdcrD.BdcrBase[1].dz_sh : BdcrD.BdcrBase[0].dz_sh;  // 0=I-MAX, 1=I-MIN, 2=J-MAX, 3=J-MIN.
			adCc_gr[i] = (dMuy < 0.0) ? BdcrD.BdcrBase[1].dCc_gr : BdcrD.BdcrBase[0].dCc_gr;
			adCc_sl[i] = (dMuy < 0.0) ? BdcrD.BdcrBase[1].dCc_sl : BdcrD.BdcrBase[0].dCc_sl;
		}
		else    // J
		{
			adZ_sh[i] = (dMuy < 0.0) ? BdcrD.BdcrBase[3].dz_sh : BdcrD.BdcrBase[2].dz_sh;  // 0=I-MAX, 1=I-MIN, 2=J-MAX, 3=J-MIN.
			adCc_gr[i] = (dMuy < 0.0) ? BdcrD.BdcrBase[3].dCc_gr : BdcrD.BdcrBase[2].dCc_gr;
			adCc_sl[i] = (dMuy < 0.0) ? BdcrD.BdcrBase[3].dCc_sl : BdcrD.BdcrBase[2].dCc_sl;
		}
	}

	if (CDBLib::IsPscCodeLSD(m_iCivilCode) || m_iCivilCode == IRC_112_2011_PSC || m_iCivilCode == IRC_112_2020_PSC)
	{
		if (!m_pPscDataCtrl->Get_CrmtData_Composite(ElemK, MembInD, adZ_sh, adCc_gr, adCc_sl, rData)) return FALSE;
	}
	else if (m_iCivilCode == IRS_PSC)
	{
		CString sBendingErrMsg = _T("");
		CString strIJ = i < 3 ? _T("I") : _T("J");
		CString strPN = i % 2 == 0 ? _T("P") : _T("N"); // Positive/Negative
		CString strPosi;
		strPosi.Format(_T("%d-%s(%s)"), ElemK, strIJ, strPN);
		sBendingErrMsg.Format(_LS(IDS_DGN_WARN_IRS_PSCCOMP_TOR_Err), strPosi); //IDS_DGN_WARN_IRS_PSCCOMP_TOR_Err= _T("[Warning] IRS Torsion Design/Check is Currently Not Supported for PSC COmposite Section(Elem No.: %s).") .
		GSaveHistoryFormatNF(sBendingErrMsg);
	}
	else ASSERT(0);

	return TRUE;
}

BOOL CCRCDataCtrl::Calc_CStageResCpt(ElemPairK ElemK, PSC_DATA_MEMB &MembInD, T_STRS_CPT &StrsD, T_SHRS_CPT &ShrsD, T_FYSG_PSC_COMP &FysgD, T_FPSG_PSC_COMP &FpsgD)
{
	T_CONC_AGE_D AgeD;
	if(!GetInitAgesOfConcrete(ElemK, AgeD)) ASSERT(0);
	BOOL bGetTdme_Gr = AgeD.bTdmeGr;
	BOOL bGetTdme_Sl = AgeD.bTdmeSl;
	int nMatlElastKey_Part1 = AgeD.TdmeKGr;
	int nMatlElastKey_Part2 = AgeD.TdmeKSl;
	double dAgeGr = AgeD.dAgeGr;
	double dAgeSl = AgeD.dAgeSl;

	CArray<T_STAG_K, T_STAG_K> aStagK;
	m_pStageInfo->GetResultSavedStagKeyList(aStagK);
	int nStageSize = aStagK.GetSize();
	if (nStageSize == 0)	return FALSE;

	int nStepGr = 0, nStepSlab = 0;
	double dFirstStep_Day = 0.0;
	double dStartStepSlab = 0.0;
	double dMaxRatioGr[4] = { -DBL_MAX, -DBL_MAX, -DBL_MAX, -DBL_MAX }; // 0=I-MAX, 1=I-MIN, 2=J-MAX, 3=J-MIN.
	double dMaxRatioSl[4] = { -DBL_MAX, -DBL_MAX, -DBL_MAX, -DBL_MAX }; // 0=I-MAX, 1=I-MIN, 2=J-MAX, 3=J-MIN.
	// Modify, Step이 있으면 Step도 고려할 수 있도록 수정. 
	CString strSgldName = _LS(IDS_DB_SGLD_SUM);	// SUM.
	T_SGLD_K SgldK = m_pAttrCtrl->GetSgldKey(strSgldName);
	for (int i = 0; i < nStageSize; ++i)
	{
		T_STAG_K StagK = aStagK.GetAt(i);
		// MQC. 4145
		if (!m_pStageInfo->IsActiveElemInTgtStag(StagK, ElemK)) continue;

		// 0:오류 또는 시공 합성 단면 아님
		// 1:시공 합성 단면 : 합성 전 (Active Stage 이전)
		// 2:시공 합성 단면 : 합성 중 (Active되고 모든 Part가 합성되기 전)
		// 3:시공 합성 단면 : 합성 후 (모든 Part가 합성된 후)
		T_CSCS_D CscsD; CscsD.Initialize();
		int nCompositeType = m_pAttrCtrl->GetElemSectCompositeInfoDgn(ElemK, StagK, CscsD);
		if (nCompositeType == 0 || nCompositeType == 1) continue;

		T_STAG_STEP_INFO StageInfo; StageInfo.Initialize();
		m_pAttrCtrl->GetStagStepInfo(StagK, StageInfo);
		int iStepSize = StageInfo.aInfo.GetSize();
		int nStepArr = iStepSize == 0 ? 1 : iStepSize;
		int nCurStep = 0;
		for (int jj = 0; jj < nStepArr; ++jj)
		{
			T_FYSG_PSC_COMP FysgT;

			_DGN_STRS_CRC StrsMaxGr; // 거더
			_DGN_STRS_CRC StrsMinGr;
			_DGN_STRS_CRC StrsMaxSl; // 슬래브
			_DGN_STRS_CRC StrsMinSl;

			_DGN_SHRS_CRC ShrsMaxGr; // 거더
			_DGN_SHRS_CRC ShrsMinGr;
			_DGN_SHRS_CRC ShrsMaxSl; // 슬래브
			_DGN_SHRS_CRC ShrsMinSl;

			nCurStep = jj + 1;
			if (iStepSize == 0)
			{
				int iFinalStepNo = 0;
				Get_LastStepInCurStage(StagK, iFinalStepNo);
				if (nCompositeType == 2)
				{
					if (!m_ForceCtrl.Get_StrsPartBySgld(ElemK, SgldK, StagK, iFinalStepNo, 1, StrsMaxGr, StrsMinGr))	continue;
					//
					if (!m_ForceCtrl.Get_ShrsPartBySgld(ElemK, SgldK, StagK, iFinalStepNo, 1, ShrsMaxGr, ShrsMinGr, 4))	continue;	// 4=Principal.
				}
				else if (nCompositeType >= 3)
				{
					if (!m_ForceCtrl.Get_StrsPartBySgld(ElemK, SgldK, StagK, iFinalStepNo, 1, StrsMaxGr, StrsMinGr))	continue;
					if (!m_ForceCtrl.Get_StrsPartBySgld(ElemK, SgldK, StagK, iFinalStepNo, 2, StrsMaxSl, StrsMinSl))	continue;
					//
					if (!m_ForceCtrl.Get_ShrsPartBySgld(ElemK, SgldK, StagK, iFinalStepNo, 1, ShrsMaxGr, ShrsMinGr, 4))	continue;	// 4=Principal.
					if (!m_ForceCtrl.Get_ShrsPartBySgld(ElemK, SgldK, StagK, iFinalStepNo, 2, ShrsMaxSl, ShrsMinSl, 4))	continue;	// 4=Principal.
				}
				else ASSERT(0);
			}
			else
			{

				int iSerialStep = 0;
				if (m_pStageInfo->GetStepSerialKey(StagK, nCurStep, iSerialStep))
				{
					if (nCompositeType == 2)
					{
						if (!m_ForceCtrl.Get_StrsPartBySgld(ElemK, SgldK, StagK, iSerialStep, 1, StrsMaxGr, StrsMinGr))	continue;
						//
						if (!m_ForceCtrl.Get_ShrsPartBySgld(ElemK, SgldK, StagK, iSerialStep, 1, ShrsMaxGr, ShrsMinGr, 4))	continue;	// 4=Principal.
					}
					else if (nCompositeType >= 3)
					{
						if (!m_ForceCtrl.Get_StrsPartBySgld(ElemK, SgldK, StagK, iSerialStep, 1, StrsMaxGr, StrsMinGr))	continue;
						if (!m_ForceCtrl.Get_StrsPartBySgld(ElemK, SgldK, StagK, iSerialStep, 2, StrsMaxSl, StrsMinSl))	continue;
						//
						if (!m_ForceCtrl.Get_ShrsPartBySgld(ElemK, SgldK, StagK, iSerialStep, 1, ShrsMaxGr, ShrsMinGr, 4))	continue;	// 4=Principal.
						if (!m_ForceCtrl.Get_ShrsPartBySgld(ElemK, SgldK, StagK, iSerialStep, 2, ShrsMaxSl, ShrsMinSl, 4))	continue;	// 4=Principal.
					}
					else ASSERT(0);
				}
			}
			double dStep_Day = 0.0;
			m_pStageInfo->GetStagStepDay(StagK, nCurStep, dStep_Day); // Stage에서 각 step의 날짜

			nStepGr++;
			if (nStepGr == 1) dFirstStep_Day = dStep_Day;
			double dCurrStepAge = dStep_Day - dFirstStep_Day;

			T_ELFM_D dDayActive; dDayActive.Initialize();
			m_pPostCtrl->GetElfmDgn(StagK, ElemK, dDayActive);

			double dCurrAgeGr = dAgeGr + dCurrStepAge;
			
			double dfci_Gr = 0.0;
			double dfci_Sl = 0.0;
			if (bGetTdme_Gr)
			{
				Get_InitCompressStrength(nMatlElastKey_Part1, dCurrAgeGr, dfci_Gr);
			}
			else
			{
				dfci_Gr = MembInD.Pos[0].MatlD.C_fci;
			}

			if ( nCompositeType >= 3 )
			{
				nStepSlab++;
				if ( nStepSlab == 1 )
				{
					dStartStepSlab = dStep_Day;
				}
			}

			double dCurrAgeSl = dStep_Day - dStartStepSlab + dAgeSl;
			if (bGetTdme_Sl == TRUE)
			{
				if ( nCompositeType >= 3 )
				{
					Get_InitCompressStrength(nMatlElastKey_Part2, dCurrAgeSl, dfci_Sl);
				}
			}
			else if (bGetTdme_Sl == FALSE)  //Part2 의 Material 설정 미지정 시 Part1의 값 사용!
			{
				if(nCompositeType >= 3)
				{
					if(bGetTdme_Gr)
					{
						Get_InitCompressStrength(nMatlElastKey_Part1, dCurrAgeSl, dfci_Sl);
					}
				}
			}
			else ASSERT(0);

			// ************************
			// 파트별 시공단계 응력
			// ************************
			// Set Data. 거더
			for (int kk = 0; kk < 4; ++kk)
			{
				// 0=I-MAX, 1=I-MIN, 2=J-MAX, 3=J-MIN.
				_DGN_STRS_CRC &StrsCrc = (kk % 2 == 0 ? StrsMaxGr : StrsMinGr);
				int nIx = kk / 2;
				if (StrsCrc.dScom[nIx] == 0.0)	continue;

				T_FYSG_PSC_COMP_BASE &FysgB = FysgT.FysgGrBase[kk];
				FysgB.bCHK = Get_ChkFlag(ElemK, nIx, TRUE);
				FysgB.StageK = StrsCrc.iRefNo[nIx];
				FysgB.StepK = StrsCrc.iSerialStep[nIx];
				FysgB.dFT = StrsCrc.dStop[nIx];
				FysgB.dFB = StrsCrc.dSbot[nIx];
				FysgB.dFTL = StrsCrc.dStl[nIx];
				FysgB.dFBL = StrsCrc.dSbl[nIx];
				FysgB.dFTR = StrsCrc.dStr[nIx];
				FysgB.dFBR = StrsCrc.dSbr[nIx];
				FysgB.dFMAX = StrsCrc.dScom[nIx];
				FysgB.dfci = dfci_Gr;
				FysgB.dDuration = dCurrAgeGr;
				FysgB.dALW = 0.0;	// From CRC.
			}

			// Set Data. 슬래브
			for (int kk = 0; kk < 4; ++kk)
			{
				// 0=I-MAX, 1=I-MIN, 2=J-MAX, 3=J-MIN.
				_DGN_STRS_CRC &StrsCrc = (kk % 2 == 0 ? StrsMaxSl : StrsMinSl);
				int nIx = kk / 2;
				if (StrsCrc.dScom[nIx] == 0.0)	continue;

				T_FYSG_PSC_COMP_BASE &FysgB = FysgT.FysgSlBase[kk];
				FysgB.bCHK = Get_ChkFlag(ElemK, nIx, TRUE);
				FysgB.StageK = StrsCrc.iRefNo[nIx];
				FysgB.StepK = StrsCrc.iSerialStep[nIx];
				FysgB.dFT = StrsCrc.dStop[nIx];
				FysgB.dFB = StrsCrc.dSbot[nIx];
				FysgB.dFTL = StrsCrc.dStl[nIx];
				FysgB.dFBL = StrsCrc.dSbl[nIx];
				FysgB.dFTR = StrsCrc.dStr[nIx];
				FysgB.dFBR = StrsCrc.dSbr[nIx];
				FysgB.dFMAX = StrsCrc.dScom[nIx];
				FysgB.dfci = dfci_Sl;
				FysgB.dDuration = dCurrAgeSl;
				FysgB.dALW = 0.0;	// From CRC.
			}

			switch (m_iCivilCode)
			{
			case KDS_24_14_21_2022_PSC:
			case KSCE_LSD15_PSC:
			case EUROCODE2_2_05_PSC:
			case IRC_112_2011_PSC:
			case IRC_112_2020_PSC:
			case AS_5100_5_17_PSC:
			case IRS_PSC:
			case TMH07_3_1989:
			case BS5400_90_PSC:
			case ABNT_NBR_6118_2023_PSC:
			{
				if (!m_pPscDataCtrl->Get_FysgData_Composite(ElemK, MembInD, FysgT)) return FALSE;
				//
				//if ( !m_pPscDataCtrl->Get_FpsgData_Composite(ElemK, MembInD, FpsgD) ) return FALSE;
				break;
			}
			default:
			{ASSERT(0); break; }
			}

			for (int kk = 0; kk < 4; ++kk)
			{
				double dRatioGr = fabs(FysgT.FysgGrBase[kk].dRatio);
				if (!FysgT.FysgGrBase[kk].bCHK) continue;
				if (dMaxRatioGr[kk] <= dRatioGr)
				{
					dMaxRatioGr[kk] = dRatioGr;
					FysgD.FysgGrBase[kk] = FysgT.FysgGrBase[kk];
				}
			}
			for (int kk = 0; kk < 4; ++kk)
			{
				double dRatioSl = fabs(FysgT.FysgSlBase[kk].dRatio);
				if (!FysgT.FysgSlBase[kk].bCHK) continue;
				if (dMaxRatioSl[kk] <= dRatioSl)
				{
					dMaxRatioSl[kk] = dRatioSl;
					FysgD.FysgSlBase[kk] = FysgT.FysgSlBase[kk];
				}
			}
		}
	}

	return TRUE;
}

