BOOL CCRCDataCtrl::Get_BdcrDataSNiP(ElemPairK ElemK, T_BDCR_SNIP &rData)
{
	rData.Initialize();
	// Check Calculating Item.
	if (!Is_CalcItem(ElemK, TRUE))  return FALSE;
	// PSC-Design/Strs(5), PSC-Design/Strn(6).
	int iDgnStatus = m_pDoc->GetDesignStatus();
	m_pDoc->SetDesignStatus(6);

	double dMyMax[2] = { 0.,0. }, dMyMin[2] = { 0.,0. };
	int iMaxDgnLcom[2] = { 0,0 }, iMinDgnLcom[2] = { 0,0 };

	// 필요한 Force Max/Min 값을 찾음.
	BOOL bStrength = TRUE;
	if (!Get_CheckForceMu_MaxMin(bStrength, ElemK, dMyMax, dMyMin, iMaxDgnLcom, iMinDgnLcom)) return FALSE;

	for (int i = 0; i < 4; ++i)
	{
		// 0=I-MAX, 1=I-MIN, 2=J-MAX, 3=J-MIN.
		int iDgnLcomNo = (i % 2 == 0 ? iMaxDgnLcom[i / 2] : iMinDgnLcom[i / 2]);
		CString strOrgLcomNa = _T("");
		int iMaxMinType = 0;
		if (!m_ForceCtrl.Get_LcomType(iDgnLcomNo, strOrgLcomNa, iMaxMinType))	ASSERT(0);
		double dMuy = (i % 2 == 0 ? dMyMax[i / 2] : dMyMin[i / 2]);
		if (i % 2 == 0) { dMuy = (dMuy < 0.0 ? 0.0 : dMuy); }
		else { dMuy = (dMuy > 0.0 ? 0.0 : dMuy); }

		rData.BdcrBase[i].bCHK = Get_ChkFlag(ElemK, i / 2, TRUE);
		rData.BdcrBase[i].LcomK = iDgnLcomNo;
		rData.BdcrBase[i].iKind = m_ForceCtrl.Get_LcomKind(iDgnLcomNo);
		rData.BdcrBase[i].iMax = iMaxMinType;
		rData.BdcrBase[i].dMu = dMuy;
	}

	if (!m_pPscDataCtrl->Get_BdcrDataSNiP(ElemK, rData)) return FALSE;

	CString sBendingErrMsg = _T("");
	for (int i = 0; i < 4; ++i)
	{
		if (rData.BdcrBase[i].bCHK)
		{
			CString strIJ = i < 2 ? _T("I") : _T("J");
			if (rData.BdcrBase[i].bOK == D_PSC_FRC_ERR_Iteration_Over)
			{
				CString strPN = i % 2 == 0 ? _T("P") : _T("N"); // Positive/Negative
				CString strPosi;
				strPosi.Format(_T("%d-%s(%s)"), ElemK, strIJ, strPN);
				sBendingErrMsg.Format(_LS(IDS_DGN_WARN_BEND_NEUTRAL_AXIS_Err), strPosi); // [Warning] Midas Civil has failed to find the neutral axis(member no.: xxxx). Please check the PSC Design Calculation sheet for details.
				GSaveHistoryFormatNF(sBendingErrMsg);
			}
		}
	}

	return TRUE;
}

BOOL CCRCDataCtrl::Get_CumsDataSNiP(ElemPairK ElemK, T_CUMS_SNIP &rCums, T_CRMT_SNIP &rCrmt)
{
	rCums.Initialize();
	rCrmt.Initialize();
	// Check Calculating Item.
	if (!Is_CalcItem(ElemK, FALSE))  return FALSE;
	// PSC-Design/Strs(5), PSC-Design/Strn(6).
	int iDgnStatus = m_pDoc->GetDesignStatus();
	m_pDoc->SetDesignStatus(6);

	_DGN_FORC_CRC ForceFzMaxD;
	_DGN_FORC_CRC ForceFzMinD;
	_DGN_STRS_CRC StressFzMaxD;
	_DGN_STRS_CRC StressFzMinD;

	double dFzMax[2] = { 0,0 }, dFzMin[2] = { 0,0 };
	double dFzMaxMy[2] = { 0,0 }, dFzMinMy[2] = { 0,0 };
	double dFzMaxFx[2] = { 0,0 }, dFzMinFx[2] = { 0,0 };
	int iMaxDgnLcom[2] = { 0,0 }, iMinDgnLcom[2] = { 0,0 };

	//////////////////////////////////////////////////////////////////////////  
	CString strTP = _LS(IDS_DB_SGLD_TP);
	T_SGLD_K SgldTempK = m_pAttrCtrl->GetSgldKey(strTP);
	T_STEP_K StepK = 0;
	T_LCOM_D LcasD;
	T_STRB_D StrbMax; StrbMax.Initialize();
	m_pPostCtrl->MakeLoadComb(D_LOADCASE_STAGE, SgldTempK, LcasD);
	m_pPostCtrl->SelectLoadCombNew(LcasD, StepK, 2);	// 0=Nonlinear, 1=Pushover, 2=Consruction.	  
	m_pPostCtrl->GetStrbNew(ElemK.first, &StrbMax, NULL, NULL, FALSE, NULL, ElemK.second);
	double dFx_TP[2] = { 0.0, 0.0 };
	dFx_TP[0] = StrbMax.dblForce[0][0];
	dFx_TP[1] = StrbMax.dblForce[3][6];
	//////////////////////////////////////////////////////////////////////////  

	if (!Get_CumsForceFz_MaxMin(ElemK, ForceFzMaxD, ForceFzMinD, StressFzMaxD, StressFzMinD, iMaxDgnLcom, iMinDgnLcom)) return FALSE;
	for (int i = 0; i < 2; ++i)
	{
		dFzMax[i] = ForceFzMaxD.dFzz[i];
		dFzMaxMy[i] = ForceFzMaxD.dMuy[i];
		dFzMaxFx[i] = ForceFzMaxD.dFxx[i];
		//
		dFzMin[i] = ForceFzMinD.dFzz[i];
		dFzMinMy[i] = ForceFzMinD.dMuy[i];
		dFzMinFx[i] = ForceFzMinD.dFxx[i];
	}

	for (int i = 0; i < 4; ++i)
	{
		// 0=I-MAX, 1=I-MIN, 2=J-MAX, 3=J-MIN.
		int nIx = i / 2;
		int iDgnLcomNo = (i % 2 == 0 ? iMaxDgnLcom[nIx] : iMinDgnLcom[nIx]);
		CString strOrgLcomNa = _T("");
		int iMaxMinType = 0;
		if (!m_ForceCtrl.Get_LcomType(iDgnLcomNo, strOrgLcomNa, iMaxMinType))	ASSERT(0);
		double dFzz = (i % 2 == 0 ? dFzMax[nIx] : dFzMin[nIx]);
		double dMuy = (i % 2 == 0 ? dFzMaxMy[nIx] : dFzMinMy[nIx]);
		double dFxx = (i % 2 == 0 ? dFzMaxFx[nIx] + dFx_TP[nIx] : dFzMinFx[nIx] + dFx_TP[nIx]);
		double dft = (i % 2 == 0 ? StressFzMaxD.dStop[nIx] : StressFzMinD.dStop[nIx]);
		double dfb = (i % 2 == 0 ? StressFzMaxD.dSbot[nIx] : StressFzMinD.dSbot[nIx]);

		rCums.CumsBase[i].bCHK = Get_ChkFlag(ElemK, nIx, FALSE);
		rCums.CumsBase[i].LcomK = iDgnLcomNo;
		rCums.CumsBase[i].iKind = m_ForceCtrl.Get_LcomKind(iDgnLcomNo);
		rCums.CumsBase[i].iMax = iMaxMinType;
		rCums.CumsBase[i].dPu = dFxx;
		rCums.CumsBase[i].dQu = dFzz;
		rCums.CumsBase[i].dMu = dMuy;
	}

	if (!m_pPscDataCtrl->Get_CumsDataSNiP(ElemK, rCums)) return FALSE;

	return TRUE;
}

BOOL CCRCDataCtrl::Get_FatiDataSNiP(ElemPairK ElemK, T_FATI_SNIP &rData)
{
	rData.Initialize();
	// Check Calculating Item.
	if (!Is_CalcItem(ElemK, TRUE))  return FALSE;
	// PSC-Design/Strs(5), PSC-Design/Strn(6).
	int iDgnStatus = m_pDoc->GetDesignStatus();
	m_pDoc->SetDesignStatus(5);

	double dMyMax[2] = { 0.,0. }, dMyMin[2] = { 0.,0. };
	int iMaxDgnLcom[2] = { 0,0 }, iMinDgnLcom[2] = { 0,0 };
	double dMaxRat[4] = { 0.0 };
	int iCheckCount[4] = { 0 };

	T_FATI_SNIP FatiD;
	int iLcomNum = m_ForceCtrl.Get_LcomDataCount();
	ADGNFORCE aForceLcom;
	if (!m_ForceCtrl.Get_LcomDataForDesign(ElemK, 0, TRUE, FALSE, aForceLcom, iLcomNum))	return FALSE;

	ADGNSTRESS aStressLcom;
	ADGNSTRESS aStressTnpr;
	if (!m_ForceCtrl.Get_LcomDataForStress(ElemK, 0, TRUE, FALSE, aStressLcom, aStressTnpr, iLcomNum)) return FALSE;

	// 전체하중조합을 검토한다.
	int iLcomSize = aForceLcom.GetSize();
	int nStressLcomSize = aStressLcom.GetSize();
	for (int i = 0; i < iLcomSize; ++i)
	{
		if (!m_ForceCtrl.Is_LcomForStrs(i + 1))	continue;
		_DGN_FORC_CRC &ForceD = aForceLcom[i];
		_DGN_STRS_CRC &StressD = aStressLcom[i];
		FatiD.Initialize();

		int iDgnLcomNo = i + 1;
		CString strOrgLcomNa = _T("");
		int iMaxMinType = 0;
		if (!m_ForceCtrl.Get_LcomType(iDgnLcomNo, strOrgLcomNa, iMaxMinType))	ASSERT(0);

		for (int j = 0; j < 4; ++j)
		{
			double dMuy = (j < 2 ? ForceD.dMuy[0] : ForceD.dMuy[1]);
			double dFxx = (j < 2 ? ForceD.dFxx[0] : ForceD.dFxx[1]);
			double dft = (j < 2 ? StressD.dStop[0] : StressD.dStop[1]);
			double dfb = (j < 2 ? StressD.dSbot[0] : StressD.dSbot[1]);
			//if(j%2==1) { dMuy = ( dMuy<0.0 ? 0.0 : dMuy ); } // negative면 Top검토 
			//else       { dMuy = ( dMuy>0.0 ? 0.0 : dMuy ); }

			FatiD.FatiBase[j].bCHK = Get_ChkFlag(ElemK, j / 2, TRUE);
			FatiD.FatiBase[j].LcomK = iDgnLcomNo;
			FatiD.FatiBase[j].nKind = m_ForceCtrl.Get_ServLcomType(iDgnLcomNo);
			FatiD.FatiBase[j].nLSTerm = m_ForceCtrl.Get_LcomKind(iDgnLcomNo);
			FatiD.FatiBase[j].nMax = iMaxMinType;
			//       FatiD.FatiBase[j].dPu   = dFxx;
			//       FatiD.FatiBase[j].dMu   = dMuy;
			//       FatiD.FatiBase[j].dft   = dft;
			//       FatiD.FatiBase[j].dfb   = dfb;
		}
		//
		if (!m_pPscDataCtrl->Get_FatiDataSNiP(ElemK, FatiD)) return FALSE;

		for (int j = 0; j < 4; ++j)
		{
			T_FATI_SNIP_BASE FatiBaseD = FatiD.FatiBase[j];
			ASSERT(0);
			//       if (FatiBaseD.bCHK) iCheckCount[j] += 1;
			//     
			//       if (iCheckCount[j]==1)
			//       {            
			//         dMaxRat[j] = FatiBaseD.dRatio;
			//         rData.FatiBase[j] = FatiBaseD;
			//       }
			//       else if (iCheckCount[j]>1)
			//       {
			//         if(dMaxRat[j]<FatiBaseD.dRatio)
			//         {
			//           dMaxRat[j]=FatiBaseD.dRatio;
			//           rData.FatiBase[j] = BdcwBaseD;
			//         }            
			//       }
		}
	} // i End

	return TRUE;
}

BOOL CCRCDataCtrl::Get_PSCCheckResultAS(ElemPairK ElemK, T_DRST_D &Drst)
{
	BOOL bComposite = IsCompositePSCSect(ElemK);

	PSC_DATA_MEMB PscMembD;
	if (!m_pPscDataCtrl->Get_PscDataPosi(ElemK, 0, PscMembD.Pos[0], bComposite)) return FALSE;
	if (!m_pPscDataCtrl->Get_PscDataPosi(ElemK, 1, PscMembD.Pos[1], bComposite)) return FALSE;
	//PscMembD.Pos[0].pTdnaInfo = &m_TdnaInfo;
	//PscMembD.Pos[1].pTdnaInfo = &m_TdnaInfo;

	CPCDesign *pPCDgn = m_pPostCtrl->GetPCDesign();

	double dHeight[2] = { 0.0 };
	dHeight[0] = PscMembD.Pos[0].SectgD.dzDim;
	dHeight[1] = PscMembD.Pos[1].SectgD.dzDim;
	m_ForceCtrl.Set_SectHeight4PscGen(dHeight);

	T_FYSG_PSC_AS FysgD; FysgD.bComposite = bComposite;
	T_FPMT_JTG    FpsgD;
	Get_CStageResPSC_AS(ElemK, PscMembD, FysgD, FpsgD);
	pPCDgn->WriteFysg_AS(ElemK, FysgD);
	pPCDgn->WriteFssg_AASHTO(ElemK, FpsgD);

	T_TRAN_PSC_AS TranD;
	T_BDCW_PSC_AS TrcrD;

	Get_TransferPSC_AS(ElemK, PscMembD, TranD, TrcrD);
	pPCDgn->WriteTran_AS(ElemK, TranD);
	pPCDgn->WriteTrcr_AS(ElemK, TrcrD);

	T_FYCM_PSC_AS FycmD; FycmD.bComposite = bComposite;
	T_FPMS_PSC    FpmsD;
	Get_StressResSLSPSC_AS(ElemK, PscMembD, FycmD, FpmsD);
	pPCDgn->WriteFycm_AS(ElemK, FycmD);
	pPCDgn->WriteFpms_PSC(ElemK, FpmsD);

	T_BDCW_PSC_AS BdcwD; BdcwD.bComposite = bComposite;
	Get_CrackResSLSPSC_AS(ElemK, PscMembD, BdcwD);
	pPCDgn->WriteBdcw_AS(ElemK, BdcwD);

	T_BDCR_PSC_AS BdcrD; BdcrD.bComposite = bComposite;
	T_SHRR_PSC_AS ShrrD; ShrrD.bComposite = bComposite;
	T_TORR_PSC_AS TorrD; TorrD.bComposite = bComposite;
	Get_StrengthResULSPSC_AS(ElemK, PscMembD, BdcrD, ShrrD, TorrD);

	pPCDgn->WriteBdcr_AS(ElemK, BdcrD);
	pPCDgn->WriteShrr_AS(ElemK, ShrrD);
	pPCDgn->WriteTorr_AS(ElemK, TorrD);

	if (Drst.bFysg == FALSE)
	{
		Drst.bFysg = (FysgD.FysgGrB[0].bCHK || FysgD.FysgGrB[1].bCHK || FysgD.FysgGrB[2].bCHK || FysgD.FysgGrB[3].bCHK);
	}
	if (Drst.bFpsg == FALSE)
	{
		Drst.bFpsg = (FpsgD.FpmtBase[0].bCHK || FpsgD.FpmtBase[1].bCHK || FpsgD.FpmtBase[2].bCHK || FpsgD.FpmtBase[3].bCHK);
	}
	if (Drst.bFycm == FALSE)
	{
		Drst.bFycm = (FycmD.FycmGrB[0].bCHK || FycmD.FycmGrB[1].bCHK || FycmD.FycmGrB[2].bCHK || FycmD.FycmGrB[3].bCHK);
	}
	if (Drst.bFpms == FALSE)
	{
		Drst.bFpms = (FpmsD.FpmsBase[0].bCHK || FpmsD.FpmsBase[1].bCHK || FpmsD.FpmsBase[2].bCHK || FpmsD.FpmsBase[3].bCHK);
	}
	if (Drst.bBdcw == FALSE)
	{
		Drst.bBdcw = (BdcwD.BdcwB[0].bCHK || BdcwD.BdcwB[1].bCHK || BdcwD.BdcwB[2].bCHK || BdcwD.BdcwB[3].bCHK);
	}
	if (Drst.bBdcr == FALSE)
	{
		Drst.bBdcr = (BdcrD.BdcrB[0].bCHK || BdcrD.BdcrB[1].bCHK || BdcrD.BdcrB[2].bCHK || BdcrD.BdcrB[3].bCHK);
	}
	if (Drst.bShrr == FALSE)
	{
		Drst.bShrr = (ShrrD.ShrrB[0].bCHK || ShrrD.ShrrB[1].bCHK || ShrrD.ShrrB[2].bCHK || ShrrD.ShrrB[3].bCHK);
	}
	if (Drst.bTorr == FALSE)
	{
		Drst.bTorr = (TorrD.TorrB[0].bCHK || TorrD.TorrB[1].bCHK || TorrD.TorrB[2].bCHK || TorrD.TorrB[3].bCHK);
	}
	if (Drst.bTran == FALSE)
	{
		Drst.bTran = (TranD.GrB[0].bCHK || TranD.GrB[1].bCHK || TranD.GrB[2].bCHK || TranD.GrB[3].bCHK);
	}
	if (Drst.bTrcr == FALSE)
	{
		Drst.bTrcr = (TrcrD.BdcwB[0].bCHK || TrcrD.BdcwB[1].bCHK || TrcrD.BdcwB[2].bCHK || TrcrD.BdcwB[3].bCHK);
	}

	return TRUE;
}

