BOOL CCRCDataCtrl::Get_CStageResPSC_AS(ElemPairK ElemK, PSC_DATA_MEMB &MembInD, T_FYSG_PSC_AS &FysgD, T_FPMT_JTG &FpsgD)
{
	if (!Is_CalcItem(ElemK, TRUE))  return FALSE;
	int iDgnStatus = m_pDoc->GetDesignStatus();
	m_pDoc->SetDesignStatus(5);

	BOOL bIsCpt = IsCompositePSCSect(ElemK);
	T_CONC_AGE_D AgeD;
	if(!GetInitAgesOfConcrete(ElemK, AgeD)) ASSERT(0);
	BOOL bGetTdme = AgeD.bTdmeGr;
	BOOL bGetTdmeSL = AgeD.bTdmeSl;
	double dAgeGr = 0.0;
	double dAgeSl = 0.0;
	if(bIsCpt)
	{
		dAgeGr = AgeD.dAgeGr;
		dAgeSl = AgeD.dAgeSl;
	}

	_DGN_STRS_CRC StrsMax;
	_DGN_STRS_CRC StrsMin;

	_DGN_SHRS_CRC ShrsMax;
	_DGN_SHRS_CRC ShrsMin;

	CArray<T_STAG_K, T_STAG_K> aStagK;
	m_pStageInfo->GetResultSavedStagKeyList(aStagK);
	if (aStagK.GetSize() == 0)	return FALSE;

	int nStepGr=0, nStepSlab = 0;
	double dFirstStep_Day = 0.0;
	double dStartStepSlab = 0.0;
    // Modify, Step이 있으면 Step도 고려할 수 있도록 수정. 
    CString strSgldName = _LS(IDS_DB_SGLD_SUM);	// SUM.
    T_SGLD_K SgldK = m_pAttrCtrl->GetSgldKey(strSgldName);
    for(int i=0; i<aStagK.GetSize(); ++i)
    {
        T_STAG_K StagK = aStagK.GetAt(i);
        if(!m_pStageInfo->IsActiveElemInTgtStag(StagK, ElemK)) continue;

		T_STAG_STEP_INFO StageInfo; StageInfo.Initialize();
		m_pAttrCtrl->GetStagStepInfo(StagK, StageInfo);
		int iStepSize = StageInfo.aInfo.GetSize();
		int nStepArr = iStepSize == 0 ? 1 : iStepSize;
		int iSerialStep = 0;
		int nCurStep = 0;

		// 0:오류 또는 시공 합성 단면 아님
		// 1:시공 합성 단면 : 합성 전 (Active Stage 이전)
		// 2:시공 합성 단면 : 합성 중 (Active되고 모든 Part가 합성되기 전)
		// 3:시공 합성 단면 : 합성 후 (모든 Part가 합성된 후)
		T_CSCS_D CscsD; CscsD.Initialize();
		int nCompositeType = m_pAttrCtrl->GetElemSectCompositeInfoDgn(ElemK, StagK, CscsD);
		if (bIsCpt == TRUE)
		{
			if (nCompositeType == 0 || nCompositeType == 1) continue;
		}
		
		for (int jj = 0; jj < nStepArr; ++jj)
		{
			_DGN_STRS_CRC StrsStagCurMax;
			_DGN_STRS_CRC StrsStagCurMin;
			_DGN_STRS_CRC StrsStagCurMax_Sl;
			_DGN_STRS_CRC StrsStagCurMin_Sl;

			_DGN_SHRS_CRC ShrsStagCurMax;
			_DGN_SHRS_CRC ShrsStagCurMin;
			_DGN_SHRS_CRC ShrsStagCurMax_Sl;
			_DGN_SHRS_CRC ShrsStagCurMin_Sl;

			nCurStep = jj + 1;
			if (iStepSize == 0)
			{
				Get_LastStepInCurStage(StagK, iSerialStep);
			}
			else
			{
				iSerialStep = 0;
				if (!m_pStageInfo->GetStepSerialKey(StagK, nCurStep, iSerialStep)) continue;
			}

			if (bIsCpt == FALSE)
			{
				if (!m_ForceCtrl.Get_StrsBySgld(ElemK, SgldK, StagK, iSerialStep, StrsStagCurMax, StrsStagCurMin))	continue;
				//
				if (!m_ForceCtrl.Get_ShrsBySgld(ElemK, SgldK, StagK, iSerialStep, ShrsStagCurMax, ShrsStagCurMin, 4))	continue;	// 4=Principal.
			}
			else
			{
				if (nCompositeType == 2)
				{
					if (!m_ForceCtrl.Get_StrsPartBySgld(ElemK, SgldK, StagK, iSerialStep, 1, StrsStagCurMax, StrsStagCurMin))	continue;
					if (!m_ForceCtrl.Get_ShrsPartBySgld(ElemK, SgldK, StagK, iSerialStep, 1, ShrsStagCurMax, ShrsStagCurMin, 4))	continue;	// 4=Principal.
				}
				else if (nCompositeType >= 3)
				{
					if (!m_ForceCtrl.Get_StrsPartBySgld(ElemK, SgldK, StagK, iSerialStep, 1, StrsStagCurMax, StrsStagCurMin))	continue;
					if (!m_ForceCtrl.Get_StrsPartBySgld(ElemK, SgldK, StagK, iSerialStep, 2, StrsStagCurMax_Sl, StrsStagCurMin_Sl))	continue;
					//
					if (!m_ForceCtrl.Get_ShrsPartBySgld(ElemK, SgldK, StagK, iSerialStep, 1, ShrsStagCurMax, ShrsStagCurMin, 4))	continue;	// 4=Principal.
					if (!m_ForceCtrl.Get_ShrsPartBySgld(ElemK, SgldK, StagK, iSerialStep, 2, ShrsStagCurMax_Sl, ShrsStagCurMin_Sl, 4))	continue;	// 4=Principal.
				}
				else ASSERT(0);
			}

			double dStep_Day=0.0;
            m_pStageInfo->GetStagStepDay(StagK, nCurStep, dStep_Day); // Stage에서 각 step의 날짜

			nStepGr++;
			if (nStepGr == 1) dFirstStep_Day = dStep_Day;
			double dCurrStepAge = dStep_Day - dFirstStep_Day;

            T_ELFM_D dDayActive; dDayActive.Initialize();
			m_pPostCtrl->GetElfmDgn(StagK, ElemK, dDayActive);

			double dCurrAgeGr = dAgeGr + dCurrStepAge;

            double dfci=0.0;
            if(bGetTdme) Get_InitCompressStrength(AgeD.TdmeKGr, dCurrAgeGr, dfci);

			if ( nCompositeType >= 3 )
			{
				nStepSlab++;
				if ( nStepSlab == 1 )
				{
					dStartStepSlab = dStep_Day;
				}
			}

            double dfci_sl= 0.0;
			if ( bGetTdmeSL )
			{
				if ( nCompositeType >= 3 )
				{
					double dCurrAgeSl = dStep_Day - dStartStepSlab + dAgeSl;
					Get_InitCompressStrength(AgeD.TdmeKSl, dCurrAgeSl, dfci_sl);
				}				
			}

			for (int kk = 0; kk < 4; ++kk)
			{
				// 0=I-MAX, 1=I-MIN, 2=J-MAX, 3=J-MIN.
				_DGN_STRS_CRC &StrsCrc = (kk % 2 == 0 ? StrsStagCurMax : StrsStagCurMin);
				//if(StrsCrc.dScom[i/2]==0.0)	continue;
				FysgD.FysgGrB[kk].bCHK = Get_ChkFlag(ElemK, kk / 2, TRUE);
				FysgD.FysgGrB[kk].StageK = StrsCrc.iRefNo[kk / 2];
				FysgD.FysgGrB[kk].StepK = iSerialStep;
				FysgD.FysgGrB[kk].dFT = StrsCrc.dStop[kk / 2];
				FysgD.FysgGrB[kk].dFB = StrsCrc.dSbot[kk / 2];
				FysgD.FysgGrB[kk].dFTL = StrsCrc.dStl[kk / 2];
				FysgD.FysgGrB[kk].dFBL = StrsCrc.dSbl[kk / 2];
				FysgD.FysgGrB[kk].dFTR = StrsCrc.dStr[kk / 2];
				FysgD.FysgGrB[kk].dFBR = StrsCrc.dSbr[kk / 2];
				FysgD.FysgGrB[kk].dFMAX = StrsCrc.dScom[kk / 2];

				FysgD.FysgGrB[kk].dfci = dfci;
				FysgD.FysgGrB[kk].dALW = 0.0;

                if (bIsCpt==TRUE && nCompositeType >= 3 )
                {
                    _DGN_STRS_CRC &StrsCrc_Sl = (kk%2==0 ? StrsStagCurMax_Sl : StrsStagCurMin_Sl);
                    FysgD.FysgSlB[kk].bCHK	 = Get_ChkFlag(ElemK, kk/2, TRUE);
                    FysgD.FysgSlB[kk].StageK = StrsCrc_Sl.iRefNo[kk/2];
                    FysgD.FysgSlB[kk].StepK	 = iSerialStep;
                    FysgD.FysgSlB[kk].dFT		 = StrsCrc_Sl.dStop[kk/2];
                    FysgD.FysgSlB[kk].dFB		 = StrsCrc_Sl.dSbot[kk/2];
                    FysgD.FysgSlB[kk].dFTL	 = StrsCrc_Sl.dStl[kk/2];
                    FysgD.FysgSlB[kk].dFBL	 = StrsCrc_Sl.dSbl[kk/2];
                    FysgD.FysgSlB[kk].dFTR	 = StrsCrc_Sl.dStr[kk/2];
                    FysgD.FysgSlB[kk].dFBR	 = StrsCrc_Sl.dSbr[kk/2];
                    FysgD.FysgSlB[kk].dFMAX  = StrsCrc_Sl.dScom[kk/2];

					FysgD.FysgSlB[kk].dfci = dfci_sl;
					FysgD.FysgSlB[kk].dALW = 0.0;
				}

				_DGN_SHRS_CRC &ShrsKsce = (kk % 2 == 0 ? ShrsStagCurMax : ShrsStagCurMin);
				if (ShrsKsce.dSspAbs[kk / 2] == 0.0)	continue;

				FpsgD.FpmtBase[kk].bCHK = Get_ChkFlag(ElemK, kk / 2, FALSE);
				FpsgD.FpmtBase[kk].LcomK = ShrsKsce.iRefNo[kk / 2]; // LcomK에 Stage Key를 입력한다.     
				FpsgD.FpmtBase[kk].dFP1 = ShrsKsce.dSsp[kk / 2][0];
				FpsgD.FpmtBase[kk].dFP2 = ShrsKsce.dSsp[kk / 2][1];
				FpsgD.FpmtBase[kk].dFP3 = ShrsKsce.dSsp[kk / 2][2];
				FpsgD.FpmtBase[kk].dFP4 = ShrsKsce.dSsp[kk / 2][3];
				FpsgD.FpmtBase[kk].dFP5 = ShrsKsce.dSsp[kk / 2][4];
				FpsgD.FpmtBase[kk].dFP6 = ShrsKsce.dSsp[kk / 2][5];
				FpsgD.FpmtBase[kk].dFP7 = ShrsKsce.dSsp[kk / 2][6];
				FpsgD.FpmtBase[kk].dFP8 = ShrsKsce.dSsp[kk / 2][7];
				FpsgD.FpmtBase[kk].dFP9 = ShrsKsce.dSsp[kk / 2][8];
				FpsgD.FpmtBase[kk].dFP10 = ShrsKsce.dSsp[kk / 2][9];
				FpsgD.FpmtBase[kk].dFMAX = ShrsKsce.dSspAbs[kk / 2];	//Max,Min
				FpsgD.FpmtBase[kk].dfci = dfci;
				FpsgD.FpmtBase[kk].dAFP = 0.0;	// From JTG D62-04          
			}

			m_pPscDataCtrl->Get_StressCheckCS(ElemK, MembInD, FysgD, FpsgD);
		}
	}

	for (int m = 0; m < 4; ++m)
	{
		auto& FysgGrB = FysgD.FysgGrB[m];
		FysgGrB.dFT   *= -1.0;
		FysgGrB.dFB   *= -1.0;
		FysgGrB.dFTL  *= -1.0;
		FysgGrB.dFBL  *= -1.0;
		FysgGrB.dFTR  *= -1.0;
		FysgGrB.dFBR  *= -1.0;
		FysgGrB.dFMAX *= -1.0;

		auto& FysgSlB = FysgD.FysgSlB[m];
		FysgSlB.dFT   *= -1.0;
		FysgSlB.dFB   *= -1.0;
		FysgSlB.dFTL  *= -1.0;
		FysgSlB.dFBL  *= -1.0;
		FysgSlB.dFTR  *= -1.0;
		FysgSlB.dFBR  *= -1.0;
		FysgSlB.dFMAX *= -1.0;				
	}		

	return TRUE;
}

BOOL CCRCDataCtrl::Get_TransferPSC_AS(ElemPairK ElemK, PSC_DATA_MEMB &MembInD, T_TRAN_PSC_AS& TranD, T_BDCW_PSC_AS &CrackD)
{
	if (!Is_CalcItem(ElemK, TRUE))  return FALSE;
	int iDgnStatus = m_pDoc->GetDesignStatus();
	m_pDoc->SetDesignStatus(5);

	BOOL bChkI = Get_ChkFlag(ElemK, 0, TRUE);
	BOOL bChkJ = Get_ChkFlag(ElemK, 1, TRUE);

	BOOL bIsCpt = IsCompositePSCSect(ElemK);

	int nMatlK = GetMaterialKey4ElemPairK(ElemK);

	BOOL bGetTdme = FALSE;
	T_TMAT_D TmatD; TmatD.Initialize();
	if (m_pPostCtrl->GetTmatPost(nMatlK, TmatD))
		bGetTdme = m_pAttrCtrl->ExistTdme(TmatD.TdMatlElastKey);

	CArray<T_STAG_K, T_STAG_K> aStagK;
	m_pStageInfo->GetResultSavedStagKeyList(aStagK);
	if (aStagK.GetSize() == 0)	return FALSE;

	_DGN_STRS_CRC StrsMax;
	_DGN_STRS_CRC StrsMin;

	int nStepNo = m_pTendonInfo->GetTendonPrestressedStep(ElemK);  // Serial Step 인가?
	T_STAG_K StagK = m_pStageInfo->GetStagKeyBySerial(nStepNo);

	T_CSCS_D CscsD; CscsD.Initialize();
	int nCompositeType = m_pAttrCtrl->GetElemSectCompositeInfoDgn(ElemK, StagK, CscsD);

	T_STAG_STEP_INFO StageInfo; StageInfo.Initialize();
	m_pAttrCtrl->GetStagStepInfo(StagK, StageInfo);
	int nStepSize = StageInfo.aInfo.GetSize();

	T_STCT_D StctD; StctD.Initialize();
	m_pAttrCtrl->GetStct(StctD);

    double dDay=0.0;
    Get_Day4fci(ElemK, bIsCpt, TRUE, StagK, nStepNo, dDay);
    double dfci=0.0;
    if ( MembInD.Pos[0].MatlD.bfci_u )
    {
        dfci = MembInD.Pos[0].MatlD.C_fci;
    }
    else
    {
        if ( bGetTdme )
        {
            Get_InitCompressStrength(TmatD.TdMatlElastKey, dDay, dfci);
        }
        else
        {
            dfci = MembInD.Pos[0].MatlD.C_fci;
        }        
    }
    
	double dfcp_cr[4] = { 0.0, };
	double dfct_cr[4] = { 0.0, };
	_BDCW_PSC_LRFD_BASE BdcwCrD[4];  //0=I-Top, 1=I-Bottom, 2=J-Top. 3=J-Bottom

	int nChkTB[4] = { 0, };

	for (INT_PTR i = 0; i < m_ForceCtrl.m_aTranDgnLcomK.GetSize(); ++i)
	{
		int nDgnLcomNo = m_ForceCtrl.m_aTranDgnLcomK[i];

		_DGN_LCOM LcomD;
		m_ForceCtrl.Get_DgnLcomData(nDgnLcomNo, LcomD);

		CString strOrgLcomNa = _T("");
		int nLcomK = 0;
		int nSerLcomCount = 0;
		int nMaxMinType = 0;
		if (!m_ForceCtrl.Get_LcomType(nDgnLcomNo, strOrgLcomNa, nLcomK, nSerLcomCount, nMaxMinType))
		{
			ASSERT(0);
		}

		_DGN_STRS_CRC StressD;
		_DGN_STRS_CRC StrLTD;
		_DGN_STRS_CRC StrSTD;

		_DGN_FORC_CRC FcsDL;
		_DGN_STRS_CRC StrP2;
		_DGN_STRS_CRC StrLTP2;
		_DGN_STRS_CRC StrSTP2;
		m_ForceCtrl.Get_Strs4Tranfer(StctD, ElemK, bIsCpt, nDgnLcomNo, StagK, nStepNo, StressD, StrLTD, StrSTD, StrP2, StrLTP2, StrSTP2);

		for (int kk = 0; kk < 4; ++kk)
		{
			_DGN_STRS_CRC StrsB = (kk % 2 == 0 ? StressD : StressD);
			//StrsB *= -1.0; // 압축을 (+)
			T_TRAN_PSC_AS_BASE& TranB = TranD.GrB[kk];
			int nPosId = kk / 2;
			TranB.bCHK = Get_ChkFlag(ElemK, nPosId, TRUE);
			TranB.StageK = StagK;
			TranB.StepK = nStepNo;
			TranB.LcomK = nLcomK;
			TranB.dft = StrsB.dStop[nPosId];
			TranB.dfb = StrsB.dSbot[nPosId];
			TranB.dStress[0] = StrsB.dStl[nPosId];
			TranB.dStress[1] = StrsB.dStr[nPosId];
			TranB.dStress[2] = StrsB.dSbr[nPosId];
			TranB.dStress[3] = StrsB.dSbl[nPosId];
			TranB.dftc = min(TranB.dStress[0], TranB.dStress[1]);
			TranB.dfbc = min(TranB.dStress[2], TranB.dStress[3]);
			TranB.dfmax = min(TranB.dftc, TranB.dfbc);
			TranB.dfcp = dfci;
		}

		m_pPscDataCtrl->Get_TransferCheck(ElemK, MembInD, TranD);

		_LCOM_INFO_B       LcomInf[2];
		BOOL bCurChk[2] = { bChkI, bChkJ };
		for (int j = 0; j < 2; ++j)
		{
			bool bIsChk = bCurChk[j] ? true : false;
			LcomInf[j].SetInfo(bIsChk, nDgnLcomNo, nMaxMinType, 0);
			LcomInf[j].bTransfer = true;
		}

		_DGN_FORC_CRC ForceD;
		_DGN_FORC_CRC TnprForD;
		_DGN_FORC_CRC ForLTD;
		_DGN_FORC_CRC ForSTD;
		m_ForceCtrl.Get_Force4Tranfer(StctD, ElemK, nDgnLcomNo, StagK, nStepNo, ForceD, ForLTD, ForSTD, TnprForD);

		_LCOM_FOR_B        ForB[2];
		_LCOM_FOR_B        ForP2[2];
		PSC_BDCW_CR_PROP_R CrackP[2];

		Get_ForceInfo4Crack(2, bIsCpt, ForceD, TnprForD, ForLTD, ForSTD, StressD, StrLTD, StrSTD, StrP2, StrLTP2, StrSTP2, ForB, ForP2, CrackP);

		_BDCW_PSC_LRFD_BASE BdcwTB[4]; // 
		for (int j = 0; j < 2; ++j)
		{
			BdcwTB[j].LInf = LcomInf[0];

			BdcwTB[j].ForB = ForB[0];
			BdcwTB[j].ForP2 = ForP2[0];
			BdcwTB[j].CrPropD = CrackP[0];
			BdcwTB[j + 2].LInf = LcomInf[1];
			BdcwTB[j + 2].ForB = ForB[1];
			BdcwTB[j + 2].ForP2 = ForP2[1];
			BdcwTB[j + 2].CrPropD = CrackP[1];
		}

		m_pPscDataCtrl->Get_BdcwDataAS(ElemK, MembInD, BdcwTB);

		for (int j = 0; j < 4; ++j)
		{
			double dfct = j == 0 || j == 2 ? BdcwTB[j].ForB.dFT : BdcwTB[j].ForB.dFB;
			if (nChkTB[j] == 0)
			{
				dfct_cr[j] = dfct;
				BdcwCrD[j] = BdcwTB[j];
			}
			else
			{
				if (dfct_cr[j] < dfct)
				{
					dfct_cr[j] = dfct;
					BdcwCrD[j] = BdcwTB[j];
				}
			}
			nChkTB[j]++;
		}

	}

	CDgn_PSCManager PscManager;
	for (int i = 0; i < 4; ++i)
	{
		PscManager.ConvertBdcw_EngineToCivilAS(BdcwCrD[i], CrackD.BdcwB[i]);
	}

	return TRUE;
}

BOOL CCRCDataCtrl::Get_StressResSLSPSC_AS(ElemPairK ElemK, PSC_DATA_MEMB &MembInD, T_FYCM_PSC_AS &FycmD, T_FPMS_PSC &FpmsD)
{
	// Check Calculating Item.
	if (!Is_CalcItem(ElemK, TRUE))  return FALSE;
	// PSC-Design/Strs(5), PSC-Design/Strn(6).
	int iDgnStatus = m_pDoc->GetDesignStatus();
	m_pDoc->SetDesignStatus(5);

	_DGN_STRS_CRC StrsMax;
	_DGN_STRS_CRC StrsMin;

	_DGN_STRS_CRC StrsMax_Sl;
	_DGN_STRS_CRC StrsMin_Sl;

	_DGN_STRS_CRC StressTnpr;
	_DGN_STRS_CRC StressTnsc;

	_DGN_SHRS_CRC ShrsMax;
	_DGN_SHRS_CRC ShrsMin;

	BOOL bIsCpt = IsCompositePSCSect(ElemK);

	m_ForceCtrl.Debug_PrintOpt(3);	// For DEBUG.
	int iShortLongTerm = 3;

	if (bIsCpt == FALSE)
	{
		if (!m_ForceCtrl.Get_StrsByLcom(ElemK, 0, StrsMax, StrsMin, iShortLongTerm))	return FALSE;
	}
	else
	{
		if (!m_ForceCtrl.Get_StrsByLcom(ElemK, 1, StrsMax, StrsMin, iShortLongTerm))	return FALSE;
		//
		if (!m_ForceCtrl.Get_StrsByLcom(ElemK, 2, StrsMax_Sl, StrsMin_Sl, iShortLongTerm))	return FALSE;
	}

	if (!m_ForceCtrl.Get_ShrsByLcom(ElemK, ShrsMax, ShrsMin, 4, FALSE))	return FALSE;	// 3=Shear+Torsion.

	// Set Data.
	for (int i = 0; i < 4; ++i)
	{
		//StressTnpr.Initialize();
		//StressTnsc.Initialize();

		// 0=I-MAX, 1=I-MIN, 2=J-MAX, 3=J-MIN.
		_DGN_STRS_CRC &StrsCrc = (i % 2 == 0 ? StrsMax : StrsMin);
		int nIx = i / 2;
		//if(StrsCrc.dScom[nIx]==0.0)	continue;

		int iDgnLcomNo = StrsCrc.iRefNo[nIx];
		CString strOrgLcomNa = _T("");
		int iMaxMinType = 0;
		if (!m_ForceCtrl.Get_LcomType(iDgnLcomNo, strOrgLcomNa, iMaxMinType))	ASSERT(0);

		//GetDesignForceResult()->GetStressTnprResult(ElemK, iDgnLcomNo, StressTnpr);
		//GetDesignForceResult()->GetStressTnscResult(ElemK, iDgnLcomNo, StressTnsc);

		FycmD.FycmGrB[i].bCHK = Get_ChkFlag(ElemK, i / 2, TRUE);
		FycmD.FycmGrB[i].LcomK = iDgnLcomNo;
		FycmD.FycmGrB[i].nKind = m_ForceCtrl.Get_LcomKind(iDgnLcomNo);
		FycmD.FycmGrB[i].nMax = iMaxMinType;
		FycmD.FycmGrB[i].dFT = StrsCrc.dStop[nIx];
		FycmD.FycmGrB[i].dFB = StrsCrc.dSbot[nIx];
		FycmD.FycmGrB[i].dFTL = StrsCrc.dStl[nIx];
		FycmD.FycmGrB[i].dFBL = StrsCrc.dSbl[nIx];
		FycmD.FycmGrB[i].dFTR = StrsCrc.dStr[nIx];
		FycmD.FycmGrB[i].dFBR = StrsCrc.dSbr[nIx];
		FycmD.FycmGrB[i].dFMAX = StrsCrc.dScom[nIx];

		//     FycmD.FycmBase[i].dFT_PS   = StressTnpr.dStop[i/2] + StressTnsc.dStop[i/2];
		//     FycmD.FycmBase[i].dFB_PS   = StressTnpr.dSbot[i/2] + StressTnsc.dSbot[i/2];
		//     FycmD.FycmBase[i].dFTL_PS  = StressTnpr.dStl[i/2]  + StressTnsc.dStl[i/2] ;
		//     FycmD.FycmBase[i].dFBL_PS  = StressTnpr.dSbl[i/2]  + StressTnsc.dSbl[i/2] ;
		//     FycmD.FycmBase[i].dFTR_PS  = StressTnpr.dStr[i/2]  + StressTnsc.dStr[i/2] ;
		//     FycmD.FycmBase[i].dFBR_PS  = StressTnpr.dSbr[i/2]  + StressTnsc.dSbr[i/2] ;
		//     FycmD.FycmBase[i].dFMAX_PS = StressTnpr.dScom[i/2] + StressTnsc.dScom[i/2];

		FycmD.FycmGrB[i].dALW = 0.0;	// From CRC.

		_DGN_SHRS_CRC &ShrsD = (i % 2 == 0 ? ShrsMax : ShrsMin);
		if (ShrsD.dSspAbs[i / 2] == 0.0)	continue;

		FpmsD.FpmsBase[i].bCHK = Get_ChkFlag(ElemK, nIx, FALSE);
		FpmsD.FpmsBase[i].LcomK = iDgnLcomNo;
		FpmsD.FpmsBase[i].iKind = m_ForceCtrl.Get_ServLcomType(iDgnLcomNo); //m_ForceCtrl.Get_LcomKind(iDgnLcomNo);
		FpmsD.FpmsBase[i].iMax = iMaxMinType;
		FpmsD.FpmsBase[i].dFP1 = ShrsD.dSsp[nIx][0];
		FpmsD.FpmsBase[i].dFP2 = ShrsD.dSsp[nIx][1];
		FpmsD.FpmsBase[i].dFP3 = ShrsD.dSsp[nIx][2];
		FpmsD.FpmsBase[i].dFP4 = ShrsD.dSsp[nIx][3];
		FpmsD.FpmsBase[i].dFP5 = ShrsD.dSsp[nIx][4];
		FpmsD.FpmsBase[i].dFP6 = ShrsD.dSsp[nIx][5];
		FpmsD.FpmsBase[i].dFP7 = ShrsD.dSsp[nIx][6];
		FpmsD.FpmsBase[i].dFP8 = ShrsD.dSsp[nIx][7];
		FpmsD.FpmsBase[i].dFP9 = ShrsD.dSsp[nIx][8];
		FpmsD.FpmsBase[i].dFP10 = ShrsD.dSsp[nIx][9];
		FpmsD.FpmsBase[i].dFMAX = ShrsD.dSspAbs[nIx];	//Max,Min
		FpmsD.FpmsBase[i].dAFP = 0.0;
	}
	//
	if (bIsCpt == TRUE)
	{
		for (int i = 0; i < 4; ++i)
		{
			// 0=I-MAX, 1=I-MIN, 2=J-MAX, 3=J-MIN.
			_DGN_STRS_CRC &StrsCrc = (i % 2 == 0 ? StrsMax_Sl : StrsMin_Sl);
			int nIx = i / 2;
			if (StrsCrc.dScom[nIx] == 0.0)	continue;

			int iDgnLcomNo = StrsCrc.iRefNo[nIx];
			CString strOrgLcomNa = _T("");
			int iMaxMinType = 0;
			if (!m_ForceCtrl.Get_LcomType(iDgnLcomNo, strOrgLcomNa, iMaxMinType))	ASSERT(0);

			FycmD.FycmSlB[i].bCHK = Get_ChkFlag(ElemK, nIx, TRUE);
			FycmD.FycmSlB[i].LcomK = iDgnLcomNo;
			FycmD.FycmSlB[i].nKind = m_ForceCtrl.Get_LcomKind(iDgnLcomNo);
			FycmD.FycmSlB[i].nMax = iMaxMinType;
			FycmD.FycmSlB[i].dFT = StrsCrc.dStop[nIx];
			FycmD.FycmSlB[i].dFB = StrsCrc.dSbot[nIx];
			FycmD.FycmSlB[i].dFTL = StrsCrc.dStl[nIx];
			FycmD.FycmSlB[i].dFBL = StrsCrc.dSbl[nIx];
			FycmD.FycmSlB[i].dFTR = StrsCrc.dStr[nIx];
			FycmD.FycmSlB[i].dFBR = StrsCrc.dSbr[nIx];
			FycmD.FycmSlB[i].dFMAX = StrsCrc.dScom[nIx];
			FycmD.FycmSlB[i].dALW = 0.0;	// From CRC.
		}
	}

	m_pPscDataCtrl->Get_StressCheckSLS(ElemK, MembInD, FycmD, FpmsD);

	for (int m = 0; m < 4; ++m)
	{
		auto& FycmGrB = FycmD.FycmGrB[m];
		FycmGrB.dFT   *= -1.0;
		FycmGrB.dFB   *= -1.0;
		FycmGrB.dFTL  *= -1.0;
		FycmGrB.dFBL  *= -1.0;
		FycmGrB.dFTR  *= -1.0;
		FycmGrB.dFBR  *= -1.0;
		FycmGrB.dFMAX *= -1.0;

		auto& FycmSlB = FycmD.FycmSlB[m];
		FycmSlB.dFT   *= -1.0;
		FycmSlB.dFB   *= -1.0;
		FycmSlB.dFTL  *= -1.0;
		FycmSlB.dFBL  *= -1.0;
		FycmSlB.dFTR  *= -1.0;
		FycmSlB.dFBR  *= -1.0;
		FycmSlB.dFMAX *= -1.0;

		auto& FpmsB = FpmsD.FpmsBase[m];
		FpmsB.dFP1  *= -1.0;
		FpmsB.dFP2  *= -1.0;
		FpmsB.dFP3  *= -1.0;
		FpmsB.dFP4  *= -1.0;
		FpmsB.dFP5  *= -1.0;
		FpmsB.dFP6  *= -1.0;
		FpmsB.dFP7  *= -1.0;
		FpmsB.dFP8  *= -1.0;
		FpmsB.dFP9  *= -1.0;
		FpmsB.dFP10 *= -1.0;
		FpmsB.dFMAX *= -1.0;
	}

	return TRUE;
}

BOOL CCRCDataCtrl::Get_CrackResSLSPSC_AS(ElemPairK ElemK, PSC_DATA_MEMB &MembInD, T_BDCW_PSC_AS &BdcwD)
{
	m_pDoc->SetDesignStatus(5);

	T_STCT_D StctD; StctD.Initialize();
	m_pDoc->m_pAttrCtrl->GetStct(StctD);

	int nLcomNum = m_ForceCtrl.Get_LcomDataCount();
	ADGNFORCE aForceLcom;
	ADGNFORCE aForceTnpr;
	ADGNFORCE aForceTnsc;
	ADGNFORCE aForceLTerm;
	ADGNFORCE aForceSTerm;
	ADGNSHRSADD aStssLcom;
	if (!m_ForceCtrl.Get_LcomDataForDesign(ElemK, TRUE, TRUE, aForceLcom, aForceTnpr, aForceTnsc, aForceLTerm, aForceSTerm, aStssLcom, nLcomNum)) return FALSE;

	ADGNSTRESS aStressLcom;
	ADGNSTRESS aStressTnpr;
	ADGNSTRESS aStressTnsc;
	ADGNSTRSADD aStressAdd;
	ADGNSTRESS aStressLterm;
	ADGNSTRESS aStressSterm;
	if (!m_ForceCtrl.Get_LcomDataForStress(ElemK, TRUE, TRUE, aStressLcom, aStressAdd, aStressLterm, aStressSterm, nLcomNum)) return FALSE;
	if (!m_ForceCtrl.Get_LcomDataForStress(ElemK, TRUE, TRUE, aStressLcom, aStressTnpr, aStressTnsc, nLcomNum)) return FALSE;
	//if(m_ForceCtrl.Get_LcomNumForStrs()==0)	return FALSE;

	T_STAG_K nGdLastStagK = 0;
	int nLastStepNo = 0;
	m_ForceCtrl.GetGirderLastStageKey(ElemK, nGdLastStagK, nLastStepNo);

	BOOL bComposite = MembInD.Pos[0].bComposite;

	BOOL bChkI = Get_ChkFlag(ElemK, 0, TRUE);
	BOOL bChkJ = Get_ChkFlag(ElemK, 1, TRUE);

	double dfcp_cr[4] = { 0.0, 0.0, 0.0, 0.0 };
	double dfct_cr[4] = { 0.0, 0.0, 0.0, 0.0 };
	_BDCW_PSC_LRFD_BASE BdcwCrD[4];  //0=I-Top, 1=I-Bottom, 2=J-Top. 3=J-Bottom

	int nChkTB[4] = { 0, };
	int nForcLcomSize = aForceLcom.GetSize();
	for (int i = 0; i < nForcLcomSize; ++i)
	{
		int nDgnLcomNo = i + 1;
		if (!m_ForceCtrl.Is_LcomForServ(nDgnLcomNo))	continue;
		if (m_ForceCtrl.Is_LcomForTran(nDgnLcomNo)) continue;

		_DGN_FORC_CRC &ForceD = aForceLcom[i];
		_DGN_FORC_CRC &TnprForD = aForceTnpr[i];
		_DGN_FORC_CRC &ForSTD = aForceSTerm[i];
		_DGN_STRS_CRC &StressD = aStressLcom[i];
		_DGN_STRS_CRC &StrLTermD = aStressLterm[i];
		_DGN_STRS_CRC &StrSTermD = aStressSterm[i];
		_DGN_STRS_CRC &StrTnprD = aStressTnpr[i];
		_DGN_STRS_CRC &StrTnscD = aStressTnsc[i];

		CString strOrgLcomNa = _T("");
		int nMaxMinType = 0;
		if (!m_ForceCtrl.Get_LcomType(nDgnLcomNo, strOrgLcomNa, nMaxMinType))	ASSERT(0);

		_DGN_FORC_CRC FcsDL;
		_DGN_STRS_CRC StrP2;
		_DGN_STRS_CRC StrLTP2;
		_DGN_STRS_CRC StrSTP2;
		if (bComposite)
		{
			// 시공중 거더 Force
			int nForceBeforeType = 1;
			m_ForceCtrl.Get_GirderForce4CSLoadOfLCOM(FALSE, StctD, ElemK, nGdLastStagK, nLastStepNo, nDgnLcomNo, nForceBeforeType, FcsDL);
			m_ForceCtrl.GetDgnForce()->GetStressLcomResult_Part2(ElemK, nDgnLcomNo, StrP2);
			m_ForceCtrl.GetDgnForce()->GetStressLcomLTerm_Part2(ElemK, nDgnLcomNo, StrLTP2);
			m_ForceCtrl.GetDgnForce()->GetStressLcomSTerm_Part2(ElemK, nDgnLcomNo, StrSTP2);
		}

		BOOL bIsChkTop[2] = { FALSE,FALSE };
		//_BDCW_PSC_LRFD_BASE BdcwPosD[2]; // I,J

		_LCOM_INFO_B       LcomInf[2];
		_LCOM_FOR_B        ForB[2];
		_LCOM_FOR_B        ForP2[2];
		PSC_BDCW_CR_PROP_R CrackP[2];
		for (int j = 0; j < 2; ++j)
		{
			LcomInf[j].bCHK = j == 0 ? bChkI : bChkJ;
			LcomInf[j].LcomK = nDgnLcomNo;
			LcomInf[j].nKind = m_ForceCtrl.Get_LcomKind(nDgnLcomNo);
			LcomInf[j].nMax = nMaxMinType;

			ForB[j].dForce[0] = ForceD.dFxx[j] - TnprForD.dFxx[j];
			ForB[j].dForce[1] = ForceD.dFyy[j] - TnprForD.dFyy[j];
			ForB[j].dForce[2] = ForceD.dFzz[j] - TnprForD.dFzz[j];
			ForB[j].dForce[3] = ForceD.dMux[j] - TnprForD.dMux[j];
			ForB[j].dForce[4] = ForceD.dMuy[j] - TnprForD.dMuy[j];
			ForB[j].dForce[5] = ForceD.dMuz[j] - TnprForD.dMuz[j];
			if (bComposite)
			{
				CrackP[j].dPu = FcsDL.dFxx[j];
				CrackP[j].dMu = FcsDL.dMuy[j];
				CrackP[j].dPu_st = ForSTD.dFxx[j];
				CrackP[j].dMu_st = ForSTD.dMuy[j];
				_DGN_FORC_CRC ForLTD;
				ForLTD += ForceD;
				ForLTD -= TnprForD;
				ForLTD -= ForSTD;
				CrackP[j].dPu_lt = ForLTD.dFxx[j];
				CrackP[j].dMu_lt = ForLTD.dMuy[j];
				CrackP[j].dPu_c = ForLTD.dFxx[j] + ForSTD.dFxx[j];
				CrackP[j].dMu_c = ForLTD.dMuy[j] + ForSTD.dMuy[j];
			}
			else
			{
				CrackP[j].dPu = ForB[j].dForce[0];
				CrackP[j].dMu = ForB[j].dForce[4];
			}
			double dft_PL = StrLTermD.dStop[j]; // DL(Long Term)
			double dfb_PL = StrLTermD.dSbot[j];
			double dft_LL = StrSTermD.dStop[j];
			double dfb_LL = StrSTermD.dSbot[j];

			ForB[j].dFT = StressD.dStop[j];
			ForB[j].dFB = StressD.dSbot[j];
			ForB[j].dft_DL = dft_PL;
			ForB[j].dfb_DL = dfb_PL;
			ForB[j].dft_LL = dft_LL;
			ForB[j].dfb_LL = dfb_LL;
			if (bComposite)
			{
				ForP2[j].dFT = StrP2.dStop[j];
				ForP2[j].dFB = StrP2.dSbot[j];
				ForP2[j].dft_DL = StrLTP2.dStop[j];
				ForP2[j].dfb_DL = StrLTP2.dSbot[j];
				ForP2[j].dft_LL = StrSTP2.dStop[j];
				ForP2[j].dfb_LL = StrSTP2.dSbot[j];
			}
		}
		//
		if (m_iCivilCode == AS_5100_5_17_PSC)
		{
			_BDCW_PSC_LRFD_BASE BdcwTB[4]; // 
			for (int j = 0; j < 2; ++j)
			{
				BdcwTB[j].LInf = LcomInf[0];
				BdcwTB[j].ForB = ForB[0];
				BdcwTB[j].ForP2 = ForP2[0];
				BdcwTB[j].CrPropD = CrackP[0];
				BdcwTB[j + 2].LInf = LcomInf[1];
				BdcwTB[j + 2].ForB = ForB[1];
				BdcwTB[j + 2].ForP2 = ForP2[1];
				BdcwTB[j + 2].CrPropD = CrackP[1];
			}

			m_pPscDataCtrl->Get_BdcwDataAS(ElemK, MembInD, BdcwTB);

			for (int j = 0; j < 4; ++j)
			{
				double dfct = j == 0 || j == 2 ? BdcwTB[j].ForB.dFT : BdcwTB[j].ForB.dFB;
				if (nChkTB[j] == 0)
				{
					dfct_cr[j] = dfct;
					BdcwCrD[j] = BdcwTB[j];
				}
				else
				{
					if (dfct_cr[j] < dfct)
					{
						dfct_cr[j] = dfct;
						BdcwCrD[j] = BdcwTB[j];
					}
				}
				nChkTB[j]++;
			}
		}
		else ASSERT(0);
	}

	CDgn_PSCManager PscManager;
	for (int i = 0; i < 4; ++i)
	{
		PscManager.ConvertBdcw_EngineToCivilAS(BdcwCrD[i], BdcwD.BdcwB[i]);
	}

	return TRUE;
}

BOOL CCRCDataCtrl::Get_StrengthResULSPSC_AS(ElemPairK ElemK, PSC_DATA_MEMB &MembInD, T_BDCR_PSC_AS &BdcrD, T_SHRR_PSC_AS &ShrrD, T_TORR_PSC_AS &TorrD)
{
	m_pDoc->SetDesignStatus(6);

	//////////////////////////////////////////////////////////////////////////  
	double dForceTpI[6] = { 0.0, };
	double dForceTpJ[6] = { 0.0, };
	m_ForceCtrl.Get_ForceByTnPr(ElemK, dForceTpI, dForceTpJ);
	//////////////////////////////////////////////////////////////////////////  

	// 휨 강도 검토
	Get_BdcrDataAS(ElemK, MembInD, BdcrD);

	int nLcomNum = m_ForceCtrl.Get_LcomDataCount();
	ADGNFORCE aForceLcom;
	ADGNFORCE aForceTnpr;
	ADGNFORCE aForceTnsc;
	ADGNFORCE aForceLTerm;
	ADGNFORCE aForceSTerm;
	ADGNSHRSADD aStssLcom;
	if (!m_ForceCtrl.Get_LcomDataForDesign(ElemK, TRUE, TRUE, aForceLcom, aForceTnpr, aForceTnsc, aForceLTerm, aForceSTerm, aStssLcom, nLcomNum)) return FALSE;

	double dRatScr[2] = { 0.0, 0.0 };
	double dRatTcr[2] = { 0.0, 0.0 };
	_CUMS_AASHTO_BASE ShearCrD[2];
	_STCM_AASHTO_BASE TorsionCrD[2];

	BOOL bChkShrI = Get_ChkFlag(ElemK, 0, FALSE);
	BOOL bChkShrJ = Get_ChkFlag(ElemK, 1, FALSE);
	BOOL bChkTorI = Get_ChkFlag(ElemK, 0, FALSE);
	BOOL bChkTorJ = Get_ChkFlag(ElemK, 1, FALSE);
	BOOL bChkI = (bChkShrI || bChkTorI);
	BOOL bChkJ = (bChkShrJ || bChkTorJ);

	int nCount = 0;
	int nForcLcomSize = aForceLcom.GetSize();
	for (int i = 0; i < nForcLcomSize; ++i)
	{
		if (!m_ForceCtrl.Is_LcomForStrn(i + 1))	continue;
		nCount++;

		_DGN_FORC_CRC &ForceD = aForceLcom.GetAt(i);

		int nDgnLcomNo = i + 1;
		CString strOrgLcomNa = _T("");
		int nMaxMinType = 0;
		if (!m_ForceCtrl.Get_LcomType(nDgnLcomNo, strOrgLcomNa, nMaxMinType))	ASSERT(0);

		_CUMS_AASHTO_BASE ShrD[2]; // I,J

		for (int j = 0; j < 2; ++j)
		{
			ShrD[j].bCHK = (j == 0) ? bChkShrI : bChkShrJ;
			ShrD[j].LcomK = nDgnLcomNo;
			ShrD[j].iKind = m_ForceCtrl.Get_LcomKind(nDgnLcomNo);
			ShrD[j].iMax = nMaxMinType;
			ShrD[j].dNu = ForceD.dFxx[j];
			ShrD[j].dVu = ForceD.dFzz[j];
			ShrD[j].dMu = GetDgnMoment(ForceD.dMuy[j]);
			ShrD[j].dTu = ForceD.dMux[j];
			//ShrTorD[j].dMr   = (ForceD.dMuy[j]>=0.0) ? BcdrRes.BdcrBase[j*2].dMr : BcdrRes.BdcrBase[j*2+1].dMr;    
			for (int nFor = 0; nFor < 6; ++nFor)
			{
				ShrD[j].dForceTP[nFor] = j == 0 ? dForceTpI[nFor] : dForceTpJ[nFor];
			}
		}
		//
		m_pPscDataCtrl->Get_CumsDataAS(ElemK, MembInD, ShrD);

		_STCM_AASHTO_BASE ShrTorD[2]; // I,J

		for (int j = 0; j < 2; ++j)
		{
			ShrTorD[j].Tor.bCHK = ShrTorD[j].Shr.bCHK = (j == 0) ? bChkTorI : bChkTorJ;
			ShrTorD[j].Tor.LcomK = ShrTorD[j].Shr.LcomK = nDgnLcomNo;
			ShrTorD[j].Tor.iKind = ShrTorD[j].Shr.iKind = m_ForceCtrl.Get_LcomKind(nDgnLcomNo);
			ShrTorD[j].Tor.iMax = ShrTorD[j].Shr.iMax = nMaxMinType;
			ShrTorD[j].Tor.dNu = ShrTorD[j].Shr.dNu = ForceD.dFxx[j];
			ShrTorD[j].Tor.dVu = ShrTorD[j].Shr.dVu = ForceD.dFzz[j];
			ShrTorD[j].Tor.dMu = ShrTorD[j].Shr.dMu = GetDgnMoment(ForceD.dMuy[j]);
			ShrTorD[j].Tor.dTu = ShrTorD[j].Shr.dTu = ForceD.dMux[j];
			//ShrTorD[j].dMr   = (ForceD.dMuy[j]>=0.0) ? BcdrRes.BdcrBase[j*2].dMr : BcdrRes.BdcrBase[j*2+1].dMr;      
			for (int nFor = 0; nFor < 6; ++nFor)
			{
				ShrTorD[j].Tor.dForceTP[nFor] = j == 0 ? dForceTpI[nFor] : dForceTpJ[nFor];
				ShrTorD[j].Shr.dForceTP[nFor] = j == 0 ? dForceTpI[nFor] : dForceTpJ[nFor];
			}
		}
		//
		m_pPscDataCtrl->Get_CrmtDataAS(ElemK, MembInD, ShrTorD);

		BOOL bChkShrIJ[2] = { bChkShrI, bChkShrJ };
		BOOL bChkTorIJ[2] = { bChkTorI, bChkTorJ };
		if (nCount == 1)
		{
			for (int k = 0; k < 2; ++k)
			{
				if (bChkShrIJ[k] == TRUE)
				{
					dRatScr[k] = ShrD[k].dV_rat;
					ShearCrD[k] = ShrD[k];
				}
				if (bChkTorIJ[k] == TRUE)
				{
					dRatTcr[k] = ShrTorD[k].Tor.dCombRat;
					TorsionCrD[k] = ShrTorD[k];
				}
			}
		}
		else
		{
			for (int k = 0; k < 2; ++k)
			{
				if (bChkShrIJ[k] == TRUE)
				{
					if (dRatScr[k] < ShrD[k].dV_rat)
					{
						dRatScr[k] = ShrD[k].dV_rat;
						ShearCrD[k] = ShrD[k];
					}
				}
				if (bChkTorIJ[k] == TRUE)
				{
					if (dRatTcr[k] < ShrTorD[k].Tor.dCombRat)
					{
						dRatTcr[k] = ShrTorD[k].Tor.dCombRat;
						TorsionCrD[k] = ShrTorD[k];
					}
				}
			}
		}
	}

	CDgn_PSCManager PscManager;
	for (int i = 0; i < 2; ++i)
	{
		PscManager.ConvertCums_EngineToCivilAS(ShearCrD[i], ShrrD.ShrrB[i]);
		PscManager.ConvertCrmt_EngineToCivilAS(TorsionCrD[i], TorrD.TorrB[i]);
	}

	return TRUE;
}

BOOL CCRCDataCtrl::Get_BdcrDataAS(ElemPairK ElemK, PSC_DATA_MEMB &MembInD, T_BDCR_PSC_AS &rData)
{
	rData.Initialize();
	// Check Calculating Item.
	if (!Is_CalcItem(ElemK, TRUE))  return FALSE;
	// PSC-Design/Strs(5), PSC-Design/Strn(6).
	int iDgnStatus = m_pDoc->GetDesignStatus();
	m_pDoc->SetDesignStatus(6);

	double dMyMax[2] = { 0.,0. }, dMyMin[2] = { 0.,0. };
	int iMaxDgnLcom[2] = { 0,0 }, iMinDgnLcom[2] = { 0,0 };

	// 필요한 Force Max/Min 값을 찾음.
	BOOL bStrength = TRUE;
	if (!Get_CheckForceMu_MaxMin(bStrength, ElemK, dMyMax, dMyMin, iMaxDgnLcom, iMinDgnLcom)) return FALSE;

	BOOL bChkFlex[4] = { FALSE, FALSE, FALSE, FALSE };
	for (int i = 0; i < 4; ++i)
	{
		// 0=I-MAX, 1=I-MIN, 2=J-MAX, 3=J-MIN.
		int iDgnLcomNo = (i % 2 == 0 ? iMaxDgnLcom[i / 2] : iMinDgnLcom[i / 2]);
		CString strOrgLcomNa = _T("");
		int iMaxMinType = 0;
		if (!m_ForceCtrl.Get_LcomType(iDgnLcomNo, strOrgLcomNa, iMaxMinType))	ASSERT(0);
		double dMuy = (i % 2 == 0 ? dMyMax[i / 2] : dMyMin[i / 2]);
		if (i % 2 == 0) { dMuy = (dMuy < 0.0 ? 0.0 : dMuy); }
		else { dMuy = (dMuy > 0.0 ? 0.0 : dMuy); }

		rData.BdcrB[i].bCHK = Get_ChkFlag(ElemK, i / 2, TRUE);
		rData.BdcrB[i].LcomK = iDgnLcomNo;
		rData.BdcrB[i].nKind = m_ForceCtrl.Get_LcomKind(iDgnLcomNo);
		rData.BdcrB[i].nMax = iMaxMinType;
		rData.BdcrB[i].dMu = GetDgnMoment(dMuy);
		bChkFlex[i] = Get_ChkFlag(ElemK, i / 2, TRUE) || Get_ChkFlag(ElemK, i / 2, FALSE);
	}

	if (!m_pPscDataCtrl->Get_BdcrDataAS(ElemK, bChkFlex, MembInD, rData)) return FALSE;

	CString sBendingErrMsg = _T("");
	for (int i = 0; i < 4; ++i)
	{
		if (rData.BdcrB[i].bCHK)
		{
			CString strIJ = i < 2 ? _T("I") : _T("J");
			if (rData.BdcrB[i].bOK == D_PSC_FRC_ERR_Iteration_Over)
			{
				CString strPN = i % 2 == 0 ? _T("P") : _T("N"); // Positive/Negative
				CString strPosi;
				strPosi.Format(_T("%d-%s(%s)"), ElemK, strIJ, strPN);
				sBendingErrMsg.Format(_LS(IDS_DGN_WARN_BEND_NEUTRAL_AXIS_Err), strPosi); // [Warning] Midas Civil has failed to find the neutral axis(member no.: xxxx). Please check the PSC Design Calculation sheet for details.
				GSaveHistoryFormatNF(sBendingErrMsg);
			}
		}
	}

	return TRUE;
}

BOOL CCRCDataCtrl::Convert_FypcToAS(const T_FYPC_AASHTO &rIn, T_FYPC_PSC_AS &rData)
{
	rData.bCHK = rIn.bCHK;
	rData.nLoadType = rIn.nLoadType;
	rData.dFDL1 = rIn.dFDL1;
	rData.dFDL2 = rIn.dFDL2;
	rData.dFDL3 = rIn.dFDL3;
	rData.dFLL1 = rIn.dFLL1;
	rData.dFLL2 = rIn.dFLL2;
	rData.dAFDL1 = rIn.dAFDL1;
	rData.dAFDL2 = rIn.dAFDL2;
	rData.dAFDL3 = rIn.dAFDL3;
	rData.dAFLL1 = rIn.dAFLL1;
	rData.dAFLL2 = rIn.dAFLL2;
	rData.bOK = rIn.bOK;

	//nElemFDL1 = nElemFDL2 = nElemFLL1 = 0;
	//nPartFDL1 = nPartFDL2 = nPartFLL1 = 0;
	//nStage    = 0;

	return TRUE;
}

BOOL CCRCDataCtrl::Get_ForceInfo4Crack(int nSize, BOOL bComposite,
	_DGN_FORC_CRC& ForceD, _DGN_FORC_CRC& TnprForD, _DGN_FORC_CRC& FcsDL, _DGN_FORC_CRC& ForSTD,
	_DGN_STRS_CRC& StressD, _DGN_STRS_CRC& StrLTermD, _DGN_STRS_CRC& StrSTermD,
	_DGN_STRS_CRC& StrP2, _DGN_STRS_CRC& StrLTP2, _DGN_STRS_CRC& StrSTP2,
	_LCOM_FOR_B pForGr[2], _LCOM_FOR_B pForSl[2], PSC_BDCW_CR_PROP_R pCrP[2])
{
	if (nSize != 2) return FALSE;

	for (int j = 0; j < 2; ++j)
	{

		pForGr[j].dForce[0] = ForceD.dFxx[j] - TnprForD.dFxx[j];
		pForGr[j].dForce[1] = ForceD.dFyy[j] - TnprForD.dFyy[j];
		pForGr[j].dForce[2] = ForceD.dFzz[j] - TnprForD.dFzz[j];
		pForGr[j].dForce[3] = ForceD.dMux[j] - TnprForD.dMux[j];
		pForGr[j].dForce[4] = ForceD.dMuy[j] - TnprForD.dMuy[j];
		pForGr[j].dForce[5] = ForceD.dMuz[j] - TnprForD.dMuz[j];
		if (bComposite)
		{
			pCrP[j].dPu = FcsDL.dFxx[j];
			pCrP[j].dMu = FcsDL.dMuy[j];
			pCrP[j].dPu_st = ForSTD.dFxx[j];
			pCrP[j].dMu_st = ForSTD.dMuy[j];
			_DGN_FORC_CRC ForLTD;
			ForLTD += ForceD;
			ForLTD -= TnprForD;
			ForLTD -= ForSTD;
			pCrP[j].dPu_lt = ForLTD.dFxx[j];
			pCrP[j].dMu_lt = ForLTD.dMuy[j];
			pCrP[j].dPu_c = ForLTD.dFxx[j] + ForSTD.dFxx[j];
			pCrP[j].dMu_c = ForLTD.dMuy[j] + ForSTD.dMuy[j];
		}
		else
		{
			pCrP[j].dPu = pForGr[j].dForce[0];
			pCrP[j].dMu = pForGr[j].dForce[4];
		}
		double dft_PL = StrLTermD.dStop[j]; // DL(Long Term)
		double dfb_PL = StrLTermD.dSbot[j];
		double dft_LL = StrSTermD.dStop[j];
		double dfb_LL = StrSTermD.dSbot[j];

		pForGr[j].dFT = StressD.dStop[j];
		pForGr[j].dFB = StressD.dSbot[j];
		pForGr[j].dft_DL = dft_PL;
		pForGr[j].dfb_DL = dfb_PL;
		pForGr[j].dft_LL = dft_LL;
		pForGr[j].dfb_LL = dfb_LL;
		if (bComposite)
		{
			pForSl[j].dFT = StrP2.dStop[j];
			pForSl[j].dFB = StrP2.dSbot[j];
			pForSl[j].dft_DL = StrLTP2.dStop[j];
			pForSl[j].dfb_DL = StrLTP2.dSbot[j];
			pForSl[j].dft_LL = StrSTP2.dStop[j];
			pForSl[j].dfb_LL = StrSTP2.dSbot[j];
		}
	}

	return TRUE;
}

BOOL CCRCDataCtrl::Get_PSCCheckResultBS(ElemPairK ElemK, T_DRST_D &Drst)
{
	BOOL bComposite = IsCompositePSCSect(ElemK);

	PSC_DATA_MEMB PscMembD;
	if (!m_pPscDataCtrl->Get_PscDataPosi(ElemK, 0, PscMembD.Pos[0], bComposite)) return FALSE;
	if (!m_pPscDataCtrl->Get_PscDataPosi(ElemK, 1, PscMembD.Pos[1], bComposite)) return FALSE;

	CPCDesign *pPCDgn = m_pPostCtrl->GetPCDesign();

	double dHeight[2] = { 0.0 };
	dHeight[0] = PscMembD.Pos[0].SectgD.dzDim;
	dHeight[1] = PscMembD.Pos[1].SectgD.dzDim;
	m_ForceCtrl.Set_SectHeight4PscGen(dHeight);

	T_FYSG_PSC_BS FysgD; FysgD.bComposite = bComposite;
	T_FPSG_PSC    FpsgD;
	Get_CStageResPSC_BS(ElemK, PscMembD, FysgD, FpsgD);
	pPCDgn->WriteFysg_BS(ElemK, FysgD);
	pPCDgn->WriteFpsg_PSC(ElemK, FpsgD);

	T_FYCM_PSC_BS FycmD; FycmD.bComposite = bComposite;
	T_FPMS_PSC    FpmsD;
	Get_StressResSLSPSC_BS(ElemK, PscMembD, FycmD, FpmsD);
	pPCDgn->WriteFycm_BS(ElemK, FycmD);
	pPCDgn->WriteFpms_PSC(ElemK, FpmsD);

	T_BDCW_PSC_BS BdcwD; BdcwD.bComposite = bComposite;
	Get_CrackResSLSPSC_BS(ElemK, PscMembD, BdcwD);
	pPCDgn->WriteBdcw_BS(ElemK, BdcwD);

	T_BDCR_PSC_BS BdcrD; BdcrD.bComposite = bComposite;
	T_SHRR_PSC_BS ShrrD; ShrrD.bComposite = bComposite;
	T_TORR_PSC_BS TorrD; TorrD.bComposite = bComposite;
	Get_StrengthResULSPSC_BS(ElemK, PscMembD, BdcrD, ShrrD, TorrD);

	pPCDgn->WriteBdcr_BS(ElemK, BdcrD);
	pPCDgn->WriteShrr_BS(ElemK, ShrrD);
	pPCDgn->WriteTorr_BS(ElemK, TorrD);

	if (Drst.bFysg == FALSE)
	{
		Drst.bFysg = (FysgD.FysgGrB[0].bCHK || FysgD.FysgGrB[1].bCHK || FysgD.FysgGrB[2].bCHK || FysgD.FysgGrB[3].bCHK);
	}
	if (Drst.bFpsg == FALSE)
	{
		Drst.bFpsg = (FpsgD.FpsgBase[0].bCHK || FpsgD.FpsgBase[1].bCHK || FpsgD.FpsgBase[2].bCHK || FpsgD.FpsgBase[3].bCHK);
	}
	if (Drst.bFycm == FALSE)
	{
		Drst.bFycm = (FycmD.FycmGrB[0].bCHK || FycmD.FycmGrB[1].bCHK || FycmD.FycmGrB[2].bCHK || FycmD.FycmGrB[3].bCHK);
	}
	if (Drst.bFpms == FALSE)
	{
		Drst.bFpms = (FpmsD.FpmsBase[0].bCHK || FpmsD.FpmsBase[1].bCHK || FpmsD.FpmsBase[2].bCHK || FpmsD.FpmsBase[3].bCHK);
	}
	if (Drst.bBdcw == FALSE)
	{
		Drst.bBdcw = (BdcwD.BdcwB[0].bCHK || BdcwD.BdcwB[1].bCHK || BdcwD.BdcwB[2].bCHK || BdcwD.BdcwB[3].bCHK);
	}
	if (Drst.bBdcr == FALSE)
	{
		Drst.bBdcr = (BdcrD.BdcrB[0].bCHK || BdcrD.BdcrB[1].bCHK || BdcrD.BdcrB[2].bCHK || BdcrD.BdcrB[3].bCHK);
	}
	if (Drst.bShrr == FALSE)
	{
		Drst.bShrr = (ShrrD.ShrrB[0].bCHK || ShrrD.ShrrB[1].bCHK || ShrrD.ShrrB[2].bCHK || ShrrD.ShrrB[3].bCHK);
	}
	if (Drst.bTorr == FALSE)
	{
		Drst.bTorr = (TorrD.TorrB[0].bCHK || TorrD.TorrB[1].bCHK || TorrD.TorrB[2].bCHK || TorrD.TorrB[3].bCHK);
	}

	return TRUE;
}

BOOL CCRCDataCtrl::Get_CStageResPSC_BS(ElemPairK ElemK, PSC_DATA_MEMB &MembInD, T_FYSG_PSC_BS &FysgD, T_FPSG_PSC &FpsgD)
{
	if (!Is_CalcItem(ElemK, TRUE))  return FALSE;
	int iDgnStatus = m_pDoc->GetDesignStatus();
	m_pDoc->SetDesignStatus(5);

	BOOL bIsCpt = IsCompositePSCSect(ElemK);
	
	T_CONC_AGE_D AgeD;
	if(!GetInitAgesOfConcrete(ElemK, AgeD)) ASSERT(0);
	BOOL bGetTdme = AgeD.bTdmeGr;
	BOOL bGetTdmeSL = AgeD.bTdmeSl;
	double dAgeGr = 0.0;
	double dAgeSl = 0.0;
	if(bIsCpt)
	{
		dAgeGr = AgeD.dAgeGr;
		dAgeSl = AgeD.dAgeSl;
	}

	CArray<T_STAG_K, T_STAG_K> aStagK;
	m_pStageInfo->GetResultSavedStagKeyList(aStagK);
	if (aStagK.GetSize() == 0)	return FALSE;

	int nStepGr = 0, nStepSlab = 0;
	double dFirstStep_Day = 0.0;
	double dStartStepSlab = 0.0;
	// Modify, Step이 있으면 Step도 고려할 수 있도록 수정. 
	CString strSgldName = _LS(IDS_DB_SGLD_SUM);	// SUM.
	T_SGLD_K SgldK = m_pAttrCtrl->GetSgldKey(strSgldName);
	for (int i = 0; i < aStagK.GetSize(); ++i)
	{
		T_STAG_K StagK = aStagK.GetAt(i);
		if (!m_pStageInfo->IsActiveElemInTgtStag(StagK, ElemK)) continue;

		T_STAG_STEP_INFO StageInfo; StageInfo.Initialize();
		m_pAttrCtrl->GetStagStepInfo(StagK, StageInfo);
		int iStepSize = StageInfo.aInfo.GetSize();
		int nStepArr = iStepSize == 0 ? 1 : iStepSize;
		int iSerialStep = 0;
		int nCurStep = 0;

		_DGN_STRS_CRC StrsStagCurMax;
		_DGN_STRS_CRC StrsStagCurMin;
		_DGN_STRS_CRC StrsStagCurMax_Sl;
		_DGN_STRS_CRC StrsStagCurMin_Sl;

		_DGN_SHRS_CRC ShrsStagCurMax;
		_DGN_SHRS_CRC ShrsStagCurMin;
		_DGN_SHRS_CRC ShrsStagCurMax_Sl;
		_DGN_SHRS_CRC ShrsStagCurMin_Sl;

		// 0:오류 또는 시공 합성 단면 아님
		// 1:시공 합성 단면 : 합성 전 (Active Stage 이전)
		// 2:시공 합성 단면 : 합성 중 (Active되고 모든 Part가 합성되기 전)
		// 3:시공 합성 단면 : 합성 후 (모든 Part가 합성된 후)
		T_CSCS_D CscsD; CscsD.Initialize();
		int nCompositeType = m_pAttrCtrl->GetElemSectCompositeInfoDgn(ElemK, StagK, CscsD);
		if (bIsCpt == TRUE)
		{
			if (nCompositeType == 0 || nCompositeType == 1) continue;
		}

		CMapEx<int, int, double, double> mStepfci, mStepfci_sl;
		mStepfci.InitHashTable(101);
		mStepfci_sl.InitHashTable(101);
		
		for (int jj = 0; jj < nStepArr; ++jj)
		{
			nCurStep = jj + 1;
			int iSerialStep = 0;
			if (iStepSize == 0)
			{
				Get_LastStepInCurStage(StagK, iSerialStep);
				if (!bIsCpt)
				{
					if (!m_ForceCtrl.Get_StrsBySgld(ElemK, SgldK, StagK, iSerialStep, StrsStagCurMax, StrsStagCurMin))	continue;
					//
					if (!m_ForceCtrl.Get_ShrsBySgld(ElemK, SgldK, StagK, iSerialStep, ShrsStagCurMax, ShrsStagCurMin, 4))	continue;	// 4=Principal.
				}
				else
				{
					if (nCompositeType == 2)
					{
						if (!m_ForceCtrl.Get_StrsPartBySgld(ElemK, SgldK, StagK, iSerialStep, 1, StrsStagCurMax, StrsStagCurMin))	continue;
						if (!m_ForceCtrl.Get_ShrsPartBySgld(ElemK, SgldK, StagK, iSerialStep, 1, ShrsStagCurMax, ShrsStagCurMin, 4))	continue;	// 4=Principal.
					}
					else if (nCompositeType >= 3)
					{
						if (!m_ForceCtrl.Get_StrsPartBySgld(ElemK, SgldK, StagK, iSerialStep, 1, StrsStagCurMax, StrsStagCurMin))	continue;
						if (!m_ForceCtrl.Get_StrsPartBySgld(ElemK, SgldK, StagK, iSerialStep, 2, StrsStagCurMax_Sl, StrsStagCurMin_Sl))	continue;
						//
						if (!m_ForceCtrl.Get_ShrsPartBySgld(ElemK, SgldK, StagK, iSerialStep, 1, ShrsStagCurMax, ShrsStagCurMin, 4))	continue;	// 4=Principal.
						if (!m_ForceCtrl.Get_ShrsPartBySgld(ElemK, SgldK, StagK, iSerialStep, 2, ShrsStagCurMax_Sl, ShrsStagCurMin_Sl, 4))	continue;	// 4=Principal.
					}
				}
			}
			else
			{
				if (m_pStageInfo->GetStepSerialKey(StagK, nCurStep, iSerialStep))
				{
					if (!bIsCpt)
					{
						if (!m_ForceCtrl.Get_StrsBySgld(ElemK, SgldK, StagK, iSerialStep, StrsStagCurMax, StrsStagCurMin))	continue;
						//
						if (!m_ForceCtrl.Get_ShrsBySgld(ElemK, SgldK, StagK, iSerialStep, ShrsStagCurMax, ShrsStagCurMin, 4))	continue;	// 4=Principal.
					}
					else
					{
						if (nCompositeType == 2)
						{
							if (!m_ForceCtrl.Get_StrsPartBySgld(ElemK, SgldK, StagK, iSerialStep, 1, StrsStagCurMax, StrsStagCurMin))	continue;
							if (!m_ForceCtrl.Get_ShrsPartBySgld(ElemK, SgldK, StagK, iSerialStep, 1, ShrsStagCurMax, ShrsStagCurMin, 4))	continue;	// 4=Principal.
						}
						else if (nCompositeType >= 3)
						{
							if (!m_ForceCtrl.Get_StrsPartBySgld(ElemK, SgldK, StagK, iSerialStep, 1, StrsStagCurMax, StrsStagCurMin))	continue;
							if (!m_ForceCtrl.Get_StrsPartBySgld(ElemK, SgldK, StagK, iSerialStep, 2, StrsStagCurMax_Sl, StrsStagCurMin_Sl))	continue;
							//
							if (!m_ForceCtrl.Get_ShrsPartBySgld(ElemK, SgldK, StagK, iSerialStep, 1, ShrsStagCurMax, ShrsStagCurMin, 4))	continue;	// 4=Principal.
							if (!m_ForceCtrl.Get_ShrsPartBySgld(ElemK, SgldK, StagK, iSerialStep, 2, ShrsStagCurMax_Sl, ShrsStagCurMin_Sl, 4))	continue;	// 4=Principal.
						}
						else ASSERT(0);
					}
				}
			}

			double dStep_Day = 0.0;
			m_pStageInfo->GetStagStepDay(StagK, nCurStep, dStep_Day); // Stage에서 각 step의 날짜

			nStepGr++;
			if (nStepGr == 1) dFirstStep_Day = dStep_Day;
			double dCurrStepAge = dStep_Day - dFirstStep_Day;

			T_ELFM_D dDayActive; dDayActive.Initialize();
			m_pPostCtrl->GetElfmDgn(StagK, ElemK, dDayActive);

			double dCurrAgeGr = dAgeGr + dCurrStepAge;

			double dfci = 0.0;
			if (bGetTdme) Get_InitCompressStrength(AgeD.TdmeKGr, dCurrAgeGr, dfci);

			if ( nCompositeType >= 3 )
			{
				nStepSlab++;
				if ( nStepSlab == 1 )
				{
					dStartStepSlab = dStep_Day;
				}
			}

			double dfci_sl = 0.0;
			if ( bGetTdmeSL )
			{
				if ( nCompositeType >= 3 )
				{
					double dCurrAgeSl = dStep_Day - dStartStepSlab + dAgeSl;
					Get_InitCompressStrength(AgeD.TdmeKSl, dCurrAgeSl, dfci_sl);
				}
			}

			mStepfci.SetAt(iSerialStep, dfci);
			mStepfci_sl.SetAt(iSerialStep, dfci_sl);
		}

		T_FYSG_PSC_BS FysgCalcD;
		FysgCalcD.Initialize();
		T_FPSG_PSC FpsgCalcD;
		FpsgCalcD.Initialize();
		for (int kk = 0; kk < 4; ++kk)
		{
			int iIdx = (kk == 0 || kk == 1) ? 0 : 1;
			// 0=I-MAX, 1=I-MIN, 2=J-MAX, 3=J-MIN.
			_DGN_STRS_CRC &StrsCrc = (kk % 2 == 0 ? StrsStagCurMax : StrsStagCurMin);
			//if(StrsCrc.dScom[i/2]==0.0)	continue;
			FysgCalcD.FysgGrB[kk].bCHK = Get_ChkFlag(ElemK, kk / 2, TRUE);
			FysgCalcD.FysgGrB[kk].StageK = StrsCrc.iRefNo[kk / 2];
			FysgCalcD.FysgGrB[kk].StepK = StrsCrc.iSerialStep[kk / 2];
			FysgCalcD.FysgGrB[kk].dFT = StrsCrc.dStop[kk / 2];
			FysgCalcD.FysgGrB[kk].dFB = StrsCrc.dSbot[kk / 2];
			FysgCalcD.FysgGrB[kk].dFTL = StrsCrc.dStl[kk / 2];
			FysgCalcD.FysgGrB[kk].dFBL = StrsCrc.dSbl[kk / 2];
			FysgCalcD.FysgGrB[kk].dFTR = StrsCrc.dStr[kk / 2];
			FysgCalcD.FysgGrB[kk].dFBR = StrsCrc.dSbr[kk / 2];
			FysgCalcD.FysgGrB[kk].dFMAX = StrsCrc.dScom[kk / 2];

			double dfci = 0.0;
			if (!mStepfci.Lookup(StrsCrc.iSerialStep[kk / 2], dfci) || fabs(dfci) < cDgn_Zero)
			{
				dfci = MembInD.Pos[iIdx].MatlD.C_fci;
			}

			FysgCalcD.FysgGrB[kk].dfci = dfci;
			FysgCalcD.FysgGrB[kk].dALW = 0.0;

			if (bIsCpt == TRUE)
			{
				_DGN_STRS_CRC &StrsCrc_Sl = (kk % 2 == 0 ? StrsStagCurMax_Sl : StrsStagCurMin_Sl);
				FysgCalcD.FysgSlB[kk].bCHK = Get_ChkFlag(ElemK, kk / 2, TRUE);
				FysgCalcD.FysgSlB[kk].StageK = StrsCrc_Sl.iRefNo[kk / 2];
				FysgCalcD.FysgSlB[kk].StepK = StrsCrc_Sl.iSerialStep[kk / 2];
				FysgCalcD.FysgSlB[kk].dFT = StrsCrc_Sl.dStop[kk / 2];
				FysgCalcD.FysgSlB[kk].dFB = StrsCrc_Sl.dSbot[kk / 2];
				FysgCalcD.FysgSlB[kk].dFTL = StrsCrc_Sl.dStl[kk / 2];
				FysgCalcD.FysgSlB[kk].dFBL = StrsCrc_Sl.dSbl[kk / 2];
				FysgCalcD.FysgSlB[kk].dFTR = StrsCrc_Sl.dStr[kk / 2];
				FysgCalcD.FysgSlB[kk].dFBR = StrsCrc_Sl.dSbr[kk / 2];
				FysgCalcD.FysgSlB[kk].dFMAX = StrsCrc_Sl.dScom[kk / 2];

				double dfci_sl = 0.0;
				if (!mStepfci_sl.Lookup(StrsCrc_Sl.iSerialStep[kk / 2], dfci_sl) || fabs(dfci_sl) < cDgn_Zero)
				{
					dfci_sl = MembInD.Pos[iIdx].MatlD.C_fci;
				}

				FysgCalcD.FysgSlB[kk].dfci = dfci_sl;
				FysgCalcD.FysgSlB[kk].dALW = 0.0;
			}

			_DGN_SHRS_CRC &ShrsD = (kk % 2 == 0 ? ShrsStagCurMax : ShrsStagCurMin);

			if (!bIsCpt)
			{
				T_FPSG_PSC_BASE &FpsgB = FpsgCalcD.FpsgBase[kk];
				FpsgB.bCHK = Get_ChkFlag(ElemK, kk / 2, FALSE);
				FpsgB.StageK = ShrsD.iRefNo[kk / 2]; // LcomK에 Stage Key를 입력한다.     
				FpsgB.StepK = ShrsD.iSerialStep[kk / 2];
				FpsgB.dFP1 = ShrsD.dSsp[kk / 2][0];
				FpsgB.dFP2 = ShrsD.dSsp[kk / 2][1];
				FpsgB.dFP3 = ShrsD.dSsp[kk / 2][2];
				FpsgB.dFP4 = ShrsD.dSsp[kk / 2][3];
				FpsgB.dFP5 = ShrsD.dSsp[kk / 2][4];
				FpsgB.dFP6 = ShrsD.dSsp[kk / 2][5];
				FpsgB.dFP7 = ShrsD.dSsp[kk / 2][6];
				FpsgB.dFP8 = ShrsD.dSsp[kk / 2][7];
				FpsgB.dFP9 = ShrsD.dSsp[kk / 2][8];
				FpsgB.dFP10 = ShrsD.dSsp[kk / 2][9];
				FpsgB.dFMAX = ShrsD.dSspAbs[kk / 2];	//Max,Min
				FpsgB.dAFP = 0.0;
			}
		}

		m_pPscDataCtrl->Get_StressCheckCSBS(ElemK, MembInD, FysgCalcD, FpsgCalcD);
		for (int kk = 0; kk < 4; ++kk)
		{
			if (FysgD.FysgGrB[kk].dALW < cDgn_Zero)
			{
				FysgD.FysgGrB[kk] = FysgCalcD.FysgGrB[kk];
				FysgD.FysgSlB[kk] = FysgCalcD.FysgSlB[kk];
			}
			else
			{
				double dRatCur = FysgCalcD.FysgGrB[kk].dALW > 0.0 ? fabs(FysgCalcD.FysgGrB[kk].dFMAX) / FysgCalcD.FysgGrB[kk].dALW : 0.0;
				double dRatMax = FysgD.FysgGrB[kk].dALW > 0.0 ? fabs(FysgD.FysgGrB[kk].dFMAX) / FysgD.FysgGrB[kk].dALW : 0.0;
				double dRatslCur = FysgCalcD.FysgSlB[kk].dALW > 0.0 ? fabs(FysgCalcD.FysgSlB[kk].dFMAX) / FysgCalcD.FysgSlB[kk].dALW : 0.0;
				double dRatslMax = FysgD.FysgSlB[kk].dALW > 0.0 ? fabs(FysgD.FysgSlB[kk].dFMAX) / FysgD.FysgSlB[kk].dALW : 0.0;
				if (max(dRatCur, dRatslCur) > max(dRatMax, dRatslMax)) {
					FysgD.FysgGrB[kk] = FysgCalcD.FysgGrB[kk];
					FysgD.FysgSlB[kk] = FysgCalcD.FysgSlB[kk];
				}
			}

			if (FpsgD.FpsgBase[kk].dAFP < cDgn_Zero)
			{
				FpsgD.FpsgBase[kk] = FpsgCalcD.FpsgBase[kk];
			}
			else
			{
				double dRatCur = FpsgCalcD.FpsgBase[kk].dAFP > 0.0 ? fabs(FpsgCalcD.FpsgBase[kk].dFMAX) / FpsgCalcD.FpsgBase[kk].dAFP : 0.0;
				double dRatMax = FpsgD.FpsgBase[kk].dAFP > 0.0 ? fabs(FpsgD.FpsgBase[kk].dFMAX) / FpsgD.FpsgBase[kk].dAFP : 0.0;
				if (dRatCur > dRatMax) {
					FpsgD.FpsgBase[kk] = FpsgCalcD.FpsgBase[kk];
				}
			}
		}
	}

	return TRUE;
}

BOOL CCRCDataCtrl::Get_StressResSLSPSC_BS(ElemPairK ElemK, PSC_DATA_MEMB &MembInD, T_FYCM_PSC_BS &FycmD, T_FPMS_PSC &FpmsD)
{
	// Check Calculating Item.
	if (!Is_CalcItem(ElemK, TRUE))  return FALSE;
	// PSC-Design/Strs(5), PSC-Design/Strn(6).
	int iDgnStatus = m_pDoc->GetDesignStatus();
	m_pDoc->SetDesignStatus(5);

	_DGN_STRS_CRC StrsMax;
	_DGN_STRS_CRC StrsMin;

	_DGN_STRS_CRC StrsMax_Sl;
	_DGN_STRS_CRC StrsMin_Sl;

	_DGN_STRS_CRC StressTnpr;
	_DGN_STRS_CRC StressTnsc;

	_DGN_SHRS_CRC ShrsMax;
	_DGN_SHRS_CRC ShrsMin;

	BOOL bIsCpt = IsCompositePSCSect(ElemK);

	m_ForceCtrl.Debug_PrintOpt(3);	// For DEBUG.

	int iClass[2] = { 0, };

	iClass[0] = MembInD.Pos[0].CalcD.nClass;
	iClass[1] = MembInD.Pos[1].CalcD.nClass;

	if (bIsCpt == FALSE)
	{
		if (!m_ForceCtrl.Get_StrsByLcomBS(ElemK, 0, StrsMax, StrsMin, iClass))	return FALSE;
	}
	else
	{
		if (!m_ForceCtrl.Get_StrsByLcomBS(ElemK, 1, StrsMax, StrsMin, iClass))	return FALSE;
		//
		if (!m_ForceCtrl.Get_StrsByLcomBS(ElemK, 2, StrsMax_Sl, StrsMin_Sl, iClass))	return FALSE;
	}

	if (!m_ForceCtrl.Get_ShrsByLcom(ElemK, ShrsMax, ShrsMin, 4, FALSE))	return FALSE;	// 3=Shear+Torsion.

	// Set Data.
	for (int i = 0; i < 4; ++i)
	{
		// 0=I-MAX, 1=I-MIN, 2=J-MAX, 3=J-MIN.
		_DGN_STRS_CRC &StrsCrc = (i % 2 == 0 ? StrsMax : StrsMin);
		int nIx = i / 2;

		int iDgnLcomNo = StrsCrc.iRefNo[nIx];
		if (iDgnLcomNo == 0) continue;
		CString strOrgLcomNa = _T("");
		int iMaxMinType = 0;
		if (!m_ForceCtrl.Get_LcomType(iDgnLcomNo, strOrgLcomNa, iMaxMinType))	ASSERT(0);

		FycmD.FycmGrB[i].bCHK = Get_ChkFlag(ElemK, i / 2, TRUE);
		FycmD.FycmGrB[i].LcomK = iDgnLcomNo;
		FycmD.FycmGrB[i].nKind = m_ForceCtrl.Get_ServLcomType(iDgnLcomNo);
		FycmD.FycmGrB[i].nMax = iMaxMinType;
		FycmD.FycmGrB[i].dFT = StrsCrc.dStop[nIx];
		FycmD.FycmGrB[i].dFB = StrsCrc.dSbot[nIx];
		FycmD.FycmGrB[i].dFTL = StrsCrc.dStl[nIx];
		FycmD.FycmGrB[i].dFBL = StrsCrc.dSbl[nIx];
		FycmD.FycmGrB[i].dFTR = StrsCrc.dStr[nIx];
		FycmD.FycmGrB[i].dFBR = StrsCrc.dSbr[nIx];
		FycmD.FycmGrB[i].dFMAX = StrsCrc.dScom[nIx];

		FycmD.FycmGrB[i].dALW = 0.0;	// From CRC.

		if (!bIsCpt)
		{
			_DGN_SHRS_CRC &ShrsD = (i % 2 == 0 ? ShrsMax : ShrsMin);
			if (ShrsD.dSspAbs[i / 2] == 0.0)	continue;

			FpmsD.FpmsBase[i].bCHK = Get_ChkFlag(ElemK, nIx, FALSE);
			FpmsD.FpmsBase[i].LcomK = iDgnLcomNo;
			FpmsD.FpmsBase[i].iKind = m_ForceCtrl.Get_ServLcomType(iDgnLcomNo); //m_ForceCtrl.Get_LcomKind(iDgnLcomNo);
			FpmsD.FpmsBase[i].iMax = iMaxMinType;
			FpmsD.FpmsBase[i].dFP1 = ShrsD.dSsp[nIx][0];
			FpmsD.FpmsBase[i].dFP2 = ShrsD.dSsp[nIx][1];
			FpmsD.FpmsBase[i].dFP3 = ShrsD.dSsp[nIx][2];
			FpmsD.FpmsBase[i].dFP4 = ShrsD.dSsp[nIx][3];
			FpmsD.FpmsBase[i].dFP5 = ShrsD.dSsp[nIx][4];
			FpmsD.FpmsBase[i].dFP6 = ShrsD.dSsp[nIx][5];
			FpmsD.FpmsBase[i].dFP7 = ShrsD.dSsp[nIx][6];
			FpmsD.FpmsBase[i].dFP8 = ShrsD.dSsp[nIx][7];
			FpmsD.FpmsBase[i].dFP9 = ShrsD.dSsp[nIx][8];
			FpmsD.FpmsBase[i].dFP10 = ShrsD.dSsp[nIx][9];
			FpmsD.FpmsBase[i].dFMAX = ShrsD.dSspAbs[nIx];	//Max,Min
			FpmsD.FpmsBase[i].dAFP = 0.0;
		}
	}
	//
	if (bIsCpt == TRUE)
	{
		for (int i = 0; i < 4; ++i)
		{
			// 0=I-MAX, 1=I-MIN, 2=J-MAX, 3=J-MIN.
			_DGN_STRS_CRC &StrsCrc = (i % 2 == 0 ? StrsMax_Sl : StrsMin_Sl);
			int nIx = i / 2;
			if (StrsCrc.dScom[nIx] == 0.0)	continue;

			int iDgnLcomNo = StrsCrc.iRefNo[nIx];
			CString strOrgLcomNa = _T("");
			int iMaxMinType = 0;
			if (!m_ForceCtrl.Get_LcomType(iDgnLcomNo, strOrgLcomNa, iMaxMinType))	ASSERT(0);

			FycmD.FycmSlB[i].bCHK = Get_ChkFlag(ElemK, nIx, TRUE);
			FycmD.FycmSlB[i].LcomK = iDgnLcomNo;
			FycmD.FycmSlB[i].nKind = m_ForceCtrl.Get_ServLcomType(iDgnLcomNo);
			FycmD.FycmSlB[i].nMax = iMaxMinType;
			FycmD.FycmSlB[i].dFT = StrsCrc.dStop[nIx];
			FycmD.FycmSlB[i].dFB = StrsCrc.dSbot[nIx];
			FycmD.FycmSlB[i].dFTL = StrsCrc.dStl[nIx];
			FycmD.FycmSlB[i].dFBL = StrsCrc.dSbl[nIx];
			FycmD.FycmSlB[i].dFTR = StrsCrc.dStr[nIx];
			FycmD.FycmSlB[i].dFBR = StrsCrc.dSbr[nIx];
			FycmD.FycmSlB[i].dFMAX = StrsCrc.dScom[nIx];
			FycmD.FycmSlB[i].dALW = 0.0;	// From CRC.
		}
	}

	m_pPscDataCtrl->Get_StressCheckSLSBS(ElemK, MembInD, FycmD, FpmsD);

	return TRUE;
}

BOOL CCRCDataCtrl::Get_CrackResSLSPSC_BS(ElemPairK ElemK, PSC_DATA_MEMB &MembInD, T_BDCW_PSC_BS &rData)
{
	rData.Initialize();
	if (m_iCivilCode != CS_454_20_PSC_RATING) return FALSE;

	// Check Calculating Item.
	if (!Is_CalcItem(ElemK, TRUE))  return FALSE;
	// PSC-Design/Strs(5), PSC-Design/Strn(6).
	int iDgnStatus = m_pDoc->GetDesignStatus();
	m_pDoc->SetDesignStatus(6);

	BOOL bChkI = Get_ChkFlag(ElemK, 0, TRUE);
	BOOL bChkJ = Get_ChkFlag(ElemK, 1, TRUE);

	int icounter1 = 0;
	int ilc1[2] = { 0,0 }, istresslcom[2] = { 0,0 };
	double dMyMax[2] = { 0.,0. }, dMyMin[2] = { 0.,0. };
	int iMaxDgnLcom[2] = { 0,0 }, iMinDgnLcom[2] = { 0,0 };
	int iAbsMaxDgnLcom[2] = { 0,0 }, iAbsMinDgnLcom[2] = { 0,0 };
	double dStrs_cmax[2] = { 0,0 }, dStrs_tmax[2] = { 0,0 };

	// 필요한 Force Max/Min 값을 찾음.
	BOOL bStrength = FALSE;
	if (!Get_CheckForceMu_MaxMin(bStrength, ElemK, dMyMax, dMyMin, iMaxDgnLcom, iMinDgnLcom)) return FALSE;

	CArray<T_LCOM_K, T_LCOM_K> arLcomKey;
	m_pAttrCtrl->GetLcomKeyList(D_LCOMTYPE_CONCRETE, arLcomKey);
	for (int lc = 0; lc < arLcomKey.GetSize(); lc++)
	{
		T_LCOM_D LcomData;
		LcomData.Initialize();
		m_pAttrCtrl->GetLcom(D_LCOMTYPE_CONCRETE, arLcomKey[lc], LcomData);

		if (LcomData.nServLcomType >= 1)//Selected Load Combination from CDgnGenLcomServAS5100Dlg
		{
			ADGNFORCE aForceLcom;
			if (!m_ForceCtrl.Get_LcomDataForDesign(ElemK, 0, TRUE, FALSE, aForceLcom, lc + 1))	return FALSE;

			ADGNSTRESS aStressLcom;
			ADGNSTRESS aStressTnpr;
			if (!m_ForceCtrl.Get_LcomDataForStress(ElemK, 0, TRUE, FALSE, aStressLcom, aStressTnpr, lc + 1)) return FALSE;
			int nStressLcomSize = aStressLcom.GetSize();
			int icounter = 0;
			double dMaxTensStressTop[2], dMaxTensStressBot[2];
			double dStrs_c = 0.0, dStrs_t = 0.0;

			for (int i = 0; i < nStressLcomSize; ++i)
			{
				_DGN_FORC_CRC &ForceD = aForceLcom[i];
				_DGN_STRS_CRC &StressD = aStressLcom[i];

				for (int j = 0; j < 2; j++)
				{

					m_ForceCtrl.Get_CompTensStress(j, StressD, dStrs_c, dStrs_t);

					if (icounter + icounter1 == 0)
					{
						dMaxTensStressTop[j] = dStrs_t;
						dMaxTensStressBot[j] = dStrs_c;
						iMaxDgnLcom[j] = LcomData.LoadCombId;
						iMinDgnLcom[j] = LcomData.LoadCombId;
						istresslcom[j] = icounter;
					}
					else
					{

						dMaxTensStressTop[j] = abs(dMaxTensStressTop[j]) > abs(dStrs_t) ? dMaxTensStressTop[j] : dStrs_t;
						dMaxTensStressBot[j] = abs(dMaxTensStressBot[j]) > abs(dStrs_c) ? dMaxTensStressBot[j] : dStrs_c;

						if (abs(dMaxTensStressTop[j]) == abs(dStrs_t)) { iMaxDgnLcom[j] = LcomData.LoadCombId; istresslcom[0] = icounter; }
						if (abs(dMaxTensStressBot[j]) == abs(dStrs_c)) { iMinDgnLcom[j] = LcomData.LoadCombId; istresslcom[1] = icounter; }
					}
				}
				icounter++;
			}
			for (int j = 0; j < 2; j++)
			{
				if (icounter1 == 0)
				{
					dStrs_tmax[j] = dMaxTensStressTop[j], dStrs_cmax[j] = dMaxTensStressBot[j];
					iAbsMaxDgnLcom[j] = lc;
					iAbsMinDgnLcom[j] = lc;
					ilc1[j] = istresslcom[j];
				}
				else
				{
					dStrs_cmax[j] = abs(dStrs_c) > abs(dStrs_cmax[j]) ? dStrs_c : dStrs_cmax[j];
					dStrs_tmax[j] = abs(dStrs_t) > abs(dStrs_tmax[j]) ? dStrs_t : dStrs_tmax[j];

					if (abs(dStrs_c) == abs(dStrs_cmax[j])) { iAbsMaxDgnLcom[j] = lc; ilc1[0] = istresslcom[0]; }
					if (abs(dStrs_t) == abs(dStrs_tmax[j])) { iAbsMinDgnLcom[j] = lc; ilc1[1] = istresslcom[1]; }
				}
			}

			icounter1++;
		}
	}

	T_LCOM_D LcomData;
	LcomData.Initialize();
	m_pAttrCtrl->GetLcom(D_LCOMTYPE_CONCRETE, arLcomKey[iAbsMaxDgnLcom[0]], LcomData);

	ADGNFORCE aForceLcom;
	if (!m_ForceCtrl.Get_LcomDataForDesign(ElemK, 0, TRUE, FALSE, aForceLcom, arLcomKey[iAbsMaxDgnLcom[0]]))	return FALSE;
	/*
		ADGNSTRESS aStressLcom;
		ADGNSTRESS aStressTnpr;
		if (!m_ForceCtrl.Get_LcomDataForStress(ElemK, 0, TRUE, FALSE, aStressLcom, aStressTnpr, arLcomKey[iAbsMaxDgnLcom[0]])) return FALSE;
	*/
	// Get MQ IRS Get Max/Min Moment by Moving Load Case.
	double dMuyMaxI = 0.0, dMuyMinI = 0.0, dMuyMaxJ = 0.0, dMuyMinJ = 0.0;
	Get_MqIRS(ElemK, dMuyMaxI, dMuyMinI, dMuyMaxJ, dMuyMinJ);
	// Set Data.
	for (int i = 0; i < 4; ++i)
	{
		// 0=I-TOP_MAX, 1=I-BOT_MAX, 2=J-TOP_MAX, 3=J-BOT_MAX.
		// 0=I-MAX, 1=I-MIN, 2=J-MAX, 3=J-MIN.
		_DGN_FORC_CRC &ForceD = aForceLcom[ilc1[i / 2]];
		//_DGN_STRS_CRC &StressD = aStressLcom[ilc1[i/2]];
		double dMuy = (i < 2 ? ForceD.dMuy[0] : ForceD.dMuy[1]);
		double dFxx = (i < 2 ? ForceD.dFxx[0] : ForceD.dFxx[1]);
		double dft = (i < 2 ? dStrs_tmax[0] : dStrs_tmax[1]);
		double dfb = (i < 2 ? dStrs_cmax[0] : dStrs_cmax[1]);

		int iDgnLcomNo = (i % 2 == 1 ? iAbsMaxDgnLcom[i / 2] : iAbsMinDgnLcom[i / 2]); iDgnLcomNo++; // negative면 Top검토
		CString strOrgLcomNa = _T("");
		int iMaxMinType = 0;
		if (!m_ForceCtrl.Get_LcomType(iDgnLcomNo, strOrgLcomNa, iMaxMinType))	ASSERT(0);
		if (i % 2 == 1) { dMuy = (dMuy < 0.0 ? 0.0 : dMuy); } // negative면 Top검토 
		else { dMuy = (dMuy > 0.0 ? 0.0 : dMuy); }

		T_BDCW_PSC_BS_BASE &BdcwB = rData.BdcwB[i];
		BdcwB.bCHK = (i / 2 == 0) ? bChkI : bChkJ;
		BdcwB.LcomK = iDgnLcomNo;
		BdcwB.iMax = iMaxMinType;
		BdcwB.dMu = dMuy;
		BdcwB.dPu = dFxx;
		BdcwB.dft = dft;
		BdcwB.dfb = dfb;
		BdcwB.dMq = (i / 2 == 0) ? abs(dMuyMinI) : abs(dMuyMinJ);
		BdcwB.dMg = (i / 2 == 0) ? abs(dMuy - dMuyMinI) : abs(dMuy - dMuyMinJ);
	}

	if (!m_pPscDataCtrl->Get_BdcwDataBS(ElemK, MembInD, rData)) return FALSE;

	return TRUE;
}

BOOL CCRCDataCtrl::Get_StrengthResULSPSC_BS(ElemPairK ElemK, PSC_DATA_MEMB &MembInD, T_BDCR_PSC_BS &BdcrD, T_SHRR_PSC_BS &ShrrD, T_TORR_PSC_BS &TorrD)
{
	m_pDoc->SetDesignStatus(6);

	//////////////////////////////////////////////////////////////////////////  
	double dForceTpI[6] = { 0.0, };
	double dForceTpJ[6] = { 0.0, };
	m_ForceCtrl.Get_ForceByTnPr(ElemK, dForceTpI, dForceTpJ);
	//////////////////////////////////////////////////////////////////////////  

	// 휨 강도 검토
	Get_BdcrDataBS(ElemK, MembInD, BdcrD);

	int nLcomNum = m_ForceCtrl.Get_LcomDataCount();
	ADGNFORCE aForceLcom;
	ADGNFORCE aForceTnpr;
	ADGNFORCE aForceTnsc;
	ADGNFORCE aForceLTerm;
	ADGNFORCE aForceSTerm;
	ADGNSHRSADD aStssLcom;
	if (!m_ForceCtrl.Get_LcomDataForDesign(ElemK, TRUE, TRUE, aForceLcom, aForceTnpr, aForceTnsc, aForceLTerm, aForceSTerm, aStssLcom, nLcomNum)) return FALSE;

	double dRatScr[2] = { 0.0, 0.0 };
	double dRatTcr[2] = { 0.0, 0.0 };
	PSC_CUMS_BASE ShearCrD[2];
	PSC_CRMT_BASE TorsionCrD[2];

	BOOL bChkShrI = Get_ChkFlag(ElemK, 0, FALSE);
	BOOL bChkShrJ = Get_ChkFlag(ElemK, 1, FALSE);
	BOOL bChkTorI = Get_ChkFlag(ElemK, 0, FALSE);
	BOOL bChkTorJ = Get_ChkFlag(ElemK, 1, FALSE);
	BOOL bChkI = (bChkShrI || bChkTorI);
	BOOL bChkJ = (bChkShrJ || bChkTorJ);

	int nCount = 0;
	int nForcLcomSize = aForceLcom.GetSize();
	for (int i = 0; i < nForcLcomSize; ++i)
	{
		if (!m_ForceCtrl.Is_LcomForStrn(i + 1))	continue;
		nCount++;

		_DGN_FORC_CRC &ForceD = aForceLcom.GetAt(i);

		int nDgnLcomNo = i + 1;
		CString strOrgLcomNa = _T("");
		int nMaxMinType = 0;
		if (!m_ForceCtrl.Get_LcomType(nDgnLcomNo, strOrgLcomNa, nMaxMinType))	ASSERT(0);

		PSC_CUMS_BASE ShrD[2]; // I,J

		for (int j = 0; j < 2; ++j)
		{
			ShrD[j].bCHK = (j == 0) ? bChkShrI : bChkShrJ;
			ShrD[j].LcomK = nDgnLcomNo;
			ShrD[j].iKind = m_ForceCtrl.Get_LcomKind(nDgnLcomNo);
			ShrD[j].iMax = nMaxMinType;
			ShrD[j].dPu = ForceD.dFxx[j];
			ShrD[j].dVu = ForceD.dFzz[j];
			ShrD[j].dMu = ForceD.dMuy[j];

            for ( int nFor = 0; nFor < 6; ++nFor )
            {
                ShrD[j].dForceTP[nFor] = j == 0 ? dForceTpI[nFor] : dForceTpJ[nFor];
            }
		}
		//
		m_pPscDataCtrl->Get_CumsDataBS(ElemK, MembInD, ShrD);

		PSC_CRMT_BASE ShrTorD[2]; // I,J

		for (int j = 0; j < 2; ++j)
		{
			ShrTorD[j].bCHK = (j == 0) ? bChkTorI : bChkTorJ;
			ShrTorD[j].LcomK = nDgnLcomNo;
			ShrTorD[j].iKind = m_ForceCtrl.Get_LcomKind(nDgnLcomNo);
			ShrTorD[j].iMax = nMaxMinType;
			ShrTorD[j].dPu = ForceD.dFxx[j];
			ShrTorD[j].dVu = ForceD.dFzz[j];
			ShrTorD[j].dMu = ForceD.dMuy[j];
			ShrTorD[j].dTu = ForceD.dMux[j];
		}
		//
		m_pPscDataCtrl->Get_CrmtDataBS(ElemK, MembInD, ShrTorD);

		BOOL bChkShrIJ[2] = { bChkShrI, bChkShrJ };
		BOOL bChkTorIJ[2] = { bChkTorI, bChkTorJ };
		if (nCount == 1)
		{
			for (int k = 0; k < 2; ++k)
			{
				if (bChkShrIJ[k] == TRUE)
				{
					dRatScr[k] = ShrD[k].dV_rat;
					ShearCrD[k] = ShrD[k];
				}
				if (bChkTorIJ[k] == TRUE)
				{
					dRatTcr[k] = ShrTorD[k].dComb_rat;
					TorsionCrD[k] = ShrTorD[k];
				}
			}
		}
		else
		{
			for (int k = 0; k < 2; ++k)
			{
				if (bChkShrIJ[k] == TRUE)
				{
					if (dRatScr[k] < ShrD[k].dV_rat)
					{
						dRatScr[k] = ShrD[k].dV_rat;
						ShearCrD[k] = ShrD[k];
					}
				}
				if (bChkTorIJ[k] == TRUE)
				{
					if (dRatTcr[k] < ShrTorD[k].dComb_rat)
					{
						dRatTcr[k] = ShrTorD[k].dComb_rat;
						TorsionCrD[k] = ShrTorD[k];
					}
				}
			}
		}
	}

	CDgn_PSCManager PscManager;
	for (int i = 0; i < 2; ++i)
	{
		PscManager.ConvertCums_EngineToCivilBS(ShearCrD[i], ShrrD.ShrrB[i]);
		PscManager.ConvertCrmt_EngineToCivilBS(TorsionCrD[i], TorrD.TorrB[i]);
	}

	return TRUE;
}

BOOL CCRCDataCtrl::Get_BdcrDataBS(ElemPairK ElemK, PSC_DATA_MEMB &MembInD, T_BDCR_PSC_BS &rData)
{
	rData.Initialize();
	// Check Calculating Item.
	if (!Is_CalcItem(ElemK, TRUE))  return FALSE;
	// PSC-Design/Strs(5), PSC-Design/Strn(6).
	int iDgnStatus = m_pDoc->GetDesignStatus();
	m_pDoc->SetDesignStatus(6);

	double dMyMax[2] = { 0.,0. }, dMyMin[2] = { 0.,0. };
	int iMaxDgnLcom[2] = { 0,0 }, iMinDgnLcom[2] = { 0,0 };

	// 필요한 Force Max/Min 값을 찾음.
	BOOL bStrength = TRUE;
	if (!Get_CheckForceMu_MaxMin(bStrength, ElemK, dMyMax, dMyMin, iMaxDgnLcom, iMinDgnLcom)) return FALSE;

	BOOL bChkFlex[4] = { FALSE, FALSE, FALSE, FALSE };
	for (int i = 0; i < 4; ++i)
	{
		// 0=I-MAX, 1=I-MIN, 2=J-MAX, 3=J-MIN.
		int iDgnLcomNo = (i % 2 == 0 ? iMaxDgnLcom[i / 2] : iMinDgnLcom[i / 2]);
		CString strOrgLcomNa = _T("");
		int iMaxMinType = 0;
		if (!m_ForceCtrl.Get_LcomType(iDgnLcomNo, strOrgLcomNa, iMaxMinType))	ASSERT(0);
		double dMuy = (i % 2 == 0 ? dMyMax[i / 2] : dMyMin[i / 2]);
		if (i % 2 == 0) { dMuy = (dMuy < 0.0 ? 0.0 : dMuy); }
		else { dMuy = (dMuy > 0.0 ? 0.0 : dMuy); }

		rData.BdcrB[i].bCHK = Get_ChkFlag(ElemK, i / 2, TRUE);
		rData.BdcrB[i].LcomK = iDgnLcomNo;
		rData.BdcrB[i].nKind = m_ForceCtrl.Get_LcomKind(iDgnLcomNo);
		rData.BdcrB[i].nMax = iMaxMinType;
		rData.BdcrB[i].dMy = dMuy;

		bChkFlex[i] = Get_ChkFlag(ElemK, i / 2, TRUE) || Get_ChkFlag(ElemK, i / 2, FALSE);
	}

	if (!m_pPscDataCtrl->Get_BdcrDataBS(ElemK, bChkFlex, MembInD, rData)) return FALSE;

	CString sBendingErrMsg = _T("");
	for (int i = 0; i < 4; ++i)
	{
		if (rData.BdcrB[i].bCHK)
		{
			CString strIJ = i < 2 ? _T("I") : _T("J");
			if (rData.BdcrB[i].bOK == D_PSC_FRC_ERR_Iteration_Over)
			{
				CString strPN = i % 2 == 0 ? _T("P") : _T("N"); // Positive/Negative
				CString strPosi;
				strPosi.Format(_T("%d-%s(%s)"), ElemK, strIJ, strPN);
				sBendingErrMsg.Format(_LS(IDS_DGN_WARN_BEND_NEUTRAL_AXIS_Err), strPosi); // [Warning] Midas Civil has failed to find the neutral axis(member no.: xxxx). Please check the PSC Design Calculation sheet for details.
				GSaveHistoryFormatNF(sBendingErrMsg);
			}
		}
	}

	return TRUE;
}

BOOL CCRCDataCtrl::Get_CheckForceMu_MaxMin(BOOL bStrengh, ElemPairK ElemK, double* pdMyMax, double* pdMyMin, int* piMaxDgnLcom, int* piMinDgnLcom)
{
	int iLcomNum = m_ForceCtrl.Get_LcomDataCount();
	ADGNFORCE aForceLcom;
	if (!m_ForceCtrl.Get_LcomDataForDesign(ElemK, 0, TRUE, FALSE, aForceLcom, iLcomNum))	return FALSE;
	if (bStrengh) { if (m_ForceCtrl.Get_LcomNumForStrn() == 0)	return FALSE; }
	else { if (m_ForceCtrl.Get_LcomNumForStrs() == 0)	return FALSE; }

	double dMyMax[2] = { 0.0,0.0 }, dMyMin[2] = { 0.0,0.0 };
	int iMaxDgnLcom[2] = { 0,0 }, iMinDgnLcom[2] = { 0,0 };
	int i = 0, j = 0;

	int iCount = 0;
	int nForceLcomSize = aForceLcom.GetSize();
	for (i = 0; i < nForceLcomSize; ++i)
	{
		if (bStrengh) { if (!m_ForceCtrl.Is_LcomForStrn(i + 1))	continue; }
		else { if (!m_ForceCtrl.Is_LcomForStrs(i + 1))	continue; }
		iCount++;
		_DGN_FORC_CRC &ForceD = aForceLcom.GetAt(i);
		for (j = 0; j < 2; ++j)	// I,J.
		{
			if (iCount == 1)
			{
				dMyMax[j] = ForceD.dMuy[j]; iMaxDgnLcom[j] = i + 1;
				dMyMin[j] = ForceD.dMuy[j]; iMinDgnLcom[j] = i + 1;
			}
			else
			{
				if (ForceD.dMuy[j] > dMyMax[j]) { dMyMax[j] = ForceD.dMuy[j]; iMaxDgnLcom[j] = i + 1; }
				if (ForceD.dMuy[j] < dMyMin[j]) { dMyMin[j] = ForceD.dMuy[j]; iMinDgnLcom[j] = i + 1; }
			}
		}
	}

	for (j = 0; j < 2; ++j)	// I,J.
	{
		pdMyMax[j] = dMyMax[j];
		pdMyMin[j] = dMyMin[j];
		piMaxDgnLcom[j] = iMaxDgnLcom[j];
		piMinDgnLcom[j] = iMinDgnLcom[j];
	}

	return TRUE;
}

BOOL CCRCDataCtrl::Get_CheckForceMu_MaxMin(BOOL bStrengh, ElemPairK ElemK, double* pdMyMax, double* pdMyMin, int* piMaxDgnLcom, int* piMinDgnLcom, double* pdFyMax, double* pdFyMin, double* pdFxMax, double* pdFxMin)
{
	int iLcomNum = m_ForceCtrl.Get_LcomDataCount();
	ADGNFORCE aForceLcom;
	if (!m_ForceCtrl.Get_LcomDataForDesign(ElemK, 0, TRUE, FALSE, aForceLcom, iLcomNum))	return FALSE;
	if (bStrengh) { if (m_ForceCtrl.Get_LcomNumForStrn() == 0)	return FALSE; }
	else { if (m_ForceCtrl.Get_LcomNumForStrs() == 0)	return FALSE; }

	double dMyMax[2] = { 0.0,0.0 }, dMyMin[2] = { 0.0,0.0 };
	double dFyMax[2] = { 0.0,0.0 }, dFyMin[2] = { 0.0,0.0 };
	double dFxMax[2] = { 0.0,0.0 }, dFxMin[2] = { 0.0,0.0 };
	int iMaxDgnLcom[2] = { 0,0 }, iMinDgnLcom[2] = { 0,0 };
	int i = 0, j = 0;

	int iCount = 0;
	int nForceLcomSize = aForceLcom.GetSize();
	for (i = 0; i < nForceLcomSize; ++i)
	{
		if (bStrengh) { if (!m_ForceCtrl.Is_LcomForStrn(i + 1))	continue; }
		else { if (!m_ForceCtrl.Is_LcomForStrs(i + 1))	continue; }
		iCount++;
		_DGN_FORC_CRC &ForceD = aForceLcom.GetAt(i);
		for (j = 0; j < 2; ++j)	// I,J.
		{
			if (iCount == 1)
			{
				dMyMax[j] = ForceD.dMuy[j]; iMaxDgnLcom[j] = i + 1;
				dMyMin[j] = ForceD.dMuy[j]; iMinDgnLcom[j] = i + 1;
				dFyMax[j] = ForceD.dFzz[j];
				dFyMin[j] = ForceD.dFzz[j];
				dFxMax[j] = ForceD.dFxx[j];
				dFxMin[j] = ForceD.dFxx[j];
			}
			else
			{
				if (ForceD.dMuy[j] > dMyMax[j]) { dMyMax[j] = ForceD.dMuy[j]; iMaxDgnLcom[j] = i + 1; dFyMax[j] = ForceD.dFzz[j]; dFxMax[j] = ForceD.dFxx[j]; }
				if (ForceD.dMuy[j] < dMyMin[j]) { dMyMin[j] = ForceD.dMuy[j]; iMinDgnLcom[j] = i + 1; dFyMin[j] = ForceD.dFzz[j]; dFxMin[j] = ForceD.dFxx[j]; }
			}
		}
	}

	for (j = 0; j < 2; ++j)	// I,J.
	{
		pdMyMax[j] = dMyMax[j];
		pdMyMin[j] = dMyMin[j];
		piMaxDgnLcom[j] = iMaxDgnLcom[j];
		piMinDgnLcom[j] = iMinDgnLcom[j];
		pdFyMax[j] = dFyMax[j];
		pdFyMin[j] = dFyMin[j];
		pdFxMax[j] = dFxMax[j];
		pdFxMin[j] = dFxMin[j];
	}

	return TRUE;
}

BOOL CCRCDataCtrl::Get_CheckSigma_MaxMin_FatgPsc(BOOL bStrengh, ElemPairK ElemK, double* pSigLcom_max_t, double* pSigLcom_min_t, int* pMaxSigLcom_t,
	double* pSigLcom_max_b, double* pSigLcom_min_b, int* pMaxSigLcom_b,
	double* pVuLcom_max, double* pVuLcom_min, int* pMaxVuLcom)
{
	int iLcomNum = m_ForceCtrl.Get_LcomDataCount();

	// 부재력
	ADGNFORCE aForceLcom;
	if (!m_ForceCtrl.Get_LcomDataForDesign(ElemK, 0, TRUE, FALSE, aForceLcom, iLcomNum))	return FALSE;
	if (bStrengh) if (m_ForceCtrl.Get_LcomNumForStrn() == 0)	return FALSE;   // Strength 하중조합
	else         if (m_ForceCtrl.Get_LcomNumForStrs() == 0)	return FALSE;   // Serviceability 하중조합 

	// 응력
	ADGNSTRESS aStressLcom;
	ADGNSTRESS aStressTnpr;
	if (!m_ForceCtrl.Get_LcomDataForStress(ElemK, 0, TRUE, FALSE, aStressLcom, aStressTnpr, iLcomNum)) return FALSE;

	double dSigLcom_max_t[2] = { 0.0 };  // I/J
	double dSigLcom_min_t[2] = { 0.0 };
	double dSigLcom_max_b[2] = { 0.0 };
	double dSigLcom_min_b[2] = { 0.0 };
	double dVuLcom_max[2] = { 0.0 };
	double dVuLcom_min[2] = { 0.0 };

	int nMaxSigLcom_t[2] = { 0 };
	int nMaxSigLcom_b[2] = { 0 };
	int nMaxVuLcom[2] = { 0 };

	CArray<T_LCOM_K, T_LCOM_K> aFatiLcomK;
	m_ForceCtrl.m_aFatiLcomId.GetSortedKeyListforUintK(aFatiLcomK);

	int nFatiLcomSize = aFatiLcomK.GetSize();
	for (int i = 0; i < nFatiLcomSize; ++i)  // 하중조합 개수
	{
		double dSig_max_t[2] = { 0.0 };  // I/J
		double dSig_min_t[2] = { 0.0 };
		double dSig_max_b[2] = { 0.0 };
		double dSig_min_b[2] = { 0.0 };
		double dVu_max[2] = { 0.0 };
		double dVu_min[2] = { 0.0 };

		T_DGN_LCOM_ID FatiLcomId;
		T_LCOM_K nLcomKOrg = aFatiLcomK[i];  // = nOrgLcomNo
		if (!m_ForceCtrl.m_aFatiLcomId.Lookup(aFatiLcomK[i], FatiLcomId)) continue;
		int nFatiConcSize = FatiLcomId.aDgnLcomId.GetSize();

		for (int j = 0; j < nFatiConcSize; ++j)  // fat 하중조합의 type개수
		{
			int nDgnLcomId = FatiLcomId.aDgnLcomId[j];
			int nOrgLcomNo = 0;
			int nSerLcomCount = 0;
			int nMaxMinType = 0;
			CString strOrgLcomNa = _T("");

			if (!m_ForceCtrl.Get_LcomType(nDgnLcomId, strOrgLcomNa, nOrgLcomNo, nSerLcomCount, nMaxMinType)) { ASSERT(0); }  // 

			int nLcomIndex = nDgnLcomId - 1;
			_DGN_FORC_CRC &ForceD = aForceLcom[nLcomIndex];
			_DGN_STRS_CRC &StressD = aStressLcom[nLcomIndex];

			for (int nIJ = 0; nIJ < 2; ++nIJ)	// I,J.
			{
				double dMu = ForceD.dMuy[nIJ];

				if (j == 0)
				{
					dSig_max_t[nIJ] = StressD.dStop[nIJ];   // - 압축 + 인장
					dSig_min_t[nIJ] = StressD.dStop[nIJ];
					dSig_max_b[nIJ] = StressD.dSbot[nIJ];
					dSig_min_b[nIJ] = StressD.dSbot[nIJ];
					dVu_max[nIJ] = ForceD.dFzz[nIJ];
					dVu_min[nIJ] = ForceD.dFzz[nIJ];
				}
				else
				{
					if (StressD.dStop[nIJ] > dSig_max_t[nIJ]) { dSig_max_t[nIJ] = StressD.dStop[nIJ]; }
					if (StressD.dStop[nIJ] < dSig_min_t[nIJ]) { dSig_min_t[nIJ] = StressD.dStop[nIJ]; }

					if (StressD.dStop[nIJ] > dSig_max_t[nIJ]) { dSig_max_t[nIJ] = StressD.dStop[nIJ]; }
					if (StressD.dStop[nIJ] < dSig_min_t[nIJ]) { dSig_min_t[nIJ] = StressD.dStop[nIJ]; }

					if (ForceD.dFzz[nIJ] > dVu_max[nIJ]) { dVu_max[nIJ] = ForceD.dFzz[nIJ]; }
					if (ForceD.dFzz[nIJ] < dVu_min[nIJ]) { dVu_min[nIJ] = ForceD.dFzz[nIJ]; }
				}
			}
		} // nFatiConcSize

		// 하중조합중 가장 불리한 것 찾기
		for (int nIJ = 0; nIJ < 2; ++nIJ)	// I,J.
		{
			if (i == 0)
			{
				dSigLcom_max_t[nIJ] = dSig_max_t[nIJ];  // I/J
				dSigLcom_min_t[nIJ] = dSig_min_t[nIJ];
				dSigLcom_max_b[nIJ] = dSig_max_b[nIJ];
				dSigLcom_min_b[nIJ] = dSig_min_b[nIJ];
				dVuLcom_max[nIJ] = dVu_max[nIJ];
				dVuLcom_min[nIJ] = dVu_min[nIJ];

				nMaxSigLcom_t[nIJ] = nLcomKOrg;
				nMaxSigLcom_b[nIJ] = nLcomKOrg;
				nMaxVuLcom[nIJ] = nLcomKOrg;
			}
			else
			{
				double dDelSigLcom_t = fabs(dSigLcom_max_t[nIJ] - dSigLcom_min_t[nIJ]);
				double dDelSigLcom_b = fabs(dSigLcom_max_b[nIJ] - dSigLcom_min_b[nIJ]);
				double dDelVuLcom = fabs(dVuLcom_max[nIJ] - dVuLcom_min[nIJ]);

				double dDelSig_t = fabs(dSig_max_t[nIJ] - dSig_min_t[nIJ]);
				double dDelSig_b = fabs(dSig_max_b[nIJ] - dSig_min_b[nIJ]);
				double dDelVu = fabs(dVu_max[nIJ] - dVu_min[nIJ]);

				if (dDelSig_t > dDelSigLcom_t)
				{
					dSigLcom_max_t[nIJ] = dSig_max_t[nIJ];
					dSigLcom_min_t[nIJ] = dSig_min_t[nIJ];
					nMaxSigLcom_t[nIJ] = nLcomKOrg;
				}

				if (dDelSig_b > dDelSigLcom_b)
				{
					dSigLcom_max_b[nIJ] = dSig_max_b[nIJ];
					dSigLcom_min_b[nIJ] = dSig_min_b[nIJ];
					nMaxSigLcom_b[nIJ] = nLcomKOrg;
				}

				if (dDelVu > dDelVuLcom)
				{
					dVuLcom_max[nIJ] = dVu_max[nIJ];
					dVuLcom_min[nIJ] = dVu_min[nIJ];
					nMaxVuLcom[nIJ] = nLcomKOrg;
				}
			}
		}
	} // nFatiLcomSize

	// 데이터 저장
	for (int nIJ = 0; nIJ < 2; ++nIJ)	// I,J.
	{
		pSigLcom_max_t[nIJ] = dSigLcom_max_t[nIJ];
		pSigLcom_min_t[nIJ] = dSigLcom_min_t[nIJ];
		pMaxSigLcom_t[nIJ] = nMaxSigLcom_t[nIJ];

		pSigLcom_max_b[nIJ] = dSigLcom_max_b[nIJ];
		pSigLcom_min_b[nIJ] = dSigLcom_min_b[nIJ];
		pMaxSigLcom_b[nIJ] = nMaxSigLcom_b[nIJ];

		pVuLcom_max[nIJ] = dVuLcom_max[nIJ];
		pVuLcom_min[nIJ] = dVuLcom_min[nIJ];
		pMaxVuLcom[nIJ] = nMaxVuLcom[nIJ];
	}

	return TRUE;
}

BOOL CCRCDataCtrl::Get_CumsForce_Mu_MaxMin(ElemPairK ElemK, double* pdMaxMu, double* pdMinMu)
{
	int iLcomNum = m_ForceCtrl.Get_LcomDataCount();

	ADGNFORCE aForceLcom;
	int nForType = 0;
	if (!m_ForceCtrl.Get_LcomDataForDesign(ElemK, nForType, TRUE, FALSE, aForceLcom, iLcomNum))	return FALSE;
	if (m_ForceCtrl.Get_LcomNumForStrn() == 0)	return FALSE;

	double dMmax[2] = { 0.,0. }, dMmin[2] = { 0.,0. };
	int i = 0, j = 0;
	int iCount = 0;

	int nForceLcomSize = aForceLcom.GetSize();
	for (i = 0; i < nForceLcomSize; ++i)
	{
		if (!m_ForceCtrl.Is_LcomForStrn(i + 1))	continue;	// Only 종국시.
		iCount++;
		_DGN_FORC_CRC &ForceD = aForceLcom.GetAt(i);

		// 모멘트가 가장 큰 경우
		for (j = 0; j < 2; ++j)	// I,J.
		{
			if (iCount == 1)
			{
				dMmax[j] = ForceD.dMuy[j];
				dMmin[j] = ForceD.dMuy[j];
				//
			}
			else
			{
				if (ForceD.dMuy[j] > dMmax[j])
				{
					dMmax[j] = ForceD.dMuy[j];
				}

				if (ForceD.dMuy[j] < dMmin[j])
				{
					dMmin[j] = ForceD.dMuy[j];
				}
			}
		}
	}

	// 데이터 저장
	for (int nIJ = 0; nIJ < 2; ++nIJ)	// I,J.
	{
		pdMaxMu[nIJ] = dMmax[nIJ];
		pdMinMu[nIJ] = dMmin[nIJ];
	}

	return TRUE;
}

BOOL CCRCDataCtrl::Get_CumsForceFz_MaxMin_LSD(ElemPairK ElemK, _DGN_FORC_CRC& FzMaxForceD, _DGN_FORC_CRC& FzMinForceD, _DGN_STRS_CRC& FzMaxStressD, _DGN_STRS_CRC& FzMinStressD, int* piMaxDgnLcom, int* piMinDgnLcom)
{
	FzMaxForceD.Initialize();
	FzMinForceD.Initialize();

	int iLcomNum = m_ForceCtrl.Get_LcomDataCount();
	ADGNFORCE aForceLcom;
	int nForType = 0;
	if (!m_ForceCtrl.Get_LcomDataForDesign(ElemK, nForType, TRUE, FALSE, aForceLcom, iLcomNum))	return FALSE;
	if (m_ForceCtrl.Get_LcomNumForStrn() == 0)	return FALSE;
	//
	ADGNSTRESS aStressLcom;
	ADGNSTRESS aStressTnpr;
	if (!m_ForceCtrl.Get_LcomDataForStress(ElemK, nForType, TRUE, FALSE, aStressLcom, aStressTnpr, iLcomNum)) return FALSE;
	//if(m_ForceCtrl.Get_LcomNumForStrs()==0)	return FALSE;

	double dMmax[2] = { 0.,0. }, dMmin[2] = { 0.,0. };

	double dFzMax[2] = { 0.,0. }, dFzMin[2] = { 0.,0. };
	double dFzMaxMy[2] = { 0,0 }, dFzMinMy[2] = { 0,0 };
	double dFzMaxFx[2] = { 0,0 }, dFzMinFx[2] = { 0,0 };
	int iMaxDgnLcom[2] = { 0,0 }, iMinDgnLcom[2] = { 0,0 };
	double dStop_max[2] = { 0.,0. }, dSbot_max[2] = { 0.,0. };
	double dStl_max[2] = { 0.,0. }, dSbl_max[2] = { 0.,0. };
	double dStr_max[2] = { 0.,0. }, dSbr_max[2] = { 0.,0. };
	double dStop_min[2] = { 0.,0. }, dSbot_min[2] = { 0.,0. };
	double dStl_min[2] = { 0.,0. }, dSbl_min[2] = { 0.,0. };
	double dStr_min[2] = { 0.,0. }, dSbr_min[2] = { 0.,0. };
	int i = 0, j = 0;
	int iCount = 0;

	// ======================================
	// 부재력검토
	// ======================================
	int nForceLcomSize = aForceLcom.GetSize();
	for (i = 0; i < nForceLcomSize; ++i)
	{
		if (!m_ForceCtrl.Is_LcomForStrn(i + 1))	continue;	// Only 종국시.
		iCount++;
		_DGN_FORC_CRC &ForceD = aForceLcom.GetAt(i);
		_DGN_STRS_CRC &StressD = aStressLcom.GetAt(i);

		// 전단력이 가장 불리한 case
		for (j = 0; j < 2; ++j)	// I,J.
		{
			if (iCount == 1)
			{
				dFzMax[j] = ForceD.dFzz[j];
				dFzMaxMy[j] = ForceD.dMuy[j];
				dFzMaxFx[j] = ForceD.dFxx[j];
				iMaxDgnLcom[j] = i + 1;
				//
				dFzMin[j] = ForceD.dFzz[j];
				dFzMinMy[j] = ForceD.dMuy[j];
				dFzMinFx[j] = ForceD.dFxx[j];
				iMinDgnLcom[j] = i + 1;
				//
			}
			else
			{
				if (ForceD.dFzz[j] > dFzMax[j])
				{
					dFzMax[j] = ForceD.dFzz[j];
					dFzMaxMy[j] = ForceD.dMuy[j];
					dFzMaxFx[j] = ForceD.dFxx[j];
					iMaxDgnLcom[j] = i + 1;
				}
				if (ForceD.dFzz[j] < dFzMin[j])
				{
					dFzMin[j] = ForceD.dFzz[j];
					dFzMinMy[j] = ForceD.dMuy[j];
					dFzMinFx[j] = ForceD.dFxx[j];
					iMinDgnLcom[j] = i + 1;
				}
			}
		}
	}

	for (j = 0; j < 2; ++j)	// I,J.
	{
		FzMaxForceD.dFzz[j] = dFzMax[j];
		FzMaxForceD.dMuy[j] = dFzMaxMy[j];
		FzMaxForceD.dFxx[j] = dFzMaxFx[j];
		//
		FzMinForceD.dFzz[j] = dFzMin[j];
		FzMinForceD.dMuy[j] = dFzMinMy[j];
		FzMinForceD.dFxx[j] = dFzMinFx[j];
		//
		piMaxDgnLcom[j] = iMaxDgnLcom[j];
		piMinDgnLcom[j] = iMinDgnLcom[j];
		//    
	}

	// ======================================
	// 응력검토
	// ======================================
	int nStressLcomSize = aStressLcom.GetSize();
	int iCountS = 0;
	for (i = 0; i < nStressLcomSize; ++i)
	{
		if (!m_ForceCtrl.Is_LcomForStrs(i + 1))	continue;	// 사용하중 조합.

		//  (iKind== 1) (_T("사용하중I"));       - Quasi-permanant
		//  (iKind== 2) (_T("사용하중III/VI"));  - Frequent
		//  (iKind== 3) (_T("지속하중"));        - Characteristic
		int iDgnLcomNo = i + 1;
		int iKind = m_ForceCtrl.Get_ServLcomType(iDgnLcomNo);
		if (CDBLib::IsPscCodeLSD_KR(m_iCivilCode))
		{
			if (iKind != 1) continue;  // 사용하중조합 I에 대한 응력만 구함(이정우 대리 요청)
		}
		iCountS++;

		_DGN_STRS_CRC &StressD = aStressLcom[i];

		for (j = 0; j < 2; ++j)	// I,J.
		{
			if (iCount == 1)
			{
				//
				dStop_max[j] = StressD.dStop[j];
				dSbot_max[j] = StressD.dSbot[j];
				//
				dStop_min[j] = StressD.dStop[j];
				dSbot_min[j] = StressD.dSbot[j];
			}
			else
			{
				//
				if (StressD.dStop[j] > dStop_max[j])
				{
					dStop_max[j] = StressD.dStop[j];
				}
				if (StressD.dSbot[j] > dSbot_max[j])
				{
					dSbot_max[j] = StressD.dSbot[j];
				}

				//
				if (StressD.dStop[j] < dStop_min[j])
				{
					dStop_min[j] = StressD.dStop[j];
				}
				if (StressD.dSbot[j] < dSbot_min[j])
				{
					dSbot_min[j] = StressD.dSbot[j];
				}
			}
		}
	}

	for (j = 0; j < 2; ++j)	// I,J.
	{
		//    
		FzMaxStressD.dStop[j] = dStop_max[j];
		FzMaxStressD.dSbot[j] = dSbot_max[j];

		FzMinStressD.dStop[j] = dStop_min[j];
		FzMinStressD.dSbot[j] = dSbot_min[j];
	}

	return TRUE;
}

BOOL CCRCDataCtrl::Get_CumsForceFz_MaxMin(ElemPairK ElemK, _DGN_FORC_CRC& FzMaxForceD, _DGN_FORC_CRC& FzMinForceD, _DGN_STRS_CRC& FzMaxStressD, _DGN_STRS_CRC& FzMinStressD, int* piMaxDgnLcom, int* piMinDgnLcom)
{
	FzMaxForceD.Initialize();
	FzMinForceD.Initialize();

	int nForType = 0;
	int iLcomNum = m_ForceCtrl.Get_LcomDataCount();
	ADGNFORCE aForceLcom;
	if (!m_ForceCtrl.Get_LcomDataForDesign(ElemK, nForType, TRUE, FALSE, aForceLcom, iLcomNum))	return FALSE;
	if (m_ForceCtrl.Get_LcomNumForStrn() == 0)	return FALSE;
	//
	ADGNSTRESS aStressLcom;
	ADGNSTRESS aStressTnpr;
	if (!m_ForceCtrl.Get_LcomDataForStress(ElemK, nForType, TRUE, FALSE, aStressLcom, aStressTnpr, iLcomNum)) return FALSE;
	//if(m_ForceCtrl.Get_LcomNumForStrs()==0)	return FALSE;

	double dFzMax[2] = { 0.,0. }, dFzMin[2] = { 0.,0. };
	double dFzMaxMy[2] = { 0,0 }, dFzMinMy[2] = { 0,0 };
	double dFzMaxFx[2] = { 0,0 }, dFzMinFx[2] = { 0,0 };
	int iMaxDgnLcom[2] = { 0,0 }, iMinDgnLcom[2] = { 0,0 };
	double dStop_max[2] = { 0.,0. }, dSbot_max[2] = { 0.,0. };
	double dStl_max[2] = { 0.,0. }, dSbl_max[2] = { 0.,0. };
	double dStr_max[2] = { 0.,0. }, dSbr_max[2] = { 0.,0. };
	double dStop_min[2] = { 0.,0. }, dSbot_min[2] = { 0.,0. };
	double dStl_min[2] = { 0.,0. }, dSbl_min[2] = { 0.,0. };
	double dStr_min[2] = { 0.,0. }, dSbr_min[2] = { 0.,0. };
	int i = 0, j = 0;
	int iCount = 0;
	for (i = 0; i < aForceLcom.GetSize(); ++i)
	{
		if (!m_ForceCtrl.Is_LcomForStrn(i + 1))	continue;	// Only 종국시.
		iCount++;
		_DGN_FORC_CRC &ForceD = aForceLcom.GetAt(i);
		_DGN_STRS_CRC &StressD = aStressLcom.GetAt(i);

		for (j = 0; j < 2; ++j)	// I,J.
		{
			if (iCount == 1)
			{
				dFzMax[j] = ForceD.dFzz[j];
				dFzMaxMy[j] = ForceD.dMuy[j];
				dFzMaxFx[j] = ForceD.dFxx[j];
				iMaxDgnLcom[j] = i + 1;
				//
				dFzMin[j] = ForceD.dFzz[j];
				dFzMinMy[j] = ForceD.dMuy[j];
				dFzMinFx[j] = ForceD.dFxx[j];
				iMinDgnLcom[j] = i + 1;
				//
				dStop_max[j] = StressD.dStop[j];
				dSbot_max[j] = StressD.dSbot[j];
				dStl_max[j] = StressD.dStl[j];
				dSbl_max[j] = StressD.dSbl[j];
				dStr_max[j] = StressD.dStr[j];
				dSbr_max[j] = StressD.dSbr[j];
				//
				dStop_min[j] = StressD.dStop[j];
				dSbot_min[j] = StressD.dSbot[j];
				dStl_min[j] = StressD.dStl[j];
				dSbl_min[j] = StressD.dSbl[j];
				dStr_min[j] = StressD.dStr[j];
				dSbr_min[j] = StressD.dSbr[j];
			}
			else
			{
				if (ForceD.dFzz[j] > dFzMax[j])
				{
					dFzMax[j] = ForceD.dFzz[j];
					dFzMaxMy[j] = ForceD.dMuy[j];
					dFzMaxFx[j] = ForceD.dFxx[j];
					iMaxDgnLcom[j] = i + 1;
					dStop_max[j] = StressD.dStop[j];
					dSbot_max[j] = StressD.dSbot[j];
					dStl_max[j] = StressD.dStl[j];
					dSbl_max[j] = StressD.dSbl[j];
					dStr_max[j] = StressD.dStr[j];
					dSbr_max[j] = StressD.dSbr[j];
				}
				if (ForceD.dFzz[j] < dFzMin[j])
				{
					dFzMin[j] = ForceD.dFzz[j];
					dFzMinMy[j] = ForceD.dMuy[j];
					dFzMinFx[j] = ForceD.dFxx[j];
					iMinDgnLcom[j] = i + 1;
					dStop_min[j] = StressD.dStop[j];
					dSbot_min[j] = StressD.dSbot[j];
					dStl_min[j] = StressD.dStl[j];
					dSbl_min[j] = StressD.dSbl[j];
					dStr_min[j] = StressD.dStr[j];
					dSbr_min[j] = StressD.dSbr[j];
				}
			}
		}
	}

	for (j = 0; j < 2; ++j)	// I,J.
	{
		FzMaxForceD.dFzz[j] = dFzMax[j];
		FzMaxForceD.dMuy[j] = dFzMaxMy[j];
		FzMaxForceD.dFxx[j] = dFzMaxFx[j];
		//
		FzMinForceD.dFzz[j] = dFzMin[j];
		FzMinForceD.dMuy[j] = dFzMinMy[j];
		FzMinForceD.dFxx[j] = dFzMinFx[j];
		//
		piMaxDgnLcom[j] = iMaxDgnLcom[j];
		piMinDgnLcom[j] = iMinDgnLcom[j];
		//    
		FzMaxStressD.dStop[j] = dStop_max[j];
		FzMaxStressD.dSbot[j] = dSbot_max[j];
		FzMaxStressD.dStl[j] = dStl_max[j];
		FzMaxStressD.dSbl[j] = dSbl_max[j];
		FzMaxStressD.dStr[j] = dStr_max[j];
		FzMaxStressD.dSbr[j] = dSbr_max[j];

		FzMinStressD.dStop[j] = dStop_min[j];
		FzMinStressD.dSbot[j] = dSbot_min[j];
		FzMinStressD.dStl[j] = dStl_min[j];
		FzMinStressD.dSbl[j] = dSbl_min[j];
		FzMinStressD.dStr[j] = dStr_min[j];
		FzMinStressD.dSbr[j] = dSbr_min[j];
	}

	return TRUE;
}

BOOL CCRCDataCtrl::Get_CrmtForceMx_MaxMin(ElemPairK ElemK, _DGN_FORC_CRC& MxMaxForceD, _DGN_FORC_CRC& FzMaxForceD, _DGN_FORC_CRC& FzMinForceD,
	_DGN_STRS_CRC& MxMaxStressD, _DGN_STRS_CRC& FzMaxStressD, _DGN_STRS_CRC& FzMinStressD, int* piMxMaxDgnLcom, int* piFzMaxDgnLcom, int* piFzMinDgnLcom)
{
	MxMaxForceD.Initialize();
	FzMaxForceD.Initialize();
	FzMinForceD.Initialize();

	int nForType = 0;
	int iLcomNum = m_ForceCtrl.Get_LcomDataCount();
	ADGNFORCE aForceLcom;
	if (!m_ForceCtrl.Get_LcomDataForDesign(ElemK, nForType, TRUE, FALSE, aForceLcom, iLcomNum))	return FALSE;
	if (m_ForceCtrl.Get_LcomNumForStrn() == 0)	return FALSE;
	//
	ADGNSTRESS aStressLcom;
	ADGNSTRESS aStressTnpr;
	if (!m_ForceCtrl.Get_LcomDataForStress(ElemK, nForType, TRUE, FALSE, aStressLcom, aStressTnpr, iLcomNum)) return FALSE;
	//if(m_ForceCtrl.Get_LcomNumForStrs()==0)	return FALSE;

	double dMxMaxT[2] = { 0,0 }, dMxMaxV[2] = { 0,0 }, dMxMaxMy[2] = { 0,0 }, dMxMaxFx[2] = { 0,0 };
	double dFzMaxT[2] = { 0,0 }, dFzMaxV[2] = { 0,0 }, dFzMaxMy[2] = { 0,0 }, dFzMaxFx[2] = { 0,0 };
	double dFzMinT[2] = { 0,0 }, dFzMinV[2] = { 0,0 }, dFzMinMy[2] = { 0,0 }, dFzMinFx[2] = { 0,0 };
	int iMxMaxDgnLcom[2] = { 0,0 }, iFzMaxDgnLcom[2] = { 0,0 }, iFzMinDgnLcom[2] = { 0,0 };

	double dStop_Tmax[2] = { 0.,0. }, dSbot_Tmax[2] = { 0.,0. };
	double dStl_Tmax[2] = { 0.,0. }, dSbl_Tmax[2] = { 0.,0. };
	double dStr_Tmax[2] = { 0.,0. }, dSbr_Tmax[2] = { 0.,0. };
	double dStop_Vmax[2] = { 0.,0. }, dSbot_Vmax[2] = { 0.,0. };
	double dStl_Vmax[2] = { 0.,0. }, dSbl_Vmax[2] = { 0.,0. };
	double dStr_Vmax[2] = { 0.,0. }, dSbr_Vmax[2] = { 0.,0. };
	double dStop_Vmin[2] = { 0.,0. }, dSbot_Vmin[2] = { 0.,0. };
	double dStl_Vmin[2] = { 0.,0. }, dSbl_Vmin[2] = { 0.,0. };
	double dStr_Vmin[2] = { 0.,0. }, dSbr_Vmin[2] = { 0.,0. };

	int i = 0, j = 0;
	int iCount = 0;
	for (i = 0; i < aForceLcom.GetSize(); ++i)
	{
		if (!m_ForceCtrl.Is_LcomForStrn(i + 1))	continue;	// Only 종국시.
		iCount++;
		_DGN_FORC_CRC &ForceD = aForceLcom.GetAt(i);
		_DGN_STRS_CRC &StressD = aStressLcom.GetAt(i);
		for (j = 0; j < 2; ++j)	// I,J.
		{
			if (iCount == 1)
			{
				dFzMaxT[j] = ForceD.dMux[j];
				dFzMaxV[j] = ForceD.dFzz[j];
				dFzMaxMy[j] = ForceD.dMuy[j];
				dFzMaxFx[j] = ForceD.dFxx[j];
				iFzMaxDgnLcom[j] = i + 1;
				//
				dFzMinT[j] = ForceD.dMux[j];
				dFzMinV[j] = ForceD.dFzz[j];
				dFzMinMy[j] = ForceD.dMuy[j];
				dFzMinFx[j] = ForceD.dFxx[j];
				iFzMinDgnLcom[j] = i + 1;
				//
				dMxMaxT[j] = ForceD.dMux[j];
				dMxMaxV[j] = ForceD.dFzz[j];
				dMxMaxMy[j] = ForceD.dMuy[j];
				dMxMaxFx[j] = ForceD.dFxx[j];
				iMxMaxDgnLcom[j] = i + 1;
				//
				dStop_Tmax[j] = StressD.dStop[j];
				dSbot_Tmax[j] = StressD.dSbot[j];
				dStl_Tmax[j] = StressD.dStl[j];
				dSbl_Tmax[j] = StressD.dSbl[j];
				dStr_Tmax[j] = StressD.dStr[j];
				dSbr_Tmax[j] = StressD.dSbr[j];
				//
				dStop_Vmax[j] = StressD.dStop[j];
				dSbot_Vmax[j] = StressD.dSbot[j];
				dStl_Vmax[j] = StressD.dStl[j];
				dSbl_Vmax[j] = StressD.dSbl[j];
				dStr_Vmax[j] = StressD.dStr[j];
				dSbr_Vmax[j] = StressD.dSbr[j];
				//
				dStop_Vmin[j] = StressD.dStop[j];
				dSbot_Vmin[j] = StressD.dSbot[j];
				dStl_Vmin[j] = StressD.dStl[j];
				dSbl_Vmin[j] = StressD.dSbl[j];
				dStr_Vmin[j] = StressD.dStr[j];
				dSbr_Vmin[j] = StressD.dSbr[j];
			}
			else
			{
				if (ForceD.dFzz[j] >= dFzMaxV[j])
				{
					dFzMaxT[j] = ForceD.dMux[j];
					dFzMaxV[j] = ForceD.dFzz[j];
					dFzMaxMy[j] = ForceD.dMuy[j];
					dFzMaxFx[j] = ForceD.dFxx[j];
					iFzMaxDgnLcom[j] = i + 1;
					//
					dStop_Vmax[j] = StressD.dStop[j];
					dSbot_Vmax[j] = StressD.dSbot[j];
					dStl_Vmax[j] = StressD.dStl[j];
					dSbl_Vmax[j] = StressD.dSbl[j];
					dStr_Vmax[j] = StressD.dStr[j];
					dSbr_Vmax[j] = StressD.dSbr[j];
				}
				if (ForceD.dFzz[j] <= dFzMinV[j])
				{
					dFzMinT[j] = ForceD.dMux[j];
					dFzMinV[j] = ForceD.dFzz[j];
					dFzMinMy[j] = ForceD.dMuy[j];
					dFzMinFx[j] = ForceD.dFxx[j];
					iFzMinDgnLcom[j] = i + 1;
					//
					dStop_Vmin[j] = StressD.dStop[j];
					dSbot_Vmin[j] = StressD.dSbot[j];
					dStl_Vmin[j] = StressD.dStl[j];
					dSbl_Vmin[j] = StressD.dSbl[j];
					dStr_Vmin[j] = StressD.dStr[j];
					dSbr_Vmin[j] = StressD.dSbr[j];
				}
				if (fabs(ForceD.dMux[j]) >= fabs(dMxMaxT[j]))
				{
					dMxMaxT[j] = ForceD.dMux[j];
					dMxMaxV[j] = ForceD.dFzz[j];
					dMxMaxMy[j] = ForceD.dMuy[j];
					dMxMaxFx[j] = ForceD.dFxx[j];
					iMxMaxDgnLcom[j] = i + 1;
					//
					dStop_Tmax[j] = StressD.dStop[j];
					dSbot_Tmax[j] = StressD.dSbot[j];
					dStl_Tmax[j] = StressD.dStl[j];
					dSbl_Tmax[j] = StressD.dSbl[j];
					dStr_Tmax[j] = StressD.dStr[j];
					dSbr_Tmax[j] = StressD.dSbr[j];
				}
			}
		}
	}

	for (j = 0; j < 2; ++j)
	{
		MxMaxForceD.dMux[j] = dMxMaxT[j];
		MxMaxForceD.dFzz[j] = dMxMaxV[j];
		MxMaxForceD.dMuy[j] = dMxMaxMy[j];
		MxMaxForceD.dFxx[j] = dMxMaxFx[j];
		piMxMaxDgnLcom[j] = iMxMaxDgnLcom[j];
		//    
		FzMaxForceD.dMux[j] = dFzMaxT[j];
		FzMaxForceD.dFzz[j] = dFzMaxV[j];
		FzMaxForceD.dMuy[j] = dFzMaxMy[j];
		FzMaxForceD.dFxx[j] = dFzMaxFx[j];
		piFzMaxDgnLcom[j] = iFzMaxDgnLcom[j];
		//
		FzMinForceD.dMux[j] = dFzMinT[j];
		FzMinForceD.dFzz[j] = dFzMinV[j];
		FzMinForceD.dMuy[j] = dFzMinMy[j];
		FzMinForceD.dFxx[j] = dFzMinFx[j];
		piFzMinDgnLcom[j] = iFzMinDgnLcom[j];
		//    
		MxMaxStressD.dStop[j] = dStop_Tmax[j];
		MxMaxStressD.dSbot[j] = dSbot_Tmax[j];
		MxMaxStressD.dStl[j] = dStl_Tmax[j];
		MxMaxStressD.dSbl[j] = dSbl_Tmax[j];
		MxMaxStressD.dStr[j] = dStr_Tmax[j];
		MxMaxStressD.dSbr[j] = dSbr_Tmax[j];
		//    
		FzMaxStressD.dStop[j] = dStop_Vmax[j];
		FzMaxStressD.dSbot[j] = dSbot_Vmax[j];
		FzMaxStressD.dStl[j] = dStl_Vmax[j];
		FzMaxStressD.dSbl[j] = dSbl_Vmax[j];
		FzMaxStressD.dStr[j] = dStr_Vmax[j];
		FzMaxStressD.dSbr[j] = dSbr_Vmax[j];

		FzMinStressD.dStop[j] = dStop_Vmin[j];
		FzMinStressD.dSbot[j] = dSbot_Vmin[j];
		FzMinStressD.dStl[j] = dStl_Vmin[j];
		FzMinStressD.dSbl[j] = dSbl_Vmin[j];
		FzMinStressD.dStr[j] = dStr_Vmin[j];
		FzMinStressD.dSbr[j] = dSbr_Vmin[j];
	}

	return TRUE;
}

void CCRCDataCtrl::Set_UnitIndex(T_UNIT_INDEX& CodeUnit)
{
	// This function sets _T("CodeUnit") to current unit

	// Set CodeUnit, CurrUnit.
	m_CodeUnit = CodeUnit;
	m_CurrUnit = CodeUnit;

	m_pDoc->m_pUnitCtrl->SetUnitIndexCurrent(CodeUnit);
}

void CCRCDataCtrl::Get_CurrUnitIndex(T_UNIT_INDEX& CodeUnit)
{
	// Set CodeUnit, CurrUnit.
	m_CodeUnit = CodeUnit;
	m_CurrUnit = CodeUnit;

	m_pDoc->m_pUnitCtrl->GetUnitIndexCurrent(m_CurrUnit);
}

T_UNIT_INDEX CCRCDataCtrl::Get_CodeUnitIndex()
{
	return m_CodeUnit;
}
BOOL CCRCDataCtrl::Get_KscePhi(double& dPhib, double& dPhiv)
{
	if (m_iCivilCode == KSCE_USD03 || m_iCivilCode == KSCE_USD05 || m_iCivilCode == KSCE_USD10 ||
		m_iCivilCode == KSCE_RAIL_USD04 || m_iCivilCode == KSCE_RAIL_USD11 ||
		m_iCivilCode == KSCE_USD05_RATING || CDBLib::IsPscRatingCodeKRSince10(m_iCivilCode))
	{
		dPhib = 0.85;
		dPhiv = 0.80;
	}
	else { ASSERT(0); return FALSE; }	//

	return TRUE;
}

BOOL CCRCDataCtrl::Get_JtgGamma(double& dgam0)
{
	T_PSCD_D PscdD; PscdD.Initialize();
	m_pAttrCtrl->GetDgnPscd(PscdD);

	if (!(m_iCivilCode == JTG_D62_04 || m_iCivilCode == CJJ_11_2011)) { ASSERT(0); return FALSE; }	// Only JTG D62-04.
	int iSel = 0.0;
	iSel = PscdD.iSafeType;
	switch (iSel)
	{
	case 0: dgam0 = 1.1; break;
	case 1: dgam0 = 1.0; break;
	case 2: dgam0 = 0.9; break;
	}
	//Add by juhonghua 2012.03.12
	if (m_iCivilCode == CJJ_11_2011 && PscdD.bExistSpecialLoad)
	{
		dgam0 = 1.0;
	}

	return TRUE;
}

BOOL CCRCDataCtrl::Get_ConMatd(ElemPairK ElemK, T_MATD_D& MatdD)
{
	if (!m_pDoc->IsPostMode())	ASSERT(0);
	MatdD.Initialize();

	int nMatlK = GetMaterialKey4ElemPairK(ElemK);
	// Get Matl.
	if (!m_pAttrCtrl->GetMatlDesign(nMatlK, MatdD))	return FALSE;
	// Change by ZINU.('05.03.07). Con -> Con, Src(파형강판).
	if (!(MatdD.Type == _T("C") || MatdD.Type == _T("SRC")))	return FALSE;
	// Set Default.
	Get_ConMatd(MatdD);
	// Change Unit (CurrUnit -> CodeUnit).
	m_pDoc->m_pUnitCtrl->SetUnitIndexCurrent(m_CodeUnit);
	m_pDoc->m_pUnitCtrl->ConvertUnitMatdPrevious(MatdD);
	m_pDoc->m_pUnitCtrl->SetUnitIndexCurrent(m_CurrUnit);
	return TRUE;
}

BOOL CCRCDataCtrl::Get_SrcMatd(ElemPairK ElemK, T_MATD_D& MatdD)
{
	if (!m_pDoc->IsPostMode())	ASSERT(0);
	MatdD.Initialize();

	int nMatlK = GetMaterialKey4ElemPairK(ElemK);
	// Get Matl.
	if (!m_pAttrCtrl->GetMatlDesign(nMatlK, MatdD))	return FALSE;
	if (MatdD.Type != _T("SRC"))	return FALSE;
	// Set Default.
	Get_SrcMatd(MatdD);
	// Change Unit (CurrUnit -> CodeUnit).
	m_pDoc->m_pUnitCtrl->SetUnitIndexCurrent(m_CodeUnit);
	m_pDoc->m_pUnitCtrl->ConvertUnitMatdPrevious(MatdD);
	m_pDoc->m_pUnitCtrl->SetUnitIndexCurrent(m_CurrUnit);
	return TRUE;
}

BOOL CCRCDataCtrl::Get_StlMatd(ElemPairK ElemK, T_MATD_D& MatdD)
{
	if (!m_pDoc->IsPostMode())	ASSERT(0);
	MatdD.Initialize();
	
	int nMatlK = GetMaterialKey4ElemPairK(ElemK);
	// Get Matl.
	if (!m_pAttrCtrl->GetMatlDesign(nMatlK, MatdD))	return FALSE;
	if (MatdD.Type != _T("S"))	return FALSE;
	// Set Default.
	Get_StlMatd(MatdD);
	// Change Unit (CurrUnit -> CodeUnit).
	m_pDoc->m_pUnitCtrl->SetUnitIndexCurrent(m_CodeUnit);
	m_pDoc->m_pUnitCtrl->ConvertUnitMatdPrevious(MatdD);
	m_pDoc->m_pUnitCtrl->SetUnitIndexCurrent(m_CurrUnit);
	return TRUE;
}

