BOOL CCRCDataCtrl::Get_CpgRbar(ElemPairK ElemK, BOOL bPosI, BOOL bCrack, CArray<_DGN_RBAR_CRC, _DGN_RBAR_CRC&>& arRbarPosi)
{
	if (!m_pDoc->IsPostMode())	ASSERT(0);
	arRbarPosi.RemoveAll();
	// Get Elem.
	T_ELEM_D ElemD;
	ElemD.Initialize();

	////////////////////////////
	// Get Sect Data.
	T_SECT_K SectK = 0;
	T_SECT_K OrgSectK = 0;
	T_SECT_D SectD;
	SectD.Initialize();
	BOOL bGetSect = FALSE;

	if (ElemK.second == EN_EL_BEAM)
	{
		if (!m_pPostCtrl->GetElemPost(ElemK.first, ElemD))	return FALSE;
		SectK = ElemD.elpro;

		if (m_pDoc->IsPostMode())
		{
			bGetSect = m_pPostCtrl->GetSectPost(SectK, SectD);
			OrgSectK = m_pPostCtrl->GetOrgSectKeyPost(SectK);
		}
		else
		{
			bGetSect = m_pAttrCtrl->GetSect(SectK, SectD);
			OrgSectK = SectK;
		}
	}
	else if (ElemK.second == EN_EL_VBEAM)
	{
		T_VBEM_D VbemD;
		if (!m_pAttrCtrl2->GetVbem(ElemK.first, VbemD)) return FALSE;

		T_SECV_D SecvD; SecvD.Initialize();
		m_pAttrCtrl2->GetSecv(ElemK.first, SecvD); // T_SECV_K = T_VBEM_K
		SecvD.ConvertToSect(SectD);
	}
	else ASSERT(0);
	
	// Get Sect (Conc+Rbar+Tndn). 


	int nSectType = 0;
	if (SectD.nStype == D_SECT_TYPE_TAPERED && SectD.SectBefore.nStype == D_SECT_TYPE_COMPO_G) nSectType = D_SECT_TYPE_COMPO_G;
	else if (SectD.nStype == D_SECT_TYPE_COMPO_G) nSectType = D_SECT_TYPE_COMPO_G;

	// Create Rbar by CurrUnit.
	m_pDoc->m_pMatlDB->Create_RebarData(m_CurrUnit.nBase_Length, m_CurrUnit.nBase_Force, TRUE);	// Concrete=TRUE.
	if (!m_pDoc->m_pMatlDB->Exist_RebarData())	return FALSE;

	double dBs = SectD.SectAfter.SectI.Size[0];  // Slab Width
	int    dNg = SectD.SectAfter.SectI.BuiltUpFlag;  // Numer of Main Girder
	double dds = SectD.SectAfter.SectI.Size[1];  // C.T.C.
	double dBc = SectD.SectAfter.SectJ.Size[0];
	double dtc = SectD.SectAfter.SectJ.Size[1];
	double dHh = SectD.SectAfter.SectJ.Size[2];

	// Girder는 대칭이기 때문에 SectD.SectAfter.Design.YBar 사용해도 된다. 
	double dYbar_NoBar = SectD.SectAfter.Design.YBar;
	double dZbar_NoBar = SectD.SectAfter.Design.ZBar;
	// Girder.
	double dYbar_g = SectD.SectBefore.Design.YBar;
	double dZbar_g = SectD.SectBefore.Design.ZBar;
	double dCzp_g = SectD.SectBefore.Stiffness.Czp;
	double dCzm_g = SectD.SectBefore.Stiffness.Czm;
	double dzDim_g = dCzp_g + dCzm_g;

	_DGN_RBAR_CRC RbarCrc;
	if (nSectType == D_SECT_TYPE_COMPO_G)
	{
		double dPosition = bPosI ? 0.0 : 1.0;
		T_SECT_INFO_D SectInfoD;
		CSectUtil::Get_SectInfoData(ElemK, dPosition, SectInfoD, TRUE);
		int iPartSize = SectInfoD.aSectPart.GetSize();
		for (int i = 0; i < iPartSize; ++i)
		{
			T_SECT_PART_D SectPartD = SectInfoD.aSectPart[i];

			int iRebarSize = SectPartD.aRbarData.GetSize();
			//if(i==0 && iRebarSize>0) continue; // 첫번째 Part에는 철근이 있을 수 없다.
			if (iRebarSize > 0)
			{
				arRbarPosi.SetSize(iRebarSize);
				CArray<T_GSEC_RBAR, T_GSEC_RBAR&> aRbarData;
				for (int j = 0; j < iRebarSize; ++j)
				{
					T_GSEC_RBAR GsecRbar = SectPartD.aRbarData[j];
					RbarCrc.dArea = GsecRbar.dAs;
					RbarCrc.dDia = GsecRbar.dDia;
					RbarCrc.dy = GsecRbar.dyz[0];
					RbarCrc.dz = GsecRbar.dyz[1];
					arRbarPosi.SetAt(j, RbarCrc);
				}

				break; // 철근이 입력되어 있는 Part를 찾기위해. 
			}
		}
	}
	else
	{
		T_SECT_STIFFNESS SpscSect;
		SpscSect.Initialize();
		if (!CSectUtil::GetCompoSectCR(TRUE, FALSE, bCrack, 0, TRUE, ElemK, bPosI, FALSE, SpscSect)) return FALSE;
		double dYbar = SpscSect.Cym;
		double dZbar = SpscSect.Czm;
		double dyDim = SpscSect.Cym + SpscSect.Cyp;
		double dzDim = SpscSect.Czm + SpscSect.Czp;

		// Get Rbar.	  
		T_RPSC_D RpscD;
		RpscD.Initialize();

		if (ElemK.second == EN_EL_BEAM)
		{
			if (!m_pAttrCtrl->GetRpsdByConsiderRbar(TRUE, OrgSectK, RpscD))	return FALSE;
		}
		else if (ElemK.second == EN_EL_VBEAM)
		{
			T_RPSV_SSM_D RpsvSsmD; RpsvSsmD.Initialize();
			if (!m_pAttrCtrl2->GetRpsvSsm(ElemK.first, RpsvSsmD)) return FALSE;

			T_RPSC_SSM_D RpscSsmD;
			RpsvSsmD.ConvertToRpscSSM(RpscSsmD);
			m_pAttrCtrl2->ConvertRpscSSMtoRpsc(SectD, RpscSsmD, RpscD);
		}
		else ASSERT(0);


		int iPosiM = (RpscD.bMbarJ && !bPosI ? 1 : 0);
		int iMbarSize = RpscD.Mbar[iPosiM].GetSize();
		for (int i = 0; i < iMbarSize; ++i)
		{
			T_RPSC_MBAR &RpscMbar = RpscD.Mbar[iPosiM].GetAt(i);
			int iStaYRef = RpscMbar.iStaYRef;	// 0=도심에서 좌우대칭, 1=Left에서 Right로.
			int iStaZRef = RpscMbar.iStaZRef;	// 0=Top, 1=Bottom.
			int iBarNum = RpscMbar.iBarNum;
			CString strBarNa = RpscMbar.strBarNa;
			double dStaY = RpscMbar.dStaY;
			double dStaZ = RpscMbar.dStaZ;
			double dPitch = RpscMbar.dPitch;
			int iPart = RpscMbar.nPart;
			for (int j = 0; j < iBarNum; ++j)
			{
				// Position(0,0) is Section Center.
				// Slab 기준으로이고 Slab의 도심에서 떨어진 거리로 변환 
				// SM 사용 이후로 iStaYRef는 1=Left에서 Right로.. 
				//double dy1st = (iStaYRef==0 ? dStaY-dPitch*(iBarNum-1)/2. : dStaY-dYbar);
				//double dy1st = (iStaYRef==0 ? dStaY-dPitch*(iBarNum-1)/2.-(dYbar-dYbar_NoBar) : -0.5*dBc+dStaY);
				double dy1st = (iStaYRef == 0 ? dStaY - dPitch * (iBarNum - 1) / 2. : -0.5*dBc + dStaY);
				double dz1st = 0.0;
				//(iStaZRef==0 ? (dzDim-dStaZ)-dZbar : dStaZ-dZbar);
				if (iPart == 2) // slab
					dz1st = iStaZRef == 0 ? (0.5*dtc - dStaZ) : (-0.5*dtc + dStaZ);  // Slab 도심(dtc/2) 에서 떨어진 거리로 변환.         
				else if (iPart == 1)
				{
					//ASSERT(0);
					// girder
					dz1st = iStaZRef == 0 ? 0.0 : 0.0;
				}
				else ASSERT(0);

				// Set Rbar.
				RbarCrc.strRbarNa = strBarNa;
				RbarCrc.dArea = m_pDoc->m_pMatlDB->Get_RebarArea(strBarNa);
				RbarCrc.dDia = m_pDoc->m_pMatlDB->Get_RebarDia(strBarNa);
				RbarCrc.dy = dy1st + j * dPitch;
				RbarCrc.dz = dz1st;
				arRbarPosi.Add(RbarCrc);
			}
		}
	}

	if (arRbarPosi.GetSize() > 0)	return TRUE;
	else	return FALSE;
}

BOOL CCRCDataCtrl::Get_CpgRbar4Dgn(ElemPairK ElemK, BOOL bPosI, BOOL bCrack, CArray<_DGN_RBAR_CRC, _DGN_RBAR_CRC&>& arRbarPosi)
{
	if (!m_pDoc->IsPostMode())	ASSERT(0);
	arRbarPosi.RemoveAll();
	// Get Sect (Conc+Rbar+Tndn). 

	////////////////////////////
	// Get Sect Data.
	//T_SECT_K SectK = ElemD.elpro;
	//T_SECT_K OrgSectK = 0;
	T_SECT_D SectD;
	SectD.Initialize();
	
	BOOL bGetSect = m_pPostCtrl->GetSectPostTsgrDgn(ElemK, SectD);

	int nSectType = 0;
	if (SectD.nStype == D_SECT_TYPE_TAPERED && SectD.SectBefore.nStype == D_SECT_TYPE_COMPO_G) nSectType = D_SECT_TYPE_COMPO_G;
	else if (SectD.nStype == D_SECT_TYPE_COMPO_G) nSectType = D_SECT_TYPE_COMPO_G;

	// Create Rbar by CurrUnit.
	m_pDoc->m_pMatlDB->Create_RebarData(m_CurrUnit.nBase_Length, m_CurrUnit.nBase_Force, TRUE);	// Concrete=TRUE.
	if (!m_pDoc->m_pMatlDB->Exist_RebarData())	return FALSE;

	double dBs = SectD.SectAfter.SectI.Size[0];  // Slab Width
	int    dNg = SectD.SectAfter.SectI.BuiltUpFlag;  // Numer of Main Girder
	double dds = SectD.SectAfter.SectI.Size[1];  // C.T.C.
	double dBc = SectD.SectAfter.SectJ.Size[0];
	double dtc = SectD.SectAfter.SectJ.Size[1];
	double dHh = SectD.SectAfter.SectJ.Size[2];

	// Girder는 대칭이기 때문에 SectD.SectAfter.Design.YBar 사용해도 된다. 
	double dYbar_NoBar = SectD.SectAfter.Design.YBar;
	double dZbar_NoBar = SectD.SectAfter.Design.ZBar;
	// Girder.
	double dYbar_g = SectD.SectBefore.Design.YBar;
	double dZbar_g = SectD.SectBefore.Design.ZBar;
	double dCzp_g = SectD.SectBefore.Stiffness.Czp;
	double dCzm_g = SectD.SectBefore.Stiffness.Czm;
	double dzDim_g = dCzp_g + dCzm_g;

	_DGN_RBAR_CRC RbarCrc;
	if (nSectType == D_SECT_TYPE_COMPO_G)
	{
		double dPosition = bPosI ? 0.0 : 1.0;
		T_SECT_INFO_D SectInfoD;
		CSectUtil::Get_SectInfoData(ElemK, dPosition, SectInfoD, TRUE);
		int iPartSize = SectInfoD.aSectPart.GetSize();
		for (int i = 0; i < iPartSize; ++i)
		{
			T_SECT_PART_D SectPartD = SectInfoD.aSectPart[i];

			int iRebarSize = SectPartD.aRbarData.GetSize();
			//if(i==0 && iRebarSize>0) continue; // 첫번째 Part에는 철근이 있을 수 없다.
			if (iRebarSize > 0)
			{
				arRbarPosi.SetSize(iRebarSize);
				CArray<T_GSEC_RBAR, T_GSEC_RBAR&> aRbarData;
				for (int j = 0; j < iRebarSize; ++j)
				{
					T_GSEC_RBAR GsecRbar = SectPartD.aRbarData[j];
					RbarCrc.dArea = GsecRbar.dAs;
					RbarCrc.dDia = GsecRbar.dDia;
					RbarCrc.dy = GsecRbar.dyz[0];
					RbarCrc.dz = GsecRbar.dyz[1];
					arRbarPosi.SetAt(j, RbarCrc);
				}

				break; // 철근이 입력되어 있는 Part를 찾기위해. 
			}
		}
	}
	else
	{
		T_SECT_STIFFNESS SpscSect;
		SpscSect.Initialize();
		if (!CSectUtil::GetCompoStlGirderSectCR(TRUE, FALSE, bCrack, 1.0, ElemK, bPosI, FALSE, SpscSect)) return FALSE;
		double dYbar = SpscSect.Cym;
		double dZbar = SpscSect.Czm;
		double dyDim = SpscSect.Cym + SpscSect.Cyp;
		double dzDim = SpscSect.Czm + SpscSect.Czp;

		// Get Rbar.	 
		T_RPSC_D RpscD;
		RpscD.Initialize();
		m_pAttrCtrl2->GetRpsdByConsiderRbarEPairK(ElemK, TRUE, RpscD);

		int iPosiM = (RpscD.bMbarJ && !bPosI ? 1 : 0); // 설계 입력 대화상자에 철근 정보가 없는 경우, 전처리에서 입력한 철근 정보를 가져옴
		if (RpscD.Mbar[iPosiM].GetSize() < 1)
		{
			RpscD.Initialize();
			m_pAttrCtrl2->GetRpscByConsiderRbarEPairK(ElemK, TRUE, RpscD);
			iPosiM = (RpscD.bMbarJ && !bPosI ? 1 : 0);
		}

		int iMbarSize = RpscD.Mbar[iPosiM].GetSize();
		for (int i = 0; i < iMbarSize; ++i)
		{
			T_RPSC_MBAR &RpscMbar = RpscD.Mbar[iPosiM].GetAt(i);
			int iStaYRef = RpscMbar.iStaYRef;	// 0=도심에서 좌우대칭, 1=Left에서 Right로.
			int iStaZRef = RpscMbar.iStaZRef;	// 0=Top, 1=Bottom.
			int iBarNum = RpscMbar.iBarNum;
			CString strBarNa = RpscMbar.strBarNa;
			double dStaY = RpscMbar.dStaY;
			double dStaZ = RpscMbar.dStaZ;
			double dPitch = RpscMbar.dPitch;
			int iPart = RpscMbar.nPart;
			for (int j = 0; j < iBarNum; ++j)
			{
				// Position(0,0) is Section Center.
				// Slab 기준으로이고 Slab의 도심에서 떨어진 거리로 변환 
				// SM 사용 이후로 iStaYRef는 1=Left에서 Right로.. 
				//double dy1st = (iStaYRef==0 ? dStaY-dPitch*(iBarNum-1)/2. : dStaY-dYbar);
				//double dy1st = (iStaYRef==0 ? dStaY-dPitch*(iBarNum-1)/2.-(dYbar-dYbar_NoBar) : -0.5*dBc+dStaY);
				double dy1st = (iStaYRef == 0 ? dStaY - dPitch * (iBarNum - 1) / 2. : -0.5*dBc + dStaY);
				double dz1st = 0.0;
				//(iStaZRef==0 ? (dzDim-dStaZ)-dZbar : dStaZ-dZbar);
				if (iPart == 2) // slab
					dz1st = iStaZRef == 0 ? (0.5*dtc - dStaZ) : (-0.5*dtc + dStaZ);  // Slab 도심(dtc/2) 에서 떨어진 거리로 변환.         
				else if (iPart == 1)
				{
					ASSERT(0);
					// girder
					dz1st = iStaZRef == 0 ? 0.0 : 0.0;
				}
				else ASSERT(0);

				// Set Rbar.
				// Change Unit (CurrUnit -> CodeUnit).
				RbarCrc.strRbarNa = strBarNa;
				RbarCrc.dArea = m_pDoc->m_pMatlDB->Get_RebarArea(strBarNa);
				RbarCrc.dDia = m_pDoc->m_pMatlDB->Get_RebarDia(strBarNa);
				RbarCrc.dy = dy1st + j * dPitch;
				RbarCrc.dz = dz1st;
				arRbarPosi.Add(RbarCrc);
			}
		}
	}

	if (arRbarPosi.GetSize() > 0)	return TRUE;
	else	return FALSE;
}

BOOL CCRCDataCtrl::Get_CpgLsti(ElemPairK ElemK, BOOL bPosI, CArray<CPG_LSTI_DATA, CPG_LSTI_DATA&>& arLstiPosi)
{
	if (!m_pDoc->IsPostMode())	ASSERT(0);
	arLstiPosi.RemoveAll();
	// Get Elem.
	T_ELEM_D ElemD;
	ElemD.Initialize();
	if (!m_pPostCtrl->GetElemPost(ElemK.first, ElemD))	return FALSE;

	////////////////////////////
	// Get Sect Data.
	T_SECT_K SectK = ElemD.elpro;
	T_SECT_K OrgSectK = 0;
	T_SECT_D SectD;
	SectD.Initialize();
	BOOL bGetSect = FALSE;
	if (m_pDoc->IsPostMode())
	{
		bGetSect = m_pPostCtrl->GetSectPost(SectK, SectD);
		OrgSectK = m_pPostCtrl->GetOrgSectKeyPost(SectK);
	}
	else
	{
		bGetSect = m_pAttrCtrl->GetSect(SectK, SectD);
		OrgSectK = SectK;
	}

	double dtf1 = SectD.SectBefore.SectI.Size[3];
	double dtf2 = SectD.SectBefore.SectI.Size[5];
	double dZbar_g = SectD.SectBefore.Design.ZBar;
	double dCzp_g = SectD.SectBefore.Stiffness.Czp;
	double dCzm_g = SectD.SectBefore.Stiffness.Czm;
	double dzDim_g = dCzp_g + dCzm_g;

	CPG_LSTI_DATA LstiData;
	T_CLRS_D ClrsD;
	ClrsD.Initialize();
	m_pAttrCtrl->GetClrs(OrgSectK, ClrsD);

	int iPosiM = (ClrsD.bLStifJ && !bPosI ? 1 : 0);
	int iStifSize = ClrsD.LStif[iPosiM].GetSize();
	for (int i = 0; i < iStifSize; ++i)
	{
		T_CLRS_STIF ClrsStif = ClrsD.LStif[iPosiM].GetAt(i);
		int iStaZRef = ClrsStif.iStaZRef;	// 0=Top, 1=Bottom.
		int iBarNum = ClrsStif.iBarNum;
		double dStaZ = ClrsStif.dStaZ;
		double dPitch = ClrsStif.dPitch;
		double dWidth = ClrsStif.dWidth;
		double dt = ClrsStif.dt;
		double dArea = dWidth * dt;
		for (int j = 0; j < iBarNum; ++j)
		{
			double dz1st = iStaZRef == 0 ? dStaZ : (dzDim_g - dtf1 - dtf2) - dStaZ - dPitch * (iBarNum - 1);
			// Set Rbar.
			// Change Unit (CurrUnit -> CodeUnit).			
			if (iStaZRef == 0) LstiData.dz = dz1st + j * dPitch;
			else            LstiData.dz = dz1st + j * dPitch;
			LstiData.dWidth = dWidth;
			LstiData.dt = dt;
			LstiData.dArea = dArea;
			arLstiPosi.Add(LstiData);
		}
	}

	CArray<CPG_LSTI_DATA, CPG_LSTI_DATA&> arTempLsti;
	arTempLsti.SetSize(arLstiPosi.GetSize());
	// dz가 작은 순으로 배열
	for (int i = 0; i < arLstiPosi.GetSize(); ++i)
	{
		LstiData = arLstiPosi[i];
		double dz = LstiData.dz;
		int iCount = 0;
		for (int j = 0; j < arLstiPosi.GetSize(); ++j)
		{
			if (i == j) continue;
			if (dz > arLstiPosi[j].dz)
				iCount++;
		}
		arTempLsti.SetAt(iCount, arLstiPosi[i]);
	}
	//
	arLstiPosi.RemoveAll();
	arLstiPosi.Copy(arTempLsti);

	if (arLstiPosi.GetSize() > 0)	return TRUE;
	else	return FALSE;
}

BOOL CCRCDataCtrl::Get_ConForc(ElemPairK ElemK, BOOL bIncludeTP, T_LCOM_K LcomK, _DGN_FORC_CRC& ForcLcom, _DGN_FORC_CRC& ForcTnpr)
{
	if (!m_pDoc->IsPostMode())	ASSERT(0);

	int iLcomNum = m_ForceCtrl.Get_LcomDataCount();
	ForcLcom.Initialize();
	ADGNFORCE arForcLcom;
	ForcTnpr.Initialize();
	ADGNFORCE arForcTnpr;
	// Change by ZINU.('04.12.27). Include Tendon Primary(TRUE -> User Option).
	if (!m_ForceCtrl.Get_LcomDataForDesign(ElemK, bIncludeTP, FALSE, arForcLcom, arForcTnpr, iLcomNum))	return FALSE;
	// Change Unit (CurrUnit -> CodeUnit).
	ForcLcom = arForcLcom.GetAt(LcomK - 1);
	ForcTnpr = arForcTnpr.GetAt(LcomK - 1);

	return TRUE;
}

double CCRCDataCtrl::Get_AwCmpWeb(ElemPairK ElemK, BOOL bPosI)
{
	double dAw = 0.0;
	// Get Elem.
	T_ELEM_D ElemD;
	ElemD.Initialize();
	if (!m_pPostCtrl->GetElemPost(ElemK.first, ElemD)) { ASSERT(0); return 0.0; }
	// Get Sect.
	T_SECT_D SectD;
	SectD.Initialize();
	if (!m_pPostCtrl->GetSectPost(ElemD.elpro, SectD)) { ASSERT(0); return 0.0; }

	BOOL bGetI = CDBLib::IsSectI(bPosI, SectD.nStype);

	T_SECT_SECTBASE_D SectBaseD = (bGetI ? SectD.SectBefore.SectI : SectD.SectBefore.SectJ);
	BOOL bHunch = SectD.SectBefore.bSmallHole;
	double dEffH = 0.0;
	if (!CSectUtil::GetPscCmpWebEffH(&SectBaseD, bHunch, dEffH)) { ASSERT(0); return 0.0; }
	double dt = SectBaseD.Size[59];
	// Get Aw.
	dAw = dt * dEffH;

	return dAw;
}

