BOOL CCRCDataCtrl::Cal_RatingCaseDataForAASHTO()
{
	m_arBlrdElemK.RemoveAll();
	m_arServBlrcK.RemoveAll();
	m_arStreBlrcK.RemoveAll();

	ArrElemPairKey arElemK;
	if (!Get_ElemListForBlrDgn(FALSE, arElemK))	return FALSE;

	m_ForceCtrl.Set_Write5PositionDgnForce(true);

	// Get Check Element
	m_arBlrdElemK.Copy(arElemK);
	//
	m_arCheckElemK.Copy(arElemK);
	m_iDgnElemNum = m_arBlrdElemK.GetSize();
	Set_SerialCheckElemData();

	// Get Rating Case
	CDBLib::GetRatingCaseforBLR(m_arServBlrcK, m_arStreBlrcK);

	int iStageNum = m_pAttrCtrl->GetCountStag();

	BOOL bExistStage = m_pDoc->m_pStagCtrl->ExistStag();
	T_STAG_K CurStagK = m_pDoc->m_pStagCtrl->GetCurStag();
	BOOL bPostCS = m_pDoc->m_pStagCtrl->IsFinalStagKey(CurStagK);
	if (bExistStage && !bPostCS)
	{
		if (iStageNum > 0)
			m_pDoc->m_pStagCtrl->SetFinalStagWithoutUpdateNotify();
	}
	BOOL bIsPLCB = m_pDoc->m_pAttrCtrl->ExistPlcb();

	int i = 0, j = 0;
	m_amLcbaD.clear();

	m_ForceCtrl.m_arBlrdForceElem.clear();
	m_ForceCtrl.m_arBlrdStressElem.clear();
	m_ForceCtrl.m_arBlrdPreCompoForecElem.clear();

	m_ForceCtrl.Set_DataCtrl(this);
	//
	m_ForceCtrl.Set_LcomForElem(arElemK);

	//
	m_ForceCtrl.PrestressStldKey(arElemK);
	//
	m_ForceCtrl.MakePLCBStldKey(m_iCivilCode);

	CArray<FORCE_BLRD_RCASE, FORCE_BLRD_RCASE> arForceRCase;
	CArray<STRESS_BLRD_RCASE, STRESS_BLRD_RCASE> arStressRCase;

	FORCE_BLRD_ELEM ForceBlrdElem;
	STRESS_BLRD_ELEM StressBlrdElem;
	STRESS_BLRD_ELEM SlabStressElem;
	FORCE_BLRD_ELEM ForcePreCompoElem;
	for (i = 0; i < arElemK.GetSize(); ++i)
	{
		auto ElemK = arElemK.GetAt(i);
		arForceRCase.RemoveAll();
		arStressRCase.RemoveAll();

		SlabStressElem.Initialize();
		ForcePreCompoElem.Initialize();
		m_ForceCtrl.Get_ForceStressPSCDataForAASHTO(ElemK, arForceRCase, arStressRCase, SlabStressElem.arStressRCase, ForcePreCompoElem.arForceRCase);
		// Force
		ForceBlrdElem.Initialize();
		ForceBlrdElem.arForceRCase.Copy(arForceRCase);
		m_ForceCtrl.m_arBlrdForceElem.insert({ElemK, ForceBlrdElem});
		// Stress
		StressBlrdElem.Initialize();
		StressBlrdElem.arStressRCase.Copy(arStressRCase);
		m_ForceCtrl.m_arBlrdStressElem.insert({ElemK, StressBlrdElem});
		// Slab Stress
		m_ForceCtrl.m_arBlrdSlabStressElem.insert({ElemK, SlabStressElem});
		// PreCompo Force
		if (bIsPLCB == TRUE) m_ForceCtrl.m_arBlrdPreCompoForecElem.insert({ElemK, ForcePreCompoElem});
	}

	if (bExistStage && !bPostCS)
	{
		if (iStageNum > 0)
			m_pDoc->m_pStagCtrl->SetCurStagWithoutUpdateNotify(CurStagK);
	}

	return TRUE;
}

