BOOL CCRCDataCtrl::Cal_RatingCaseDataForKSCE05(const int &nDgnCode)
{
	m_arBlrdElemK.RemoveAll();
	m_arServBlrcK.RemoveAll();
	m_arStreBlrcK.RemoveAll();

	ArrElemPairKey arElemK;
	switch (nDgnCode)
	{
	case KSCE_USD05_RATING:
	case KSCE_USD10_RATING:
	case KSCE_RAIL_USD11_RATING:
	case KSCE_LSD15_RATING:	{
		
		if (!Get_ElemListForBlrDgn(FALSE, arElemK))	return FALSE;		
		break;
	}
	case KSCE_USD10_RC_RATING:
	case KSCE_RAIL_USD11_RC_RATING:
	case KSCE_LSD15_RC_RATING:
	{
		CArray<T_ELEM_K, T_ELEM_K> aTempElemK;
		if (!Get_ElemListForBlrDgn_RC(TRUE, aTempElemK))	return FALSE;
		ConvertElemKeyToElemPairKey(aTempElemK, arElemK);
		break;
	}
	case STL_KSCE_ASD05:
	case STL_KSCE_ASD10:
	case STL_KSCE_RAIL_ASD04:
	case STL_KSCE_RAIL_ASD11:
	case STL_KSCE_LSD15:
	{
		if (!Get_ElemListForBlrDgn_STL(FALSE, arElemK))	return FALSE;
		break;
	}
	default:
		ASSERT(0);
	}

	// Get Check Element
	m_arBlrdElemK.Copy(arElemK);
	m_arCheckElemK.Copy(arElemK);

	MakeUnbracedLengthMembData();
	MakeUnbracedLengthPosition();

	ArrElemPairKey aTChkElemK;
	if (Get_ModiCheckElemKey(arElemK, m_aChkElemUblmKey, aTChkElemK))
	{
		arElemK.Copy(aTChkElemK);
		m_arCheckElemK.Copy(aTChkElemK);
	}

	m_iDgnElemNum = arElemK.GetSize();
	Set_SerialCheckElemData();

	/*
	int iStageNum = m_pAttrCtrl->GetCountStag();

	T_STAG_K CurStagK = m_pDoc->m_pStagCtrl->GetCurStag();
	BOOL bPostCS = m_pDoc->m_pStagCtrl->IsFinalStagKey(CurStagK);
	if(!bPostCS)
	{
	if(iStageNum>0)
	m_pDoc->m_pStagCtrl->SetFinalStagWithoutUpdateNotify();
	}
	*/

	// Pre-Combined Composite Bridge
	BOOL bIsPLCB = m_pDoc->m_pAttrCtrl->ExistPlcb();

	int i = 0, j = 0;
	m_ForceCtrl.m_arBlrdForceElemKR.clear();
	m_ForceCtrl.m_arBlrdForceElemKR_Str.clear();
	m_ForceCtrl.m_arBlrdStressElemKR.clear();
	m_ForceCtrl.m_arBlrdStressElemKR_Str.clear();
	//m_ForceCtrl.m_aBlrdComForceElem.RemoveAll();
	//m_ForceCtrl.m_aBlrdComStressElem.RemoveAll();

	m_ForceCtrl.Set_DataCtrl(this);
	//
	m_ForceCtrl.Set_LcomForElem(arElemK);

	CArray<FORCE_RCASE_KR, FORCE_RCASE_KR> arForceRCase; // Only Rating - Get Check Load Case
	CArray<FORCE_RCASE_KR, FORCE_RCASE_KR> arForceRCase_Str; // Rating Strength Check - Get All Load Cases
	CArray<STRESS_RCASE_KR, STRESS_RCASE_KR> arStressRCase;
	CArray<STRESS_RCASE_KR, STRESS_RCASE_KR> arStressRCase_Str;

	FORCE_LRKR_ELEM ForceLrkrElem;
	FORCE_LRKR_ELEM ForceLrkrElem_Str;
	STRESS_LRKR_ELEM StressLrkrElem;
	STRESS_LRKR_ELEM StressLrkrElem_Str;
	FORCE_RCASE_PRECOMP_ELEM ForcePreComElem;
	for (i = 0; i < arElemK.GetSize(); ++i)
	{
		auto ElemK = arElemK.GetAt(i);
		arForceRCase.RemoveAll();
		arForceRCase_Str.RemoveAll();
		arStressRCase.RemoveAll();
		arStressRCase_Str.RemoveAll();

		// Force for only Rating include 
		BOOL bIncludeStatic = FALSE;
		m_ForceCtrl.Get_ForceStressDataForRatingKSCE05(bIsPLCB, ElemK, arForceRCase, arStressRCase, ForcePreComElem, nDgnCode, bIncludeStatic);
		ForceLrkrElem.Initialize();
		ForceLrkrElem.arForceRCase.Copy(arForceRCase);
		m_ForceCtrl.m_arBlrdForceElemKR.insert({ElemK, ForceLrkrElem});

		// Stress
		StressLrkrElem.Initialize();
		StressLrkrElem.arStressRCase.Copy(arStressRCase);
		m_ForceCtrl.m_arBlrdStressElemKR.insert({ElemK, StressLrkrElem});

		// Force for Strength Check - Include all check
		bIncludeStatic = TRUE;
		m_ForceCtrl.Get_ForceStressDataForRatingKSCE05(bIsPLCB, ElemK, arForceRCase_Str, arStressRCase_Str, ForcePreComElem, nDgnCode, bIncludeStatic);
		ForceLrkrElem_Str.Initialize();
		ForceLrkrElem_Str.arForceRCase.Copy(arForceRCase_Str);
		m_ForceCtrl.m_arBlrdForceElemKR_Str.insert({ElemK, ForceLrkrElem_Str});

		// Stress
		StressLrkrElem_Str.Initialize();
		StressLrkrElem_Str.arStressRCase.Copy(arStressRCase_Str);
		m_ForceCtrl.m_arBlrdStressElemKR_Str.insert({ElemK, StressLrkrElem_Str});

		if (bIsPLCB == TRUE)
		{
			m_ForceCtrl.m_aPreCompForceElem.insert({ElemK, ForcePreComElem});
		}
	}

	/*
	if(!bPostCS)
	{
	if(iStageNum>0)
	m_pDoc->m_pStagCtrl->SetCurStagWithoutUpdateNotify(CurStagK);
	}
	*/

	return TRUE;
}

