BOOL CCRCDataCtrl::Get_Deflection4NodeOfElem(ElemPairK ElemK, int iRcaseNo, double& dIdisp, double& dJdisp, const int &nRatingType)
{
	T_ELEM_D ElemD;
	T_NODE_K NodeK1 = 0;
	T_NODE_K NodeK2 = 0;
	if (ElemK.second == EN_EL_BEAM)
	{
		m_pAttrCtrl->GetElem(ElemK.first, ElemD);
		NodeK1 = ElemD.elnod[0];
		NodeK2 = ElemD.elnod[1];
	}
	else if (ElemK.second == EN_EL_VBEAM)
	{
		ASSERT(0);
	}
	else ASSERT(0);
	

	int iOrgRcaseNo = 0, iRatingCase = 0, iRcaseTypeDL = 0, iRcaseTypeLL = 0;
	if (!m_ForceCtrl.Get_RcaseType(iRcaseNo, iOrgRcaseNo, iRatingCase, iRcaseTypeDL, iRcaseTypeLL)) ASSERT(0);
	//
	T_LCOM_D LcomD;
	T_LCOM_D LcomMV;
	LcomD.Initialize();
	LcomMV.Initialize();
	if (nRatingType == ENUM_KS05)
	{
		T_RKLC_D RklcD;
		if (m_pAttrCtrl->GetRklc(iOrgRcaseNo, RklcD))
		{
			LcomD.nActive = RklcD.iRatingCase == 0 ? 2 : 1; // 0:inactive, 1:active or strength/stress(CIVIL RC), 2:serviceability(CIVIL RC)
			int iLcaseNum = RklcD.arLoadComb.GetSize();
			LcomD.aCombination.Copy(RklcD.arLoadComb);
			//       for(int i=0; i<iLcaseNum ; ++i)
			//       {
			//         LcomD.Combination[i] = RklcD.arLoadComb[i];
			//       }

			RklcD.MoveLoadCase.Factor = 1.0; // MQC 13677. 처짐을 계산할 때는 factor를 고려하지 않도록
			LcomMV.nActive = RklcD.iRatingCase == 0 ? 2 : 1;
			LcomMV.aCombination.Add(RklcD.MoveLoadCase);
		}
	}
	else if (nRatingType == ENUM_KSCE_ASD)
	{
		T_RLCS_D RlcsD;
		if (m_pAttrCtrl2->GetRlcs(iOrgRcaseNo, RlcsD))
		{
			LcomD.aCombination.Copy(RlcsD.arLoadComb);
			//       int iLcaseNum = RlcsD.arLoadComb.GetSize();
			//       for(int i=0; i<iLcaseNum ; ++i)
			//       {
			//         LcomD.Combination[i] = RlcsD.arLoadComb[i];
			//       }

			RlcsD.MoveLoadCase.Factor = 1.0; // MQC 13677. 처짐을 계산할 때는 factor를 고려하지 않도록
			LcomMV.nActive = 1;
			LcomMV.aCombination.Add(RlcsD.MoveLoadCase);
		}
	}

	double dIdisp_DL = 0.0;
	double dJdisp_DL = 0.0;
	double dIdisp_LL = 0.0;
	double dJdisp_LL = 0.0;

	//      
	T_DISP_D Node1MaxDisp; Node1MaxDisp.Initialize();
	T_DISP_D Node1MinDisp; Node1MinDisp.Initialize();
	T_DISP_D Node2MaxDisp; Node2MaxDisp.Initialize();
	T_DISP_D Node2MinDisp; Node2MinDisp.Initialize();

	m_pPostCtrl->SelectLoadCombNew(LcomD);
	m_pPostCtrl->GetDispNew(NodeK1, &Node1MaxDisp, &Node1MinDisp, NULL);
	m_pPostCtrl->GetDispNew(NodeK2, &Node2MaxDisp, &Node2MinDisp, NULL);
	//
	if (iRcaseTypeDL == 0)
	{
		dIdisp_DL = Node1MaxDisp.dblDisp[2];
		dJdisp_DL = Node2MaxDisp.dblDisp[2];
	}
	else // Max/Min Type
	{
		dIdisp_DL = Node1MinDisp.dblDisp[2]; // Max/Min Type이면 Min만...
		dJdisp_DL = Node2MinDisp.dblDisp[2];
	}

	//++++++++++
	// Moving
	T_DISP_D Node1MaxDispMV; Node1MaxDispMV.Initialize();
	T_DISP_D Node1MinDispMV; Node1MinDispMV.Initialize();
	T_DISP_D Node2MaxDispMV; Node2MaxDispMV.Initialize();
	T_DISP_D Node2MinDispMV; Node2MinDispMV.Initialize();

	m_pPostCtrl->SelectLoadCombNew(LcomMV);
	m_pPostCtrl->GetDispNew(NodeK1, &Node1MaxDispMV, &Node1MinDispMV, NULL);
	m_pPostCtrl->GetDispNew(NodeK2, &Node2MaxDispMV, &Node2MinDispMV, NULL);

	// 
	if (iRcaseTypeLL == 0)
	{
		dIdisp_LL = Node1MaxDispMV.dblDisp[2];
		dJdisp_LL = Node2MaxDispMV.dblDisp[2];
	}
	else // Max/Min Type
	{
		dIdisp_LL = Node1MinDispMV.dblDisp[2]; // Max/Min Type이면 Min만...
		dJdisp_LL = Node2MinDispMV.dblDisp[2];
	}

	//PMS:RATING BSC-20140401 Dead Load 에 의한 처짐은 포함 안함 (이두영)
	dIdisp = /*dIdisp_DL + */dIdisp_LL;
	dJdisp = /*dJdisp_DL + */dJdisp_LL;

	return TRUE;
}

BOOL CCRCDataCtrl::Calc_AdjustmentFactorK(BOOL bAppAFK, BOOL bAutoAFK, double dEpsiC, double dEpsiT, double dKb, double dKuser, double &dKa, double &dK)
{
	dK = 1.0;
	if (bAppAFK == TRUE)
	{
		if (bAutoAFK == TRUE)
		{
			dKa = (dEpsiT == 0.0) ? 0.0 : dEpsiC / dEpsiT - 1;
			dK = 1.0 + dKa * dKb;
		}
		else
		{
			dK = dKuser;
		}
	}
	return TRUE;
}

BOOL CCRCDataCtrl::Calc_Stress4MVpr(ElemPairK ElemK, int nPos, int nCC, double dEc,
	STRESS_BLRD_RCASE &StressD,
	double &dEpsiCal)
{
	int nChkLcomSize = 1;

	double dEpsiCalMax = 0.0;
	for (int i = 0; i < nChkLcomSize; ++i)
	{
		double dEpsi_tl = 0.0, dEpsi_tr = 0.0, dEpsi_br = 0.0, dEpsi_bl = 0.0;
		double dEpsiPos[4] = { 0.0, };
		if (fabs(dEc) > cDgn_Zero)
		{
			dEpsiPos[0] = StressD.StressPrVehicle[nCC].dStl[nPos] / dEc;
			dEpsiPos[1] = StressD.StressPrVehicle[nCC].dStr[nPos] / dEc;
			dEpsiPos[2] = StressD.StressPrVehicle[nCC].dSbr[nPos] / dEc;
			dEpsiPos[3] = StressD.StressPrVehicle[nCC].dSbl[nPos] / dEc;
		}

		double dEpsiCalCur = 0.0;
		for (int j = 0; j < 4; ++j)
		{
			if (j == 0)
			{
				dEpsiCalCur = fabs(dEpsiPos[j]);
			}
			else
			{
				double dEpsi = fabs(dEpsiPos[j]);
				if (dEpsi > dEpsiCalCur) dEpsiCalCur = dEpsi;
			}
		}

		if (i == 0)
		{
			dEpsiCalMax = dEpsiCalCur;
		}
		else
		{
			if (dEpsiCalCur > dEpsiCalMax)
			{
				dEpsiCalMax = dEpsiCal;
			}
		}
	}

	dEpsiCal = dEpsiCalMax;

	return TRUE;
}

BOOL CCRCDataCtrl::Calc_StressCpt4MVpr(ElemPairK ElemK, int nPos, int nCC, double dEc, double dEcs, STRESS_BLRD_RCASE &StressD, STRESS_BLRD_RCASE &StressSlabD, double &dEpsiCal)
{
	// Girder
	double dEpsiCg = 0.0;
	Calc_Stress4MVpr(ElemK, nPos, nCC, dEc, StressD, dEpsiCg);
	// Slab
	double dEpsiCs = 0.0;
	Calc_Stress4MVpr(ElemK, nPos, nCC, dEcs, StressSlabD, dEpsiCs);

	dEpsiCal = max(dEpsiCg, dEpsiCs);

	return TRUE;
}

BOOL CCRCDataCtrl::Get_DeflectionOfNode(ElemPairK ElemK, T_BLRC_D &BlrcD, T_LCOM_D &LcomDE, double &dIdisp, double &dJdisp)
{
	T_ELEM_D ElemD;
	T_NODE_K NodeK1 = 0;
	T_NODE_K NodeK2 = 0;
	if (ElemK.second == EN_EL_BEAM)
	{
		m_pDoc->m_pAttrCtrl->GetElem(ElemK.first, ElemD);
	}
	else if (ElemK.second == EN_EL_VBEAM)
	{
		ASSERT(0);
	}
	else ASSERT(0);

	NodeK1 = ElemD.elnod[0];
	NodeK2 = ElemD.elnod[1];

	double dIdisp_DL = 0.0;
	double dJdisp_DL = 0.0;

	//++++++++++
	// Moving
	T_DISP_D Node1MaxDispMV; Node1MaxDispMV.Initialize();
	T_DISP_D Node1MinDispMV; Node1MinDispMV.Initialize();
	T_DISP_D Node2MaxDispMV; Node2MaxDispMV.Initialize();
	T_DISP_D Node2MinDispMV; Node2MinDispMV.Initialize();

	T_LCOM_D LcomMV;  LcomMV.Initialize();
	LcomMV.aCombination.Add(BlrcD.PrimaryVeh);

	m_pDoc->m_pPostCtrl->SelectLoadCombNew(LcomMV);
	m_pDoc->m_pPostCtrl->GetDispNew(NodeK1, &Node1MaxDispMV, &Node1MinDispMV, NULL);
	m_pDoc->m_pPostCtrl->GetDispNew(NodeK2, &Node2MaxDispMV, &Node2MinDispMV, NULL);

	double dIdisp_LL = max(fabs(Node1MaxDispMV.dblDisp[2]), fabs(Node1MinDispMV.dblDisp[2]));
	double dJdisp_LL = max(fabs(Node2MaxDispMV.dblDisp[2]), fabs(Node2MinDispMV.dblDisp[2]));

	// Moving만 적용한다. 
	dIdisp = dIdisp_LL;
	dJdisp = dJdisp_LL;
	return TRUE;
}

BOOL CCRCDataCtrl::Calc_StressRatingDataKS05()
{
	// Stress(5), Strength(6).
	int iDgnStatus = m_pDoc->GetDesignStatus();
	m_pDoc->SetDesignStatus(5);


	int iTotalElement = m_arBlrdElemK.GetSize();

	T_RAKR_D RakrD;
	RakrD.Initialize();
	//m_pDoc->m_pUnitCtrl->SetUnitIndexCurrent(m_CodeUnit);
	m_pAttrCtrl2->GetRakr(RakrD);
	//m_pDoc->m_pUnitCtrl->SetUnitIndexCurrent(m_CurrUnit);  

	int iRcaseNum = m_ForceCtrl.Get_LcomDataCount();

	double dDgnLiveLoad = RakrD.dDgnLiveLoad;

	int i, j, k, m;
	STRESS_LRKR_ELEM StressLrkrElem;
	for (i = 0; i < iTotalElement; ++i)
	{		
		auto CheckEPairK = m_arBlrdElemK[i];

		BOOL bCompoSect = m_pDoc->m_pPostCtrl->IsElem4CompositePSCSect(CheckEPairK);

		T_RKCE_D RkceD; RkceD.Initialize();
		if (CheckEPairK.second == EN_EL_BEAM)
		{
			m_pAttrCtrl->GetRkce(CheckEPairK.first, RkceD);
		}
		else if (CheckEPairK.second == EN_EL_VBEAM)
		{
			m_pAttrCtrl->GetRkcv(CheckEPairK.first, RkceD);
		}
		else ASSERT(0);		

		StressLrkrElem.Initialize();
		const auto& itStressElem = m_ForceCtrl.m_arBlrdStressElemKR.find(CheckEPairK);
		if (itStressElem == m_ForceCtrl.m_arBlrdStressElemKR.end()) continue;
		StressLrkrElem = itStressElem->second;

		CArray<STRESS_RCASE_KR, STRESS_RCASE_KR> arStressRCase;
		arStressRCase.RemoveAll();
		arStressRCase.Copy(StressLrkrElem.arStressRCase);

		double IendTopTensPC = 1.0 / pow(m_dZero, 10);
		double IendTopCompPC = 1.0 / pow(m_dZero, 10);
		double IendBotTensPC = 1.0 / pow(m_dZero, 10);
		double IendBotCompPC = 1.0 / pow(m_dZero, 10);
		double JendTopTensPC = 1.0 / pow(m_dZero, 10);
		double JendTopCompPC = 1.0 / pow(m_dZero, 10);
		double JendBotTensPC = 1.0 / pow(m_dZero, 10);
		double JendBotCompPC = 1.0 / pow(m_dZero, 10);

		BOOL bFindCompRF = FALSE;
		BOOL bFindTensRF = FALSE;

		T_RKST_BASE IendTopTensRkst; IendTopTensRkst.Initialize();
		T_RKST_BASE IendTopCompRkst; IendTopCompRkst.Initialize();
		T_RKST_BASE IendBotTensRkst; IendBotTensRkst.Initialize();
		T_RKST_BASE IendBotCompRkst; IendBotCompRkst.Initialize();
		T_RKST_BASE JendTopTensRkst; JendTopTensRkst.Initialize();
		T_RKST_BASE JendTopCompRkst; JendTopCompRkst.Initialize();
		T_RKST_BASE JendBotTensRkst; JendBotTensRkst.Initialize();
		T_RKST_BASE JendBotCompRkst; JendBotCompRkst.Initialize();

		IendTopTensRkst.ElemK = CheckEPairK.first;
		IendTopCompRkst.ElemK = CheckEPairK.first;
		IendBotTensRkst.ElemK = CheckEPairK.first;
		IendBotCompRkst.ElemK = CheckEPairK.first;
		JendTopTensRkst.ElemK = CheckEPairK.first;
		JendTopCompRkst.ElemK = CheckEPairK.first;
		JendBotTensRkst.ElemK = CheckEPairK.first;
		JendBotCompRkst.ElemK = CheckEPairK.first;

		int iGetData = 0;
		T_RKST_CASE RkstCase;
		for (j = 0; j < iRcaseNum; ++j)
		{
			int iRcaseNo = j + 1;
			int iOrgRcaseNo = 0, iRatingCase = 0, iRcaseTypeDL = 0, iRcaseTypeLL = 0;
			if (!m_ForceCtrl.Get_RcaseType(iRcaseNo, iOrgRcaseNo, iRatingCase, iRcaseTypeDL, iRcaseTypeLL)) ASSERT(0);
			iGetData++;
			if (iRatingCase == 1) continue; //  if Strength, Skip

			// Get Disp.
			double dIdispZ = 0.0, dJdispZ = 0.0;
			Get_Deflection4NodeOfElem(CheckEPairK, iRcaseNo, dIdispZ, dJdispZ, ENUM_KS05);
			//
			T_RKLC_D RklcD;
			m_pAttrCtrl->GetRklc(iOrgRcaseNo, RklcD);

			STRESS_RCASE_KR StressRcase;
			StressRcase = arStressRCase[iGetData - 1];

			RkstCase.Initialize();
			for (k = 0; k < 2; k++) // I/J
			{
				RkstCase.RkstBase[k].bCheck = Get_ChkElemFlag4RatingKR(RkceD, k);
				RkstCase.RkstBase[k].ElemK = CheckEPairK.first;
				RkstCase.RkstBase[k].nRCaseK = iOrgRcaseNo;
				RkstCase.RkstBase[k].nDgnRCaseK = iRcaseNo;
				RkstCase.RkstBase[k].nConcurrent = Get_ConCurrType(iRcaseTypeDL, iRcaseTypeLL);
				RkstCase.RkstBase[k].dfd_p[0] = StressRcase.StressDL.dStl[k];
				RkstCase.RkstBase[k].dfd_p[1] = StressRcase.StressDL.dStr[k];
				RkstCase.RkstBase[k].dfd_p[2] = StressRcase.StressDL.dSbr[k];
				RkstCase.RkstBase[k].dfd_p[3] = StressRcase.StressDL.dSbl[k];
				RkstCase.RkstBase[k].dfl_p[0] = StressRcase.StressLL.dStl[k];
				RkstCase.RkstBase[k].dfl_p[1] = StressRcase.StressLL.dStr[k];
				RkstCase.RkstBase[k].dfl_p[2] = StressRcase.StressLL.dSbr[k];
				RkstCase.RkstBase[k].dfl_p[3] = StressRcase.StressLL.dSbl[k];
				RkstCase.RkstBase[k].dCalc_defl = k == 0 ? dIdispZ : dJdispZ;
				RkstCase.RkstBase[k].dRealDispZ = k == 0 ? RkceD.dRealDeflection[0] : RkceD.dRealDeflection[1]; //!/
				RkstCase.RkstBase[k].dImpFactor = RklcD.dImpFactor;
				RkstCase.RkstBase[k].dRealImpFactor = (k == 0) ? RkceD.dRealCrashCoeff : RkceD.dRealCrashCoeff_J;
				RkstCase.RkstBase[k].dAddResponce = (k == 0) ? RkceD.dAddResponce_I : RkceD.dAddResponce_J;
				RkstCase.RkstBase[k].dKr = RkceD.dTrafficStateCoeff;
				RkstCase.RkstBase[k].dKt = RkceD.dRoadStateCoeff;
				RkstCase.RkstBase[k].dDgnLoad = dDgnLiveLoad;
			}

			if (!m_pRatingKS05->Get_RatingAlwStress(CheckEPairK, bCompoSect, RkstCase)) continue;

			//////////////
			for (k = 0; k < 2; k++) // I,J
			{
				T_RKST_BASE RkstBase = RkstCase.RkstBase[k];
				if (!RkstBase.bCheck) continue;
				//
				for (m = 0; m < 4; m++) //
				{
					double dfl = RkstBase.dfl_p[m]; // 활하중의 응력이 기준. 

					if (k == 0) // I
					{
						if (m < 2) // Top postion. 1,2
						{
							// IendTopTensPC
							if (dfl > 0.0)
							{
								if (IendTopTensPC > RkstBase.dP0a_p[m])
								{
									IendTopTensPC = RkstBase.dP0a_p[m];
									IendTopTensRkst = RkstBase;
									IendTopTensRkst.iPosiResult = m;
								}
							}
							// IendTopCompPC
							else if (dfl < 0.0)
							{
								if (IendTopCompPC > RkstBase.dP0a_p[m])
								{
									IendTopCompPC = RkstBase.dP0a_p[m];
									IendTopCompRkst = RkstBase;
									IendTopCompRkst.iPosiResult = m;
								}
							}
						}
						else // Bottom postion. 3,4
						{
							// IendBotTensPC
							if (dfl > 0.0)
							{
								if (IendBotTensPC > RkstBase.dP0a_p[m])
								{
									IendBotTensPC = RkstBase.dP0a_p[m];
									IendBotTensRkst = RkstBase;
									IendBotTensRkst.iPosiResult = m;
								}
							}
							// IendTopCompPC
							else if (dfl < 0.0)
							{
								if (IendBotCompPC > RkstBase.dP0a_p[m])
								{
									IendBotCompPC = RkstBase.dP0a_p[m];
									IendBotCompRkst = RkstBase;
									IendBotCompRkst.iPosiResult = m;
								}
							}
						}
					}
					else // J-end
					{
						if (m < 2) // Top postion. 1,2
						{
							// JendTopTensPC
							if (dfl > 0.0)
							{
								if (JendTopTensPC > RkstBase.dP0a_p[m])
								{
									JendTopTensPC = RkstBase.dP0a_p[m];
									JendTopTensRkst = RkstBase;
									JendTopTensRkst.iPosiResult = m;
								}
							}
							// JendTopCompPC
							else if (dfl < 0.0)
							{
								if (JendTopCompPC > RkstBase.dP0a_p[m])
								{
									JendTopCompPC = RkstBase.dP0a_p[m];
									JendTopCompRkst = RkstBase;
									JendTopCompRkst.iPosiResult = m;
								}
							}
						}
						else // Bottom postion. 3,4
						{
							// JendBotTensPC
							if (dfl > 0.0)
							{
								if (JendBotTensPC > RkstBase.dP0a_p[m])
								{
									JendBotTensPC = RkstBase.dP0a_p[m];
									JendBotTensRkst = RkstBase;
									JendBotTensRkst.iPosiResult = m;
								}
							}
							// IendBotCompPC
							else if (dfl < 0.0)
							{
								if (JendBotCompPC > RkstBase.dP0a_p[m])
								{
									JendBotCompPC = RkstBase.dP0a_p[m];
									JendBotCompRkst = RkstBase;
									JendBotCompRkst.iPosiResult = m;
								}
							}
						}
					}
				}
			}
		}

		T_RKST_CASE TensMinRkstD; TensMinRkstD.Initialize();
		T_RKST_CASE CompMinRkstD; CompMinRkstD.Initialize();

		TensMinRkstD.RkstBase[0] = IendTopTensRkst;
		TensMinRkstD.RkstBase[1] = IendBotTensRkst;
		TensMinRkstD.RkstBase[2] = JendTopTensRkst;
		TensMinRkstD.RkstBase[3] = JendBotTensRkst;
		//
		CompMinRkstD.RkstBase[0] = IendTopCompRkst;
		CompMinRkstD.RkstBase[1] = IendBotCompRkst;
		CompMinRkstD.RkstBase[2] = JendTopCompRkst;
		CompMinRkstD.RkstBase[3] = JendBotCompRkst;

		int iMaxMin = 0, iConCurr = 0;
		iMaxMin = 1;
		m_pPostCtrl->GetLoadRating()->WriteConcreteStress4KR05Result(CheckEPairK, 0, iMaxMin, iConCurr, TensMinRkstD);
		iMaxMin = 2;
		m_pPostCtrl->GetLoadRating()->WriteConcreteStress4KR05Result(CheckEPairK, 0, iMaxMin, iConCurr, CompMinRkstD);
	}

	return TRUE;
}

BOOL CCRCDataCtrl::Calc_FlexuralStrengthRatingDataKR(const int &nDgnCode)
{
	// Stress(5), Strength(6).
	int iDgnStatus = m_pDoc->GetDesignStatus();
	m_pDoc->SetDesignStatus(6);

	int iTotalElement = m_arBlrdElemK.GetSize();

	// 	CArray<T_ELEM_K,T_ELEM_K> arTotalElemK;  arTotalElemK.RemoveAll();
	// 	if(!Get_CrcElemListForDgn(FALSE,arTotalElemK)) return FALSE;

	T_RAKR_D RakrD;
	RakrD.Initialize();
	m_pAttrCtrl2->GetRakr(RakrD);

	int iRcaseNum = m_ForceCtrl.Get_LcomDataCount();

	double dDgnLiveLoad = RakrD.dDgnLiveLoad;

	int i, j, k;
	//FORCE_LRKR_ELEM  ForceLrkrElem;
	//FORCE_LRKR_ELEM  ForceLrkrElem_Str;
	//STRESS_LRKR_ELEM StrssLrkrElem;
	T_RKLC_D RklcD;

	for (i = 0; i < iTotalElement; ++i)
	{
		auto CheckEPairK = m_arBlrdElemK[i];

		BOOL bCompoSect = m_pDoc->m_pPostCtrl->IsElem4CompositePSCSect(CheckEPairK);
		T_RKCE_D RkceD;

		BOOL bRkceKey = TRUE;
		if (CheckEPairK.second == EN_EL_BEAM)
		{
			if(!m_pAttrCtrl->GetRkce(CheckEPairK.first, RkceD)) bRkceKey = FALSE;
		}
		else if (CheckEPairK.second == EN_EL_VBEAM)
		{
			if (!m_pAttrCtrl->GetRkcv(CheckEPairK.first, RkceD)) bRkceKey = FALSE;
		}
		else ASSERT(0);

		const auto& itForceElem = m_ForceCtrl.m_arBlrdForceElemKR.find(CheckEPairK);
		if (itForceElem == m_ForceCtrl.m_arBlrdForceElemKR.end()) continue;

		// For Strength Check
		const auto& itForceElem_Str = m_ForceCtrl.m_arBlrdForceElemKR_Str.find(CheckEPairK);
		if (itForceElem_Str == m_ForceCtrl.m_arBlrdForceElemKR_Str.end()) continue;

		const auto& itStressElem = m_ForceCtrl.m_arBlrdStressElemKR.find(CheckEPairK);
		if (itStressElem == m_ForceCtrl.m_arBlrdStressElemKR.end()) continue;


		double dIendPosiM_P0a = 1.0 / pow(m_dZero, 10);
		double dIendNegaM_P0a = 1.0 / pow(m_dZero, 10);
		double dJendPosiM_P0a = 1.0 / pow(m_dZero, 10);
		double dJendNegaM_P0a = 1.0 / pow(m_dZero, 10);

		T_RKMC_BASE IendPosiM_Rkmc; IendPosiM_Rkmc.Initialize();
		T_RKMC_BASE IendNegaM_Rkmc; IendNegaM_Rkmc.Initialize();
		T_RKMC_BASE JendPosiM_Rkmc; JendPosiM_Rkmc.Initialize();
		T_RKMC_BASE JendNegaM_Rkmc; JendNegaM_Rkmc.Initialize();

		T_RKMC_CASE PosiMinRkmcD; PosiMinRkmcD.Initialize();
		T_RKMC_CASE NegaMinRkmcD; NegaMinRkmcD.Initialize();
		// 최소 RF를 못 찾으면 이대로 할당.
		IendPosiM_Rkmc.ElemK = CheckEPairK.first;
		IendNegaM_Rkmc.ElemK = CheckEPairK.first;
		JendPosiM_Rkmc.ElemK = CheckEPairK.first;
		JendNegaM_Rkmc.ElemK = CheckEPairK.first;

		int iGetData = 0;
		T_RKMC_CASE RkmcCase;
		for (j = 0; j < iRcaseNum; ++j)
		{
			int iRcaseNo = j + 1;
			int iOrgRcaseNo = 0, iRatingCase = 0, iRcaseTypeDL = 0, iRcaseTypeLL = 0;
			if (!m_ForceCtrl.Get_RcaseType(iRcaseNo, iOrgRcaseNo, iRatingCase, iRcaseTypeDL, iRcaseTypeLL)) ASSERT(0);
			if (nDgnCode == KSCE_USD05_RATING && iRatingCase == 0) continue; //  if Service, Skip - 2005 기준일때
			iGetData++;

			m_pAttrCtrl->GetRklc(iOrgRcaseNo, RklcD);

			// Get Disp.
			double dIdispZ = 0.0, dJdispZ = 0.0;
			Get_Deflection4NodeOfElem(CheckEPairK, iRcaseNo, dIdispZ, dJdispZ, ENUM_KS05);
			//
			FORCE_RCASE_KR  ForceRcase = itForceElem->second.arForceRCase[iGetData - 1];
			FORCE_RCASE_KR  ForceRcase_Str = itForceElem_Str->second.arForceRCase[iGetData - 1];
			ForceRcase_Str.ForceLL *= (1.0 + RklcD.dImpFactor);
			STRESS_RCASE_KR StressRcase = itStressElem->second.arStressRCase[iGetData - 1];

			RkmcCase.Initialize();
			for (k = 0; k < 2; k++) // I/J
			{
				int nConcurrent = Get_ConCurrType(iRcaseTypeDL, iRcaseTypeLL);
				RkmcCase.RkmcBase[k].bCheck = (bRkceKey) ? Get_ChkElemFlag4RatingKR(RkceD, k) : FALSE;
				RkmcCase.RkmcBase[k].bCheck2 = TRUE;   // 일단 모든 psc 요소에 대해 RF계산함.
				RkmcCase.RkmcBase[k].ElemK = CheckEPairK.first;
				RkmcCase.RkmcBase[k].nRCaseK = iOrgRcaseNo;
				RkmcCase.RkmcBase[k].nDgnRCaseK = iRcaseNo;
				RkmcCase.RkmcBase[k].nConcurrent = nConcurrent;
				RkmcCase.RkmcBase[k].dMd = ForceRcase.ForceDL.dMuy[k];
				RkmcCase.RkmcBase[k].dMd_m = ForceRcase.ForceDL.dMuy[k];
				RkmcCase.RkmcBase[k].dM_L = ForceRcase.ForceLL.dMuy[k];
				//
				RkmcCase.RkmcBase[k].dMd_str = ForceRcase_Str.ForceDL.dMuy[k];
				RkmcCase.RkmcBase[k].dM_L_str = ForceRcase_Str.ForceLL.dMuy[k];
				//
				RkmcCase.RkmcBase[k].dCalc_defl = k == 0 ? dIdispZ : dJdispZ;
				RkmcCase.RkmcBase[k].dRealDispZ = k == 0 ? RkceD.dRealDeflection[0] : RkceD.dRealDeflection[1]; //!/
				RkmcCase.RkmcBase[k].dImpFactor = RklcD.dImpFactor;
				RkmcCase.RkmcBase[k].dRealImpFactor = k == 0 ? RkceD.dRealCrashCoeff : RkceD.dRealCrashCoeff_J;
				RkmcCase.RkmcBase[k].dAddResponce = k == 0 ? RkceD.dAddResponce_I : RkceD.dAddResponce_J;
				RkmcCase.RkmcBase[k].dDgnLoad = dDgnLiveLoad;
				RkmcCase.RkmcBase[k].dKm = RkceD.dCompenCoeff;
				// 추가
				double dStl = StressRcase.StressLL.dStl[k];
				double dStr = StressRcase.StressLL.dStr[k];
				double dSbr = StressRcase.StressLL.dSbr[k];
				double dSbl = StressRcase.StressLL.dSbl[k];
				double dmax01 = max(dStl, dStr);
				double dmax02 = max(dSbr, dSbl);
				RkmcCase.RkmcBase[k].dFl = max(dmax01, dmax02); // +: 활하중에 의한 인장응력 중 가장 큰 것 
				RkmcCase.RkmcBase[k].dEstiEwip = (k == 0) ? RkceD.dStrainI * 0.001 : RkceD.dStrainJ * 0.001;
				//RkmcCase.RkmcBase[k].dCalcEwip = 0.0;  // Get_RatingFlexuralStrength에서 계산
				RkmcCase.RkmcBase[k].dMdl = RkmcCase.RkmcBase[k].dMd + RkmcCase.RkmcBase[k].dM_L;

				RkmcCase.RkmcBase[k].strLcomName.Format(_T("%s(%s)"), RklcD.strCaseName, GetLcomType(nConcurrent));
				ConvertForce2ResStr(ForceRcase.ForceDL, RkmcCase.RkmcBase[k].Rating_Force.ForceDL, k);
				ConvertForce2ResStr(ForceRcase.ForceLL, RkmcCase.RkmcBase[k].Rating_Force.ForceLL, k);
				ConvertForce2ResStr(ForceRcase_Str.ForceDL, RkmcCase.RkmcBase[k].Rating_Force_Str.ForceDL, k);
				ConvertForce2ResStr(ForceRcase_Str.ForceLL, RkmcCase.RkmcBase[k].Rating_Force_Str.ForceLL, k);
			}

			if (nDgnCode == KSCE_USD05_RATING || nDgnCode == KSCE_USD10_RATING || nDgnCode == KSCE_RAIL_USD11_RATING)
			{
				if (!m_pRatingKS05->Get_RatingFlexuralStrength(CheckEPairK, bCompoSect, RakrD, RkmcCase)) continue;
			}
			else if (nDgnCode == KSCE_LSD15_RATING)
			{
				if (!Get_RatingFlexuralStrengthKR(CheckEPairK, bCompoSect, RakrD, RkmcCase)) continue;
			}
			else ASSERT(0);

			// 등급결정
			for (k = 0; k < 2; k++) // I/J
			{
				double dMdl_Str = fabs(RkmcCase.RkmcBase[k].dMd_str + RkmcCase.RkmcBase[k].dM_L_str);
				RkmcCase.RkmcBase[k].dRatioMa = RkmcCase.RkmcBase[k].dPhiMn_Rank / dMdl_Str;
				int nOk = 0;
				if (RkmcCase.RkmcBase[k].bOK)
				{
					nOk = (RkmcCase.RkmcBase[k].dP0a > dDgnLiveLoad) ? 2 : 1;
				}
				RkmcCase.RkmcBase[k].nRankType = GetBridgeLevel(RkmcCase.RkmcBase[k].dRatioMa, nOk);
			}

			// I-end
			T_RKMC_BASE RkmcBase = RkmcCase.RkmcBase[0];
			CString strLcomType_I_max, strLcomType_I_min, strLcomType_J_max, strLcomType_J_min;
			if (RkmcBase.bCheck2)
			{
				m_pAttrCtrl->GetRklc(RkmcBase.nRCaseK, RklcD);
				RkmcBase.strLcomName.Format(_T("%s(%s)"), RklcD.strCaseName, GetLcomType(RkmcBase.nConcurrent));

				if (RkmcBase.dM_L >= 0.0) // Positive
				{
					if (dIendPosiM_P0a > RkmcBase.dP0a)
					{
						dIendPosiM_P0a = RkmcBase.dP0a;
						IendPosiM_Rkmc = RkmcBase;
					}
				}
				else if (RkmcBase.dM_L < 0.0) // Negative
				{
					if (dIendNegaM_P0a > RkmcBase.dP0a)
					{
						dIendNegaM_P0a = RkmcBase.dP0a;
						IendNegaM_Rkmc = RkmcBase;
					}
				}
			}
			// J-end
			RkmcBase = RkmcCase.RkmcBase[1];
			if (RkmcBase.bCheck2)
			{
				m_pAttrCtrl->GetRklc(RkmcBase.nRCaseK, RklcD);
				RkmcBase.strLcomName.Format(_T("%s(%s)"), RklcD.strCaseName, GetLcomType(RkmcBase.nConcurrent));

				if (RkmcBase.dM_L >= 0.0) // Positive
				{
					if (dJendPosiM_P0a > RkmcBase.dP0a)
					{
						dJendPosiM_P0a = RkmcBase.dP0a;
						JendPosiM_Rkmc = RkmcBase;
					}
				}
				else if (RkmcBase.dM_L < 0.0) // Negative
				{
					if (dJendNegaM_P0a > RkmcBase.dP0a)
					{
						dJendNegaM_P0a = RkmcBase.dP0a;
						JendNegaM_Rkmc = RkmcBase;
					}
				}
			}
		}

		//
		PosiMinRkmcD.RkmcBase[0] = IendPosiM_Rkmc;
		PosiMinRkmcD.RkmcBase[1] = JendPosiM_Rkmc;
		NegaMinRkmcD.RkmcBase[0] = IendNegaM_Rkmc;
		NegaMinRkmcD.RkmcBase[1] = JendNegaM_Rkmc;

		// Comp,Tens 순서로 쓰여짐.  
		int iMaxMin = 0, iConCurr = 0;
		iMaxMin = 1;
		m_pPostCtrl->GetLoadRating()->WriteFlexuralStrength4KR05Result(CheckEPairK, 0, iMaxMin, iConCurr, PosiMinRkmcD);
		iMaxMin = 2;
		m_pPostCtrl->GetLoadRating()->WriteFlexuralStrength4KR05Result(CheckEPairK, 0, iMaxMin, iConCurr, NegaMinRkmcD);
	}

	return TRUE;
}

BOOL CCRCDataCtrl::Get_ChkElemFlag4RatingKR(T_RKCE_D& RkceD, int iPosi)
{
	if (RkceD.nChkPosition == 0 && iPosi == 0) return TRUE;
	else if (RkceD.nChkPosition == 1 && iPosi == 1) return TRUE;
	else if (RkceD.nChkPosition == 2)	           return TRUE;

	return FALSE;
}

BOOL CCRCDataCtrl::Get_ChkElemFlag4RatingKR(T_RROC_D& RrocD, int iPosi)
{
	if (RrocD.nPosition == 0 && iPosi == 0) return TRUE;
	else if (RrocD.nPosition == 1 && iPosi == 1) return TRUE;
	else if (RrocD.nPosition == 2)	           return TRUE;

	return FALSE;
}

UINT CCRCDataCtrl::Get_ConCurrType(int iRcaseTypeDL, int iRcaseTypeLL)
{
	UINT iConcurrentType = 0;

	if (iRcaseTypeDL > 0)
	{
		iConcurrentType = iRcaseTypeDL;
	}
	else if (iRcaseTypeLL > 0)
	{
		iConcurrentType = iRcaseTypeLL;
	}
	else if (iRcaseTypeDL > 0 && iRcaseTypeLL > 0)
	{
		iConcurrentType = iRcaseTypeLL;
	}

	return iConcurrentType;
}

//PMS:RATING BSC-20140329
BOOL CCRCDataCtrl::Get_ChkElemFlag4RatingKSCEASD(ElemPairK& ElemK, int iPosi)
{
	T_RROS_D RrosD;
	RrosD.Initialize();
	if (ElemK.second == EN_EL_BEAM)
	{
		if (!m_pAttrCtrl2->GetRros(ElemK.first, RrosD))	return FALSE;
	}
	else if (ElemK.second == EN_EL_VBEAM)
	{
		if (!m_pAttrCtrl2->GetRrov(ElemK.first, RrosD))	return FALSE;
	}
	else ASSERT(0);
	
	if (iPosi == 1)	// I-End.
	{
		if (RrosD.nPosition == 0 || RrosD.nPosition == 2) return TRUE;
		else	return FALSE;
	}
	else if (iPosi == 2)	// J-End.
	{
		if (RrosD.nPosition == 1 || RrosD.nPosition == 2) return TRUE;
		else	return FALSE;
	}
	return FALSE;
}

BOOL CCRCDataCtrl::Get_Deflection4Plate(T_RRPL_K MembK, int iRcaseNo, T_NODE_K &MinNodeK, double& dDisp)
{
	CDBDoc* pDoc = CDBDoc::GetDocPoint();
	ASSERT(pDoc);

	T_RRPL_D rData;
	pDoc->m_pAttrCtrl2->GetRrpl(MembK, rData);

	int nSize = rData.arElemK.GetSize();

	double dMinMembDist = 0.0;
	T_NODE_K dMinNodeofMemb = 0;
	for (int i = 0; i < nSize; ++i)
	{
		T_ELEM_K ElemK = rData.arElemK.GetAt(i);
		T_ELEM_D ElemD;
		pDoc->m_pAttrCtrl->GetElem(ElemK, ElemD);
		T_NODE_K NodeK[4] = { 0 };

		NodeK[0] = ElemD.elnod[0];
		NodeK[1] = ElemD.elnod[1];
		NodeK[2] = ElemD.elnod[2];
		NodeK[3] = ElemD.elnod[3];

		int iOrgRcaseNo = 0, iRatingCase = 0, iRcaseTypeDL = 0, iRcaseTypeLL = 0;
		if (!m_ForceCtrl.Get_RcaseType(iRcaseNo, iOrgRcaseNo, iRatingCase, iRcaseTypeDL, iRcaseTypeLL)) ASSERT(0);

		T_LCOM_D LcomD;
		T_LCOM_D LcomMV;
		LcomD.Initialize();
		LcomMV.Initialize();

		T_RKLC_D RklcD;
		if (pDoc->m_pAttrCtrl->GetRklc(iOrgRcaseNo, RklcD))
		{
			LcomD.nActive = RklcD.iRatingCase == 0 ? 2 : 1; // 0:inactive, 1:active or strength/stress(CIVIL RC), 2:serviceability(CIVIL RC)
			LcomD.aCombination.Copy(RklcD.arLoadComb);
			//       int iLcaseNum = RklcD.arLoadComb.GetSize();
			//       for(int j=0; j<iLcaseNum ; ++j)
			//       {
			//         LcomD.Combination[j] = RklcD.arLoadComb[j];
			//       }

			RklcD.MoveLoadCase.Factor = 1.0; // MQC 13677. 처짐을 계산할 때는 factor를 고려하지 않도록
			LcomMV.nActive = RklcD.iRatingCase == 0 ? 2 : 1;
			LcomMV.aCombination.Add(RklcD.MoveLoadCase);
		}

		//++++++++++
		// Dead Load
		//++++++++++
		T_DISP_D Node1MaxDisp; Node1MaxDisp.Initialize();
		T_DISP_D Node1MinDisp; Node1MinDisp.Initialize();
		T_DISP_D Node2MaxDisp; Node2MaxDisp.Initialize();
		T_DISP_D Node2MinDisp; Node2MinDisp.Initialize();
		T_DISP_D Node3MaxDisp; Node3MaxDisp.Initialize();
		T_DISP_D Node3MinDisp; Node3MinDisp.Initialize();
		T_DISP_D Node4MaxDisp; Node4MaxDisp.Initialize();
		T_DISP_D Node4MinDisp; Node4MinDisp.Initialize();

		pDoc->m_pPostCtrl->SelectLoadCombNew(LcomD);
		pDoc->m_pPostCtrl->GetDispNew(NodeK[0], &Node1MaxDisp, &Node1MinDisp, NULL);
		pDoc->m_pPostCtrl->GetDispNew(NodeK[1], &Node2MaxDisp, &Node2MinDisp, NULL);
		pDoc->m_pPostCtrl->GetDispNew(NodeK[2], &Node3MaxDisp, &Node3MinDisp, NULL);
		pDoc->m_pPostCtrl->GetDispNew(NodeK[3], &Node4MaxDisp, &Node4MinDisp, NULL);

		double d1Disp_DL = 0.0;
		double d2Disp_DL = 0.0;
		double d3Disp_DL = 0.0;
		double d4Disp_DL = 0.0;
		if (iRcaseTypeDL == 0)
		{
			d1Disp_DL = Node1MaxDisp.dblDisp[2];
			d2Disp_DL = Node2MaxDisp.dblDisp[2];
			d3Disp_DL = Node3MaxDisp.dblDisp[2];
			d4Disp_DL = Node4MaxDisp.dblDisp[2];
		}
		else // Max/Min Type
		{
			d1Disp_DL = Node1MinDisp.dblDisp[2]; // Max/Min Type이면 Min만...
			d2Disp_DL = Node2MinDisp.dblDisp[2];
			d3Disp_DL = Node2MinDisp.dblDisp[2];
			d4Disp_DL = Node2MinDisp.dblDisp[2];
		}
		//++++++++++
		// Moving
		//++++++++++
		T_DISP_D Node1MaxDispMV; Node1MaxDispMV.Initialize();
		T_DISP_D Node1MinDispMV; Node1MinDispMV.Initialize();
		T_DISP_D Node2MaxDispMV; Node2MaxDispMV.Initialize();
		T_DISP_D Node2MinDispMV; Node2MinDispMV.Initialize();
		T_DISP_D Node3MaxDispMV; Node3MaxDispMV.Initialize();
		T_DISP_D Node3MinDispMV; Node3MinDispMV.Initialize();
		T_DISP_D Node4MaxDispMV; Node4MaxDispMV.Initialize();
		T_DISP_D Node4MinDispMV; Node4MinDispMV.Initialize();

		pDoc->m_pPostCtrl->SelectLoadCombNew(LcomMV);
		pDoc->m_pPostCtrl->GetDispNew(NodeK[0], &Node1MaxDispMV, &Node1MinDispMV, NULL);
		pDoc->m_pPostCtrl->GetDispNew(NodeK[1], &Node2MaxDispMV, &Node2MinDispMV, NULL);
		pDoc->m_pPostCtrl->GetDispNew(NodeK[2], &Node3MaxDispMV, &Node3MinDispMV, NULL);
		pDoc->m_pPostCtrl->GetDispNew(NodeK[3], &Node4MaxDispMV, &Node4MinDispMV, NULL);

		double d1Disp_LL = 0.0;
		double d2Disp_LL = 0.0;
		double d3Disp_LL = 0.0;
		double d4Disp_LL = 0.0;
		if (iRcaseTypeLL == 0)
		{
			d1Disp_LL = Node1MaxDispMV.dblDisp[2];
			d2Disp_LL = Node2MaxDispMV.dblDisp[2];
			d3Disp_LL = Node3MaxDispMV.dblDisp[2];
			d4Disp_LL = Node4MaxDispMV.dblDisp[2];
		}
		else // Max/Min Type
		{
			d1Disp_LL = Node1MinDispMV.dblDisp[2]; // Max/Min Type이면 Min만...
			d2Disp_LL = Node2MinDispMV.dblDisp[2];
			d3Disp_LL = Node3MinDispMV.dblDisp[2];
			d4Disp_LL = Node4MinDispMV.dblDisp[2];
		}

		// Dead Load 에 의한 처짐은 포함 안함
		double dDisp[4] = { 0 };
		dDisp[0] = /*d1Disp_DL + */d1Disp_LL;
		dDisp[1] = /*d2Disp_DL + */d2Disp_LL;
		dDisp[2] = /*d3Disp_DL + */d3Disp_LL;
		dDisp[3] = /*d4Disp_DL + */d4Disp_LL;

		T_NODE_K NodeMin = 0;
		double dMinNodeDist = 0.0;
		for (int j = 0; j < 4; ++j)
		{
			if (j == 0)
			{
				dMinNodeDist = dDisp[j];
				NodeMin = NodeK[j];
			}
			else
			{
				if (dDisp[j] < dMinNodeDist)
				{
					dMinNodeDist = dDisp[j];
					NodeMin = NodeK[j];
				}
			}
		}

		// Min Elem Dist.
		if (i == 0)
		{
			dMinMembDist = dMinNodeDist;
			dMinNodeofMemb = NodeMin;
		}
		else
		{
			if (dMinNodeDist < dMinMembDist)
			{
				dMinMembDist = dMinNodeDist;
				dMinNodeofMemb = NodeMin;
			}
		}
	}// for nSize

	dDisp = dMinMembDist;
	MinNodeK = dMinNodeofMemb;

	return TRUE;
}

