BOOL CCRCDataCtrl::MakePlateGiderDesignData()
{
	CCurUnitSaver Save(TRUE);

	T_UNIT_INDEX CodeUnit = Get_CodeUnitIndex();
	m_pDoc->m_pUnitCtrl->SetUnitIndexCurrent(CodeUnit);

	InitialPlateGirder();

	const BOOL bValidCode = [](int nCode)
	{
		switch (nCode)
		{
		case CSA_S6_10_CSG:
		case CSA_S6_14_CSG:
		case CSA_S6_19_CSG:
		case AASHTO_LRFD12_CSG:
		case AASHTO_LRFD16_CSG:
		case AASHTO_LRFD17_CSG:
		case AASHTO_LRFD20_CSG:
		case CS457_R1_CSG:
		case NR_GN_CIV_025_06_CSG:
		case KSSC_2014_CSG:
		case AS5100_6_17_CSG:
			return TRUE;
		default:
			return CDBLib::IsCSGCodeLSD_KR(nCode);
		}
	}(m_iCivilCode);

	if (bValidCode)
	{
		m_ForceCtrl.Set_Write5PositionDgnForce(true);
	}
	if (!Cal_LcomDataForDesignAll())	return FALSE;

	// Get ElemList for Design.
	/*
	// Get LcomData for Design.
	if(!Get_LcomDataMap(m_DgnLcomKMap))	return FALSE;
	// Get Forces for Design.
	if(!Get_ForcDataMap(m_ComfDMap))	return FALSE;
	*/

	//
	if (!ExecutePlateGirderDesign()) return FALSE;

	switch (m_iCivilCode)
	{
	case CSA_S6_19_CSG:
	case CSA_S6_14_CSG:
	case CSA_S6_10_CSG:
		{ 
			m_ForceCtrl.Set_Write5PositionDgnForce(false); 
		}
		break;
	default:
		break;
	}
	
	return TRUE;
}

BOOL CCRCDataCtrl::MakePlateGirderDesign4Report()
{
	T_UNIT_INDEX CodeUnit = Get_CodeUnitIndex();
	m_pDoc->m_pUnitCtrl->SetUnitIndexCurrent(CodeUnit);

	InitialPlateGirder();
	if (!Cal_LcomDataForDesignAll())	return FALSE;

	m_ForceStageMap.clear();
	if (!Get_StagePart1Force(m_arPgdElemK)) return FALSE;
	return TRUE;
}

BOOL CCRCDataCtrl::ExecutePlateGirderDesign()
{
	m_ForceStageMap.clear();

	for (int i = 0; i < D_CPG_CHECK_ITEM; ++i)
		m_bChkItem[i] = FALSE;

	T_CPGD_D CpgdD;
	CpgdD.Initialize();
	m_pAttrCtrl2->GetDgnCpgd(CpgdD);

	CArray<T_CGDP_K, T_CGDP_K> arPgdElemKey;  arPgdElemKey.RemoveAll();
	m_pAttrCtrl->GetCgdpKeyList(arPgdElemKey);// 선택한 요소로.     

	ArrElemPairKey aPgdElemPairKey;
	CDBLib::ConvertToElemPairKey(EN_EL_BEAM, arPgdElemKey, aPgdElemPairKey);

	switch (CpgdD.iDgnCode)
	{
	case AASHTO_LRFD20_CSG:
	case AASHTO_LRFD17_CSG:
	case AASHTO_LRFD16_CSG:
	case AASHTO_LRFD12_CSG:
	case AASHTO_LRFD07_CSG:
	case EUROCODE4_2_04_CSG:
	{
		CArray<T_CGDV_K, T_CGDV_K> aPgdVBeamKey;
		m_pAttrCtrl->GetCgdvKeyList(aPgdVBeamKey);
		if (aPgdVBeamKey.GetSize() > 0)
		{
			ArrElemPairKey aPgdVBeamPairKey;
			CDBLib::ConvertToElemPairKey(EN_EL_VBEAM, aPgdVBeamKey, aPgdVBeamPairKey);
			aPgdElemPairKey.Append(aPgdVBeamPairKey);
		}
	}
	break;
	default:
		break;
	}

	UINT nPgdElemSize = aPgdElemPairKey.GetSize();

	//m_pPostCtrl->GetPlateGirder()->WritePlateGirderSeq(nPgdElemSize);
	
	LONGLONG iCount = 0;
	for (int i = 0; i < nPgdElemSize; ++i)
	{
		iCount++;
		auto ElemK = aPgdElemPairKey[i];
		if (!m_pPostCtrl->GetPlateGirder()->WritePlateGirderElement(ElemK, iCount)) continue;
	}


	BOOL bExecuteDgn = FALSE;
	switch (CpgdD.iDgnCode)
	{
	case EUROCODE4_2_04_CSG:
		bExecuteDgn = ExecuteCSG_Eurocode4();
		break;
	case IRC22_08_CSG:
		bExecuteDgn = ExecuteCSG_IRC22();
		break;
	case KSCE_ASD10_CSG:
	case KSCE_RAIL_ASD11_CSG:
		//bExecuteDgn = ExecuteCSG_KSCE_ASD(); // test 강합성
		break;
	case KDS_24_14_31_2018_CSG:
	case KSCE_LSD15_CSG:
	case KSSC_2014_CSG:
	case AASHTO_LRFD20_CSG:
	case AASHTO_LRFD17_CSG:
	case AASHTO_LRFD16_CSG:
	case AASHTO_LRFD12_CSG:
	case AASHTO_LRFD07_CSG:
	case CSA_S6_10_CSG:
	case CSA_S6_14_CSG:
	case CSA_S6_19_CSG:
	case CS457_R1_CSG:
	case NR_GN_CIV_025_06_CSG:
	case AS5100_6_17_CSG:
		bExecuteDgn = ExecuteCSG_KSCE_LSD15();
		break;
	case IRC22_15_CSG:
		bExecuteDgn = ExecuteCSG_IRC22_15();
		break;
	default: ASSERT(0); break;
	}

	return bExecuteDgn;
}

