BOOL CCRCDataCtrl::MakeUnbracedLengthMembData()
{
	m_mUblenMemb.clear();
	m_mElemUblmKey.clear();

	CArray<T_SPAN_K, T_SPAN_K> SpanKeyList;
	m_pAttrCtrl->GetSpanKeyList(SpanKeyList);
	MakeUnbracedLengthMembDataBase(SpanKeyList, EN_EL_BEAM);
	//
	CArray<T_SPAV_K, T_SPAV_K> SpavKeyList;
	m_pAttrCtrl->GetSpavKeyList(SpavKeyList);
	MakeUnbracedLengthMembDataBase(SpavKeyList, EN_EL_VBEAM);

	return TRUE;
}

BOOL CCRCDataCtrl::MakeUnbracedLengthMembDataBase(const CArray<T_SPAN_K, T_SPAN_K>& SpanKeyList, const EN_BEAM_DGN_TYPE& enBeamType)
{
	if (SpanKeyList.GetSize() == 0) return FALSE;

	int nSpanSize = SpanKeyList.GetSize();

	T_SPAN_D SpanD;

	int nUblm = 1;
	for (int i = 0; i < nSpanSize; ++i)
	{
		SpanD.Initialize();
		T_SPAN_K SpanK = SpanKeyList[i];
		if (enBeamType == EN_EL_BEAM)
		{
			m_pAttrCtrl->GetSpan(SpanK, SpanD);
		}
		else if (enBeamType == EN_EL_VBEAM)
		{
			m_pAttrCtrl->GetSpav(SpanK, SpanD);
		}
		else ASSERT(0);
		

		T_ULEN_MEMB_D UblmD;

		T_ELEM_D ElemD;
		int nSpanElemNum = SpanD.aElemBase.GetSize();

		double dUbLength = 0.0;
		for (int j = 0; j < nSpanElemNum; ++j)
		{
			const T_SPAN_BASE &SpanB = SpanD.aElemBase[j];
			T_ELEM_K ElemK = SpanB.ElemK;
			ElemPairK TEPairK(ElemK, enBeamType);
			BOOL bEnd = FALSE;

			auto _l_SetUblmD = [&](const ElemPairK& nElemJ) -> void      //Unbrace 구간 나눔
			{
				UblmD.ElemJ = nElemJ;
				UblmD.nJpos = 1;
				UblmD.dLength = dUbLength;
				UblmD.enBType = enBeamType;
				bEnd = TRUE;
			};

			auto _is_rigidNode = [&](const T_ELEM_D& ElemD, const ElemPairK& CurEPairK) -> BOOL
			{
				if(CurEPairK.second==EN_EL_VBEAM) return FALSE;
				//rigid Link 확인.
				CArray<T_RIGD_K, T_RIGD_K> rarKey; rarKey.RemoveAll();
				CArray<T_RIGD_D, T_RIGD_D&> rarData; rarData.RemoveAll();
				T_NODE_K NodeK = ElemD.elnod[1];
				m_pAttrCtrl->GetRigd(NodeK, rarKey, rarData);
				return rarKey.GetSize() > 0;  // 절점에 RigdLink 존재
			};

			double dElemLen = 0.0;
			if (enBeamType == EN_EL_BEAM)
			{
				if (!m_pAttrCtrl->GetElem(ElemK, ElemD)) { ASSERT(0); }
				dElemLen = m_pDoc->calcLAVElem(ElemK);
			}
			else if (enBeamType == EN_EL_VBEAM)
			{
				dElemLen = m_pDoc->calcLenthVbem(ElemK);
			}
			else ASSERT(0);
			
			if (dUbLength == 0.0) UblmD.ElemI = TEPairK;
			dUbLength += dElemLen;
			int nSupport = SpanB.nSupport;
			UblmD.aElemK.Add(TEPairK);

			if (j == 0)  //Span의 시작 Elem
			{
				UblmD.ElemI = TEPairK;

				if (nSupport == 2)
				{
					_l_SetUblmD(TEPairK);
				}
			}
			else  if (j > 0 && UblmD.aElemK.GetSize() == 1)
			{
				UblmD.ElemI = TEPairK;
				if (nSupport == 2)
				{
					_l_SetUblmD(TEPairK);
				}
			}
			else if (j > 0 && nSupport > 0)
			{
				const T_SPAN_BASE &PreSpanB = SpanD.aElemBase[j - 1];
				T_ELEM_K PreElemK = PreSpanB.ElemK;
				ElemPairK PreEPairK(PreElemK, enBeamType);
				if (nSupport == 1) // I단 지점
				{
					// 이전 UbLength 정보 다시 입력
					UblmD.ElemJ = PreEPairK;
					UblmD.nJpos = 1;
					UblmD.dLength = dUbLength - dElemLen;
					UblmD.bJsupport = TRUE;
					if (UblmD.aElemK.GetSize() > 1) UblmD.aElemK.RemoveAt(UblmD.aElemK.GetSize() - 1);
					DgnBeamPairK DgnBPairK({ enBeamType, nUblm });
					m_mElemUblmKey[PreEPairK] = DgnBPairK;
					_l_SetUblmD(PreEPairK);
					m_mUblenMemb[DgnBPairK] = UblmD; //insert({DgnBPairK, UblmD});
					// 여기서 Set 하고 밑에 if(bEnd==TRUE)에서 현 요소에 대한 UblmD를 다시 입력
					// 새로운 UbLength
					dUbLength = dElemLen;
				}
				else if (_is_rigidNode(ElemD, TEPairK) == TRUE)
				{
					// MQC-20288, boundary정보가 j단에 있을 경우 비지지길에 대한 요소 그룹 잘 못 판단하는 오류 수정
					_l_SetUblmD(TEPairK);
				}
				else if (nSupport == 2) // J단 지점
				{
					_l_SetUblmD(TEPairK);
				}
			}
			else if (j == nSpanElemNum - 1)   //Span의 끝 Elem
			{
				_l_SetUblmD(TEPairK);
			}

			if (bEnd == FALSE)
			{
				if (enBeamType == EN_EL_BEAM)
				{
					CArray<T_ELEM_K, T_ELEM_K> aElemKey;
					T_NODE_K NodeK = ElemD.elnod[1];
					m_pAttrCtrl->GetElemKeyListConnectedToNode(NodeK, aElemKey);    //요소의 진행방향 노드를 공유하는 Elem 찾기
					INT nSubElemSize = aElemKey.GetSize();
					for (int nSub = 0; nSub < nSubElemSize; ++nSub)
					{
						T_ELEM_K SubElemK = aElemKey[nSub];
						T_MBTP_D MbtpD;
						if (m_pAttrCtrl->IsInterval45DegElemDirection(ElemK, SubElemK) == TRUE)   //Elem과 만나는 SubElem의 각도가 45~135도 일 경우
						{
							if (m_pAttrCtrl->GetMbtp(SubElemK, MbtpD))   //Member Type이 Brace로 지정된 경우, MQC17812 Unbraced 구간을 brace point로 결정 (MQC로 선 수정, 향후 출시에는 다른 방향으로 개선 예정)
							{
								if (MbtpD.nMbType == D_MBTP_BRACE)
								{
									_l_SetUblmD(TEPairK);
									break;
								}
							}
						}
					}
				}
				else if (enBeamType == EN_EL_VBEAM)
				{
					T_VBEM_D VbemD;
					T_VBEM_K VbemK = ElemK;

					if (!m_pDoc->m_pAttrCtrl2->GetVbem(VbemK, VbemD)) ASSERT(0);

					T_VSEC_D VsecD;
					if (!m_pDoc->m_pAttrCtrl2->GetVsec(VbemD.Vsec2, VsecD)) ASSERT(0);
					CArray<T_ELEM_K, T_ELEM_K> aElemKey;
					m_pAttrCtrl->GetElemKeyListConnectedToNode(VsecD.arKeyNode, aElemKey);
					INT nSubElemSize = aElemKey.GetSize();
					for (int nSub = 0; nSub < nSubElemSize; ++nSub)
					{
						//T_ELEM_K SubElemK = aElemKey[nSub];
						//T_MBTP_D MbtpD;
						//if (m_pAttrCtrl->IsInterval45DegVsecDirection(VsecD, SubElemK) == TRUE)   //Elem과 만나는 SubElem의 각도가 45~135도 일 경우
						//{
						//	if (m_pAttrCtrl->GetMbtp(SubElemK, MbtpD))   //Member Type이 Brace로 지정된 경우, MQC17812 Unbraced 구간을 brace point로 결정 (MQC로 선 수정, 향후 출시에는 다른 방향으로 개선 예정)
						//	{
						//		if (MbtpD.nMbType == D_MBTP_BRACE)
						//		{
						//			_l_SetUblmD(ElemK);
						//			break;
						//		}
						//	}
						//}
					}
				}
				else
					ASSERT(0);
			}

			if (bEnd == TRUE)
			{
				if (j > 0 && nSupport == 1)
				{
					nUblm++;					
					DgnBeamPairK TDgnBPairK({ enBeamType, nUblm });
					m_mElemUblmKey[TEPairK] = TDgnBPairK;
					UblmD.Initialize();
					UblmD.ElemI = TEPairK;
					UblmD.enBType = enBeamType;
					UblmD.aElemK.Add(TEPairK);
				}
				else
				{					
					DgnBeamPairK TDgnBPairK({ enBeamType, nUblm });
					m_mUblenMemb[TDgnBPairK] = UblmD; //.insert({TDgnBPairK, UblmD});
					UblmD.Initialize();
					dUbLength = 0.0;
					m_mElemUblmKey[TEPairK] = TDgnBPairK;
					nUblm++;
				}
			}
			else
			{
				DgnBeamPairK TDgnBPairK({ enBeamType, nUblm });
				if (nSpanElemNum==1)
				{
					UblmD.ElemM = TEPairK;
					UblmD.ElemJ = TEPairK;
					UblmD.nMpos = 2;
					UblmD.nJpos = 1;
					UblmD.dLength = dElemLen;
					UblmD.enBType = enBeamType;					
					//UblmD..bJsupport;
					m_mUblenMemb[TDgnBPairK] = UblmD;
				}
				m_mElemUblmKey[TEPairK] = TDgnBPairK;
			}
		} // j
	}

	return TRUE;
}

BOOL CCRCDataCtrl::MakeUnbracedLengthPosition()
{
	if (m_mUblenMemb.size() <= 0) return FALSE;

	for (auto& itUbMemb : m_mUblenMemb)
	{
		//int nUblmK = aUblmK[i];
		T_ULEN_MEMB_D& UblmD = itUbMemb.second;
		//if (m_mUblenMemb.Lookup(nUblmK, UblmD))
		{
			double dCurLength = 0.0;
			int nUblmElemSize = UblmD.aElemK.GetSize();
			for (int j = 0; j < nUblmElemSize; ++j)
			{
				auto ElemK = UblmD.aElemK[j];
				double dElemLen = 0.0; 
				if (UblmD.enBType == EN_EL_BEAM)
				{
					dElemLen = m_pDoc->calcLAVElem(ElemK.first);
				}
				else if (UblmD.enBType == EN_EL_VBEAM)
				{
					dElemLen = m_pDoc->calcLenthVbem(ElemK.first);
				}
				else ASSERT(0);
				
				dCurLength += dElemLen;
				double dLenRat = (UblmD.dLength == 0.0) ? 0.0 : dCurLength / UblmD.dLength;

				if (dLenRat > 0.5 - m_dZero)
				{
					UblmD.ElemM = ElemK;

					if (fabs(dLenRat - 0.5) < m_dZero)
					{
						UblmD.nMpos = 4;
					}
					else
					{
						double dDistMin = 0.0;
						for (int k = 0; k < 5; ++k)
						{
							double dCurDist = fabs(dCurLength - dElemLen + dElemLen * (double(k) / 4.0));
							double dDist = fabs(dCurDist - UblmD.dLength / 2.0);

							if (k == 0)
							{
								dDistMin = dDist;
							}
							else if (dDistMin > dDist)
							{
								dDistMin = dDist;
								UblmD.nMpos = k;
							}
						}
					}

					break;
				}
			}
			if (UblmD.enBType == EN_EL_BEAM)
			{
				CArray<T_ELEM_K, T_ELEM_K> aCantiElemK;
				GetElemKeyList4ElemPair(EN_EL_BEAM, UblmD.aElemK, aCantiElemK);
				UblmD.bCantilever = (IsCantilever(aCantiElemK) > 0);
			}
			
			//m_mUblenMemb.insert({ itUbMemb.first, UblmD });
		}
	}

	GetCheckElemKey4UnbracedLength(m_aChkElemUblmKey);

	return TRUE;
}

BOOL CCRCDataCtrl::GetCheckElemKey4UnbracedLength(ArrElemPairKey& aChkElemKey)
{
	ArrElemPairKey aCheckElemK;
	Get_ElemListForPlateGirder(FALSE, aCheckElemK);
	if (m_iCivilCode == STL_CS454_20)
	{
		aCheckElemK.Copy(m_arCheckElemK);
	}
	else if (m_iCivilCode == STL_NR_GN_CIV_025_06)
	{
		aCheckElemK.Copy(m_arCheckElemK);
	}
	int nChkElemSize = aCheckElemK.GetSize();
	if (nChkElemSize <= 0) return FALSE;

	std::map<ElemPairK, ElemPairK> mChkElemK;	

	for (int i = 0; i < nChkElemSize; ++i)
	{
		mChkElemK.insert({ aCheckElemK[i], aCheckElemK[i] });
	}

	for (int i = 0; i < nChkElemSize; ++i)
	{
		auto ChkElemK = aCheckElemK[i];
		int nUblmK = 0;
		auto itUblmK = m_mElemUblmKey.find(ChkElemK);
		if (itUblmK != m_mElemUblmKey.end()) //  Lookup(ChkElemK, nUblmK)
		{			
			auto itUblMemb = m_mUblenMemb.find(itUblmK->second);
			if (itUblMemb != m_mUblenMemb.end()) // Lookup(nUblmK, UblmD)
			{
				T_ULEN_MEMB_D UblmD = itUblMemb->second;
				switch (m_iCivilCode)
				{
				case CSA_S6_19_CSG:
				case CSA_S6_14_CSG:
				case CSA_S6_10_CSG:
				case AASHTO_LRFD12_CSG:
				case AASHTO_LRFD07_CSG:
				case AASHTO_LRFD16_CSG:
				case AASHTO_LRFD17_CSG:
				case AASHTO_LRFD20_CSG:
				case CS457_R1_CSG:
				case NR_GN_CIV_025_06_CSG:
				case STL_AASHTO_LRFD12:
				case STL_AASHTO_LRFD19:
				case STL_CS454_20:
				case KDS_24_14_31_2018_CSG:
				case AS5100_6_17_CSG:
				case STL_NR_GN_CIV_025_06:
					{
						// Unbraced 구간의 Member force를 다 계산
						for ( int k = 0; k < UblmD.aElemK.GetSize(); ++k )
						{							
							mChkElemK.insert({ UblmD.aElemK[k], UblmD.aElemK[k] });
						}
					}
					break;
				default:
					{
						auto EPairI = UblmD.ElemI;
						auto itEPairI = mChkElemK.find(EPairI);
						if (itEPairI == mChkElemK.end())
						{
							if (UblmD.ElemI.first != 0) mChkElemK[EPairI] = EPairI;
						}
						auto EPairM = UblmD.ElemM;
						auto itEPairM = mChkElemK.find(EPairM);
						if (itEPairM == mChkElemK.end())
						{
							if ( UblmD.ElemM.first != 0 ) mChkElemK[EPairM] = EPairM;
						}
						auto EPairJ = UblmD.ElemJ;
						auto itEPairJ = mChkElemK.find(EPairJ);
						if (itEPairJ == mChkElemK.end())
						{
							if ( UblmD.ElemJ.first != 0 ) mChkElemK[EPairJ] = EPairJ;
						}
					}
					break;
				}
			}
		}
	}

	aChkElemKey.RemoveAll();
	aChkElemKey.SetSize(mChkElemK.size());
	int nIdx = 0;
	for (auto CurElemK : mChkElemK)
	{
		aChkElemKey.SetAt(nIdx++, CurElemK.first);
	}

	return TRUE;
}

BOOL CCRCDataCtrl::GetCheckElemKeyIncludedMembEnd(CArray<T_ELEM_K, T_ELEM_K> &aElemKey, CArray<T_ELEM_K, T_ELEM_K> &aChkElemKey)
{
	CMapEx<T_ELEM_K, T_ELEM_K, T_ELEM_K, T_ELEM_K&> mChkElemK;

	for (int i = 0; i < aElemKey.GetSize(); ++i)
	{
		T_ELEM_K ElemK = aElemKey[i];
		T_ELEM_K ChkElemK = 0;

		if (!mChkElemK.Lookup(ElemK, ChkElemK))
		{
			BOOL bReverse = FALSE;
			T_ELEM_K showElemK = 0, IendElemK = 0, JendElemK = 0;
			CArray<T_ELEM_K, T_ELEM_K> aMembElemList;

			if (m_pMembCtrl->GetElemListByIncludeElem(ElemK, bReverse, showElemK, aMembElemList))
			{
				int nElemNum = aMembElemList.GetSize();

				mChkElemK.SetAt(ElemK, ElemK);
				if (nElemNum > 1)
				{
					IendElemK = aMembElemList[0];
					JendElemK = aMembElemList[nElemNum - 1];

					mChkElemK.SetAt(IendElemK, IendElemK);
					mChkElemK.SetAt(JendElemK, JendElemK);
				}
			}
		}
	}

	aChkElemKey.RemoveAll();
	mChkElemK.GetSortedKeyListforUintK(aChkElemKey);

	return TRUE;
}

BOOL CCRCDataCtrl::CalcCrossGirderLength(T_ELEM_K StaElemK, BOOL bConnNodeJ, double CGVec[3], double& dCGLength, BOOL& bNextFind)
{
	if (!bNextFind) return FALSE; // 찾을 필요 없으면...

	const double dAngleFactor = 1.0;

	double dNextElemLength = 0.0;

	auto _L_ElemVector = [&](const T_NODE_D& NoI, const T_NODE_D& NoJ, double EVec[3]) -> void
		{
			EVec[0] = NoJ.x - NoI.x;
			EVec[1] = NoJ.y - NoI.y;
			EVec[2] = NoJ.z - NoI.z;
			CMathFunc::mathNormalize(EVec, EVec);
		};

	T_ELEM_D ElemD;
	if (!m_pDoc->m_pAttrCtrl->GetElem(StaElemK, ElemD)) return 0.0;

	T_NODE_K TgtNodeK = bConnNodeJ ? ElemD.elnod[1] : ElemD.elnod[0];

	T_NODE_D TgtNode;
	m_pDoc->m_pAttrCtrl->GetNode(TgtNodeK, TgtNode);


	CArray<T_ELEM_K, T_ELEM_K> aElemK;
	m_pDoc->m_pAttrCtrl->GetConnectedElem(TgtNodeK, aElemK);

	for (int i = 0; i < aElemK.GetSize(); ++i)
	{
		T_ELEM_K ElemK = aElemK[i];
		T_UFMT_D UfmtD; UfmtD.Initialize();
		if (m_pDoc->m_pAttrCtrl->GetUfmt(ElemK, UfmtD))
		{
			if (UfmtD.nMemberType == 0) // Main girder를 만나면 그만 찾는다.
			{
				bNextFind = FALSE;
			}
		}
	}

	if (!bNextFind) return FALSE;
		
	for (int i = 0; i < aElemK.GetSize(); ++i)
	{
		T_ELEM_K ElemK = aElemK[i];
		if (ElemK == StaElemK) continue; 

		T_ELEM_D CurElemD;
		if (!m_pDoc->m_pAttrCtrl->GetElem(ElemK, CurElemD)) continue;

		
		T_NODE_D CurNodeI, CurNodeJ;
		m_pDoc->m_pAttrCtrl->GetNode(CurElemD.elnod[0], CurNodeI);
		m_pDoc->m_pAttrCtrl->GetNode(CurElemD.elnod[1], CurNodeJ);

		double CurEVec[3] = { 0.0, 0.0, 0.0 };
		_L_ElemVector(CurNodeI, CurNodeJ, CurEVec);

		if (fabs(CMathFunc::mathCrossAngle(CGVec, CurEVec)) < dAngleFactor)
		{
			if (EQ(TgtNode.x, CurNodeI.x) && EQ(TgtNode.y, CurNodeI.y) && EQ(TgtNode.z, CurNodeI.z))
			{
				bConnNodeJ = TRUE;
			}
			bNextFind = TRUE;
			double dElemLength = m_pDoc->calcLAVElem(ElemK);
			dCGLength += dElemLength;
			CalcCrossGirderLength(ElemK, bConnNodeJ, CGVec, dCGLength, bNextFind);
			
			return TRUE;
		}
	}
	bNextFind = FALSE;

	return TRUE;
}

BOOL CCRCDataCtrl::MakeNumberofSupportByTendonBetweenAnchorage()
{
	m_mNs.clear();

	CArray<T_SPAN_K, T_SPAN_K> SpanKeyList;
	m_pAttrCtrl->GetSpanKeyList(SpanKeyList);
	INT_PTR nSpanSize = SpanKeyList.GetSize();

	CArray<T_TDNA_K, T_TDNA_K> arTdnaK;
	m_pAttrCtrl->GetTdnaKeyList(arTdnaK);
	INT_PTR nTdnaSize = arTdnaK.GetSize();

	enum enSpanPos
	{
		SP_Simple   = 0,
		SP_End      = 1,
		SP_Interior = 2,
	};

	std::vector<std::map<T_ELEM_K, int>> vSpanSuport;
	std::map<T_ELEM_K, enSpanPos> mElemSpanPos;

	for (INT_PTR i = 0; i < nSpanSize; ++i)
	{
		T_SPAN_K SpanK = SpanKeyList[i];
		T_SPAN_D SpanD;
		if (m_pAttrCtrl->GetSpan(SpanK, SpanD))
		{
			int nSupportNum = 0;
			for (INT_PTR j = 0; j < SpanD.aElemBase.GetSize(); ++j)
			{
				const T_SPAN_BASE& SpanB = SpanD.aElemBase[j];
				if (SpanB.nSupport == 1 || SpanB.nSupport == 2) nSupportNum++;
			}

			int nInteriorSupportCount = 0;
			std::map<T_ELEM_K, int> mElemSupport;
			for (INT_PTR j = 0; j < SpanD.aElemBase.GetSize(); ++j)
			{
				const T_SPAN_BASE& SpanB = SpanD.aElemBase[j];

				if ( 0 < j && j < SpanD.aElemBase.GetSize()-1)
				{
					if (SpanB.nSupport == 1 || SpanB.nSupport == 2)
					{
						nInteriorSupportCount++;
					}
				}

				if (nSupportNum <= 2)
				{
					mElemSpanPos.insert({ SpanB.ElemK, SP_Simple });
				}
				else
				{
					if (nInteriorSupportCount==0)
					{
						mElemSpanPos.insert({ SpanB.ElemK, SP_End });
					}
					else if (nInteriorSupportCount == nSupportNum-2)
					{
						mElemSpanPos.insert({ SpanB.ElemK, SP_End });
					}
					else
					{
						mElemSpanPos.insert({ SpanB.ElemK, SP_Interior });
					}

				}				

				// 양 끝 요소는 제외
				if (j == 0) continue;
				if (j == SpanD.aElemBase.GetSize() - 1) continue;
				
				int nSupport = static_cast<int>(SpanB.nSupport); // ??? BOOL
				if (nSupport == 0) continue;

				mElemSupport.insert({ SpanB.ElemK, nSupport });
			}

			if (mElemSupport.size() > 0)
			{
				vSpanSuport.push_back(mElemSupport);
			}
		}
	}

	for (INT_PTR i = 0; i < nTdnaSize; ++i)
	{
		T_TDNA_K TdnaK = arTdnaK[i];
		T_TDNA_D TdnaD;
		int nNsCount = 0;
		if (m_pAttrCtrl->GetTdna(TdnaK, TdnaD))
		{
			for (INT_PTR j = 0; j < TdnaD.aElemList.GetSize(); ++j)
			{

				T_ELEM_K ElemK = TdnaD.aElemList[j];
				ElemPairK EPairK(ElemK, EN_EL_BEAM);

				auto itrPos = mElemSpanPos.find(ElemK);
				if (itrPos != mElemSpanPos.end())
				{
					int nNs = 0;
					if (itrPos->second == SP_End)
					{
						nNs = 1;
					}
					else if (itrPos->second == SP_Interior)
					{
						nNs = 2;
					}
					m_mNs[EPairK] = nNs;
				}

				for (const auto& vSpan : vSpanSuport)
				{
					auto iter = vSpan.find(ElemK);
					if (iter != vSpan.end())
					{
						if (iter->second == 1 || iter->second == 2)
						{
							nNsCount++;
						}
					}
				}
			}
			m_mNs4Td.insert({ TdnaK, nNsCount });
		}		
	}


	return TRUE;
}

int CCRCDataCtrl::IsCantilever(CArray<T_ELEM_K, T_ELEM_K> &aElemList)
{
	// int CDgnForceCtrl::IsCantilever(T_ELEM_K ElemKey) 함수 참고 

	int nCantilever = 0;
	// Cantilever(+), No Cantilever(-).
	// Lateral restraint only(1).
	// Torsional restraint only(2).
	// Lateral and torsional restraint(3).
	// Built in laterally and torsionally(4).

	int nElemSize = aElemList.GetSize();
	if (nElemSize == 0) return nCantilever;

	BOOL bReverseDir = FALSE;

	// Search Nodes (I,J) at Member.
	int nEdgeNode[2] = { 0,0 };
	T_ELEM_D eData;
	// Start Element.
	T_ELEM_K ElemKeySta = aElemList.GetAt(0);
	eData.Initialize();
	m_pAttrCtrl->GetElem(ElemKeySta, eData);
	if (!m_pAttrCtrl->IsFrameType(eData.eltyp))	return nCantilever;
	nEdgeNode[0] = (bReverseDir ? eData.elnod[1] : eData.elnod[0]);
	// End Element.
	T_ELEM_K ElemKeyEnd = aElemList.GetAt(nElemSize - 1);
	eData.Initialize();
	m_pAttrCtrl->GetElem(ElemKeyEnd, eData);
	if (!m_pAttrCtrl->IsFrameType(eData.eltyp))	return nCantilever;
	nEdgeNode[1] = (bReverseDir ? eData.elnod[0] : eData.elnod[1]);

	if (!(nEdgeNode[0] > 0 && nEdgeNode[1] > 0))	return 0;

	int nEdgeSupp[2] = { 0 };
	BOOL bFixSupp[2] = { FALSE };
	for (int i = 0; i < 2; ++i)
	{
		BOOL bFix[6] = { FALSE };
		m_pAttrCtrl->IsDofConstraintForDesign(nEdgeNode[i], bFix);
		BOOL bLatFix = (bFix[0] || bFix[1] || bFix[2] ? TRUE : FALSE);
		BOOL bTorFix = (bFix[3] || bFix[4] || bFix[5] ? TRUE : FALSE);
		if (bLatFix && bTorFix)	nEdgeSupp[i] = 3;
		else if (bTorFix)				nEdgeSupp[i] = 2;
		else if (bLatFix)				nEdgeSupp[i] = 1;
		else										nEdgeSupp[i] = 0;
		// Check Support.
		T_CONS_D ConsData;
		ConsData.Initialize();
		if (m_pAttrCtrl->GetConsNode(nEdgeNode[i], ConsData))
		{
			bFixSupp[i] = TRUE;
			for (int j = 0; j < 6; ++j)
			{
				if (ConsData.Constraint[j] != '1')	bFixSupp[i] = FALSE;
			}
		}
	}
	// Save Cantilever Data.
	if (nEdgeSupp[0] * nEdgeSupp[1] > 0)
	{
		if (bFixSupp[0] && nEdgeSupp[1] == 3)			nCantilever = 4;
		else if (bFixSupp[1] && nEdgeSupp[0] == 3)	nCantilever = 4;
		else																		nCantilever = min(nEdgeSupp[0], nEdgeSupp[1]);
		nCantilever *= -1;
	}
	else	nCantilever = max(nEdgeSupp[0], nEdgeSupp[1]);	// The other Edge.

	return nCantilever;	// If over 0, Cantilever.
}

BOOL CCRCDataCtrl::GetUbLengthElemInfo(ElemPairK ElemK, DgnBeamPairK& nUblmK, DgnBeamPairK& nCurUblmK, ElemPairK& nElemI, ElemPairK& nElemM, ElemPairK& nElemJ, int &nPosI, int &nPosM, int &nPosJ,
	BOOL &bChkUblm, BOOL &bCantilever, BOOL &bMakeMembFor, BOOL &b2SideBgg, ArrElemPairKey& aUblmElemK)
{
	auto itElemUblm = m_mElemUblmKey.find(ElemK);
	if (itElemUblm != m_mElemUblmKey.end())
	{
		nUblmK = itElemUblm->second;
		auto itUblMemb = m_mUblenMemb.find(itElemUblm->second);
		if (itUblMemb != m_mUblenMemb.end())
		{
			const T_ULEN_MEMB_D& UblmD = itUblMemb->second;

			nElemI = UblmD.ElemI;
			nElemM = UblmD.ElemM;
			nElemJ = UblmD.ElemJ;
			nPosI = UblmD.nIpos;
			nPosM = UblmD.nMpos;
			if (nPosM == 1 || nPosM == 2) nPosM = 0;
			else if (nPosM == 3 || nPosM == 4) nPosM = 1;
			nPosJ = UblmD.nJpos;
			bCantilever = UblmD.bCantilever;
			b2SideBgg = nPosJ == 1 ? FALSE : TRUE;

			bChkUblm = TRUE;
			aUblmElemK.Copy(UblmD.aElemK);
			bMakeMembFor = (nUblmK != nCurUblmK);
		}
	}
	else
	{
		aUblmElemK.RemoveAll();
		aUblmElemK.Add(ElemK);
		bMakeMembFor = TRUE;
		nCurUblmK.first = static_cast<EN_BEAM_DGN_TYPE>(ElemK.second);
		nCurUblmK.second = -1;
	}

	return TRUE;
}

BOOL CCRCDataCtrl::GetUbLengthElemInfo(ElemPairK ElemK, DgnBeamPairK& nUblmK, ElemPairK& nElemI, ElemPairK& nElemM, ElemPairK& nElemJ, int &nPosI, int &nPosM, int &nPosJ, BOOL &bCantilever)
{
	DgnBeamPairK  nCurUblmK(static_cast<EN_BEAM_DGN_TYPE>(ElemK.second), 0);
	BOOL bChkUblm = FALSE;
	BOOL bMakeMembFor = FALSE;
	BOOL b2SideBgg = FALSE;
	ArrElemPairKey aUblmElemK;
	return GetUbLengthElemInfo(ElemK, nUblmK, nCurUblmK, nElemI, nElemM, nElemJ, nPosI, nPosM, nPosJ, bChkUblm, bCantilever, bMakeMembFor, b2SideBgg, aUblmElemK);
}

