BOOL CCRCDataCtrl::Get_ChkFlagPlateGirder(ElemPairK ElemK, int iPosi)
{
	T_CGDP_D CgdpD;
	CgdpD.Initialize();
	if (ElemK.second == EN_EL_BEAM)
	{
		if (!m_pAttrCtrl->GetCgdp(ElemK.first, CgdpD))	return FALSE;
		if (iPosi == 1)	// I-End.
		{
			if (CgdpD.iDgnPosi == 0 || CgdpD.iDgnPosi == 2) return TRUE;
			else	return FALSE;
		}
		else if (iPosi == 2)	// J-End.
		{
			if (CgdpD.iDgnPosi == 1 || CgdpD.iDgnPosi == 2) return TRUE;
			else	return FALSE;
		}
	}
	else if (ElemK.second == EN_EL_VBEAM)
	{
		T_CGDV_D CgdvD;
		if (!m_pAttrCtrl->GetCgdv(ElemK.first, CgdvD)) return FALSE;
		if (iPosi == 1)	// I-End.
		{
			if (CgdvD.iDgnPosi == 0 || CgdvD.iDgnPosi == 2) return TRUE;
			else	return FALSE;
		}
		else if (iPosi == 2)	// J-End.
		{
			if (CgdvD.iDgnPosi == 1 || CgdvD.iDgnPosi == 2) return TRUE;
			else	return FALSE;
		}

	}
	else ASSERT(0);

	return FALSE;
}

BOOL CCRCDataCtrl::Calc_ClassifyCrossSectionForPGD()
{
	int i, j, k;

	int iLcomNum = m_ForceCtrl.Get_LcomDataCount();
	for (i = 0; i < m_arPgdElemK.GetSize(); ++i)
	{
		auto ElemK = m_arPgdElemK[i];

		BOOL bChkIJ[2];
		bChkIJ[0] = Get_ChkFlagPlateGirder(ElemK, 1);
		bChkIJ[1] = Get_ChkFlagPlateGirder(ElemK, 2);

		int nForType = 0;
		ADGNFORCE aForceLcom;
		if (!m_ForceCtrl.Get_LcomDataForDesign(ElemK, nForType, TRUE, FALSE, aForceLcom, iLcomNum))	continue;
		if (m_ForceCtrl.Get_LcomNumForStrn() == 0)	continue;
		//
		ADGNSTRESS aStressLcom;
		ADGNSTRSADD aStressAdd;
		if (!m_ForceCtrl.Get_LcomDataForStress(ElemK, TRUE, FALSE, aStressLcom, aStressAdd, iLcomNum))	continue;
		ASSERT(aStressLcom.GetSize() == aStressAdd.GetSize());

		int iMaxMin = 0;
		for (j = 0; j < aForceLcom.GetSize(); ++j)
		{
			int iDgnLcomNo = j + 1;
			int iOrgLcomNo = 0;
			int iSerLcomCount = 0;
			int iMaxMinType = 0;
			CString strOrgLcomNa = _T("");
			if (!m_ForceCtrl.Is_LcomForStrn(j + 1))	continue;
			_DGN_FORC_CRC &ForceCrc = aForceLcom.GetAt(j);
			_DGN_STRS_CRC &StressCrc = aStressLcom.GetAt(j);

			// Class를 계산을 위해 임의로 T_PGBR_BASE 사용
			T_PGBR_LCOM PgbrLcomD;
			PgbrLcomD.Initialize();

			T_PGBS_D PgbsD;
			PgbsD.Initialize();

			for (k = 0; k < 2; k++)	// I,J.
			{
				if (!m_ForceCtrl.Get_LcomType(iDgnLcomNo, strOrgLcomNa, iOrgLcomNo, iSerLcomCount, iMaxMinType))
				{
					ASSERT(0);
				}
				double dFxx = ForceCrc.dFxx[k];
				double dMuy = ForceCrc.dMuy[k];
				double dMuz = ForceCrc.dMuz[k];
				UINT nPosi = (k == 0 ? 1 : 2);
				PgbrLcomD.PgbrBase[k].bChk = bChkIJ[k]; // TRUE=Design option대화상자에서 입력 했다는 의미.
				PgbrLcomD.PgbrBase[k].ElemK = ElemK.first;
				PgbrLcomD.PgbrBase[k].nPosi = nPosi;
				PgbrLcomD.PgbrBase[k].LcomK = iDgnLcomNo;
				PgbrLcomD.PgbrBase[k].OrgLcomK = iOrgLcomNo;
				PgbrLcomD.PgbrBase[k].iMax = iMaxMinType;
				PgbrLcomD.PgbrBase[k].dFx = dFxx;
				PgbrLcomD.PgbrBase[k].dMy = dMuy;
				PgbrLcomD.PgbrBase[k].dMz = dMuz;
				//
				PgbsD.PgbsBase[k].bChk = bChkIJ[k];
				PgbsD.PgbsBase[k].ElemK = ElemK.first;
				PgbsD.PgbsBase[k].nPosi = nPosi;
				PgbsD.PgbsBase[k].ChkGirder.LcomK = iDgnLcomNo;
				PgbsD.PgbsBase[k].ChkGirder.OrgLcomK = iOrgLcomNo;
				PgbsD.PgbsBase[k].ChkGirder.iMax = iMaxMinType;
				PgbsD.PgbsBase[k].ChkGirder.dStress[0] = StressCrc.dStl[k];
				PgbsD.PgbsBase[k].ChkGirder.dStress[1] = StressCrc.dStr[k];
				PgbsD.PgbsBase[k].ChkGirder.dStress[2] = StressCrc.dSbr[k];
				PgbsD.PgbsBase[k].ChkGirder.dStress[3] = StressCrc.dSbl[k];
			}

			// Get Result.
			m_pPlateGirder->Make_ClassSection(ElemK, PgbsD, PgbrLcomD);
		}
	}
	return TRUE;
}

BOOL CCRCDataCtrl::Get_StagePart1Force(ArrElemPairKey& aElemK)
{
	int iElemNum = aElemK.GetSize();
	if (iElemNum > 0) m_ForceStageMap.clear();

	// Add by ZINU.('05.09.05).	PSC-Design/Strs(5), PSC-Design/Strn(6).
	int iDgnStatus = m_pDoc->GetDesignStatus();
	m_pDoc->SetDesignStatus(5);

	int i, j;
	for (i = 0; i < aElemK.GetSize(); ++i)
	{
		auto ElemK = aElemK[i];
		_DGN_FORC_CRC ForcMax;
		_DGN_FORC_CRC ForcMin;

		CArray<T_STAG_K, T_STAG_K> aStagK;
		m_pStageInfo->GetResultSavedStagKeyList(aStagK);
		if (aStagK.GetSize() == 0)	return FALSE;

		BOOL bBeforeForce = FALSE;
		for (j = 0; j < aStagK.GetSize(); ++j)
		{
			T_STAG_K StagK = aStagK.GetAt(j);

			// 0:오류 또는 시공 합성 단면 아님
			// 1:시공 합성 단면 : 합성 전 (Active Stage 이전)
			// 2:시공 합성 단면 : 합성 중 (Active되고 모든 Part가 합성되기 전)
			// 3:시공 합성 단면 : 합성 후 (모든 Part가 합성된 후)
			T_CSCS_D CscsD; CscsD.Initialize();
			int nCompositeType = m_pAttrCtrl->GetElemSectCompositeInfoDgn(ElemK, StagK, CscsD);
			if (nCompositeType == 0) continue;
			int iFinalStepNo = 0;
			// Get Last StepNo at Current Stage.
			Get_LastStepInCurStage(StagK, iFinalStepNo);
			CString strSgldName = _LS(IDS_DB_SGLD_SUM);	// SUM.
			T_SGLD_K SgldK = m_pAttrCtrl->GetSgldKey(strSgldName);

			// Modification, Jaeoh. [12/22/2011] 합성 직전의 Force를 얻기 위해..
			if (nCompositeType > 1)
			{
				double dFactor = 1.0;
				if (!m_ForceCtrl.Get_CompositeForceBySgld(ElemK, SgldK, StagK, iFinalStepNo, dFactor, ForcMax, ForcMin))	continue;
				break;
			}
		}
		//
		CPG_FORC_STAG ForceStage;
		ForceStage.Initialize();
		ForceStage.MaxForce = ForcMax;
		ForceStage.MinForce = ForcMin;
		m_ForceStageMap.insert({ElemK, ForceStage});
	}

	return TRUE;
}

