BOOL CCRCDataCtrl::Calc_BendingResistanceForPGD(BOOL bBendingChk)
{
	int i, j, k;

	// PSC-Design/Strs(5), PSC-Design/Strn(6).
	int iDgnStatus = m_pDoc->GetDesignStatus();
	m_pDoc->SetDesignStatus(6);

	// Moment 최대만 찾아서 설계?. 
	// Strength 전체 하중조합으로 하고 
	int iLcomNum = m_ForceCtrl.Get_LcomDataCount();
	for (i = 0; i < m_arPgdElemK.GetSize(); ++i)
	{
		auto ElemK = m_arPgdElemK[i];

		BOOL bChkIJ[2];
		bChkIJ[0] = Get_ChkFlagPlateGirder(ElemK, 1);
		bChkIJ[1] = Get_ChkFlagPlateGirder(ElemK, 2);

		if (bBendingChk)
		{
			if (bChkIJ[0] || bChkIJ[1])
			{
				m_bChkItem[0] = TRUE;
			}
		}
		//
		CPG_FORC_STAG ForceStage;
		ForceStage.Initialize();
		const auto& itForceStage = m_ForceStageMap.find(ElemK);
		if (itForceStage != m_ForceStageMap.end())
		{
			ForceStage = itForceStage->second;
		}
		else
			ASSERT(0);

		ADGNFORCE aForceLcom;
		if (!m_ForceCtrl.Get_LcomDataForDesign(ElemK, 0, TRUE, FALSE, aForceLcom, iLcomNum))	continue;
		if (m_ForceCtrl.Get_LcomNumForStrn() == 0)	continue;

		double dTol = -1. / pow(m_dZero, 40);
		double dPosiMinRatio_I = dTol;
		double dPosiMinRatio_J = dTol;
		double dNegaMinRatio_I = dTol;
		double dNegaMinRatio_J = dTol;
		T_PGBR_LCOM PgbrPosiRat;
		PgbrPosiRat.Initialize();
		T_PGBR_LCOM PgbrNegaRat;
		PgbrNegaRat.Initialize();
		for (j = 0; j < 2; ++j)
		{
			PgbrPosiRat.PgbrBase[j].ElemK = ElemK.first;
			PgbrNegaRat.PgbrBase[j].ElemK = ElemK.first;
		}
		int iMaxMin = 0;
		int iDgnLcomNo = 0;
		int iOrgLcomNo = 0;
		int iSerLcomCount = 0;
		int iMaxMinType = 0;
		for (j = 0; j < aForceLcom.GetSize(); ++j)
		{
			iDgnLcomNo = j + 1;
			CString strOrgLcomNa = _T("");
			if (!m_ForceCtrl.Is_LcomForStrn(j + 1))	continue;
			_DGN_FORC_CRC &ForceCrc = aForceLcom.GetAt(j);

			T_PGBR_LCOM PgbrLcomD;
			PgbrLcomD.Initialize();

			for (k = 0; k < 2; k++)	// I,J.
			{
				if (!m_ForceCtrl.Get_LcomType(iDgnLcomNo, strOrgLcomNa, iOrgLcomNo, iSerLcomCount, iMaxMinType))
				{
					ASSERT(0);
				}
				double dFxx = ForceCrc.dFxx[k];
				double dMuy = ForceCrc.dMuy[k];
				double dMuz = ForceCrc.dMuz[k];
				double dMa_Ed = ForceStage.MaxForce.dMuy[k];
				//        if(dMuy>=0.0) // 정모멘트 인데 Stage 모멘트가 부모멘트면 0으로..
				//        {
				//          if(dMa_Ed<0.0)
				//            dMa_Ed = 0.0;
				//        }
				//        else
				//        {
				//          if(dMa_Ed>0.0)
				//            dMa_Ed = 0.0;
				//        }
				UINT nPosi = (k == 0 ? 1 : 2);
				// Before
				PgbrLcomD.BeforePgbr[k].bChk = bChkIJ[k]; // TRUE=Design option대화상자에서 입력 했다는 의미.
				PgbrLcomD.BeforePgbr[k].ElemK = ElemK.first;
				PgbrLcomD.BeforePgbr[k].nPosi = nPosi;
				PgbrLcomD.BeforePgbr[k].LcomK = iDgnLcomNo;
				PgbrLcomD.BeforePgbr[k].OrgLcomK = iOrgLcomNo;
				PgbrLcomD.BeforePgbr[k].iMax = iMaxMinType;
				PgbrLcomD.BeforePgbr[k].dFx = ForceStage.MaxForce.dFxx[k];
				PgbrLcomD.BeforePgbr[k].dMy = ForceStage.MaxForce.dMuy[k];
				PgbrLcomD.BeforePgbr[k].dMz = ForceStage.MaxForce.dMuz[k];
				PgbrLcomD.BeforePgbr[k].dMa_Ed = ForceStage.MaxForce.dMuy[k];

				PgbrLcomD.PgbrBase[k].bChk = bChkIJ[k]; // TRUE=Design option대화상자에서 입력 했다는 의미.
				PgbrLcomD.PgbrBase[k].ElemK = ElemK.first;
				PgbrLcomD.PgbrBase[k].nPosi = nPosi;
				PgbrLcomD.PgbrBase[k].LcomK = iDgnLcomNo;
				PgbrLcomD.PgbrBase[k].OrgLcomK = iOrgLcomNo;
				PgbrLcomD.PgbrBase[k].iMax = iMaxMinType;
				PgbrLcomD.PgbrBase[k].dFx = dFxx - ForceStage.MaxForce.dFxx[k];;
				PgbrLcomD.PgbrBase[k].dMy = dMuy - ForceStage.MaxForce.dMuy[k];
				PgbrLcomD.PgbrBase[k].dMz = dMuz - ForceStage.MaxForce.dMuz[k];
				PgbrLcomD.PgbrBase[k].dMa_Ed = ForceStage.MaxForce.dMuy[k];
				PgbrLcomD.PgbrBase[k].dMc_Ed = PgbrLcomD.PgbrBase[k].dMy;
			}

			// Get Result.
			m_pPlateGirder->Get_BendingResistanceForPlateGirder(ElemK, PgbrLcomD);

			for (k = 0; k < 2; k++)
			{
				if (k == 0) // I
				{
					if (PgbrLcomD.PgbrBase[k].dMy >= 0.0)
					{
						if (dPosiMinRatio_I < PgbrLcomD.PgbrBase[k].dRatio)
						{
							dPosiMinRatio_I = PgbrLcomD.PgbrBase[k].dRatio;
							PgbrPosiRat.BeforePgbr[k] = PgbrLcomD.BeforePgbr[k];
							PgbrPosiRat.PgbrBase[k] = PgbrLcomD.PgbrBase[k];
						}
					}
					else
					{
						if (dNegaMinRatio_I < PgbrLcomD.PgbrBase[k].dRatio)
						{
							dNegaMinRatio_I = PgbrLcomD.PgbrBase[k].dRatio;
							PgbrNegaRat.BeforePgbr[k] = PgbrLcomD.BeforePgbr[k];
							PgbrNegaRat.PgbrBase[k] = PgbrLcomD.PgbrBase[k];
						}
					}
				}
				else // J
				{
					if (PgbrLcomD.PgbrBase[k].dMy >= 0.0)
					{
						if (dPosiMinRatio_J < PgbrLcomD.PgbrBase[k].dRatio)
						{
							dPosiMinRatio_J = PgbrLcomD.PgbrBase[k].dRatio;
							PgbrPosiRat.BeforePgbr[k] = PgbrLcomD.BeforePgbr[k];
							PgbrPosiRat.PgbrBase[k] = PgbrLcomD.PgbrBase[k];
						}
					}
					else
					{
						if (dNegaMinRatio_J < PgbrLcomD.PgbrBase[k].dRatio)
						{
							dNegaMinRatio_J = PgbrLcomD.PgbrBase[k].dRatio;
							PgbrNegaRat.BeforePgbr[k] = PgbrLcomD.BeforePgbr[k];
							PgbrNegaRat.PgbrBase[k] = PgbrLcomD.PgbrBase[k];
						}
					}
				}
			}
			// Write Result.
			m_pPostCtrl->GetPlateGirder()->WriteBendingResistanceResult(ElemK, iDgnLcomNo, iMaxMin, PgbrLcomD);
		}

		iDgnLcomNo = 0;
		// Positive, Min Ratio
		iMaxMin = 1;
		m_pPostCtrl->GetPlateGirder()->WriteBendingResistanceResult(ElemK, iDgnLcomNo, iMaxMin, PgbrPosiRat);
		// Negative, Min Ratio
		iMaxMin = 2;
		m_pPostCtrl->GetPlateGirder()->WriteBendingResistanceResult(ElemK, iDgnLcomNo, iMaxMin, PgbrNegaRat);
	}

	return TRUE;
}

BOOL CCRCDataCtrl::Calc_VerticalShearResistanceForPGD()
{
	int i, j, k;

	// PSC-Design/Strs(5), PSC-Design/Strn(6).
	int iDgnStatus = m_pDoc->GetDesignStatus();
	m_pDoc->SetDesignStatus(6);

	int iLcomNum = m_ForceCtrl.Get_LcomDataCount();
	for (i = 0; i < m_arPgdElemK.GetSize(); ++i)
	{
		auto ElemK = m_arPgdElemK[i];

		BOOL bChkIJ[2];
		bChkIJ[0] = Get_ChkFlagPlateGirder(ElemK, 1);
		bChkIJ[1] = Get_ChkFlagPlateGirder(ElemK, 2);

		if (bChkIJ[0] || bChkIJ[1])
		{
			m_bChkItem[1] = TRUE;
		}
		//
		CPG_FORC_STAG ForceStage;
		ForceStage.Initialize();
		const auto& itForceStage = m_ForceStageMap.find(ElemK);
		if (itForceStage != m_ForceStageMap.end())
		{
			ForceStage = itForceStage->second;
		}
		else
			ASSERT(0);

		T_PRVS_D PrvsD;
		PrvsD.Initialize();

		ADGNFORCE aForceLcom;
		if (!m_ForceCtrl.Get_LcomDataForDesign(ElemK, 0, TRUE, FALSE, aForceLcom, iLcomNum))	continue;
		if (m_ForceCtrl.Get_LcomNumForStrn() == 0)	continue;

		double dTol = -1. / pow(m_dZero, 40);
		double dMinRatio_I = dTol;
		double dMinRatio_J = dTol;
		T_PRVS_D PrvsRat;
		PrvsRat.Initialize();
		for (j = 0; j < 2; ++j)
			PrvsRat.PrvsBase[j].ElemK = ElemK.first;
		int iMaxMin = 0;
		int iDgnLcomNo = 0;
		int iOrgLcomNo = 0;
		int iSerLcomCount = 0;
		int iMaxMinType = 0;

		for (j = 0; j < aForceLcom.GetSize(); ++j)
		{
			iDgnLcomNo = j + 1;
			CString strOrgLcomNa = _T("");
			if (!m_ForceCtrl.Is_LcomForStrn(j + 1))	continue;
			_DGN_FORC_CRC &ForceCrc = aForceLcom.GetAt(j);

			T_PRVS_D PrvsD;
			PrvsD.Initialize();

			for (k = 0; k < 2; k++)	// I,J.
			{
				if (!m_ForceCtrl.Get_LcomType(iDgnLcomNo, strOrgLcomNa, iOrgLcomNo, iSerLcomCount, iMaxMinType))
				{
					ASSERT(0);
				}
				double dFxx = ForceCrc.dFxx[k];
				double dFzz = ForceCrc.dFzz[k];
				double dMuy = ForceCrc.dMuy[k];
				double dMuz = ForceCrc.dMuz[k];
				double dMa_Ed = ForceStage.MaxForce.dMuy[k];
				//        if(dMuy>=0.0) // 정모멘트 인데 Stage 모멘트가 부모멘트면 0으로..
				//        {
				//          if(dMa_Ed<0.0)
				//            dMa_Ed = 0.0;
				//        }
				//        else
				//        {
				//          if(dMa_Ed>0.0)
				//            dMa_Ed = 0.0;
				//        }

				UINT nPosi = (k == 0 ? 1 : 2);
				PrvsD.BeforePrvs[k].bChk = Get_ChkFlagPlateGirder(ElemK, nPosi);
				PrvsD.BeforePrvs[k].ElemK = ElemK.first;
				PrvsD.BeforePrvs[k].nPosi = nPosi;
				PrvsD.BeforePrvs[k].LcomK = iDgnLcomNo;
				PrvsD.BeforePrvs[k].OrgLcomK = iOrgLcomNo;
				PrvsD.BeforePrvs[k].iMax = iMaxMinType;

				PrvsD.BeforePrvs[k].dFx = ForceStage.MaxForce.dFxx[k]; //
				PrvsD.BeforePrvs[k].dFz = ForceStage.MaxForce.dFzz[k];
				PrvsD.BeforePrvs[k].dMy = ForceStage.MaxForce.dMuy[k];
				PrvsD.BeforePrvs[k].dMz = ForceStage.MaxForce.dMuz[k];
				PrvsD.BeforePrvs[k].dN_Ed = ForceStage.MaxForce.dFxx[k];
				PrvsD.BeforePrvs[k].dV_Ed = ForceStage.MaxForce.dFzz[k];
				PrvsD.BeforePrvs[k].dMa_Ed = ForceStage.MaxForce.dMuy[k];

				PrvsD.PrvsBase[k].bChk = Get_ChkFlagPlateGirder(ElemK, nPosi);
				PrvsD.PrvsBase[k].ElemK = ElemK.first;
				PrvsD.PrvsBase[k].nPosi = nPosi;
				PrvsD.PrvsBase[k].LcomK = iDgnLcomNo;
				PrvsD.PrvsBase[k].OrgLcomK = iOrgLcomNo;
				PrvsD.PrvsBase[k].iMax = iMaxMinType;

				PrvsD.PrvsBase[k].dFx = dFxx - ForceStage.MaxForce.dFxx[k]; //
				PrvsD.PrvsBase[k].dFz = dFzz - ForceStage.MaxForce.dFzz[k];
				PrvsD.PrvsBase[k].dMy = dMuy - ForceStage.MaxForce.dMuy[k];
				PrvsD.PrvsBase[k].dMz = dMuz - ForceStage.MaxForce.dMuz[k];
				PrvsD.PrvsBase[k].dN_Ed = PrvsD.PrvsBase[k].dFx;
				PrvsD.PrvsBase[k].dV_Ed = PrvsD.PrvsBase[k].dFz;
				PrvsD.PrvsBase[k].dMa_Ed = ForceStage.MaxForce.dMuy[k];
			}

			// Get Result.
			m_pPlateGirder->Get_VerticalShearResistanceForPlateGirder(ElemK, PrvsD);

			// 불리한 조건 찾을 때 Ratio만 적용하지 않고 다른 것도 적용해야함.
			for (k = 0; k < 2; k++)
			{
				if (k == 0) // I
				{
					if (dMinRatio_I < PrvsD.PrvsBase[k].dRatio)
					{
						dMinRatio_I = PrvsD.PrvsBase[k].dRatio;
						PrvsRat.BeforePrvs[k] = PrvsD.BeforePrvs[k];
						PrvsRat.PrvsBase[k] = PrvsD.PrvsBase[k];
					}
				}
				else // J
				{
					if (dMinRatio_J < PrvsD.PrvsBase[k].dRatio)
					{
						dMinRatio_J = PrvsD.PrvsBase[k].dRatio;
						PrvsRat.BeforePrvs[k] = PrvsD.BeforePrvs[k];
						PrvsRat.PrvsBase[k] = PrvsD.PrvsBase[k];
					}
				}
			}
			//

			// Write Result.
			m_pPostCtrl->GetPlateGirder()->WriteVerticalShearResistanceResult(ElemK, iDgnLcomNo, iMaxMin, PrvsD);
		}

		iDgnLcomNo = 0;
		// Min Ratio
		iMaxMin = 1;
		m_pPostCtrl->GetPlateGirder()->WriteVerticalShearResistanceResult(ElemK, iDgnLcomNo, iMaxMin, PrvsRat);
	}

	return TRUE;
}

BOOL CCRCDataCtrl::Calc_LateralTorsionalBucklingResistanceForPGD()
{
	int i, j, k;

	// PSC-Design/Strs(5), PSC-Design/Strn(6).
	int iDgnStatus = m_pDoc->GetDesignStatus();
	m_pDoc->SetDesignStatus(6);

	//
	int iLcomNum = m_ForceCtrl.Get_LcomDataCount();
	for (i = 0; i < m_arPgdElemK.GetSize(); ++i)
	{
		auto ElemK = m_arPgdElemK[i];

		BOOL bChkIJ[2];
		bChkIJ[0] = Get_ChkFlagPlateGirder(ElemK, 1);
		bChkIJ[1] = Get_ChkFlagPlateGirder(ElemK, 2);

		if (bChkIJ[0] || bChkIJ[1])
		{
			m_bChkItem[2] = TRUE;
		}
		CPG_FORC_STAG ForceStage;
		ForceStage.Initialize();
		const auto& itForceStage = m_ForceStageMap.find(ElemK);
		if (itForceStage != m_ForceStageMap.end())
		{
			ForceStage = itForceStage->second;
		}
		else
			ASSERT(0);

		// member
		BOOL bReverse;
		T_ELEM_K showElemK;
		CArray<T_ELEM_K, T_ELEM_K> arMembElemList;
		int iCountElem = 0;
		T_ELEM_K IendElemK = 0;
		T_ELEM_K JendElemK = 0;
		if (m_pMembCtrl->GetElemListByIncludeElem(ElemK.first, bReverse, showElemK, arMembElemList))
		{
			iCountElem = arMembElemList.GetSize();
			IendElemK = arMembElemList[0];
			JendElemK = arMembElemList[iCountElem - 1];
		}
		else
		{
		}
		ElemPairK IendEPairK = GetElemPairKey4Elem(IendElemK);
		ElemPairK JendEPairK = GetElemPairKey4Elem(JendElemK);

		ADGNFORCE aForceLcom;
		if (!m_ForceCtrl.Get_LcomDataForDesign(ElemK, 0, TRUE, FALSE, aForceLcom, iLcomNum))	continue;
		if (m_ForceCtrl.Get_LcomNumForStrn() == 0)	continue;

		double dTol = -1. / pow(m_dZero, 40);
		double dMinRatio_I = dTol;
		double dMinRatio_J = dTol;
		T_PLTB_D PltbRat;
		PltbRat.Initialize();
		for (j = 0; j < 2; ++j)
			PltbRat.PltbBase[j].ElemK = ElemK.first;
		int iMaxMin = 0;
		int iDgnLcomNo = 0;
		int iOrgLcomNo = 0;
		int iSerLcomCount = 0;
		int iMaxMinType = 0;
		double dC4 = 0.0;
		for (j = 0; j < aForceLcom.GetSize(); ++j)
		{
			iDgnLcomNo = j + 1;
			CString strOrgLcomNa = _T("");
			if (!m_ForceCtrl.Is_LcomForStrn(j + 1))	continue;
			_DGN_FORC_CRC &ForceCrc = aForceLcom.GetAt(j);

			// I-End
			_DGN_FORC_CRC MembEndForce;
			m_ForceCtrl.Get_LcomDataForDesign_LcomK(IendEPairK, iDgnLcomNo, TRUE, FALSE, MembEndForce);
			double dM1 = MembEndForce.dMuy[0];
			double dV1 = MembEndForce.dFzz[0];
			//
			MembEndForce.Initialize();
			m_ForceCtrl.Get_LcomDataForDesign_LcomK(JendEPairK, iDgnLcomNo, TRUE, FALSE, MembEndForce);
			double dM2 = MembEndForce.dMuy[1];
			double dV2 = MembEndForce.dFzz[1];
			// Get, C4 
			//if (Get_C4valueForMomentType(iDgnLcomNo, showElemK, arMembElemList, dC4))
			//{
			//	//
			//}
			//else
			//{
			//	dC4 = 0.0;
			//}

			T_PLTB_D PltbD;
			PltbD.Initialize();

			for (k = 0; k < 2; k++)	// I,J.
			{
				if (!m_ForceCtrl.Get_LcomType(iDgnLcomNo, strOrgLcomNa, iOrgLcomNo, iSerLcomCount, iMaxMinType))
				{
					ASSERT(0);
				}
				double dFxx = ForceCrc.dFxx[k];
				double dMuy = ForceCrc.dMuy[k];
				double dMuz = ForceCrc.dMuz[k];
				UINT nPosi = (k == 0 ? 1 : 2);
				PltbD.BeforePltb[k].bChk = Get_ChkFlagPlateGirder(ElemK, nPosi);
				PltbD.BeforePltb[k].ElemK = ElemK.first;
				PltbD.BeforePltb[k].nPosi = nPosi;
				PltbD.BeforePltb[k].LcomK = iDgnLcomNo;
				PltbD.BeforePltb[k].OrgLcomK = iOrgLcomNo;
				PltbD.BeforePltb[k].iMax = iMaxMinType;
				PltbD.BeforePltb[k].dFx = ForceStage.MaxForce.dFxx[k]; //
				PltbD.BeforePltb[k].dMy = ForceStage.MaxForce.dMuy[k];
				PltbD.BeforePltb[k].dMz = ForceStage.MaxForce.dMuz[k];
				PltbD.BeforePltb[k].dN_Ed = ForceStage.MaxForce.dFxx[k];
				PltbD.BeforePltb[k].dM_Ed = ForceStage.MaxForce.dMuy[k];
				//        PltbD.BeforePltb[k].dV1	= dV1;
				//        PltbD.BeforePltb[k].dV2	= dV2;
				//        PltbD.BeforePltb[k].dM1	= dM1;
				//        PltbD.BeforePltb[k].dM2	= dM2;
				//        PltbD.BeforePltb[k].dC4 = dC4;		      

				PltbD.PltbBase[k].bChk = Get_ChkFlagPlateGirder(ElemK, nPosi);
				PltbD.PltbBase[k].ElemK = ElemK.first;
				PltbD.PltbBase[k].nPosi = nPosi;
				PltbD.PltbBase[k].LcomK = iDgnLcomNo;
				PltbD.PltbBase[k].OrgLcomK = iOrgLcomNo;
				PltbD.PltbBase[k].iMax = iMaxMinType;
				PltbD.PltbBase[k].dFx = dFxx - ForceStage.MaxForce.dFxx[k]; //
				PltbD.PltbBase[k].dMy = dMuy - ForceStage.MaxForce.dMuy[k];
				PltbD.PltbBase[k].dMz = dMuz - ForceStage.MaxForce.dMuz[k];
				PltbD.PltbBase[k].dN_Ed = PltbD.PltbBase[k].dFx;
				PltbD.PltbBase[k].dM_Ed = PltbD.PltbBase[k].dMy;
				PltbD.PltbBase[k].dV1 = dV1;
				PltbD.PltbBase[k].dV2 = dV2;
				PltbD.PltbBase[k].dM1 = dM1;
				PltbD.PltbBase[k].dM2 = dM2;
				PltbD.PltbBase[k].dC4 = dC4;
			}

			// Get Result.
			m_pPlateGirder->Get_LateralTorsionalBucklingResistanceForPlateGirder(ElemK, PltbD);

			// 불리한 조건 찾을 때 Ratio만 적용하지 않고 다른 것도 적용해야함.
			for (k = 0; k < 2; k++)
			{
				if (k == 0) // I
				{
					if (dMinRatio_I < PltbD.PltbBase[k].dRatio)
					{
						dMinRatio_I = PltbD.PltbBase[k].dRatio;
						PltbRat.BeforePltb[k] = PltbD.BeforePltb[k];
						PltbRat.PltbBase[k] = PltbD.PltbBase[k];
					}
				}
				else // J
				{
					if (dMinRatio_J < PltbD.PltbBase[k].dRatio)
					{
						dMinRatio_J = PltbD.PltbBase[k].dRatio;
						PltbRat.BeforePltb[k] = PltbD.BeforePltb[k];
						PltbRat.PltbBase[k] = PltbD.PltbBase[k];
					}
				}
			}
			// Write Result.
			m_pPostCtrl->GetPlateGirder()->WriteLateralTorsionalBucklingResistanceResult(ElemK, iDgnLcomNo, iMaxMin, PltbD);
		}
		iDgnLcomNo = 0;
		// Min Ratio
		iMaxMin = 1;
		m_pPostCtrl->GetPlateGirder()->WriteLateralTorsionalBucklingResistanceResult(ElemK, iDgnLcomNo, iMaxMin, PltbRat);
	}

	return TRUE;
}

BOOL CCRCDataCtrl::Get_C4valueForMomentType(int iDgnLcomKey, ElemPairK MembK, ArrElemPairKey& arMembElemK, double& dC4, BOOL bCodeUnit) const
{
	int i;
	_DGN_FORC_CRC ForceLcom;
	CArray<_DGN_FORC_CRC, _DGN_FORC_CRC&> arForce;
	int iElemNum = arMembElemK.GetSize();
	arForce.SetSize(iElemNum);
	//
	for (i = 0; i < iElemNum; ++i)
	{
		auto ElemK = arMembElemK[i];
		ForceLcom.Initialize();
		m_ForceCtrl.Get_LcomDataForDesign_LcomK(ElemK, iDgnLcomKey, TRUE, FALSE, ForceLcom);
		arForce.SetAt(i, ForceLcom);
	}

	int iMomType = 0;
	double dPsi = 0.0;
	double dCoeff = 0.0;
	if (!Get_MomentShape_PSI(MembK, arMembElemK, arForce, iMomType, dPsi, dCoeff))
		return false;
	//
	if (!Get_C4ForUFrameModel(iMomType, dPsi, dCoeff, dC4))
		return false;

	return true;
}

BOOL CCRCDataCtrl::Get_MomentShape_PSI(ElemPairK MembK, ArrElemPairKey& arMembElemK, CArray<_DGN_FORC_CRC, _DGN_FORC_CRC&>& arForce, int& iMomType, double& dPsi, double& dCoeff) const
{
	iMomType = 0;
	int i, j;
	int iElemNum = arForce.GetSize();
	if (iElemNum <= 0.0)
		return false;

	double dM1 = 0.0, dM2 = 0.0, dM0 = 0.0;
	dM1 = arForce[0].dMuy[0];
	dM2 = arForce[iElemNum - 1].dMuy[1];
	double dM1M2 = dM1 * dM2;
	if (iElemNum == 1) // Member의 요소가 하나이면 가운데 Position의 모멘트를 알 수 없기 때문에.. 5 or 6
	{
		if (dM1M2 >= 0.0)
		{
			iMomType = 5;
		}
		else
		{
			iMomType = 6;
		}
		//
		if (!Get_PSI_EndMoment56Type(dM1, dM2, dPsi))
			return false;
	}
	else
	{
		int iNonZero = 0;
		int iInflection = 0;
		int iCurrMom = 0;
		int iPreMom = 0;
		int iGetCurrMom = 0;
		for (i = 0; i < iElemNum; ++i)
		{
			_DGN_FORC_CRC &Force = arForce[i];
			double dM12[2];
			dM12[0] = Force.dMuy[0];
			dM12[1] = Force.dMuy[1];
			for (j = 0; j < 2; ++j)
			{
				if (i == 0 && j == 0)
				{
					iPreMom = Get_MomentType4PGD(dM12[j]);
				}
				else
				{
					iCurrMom = Get_MomentType4PGD(dM12[j]);
					if (Get_CountInflection(iPreMom, iCurrMom, iGetCurrMom, iInflection))
					{
						iPreMom = iGetCurrMom;
					}
				}
			}
		}

		//
		if (iInflection == 0)
		{
			if (dM1 == 0 && dM2 == 0)
			{
				iMomType = 2;
				if (!Get_PSI_EndMoment14Type(MembK, arMembElemK, arForce, dM0, dPsi, dCoeff))
					return false;
			}
			else
			{
				iMomType = 5;
				if (!Get_PSI_EndMoment56Type(dM1, dM2, dPsi))
					return false;
			}
		}
		else if ((iInflection != 0 && iInflection % 2 == 0))
		{
			iMomType = 2;
			if (!Get_PSI_EndMoment14Type(MembK, arMembElemK, arForce, dM0, dPsi, dCoeff))
				return false;
		}
		else if (iInflection % 2 == 1 && (dM1 == 0 || dM2 == 0))
		{
			iMomType = 1;
			if (!Get_PSI_EndMoment14Type(MembK, arMembElemK, arForce, dM0, dPsi, dCoeff))
				return false;
		}
		else if (iInflection % 2 == 1 && dM1 != 0.0 && dM2 != 0.0)
		{
			iMomType = 6;
			if (!Get_PSI_EndMoment56Type(dM1, dM2, dPsi))
				return false;
		}
		// 
	}

	return true;
}

BOOL CCRCDataCtrl::Get_CountInflection(int iPre, int iCurr, int& iGetCurr, int& iCount) const
{
	if (iPre == 0 && iCurr != 0)
	{
		iGetCurr = iCurr;
	}
	else if (iPre == 1 && iCurr == -1)
	{
		iGetCurr = iCurr;
		iCount++;
		return true;
	}
	else if (iPre == -1 && iCurr == 1)
	{
		iGetCurr = iCurr;
		iCount++;
		return true;
	}

	return false;
}

int CCRCDataCtrl::Get_MomentType4PGD(double dMom) const
{
	if (dMom == 0.0)
		return 0;
	else if (dMom > 0.0)
		return 1;   // Positive
	else
		return 2;   // Negative
}

BOOL CCRCDataCtrl::Get_PSI_EndMoment56Type(double dM1, double dM2, double& dPsi) const
{
	double dM1M2 = dM1 * dM2;
	double daM1 = fabs(dM1);
	double daM2 = fabs(dM2);
	if (dM1M2 >= 0.0)
	{
		if (dM1M2 == 0.0)
		{
			if (daM1 == 0.0 && daM2 == 0.0)
				dPsi = 1.0;
			else
				dPsi = 0.0;
		}
		else if (daM1 > daM2)
			dPsi = daM1 == 0.0 ? 0.0 : daM2 / daM1;
		else if (daM1 < daM2)
			dPsi = daM2 == 0.0 ? 0.0 : daM1 / daM2;
		else if (fabs(daM1 - daM2) < m_dZero)
			dPsi = 1.0;
		else
			ASSERT(0);
	}
	else
	{
		if (fabs(daM1 - daM2) < m_dZero)
			dPsi = 1.0;
		else if (daM1 > daM2)
			dPsi = daM2 / daM1;
		else if (daM1 < daM2)
			dPsi = daM1 / daM2;
		else
			ASSERT(0);
	}

	return true;
}

BOOL CCRCDataCtrl::Get_PSI_EndMoment14Type(ElemPairK MembK, ArrElemPairKey& arMembElemK, CArray<_DGN_FORC_CRC, _DGN_FORC_CRC&>& arForce, double& dM0, double& dPsi, double& dCoeff) const
{
	int iElemNum = arMembElemK.GetSize();
	double dM1 = arForce[0].dMuy[0];
	double dM2 = arForce[iElemNum - 1].dMuy[1];
	double dM1M2 = dM1 * dM2;

	if (dM1M2 < 0.0)
		return FALSE;

	double dTotalLength = 0.0;
	if (MembK.second == EN_EL_BEAM)
	{
		dTotalLength = m_pMembCtrl->GetMembLengByIncludeElem(MembK.first);
	}
	else if (MembK.second == EN_EL_VBEAM)
	{
		for (int i=0; i<arMembElemK.GetSize(); ++i)
		{
			auto ElemK = arMembElemK[i];
			dTotalLength += CDBLib::GetLengthOfBeam(ElemK);
		}		
	}
	else ASSERT(0);
	
	double da = dTotalLength == 0.0 ? 0.0 : (dM2 - dM1) / dTotalLength;
	double db = dM1;
	//
	double dx1 = 0;
	double dM0_max = 0.0;
	for (int i = 0; i < iElemNum; ++i)
	{
		auto ElemK = arMembElemK[i];
		_DGN_FORC_CRC &Force = arForce[i];
		double dM11 = Force.dMuy[0];
		double dM22 = Force.dMuy[1];
		double dMt = Get_y_Function(da, db, dx1);
		dM0 = dMt - dM11;
		if (fabs(dM0_max) < fabs(dM0))
			dM0_max = dM0;
		//
		dx1 += CDBLib::GetLengthOfBeam(ElemK);
		dMt = Get_y_Function(da, db, dx1);
		dM0 = dMt - dM22;
		if (fabs(dM0_max) < fabs(dM0))
			dM0_max = dM0;
	}
	//
	double dMs = 0.0, dMm = 0.0;
	if (fabs(dM1) < fabs(dM2))
	{
		dMs = dM2; // standard
		dMm = dM1; // min
	}
	else
	{
		dMs = dM1;
		dMm = dM2;
	}

	dPsi = dM0_max == 0.0 ? 0.0 : dMs / dM0_max;
	if (fabs(dMm - dMs) < m_dZero)
		dCoeff = 1.0;
	else
		dCoeff = dMs == 0.0 ? 0.0 : dMm / dMs;

	return true;
}

double CCRCDataCtrl::Get_y_Function(double da, double db, double dx1) const
{
	double dy1 = da * dx1 + db;

	return dy1;
}

BOOL CCRCDataCtrl::Get_C4ForUFrameModel(int iMomType, double dPsi, double dCoeff, double& dC4) const
{
	// TABLE B1, 메일로 온 참고 자료.
	// Prospetto B1-Valori del fattore C4 per campate con carico trasversale
	int iCase = 0;
	int iPsiType = 0;
	double dPsi1 = 0.0, dPsi2 = 0.0;
	double dC1 = 0.0, dC2 = 0.0;

	double dC4_type1[9] = { 41.5, 30.2, 24.5, 21.1, 19.0, 17.5, 16.5, 15.7, 15.2, };
	double dC4_type21[9] = { 33.9, 22.7, 17.3, 14.1, 13.0, 12.0, 11.4, 10.9, 10.6, };
	double dC4_type22[9] = { 28.2, 18.0, 13.7, 11.7, 10.6, 10.0,  9.5,  9.1,  8.9, };
	double dC4_type23[9] = { 21.9, 13.9, 11.0,  9.6,  8.8,  8.3,  8.0,  7.8,  7.6, };
	double dC4_type3[9] = { 28.4, 21.8, 18.6, 16.7, 15.6, 14.8, 14.2, 13.8, 13.5, };
	double dC4_type4[9] = { 12.7,  9.8,  8.6,  8.0,  7.7,  7.4,  7.2,  7.1,  7.0, };

	double dC4List[6][9];
	for (int i = 0; i < 9; ++i)
	{
		dC4List[0][i] = dC4_type1[i];
		dC4List[1][i] = dC4_type21[i];
		dC4List[2][i] = dC4_type22[i];
		dC4List[3][i] = dC4_type23[i];
		dC4List[4][i] = dC4_type3[i];
		dC4List[5][i] = dC4_type4[i];
	}

	int iPsi1 = 0, iPsi2 = 0;
	int iCoeff1 = 0, iCoeff2 = 0;
	double dPsiRat = 0.0, dCoeffRat = 0.0;
	BOOL bGetPsiData = Get_PsiDataForInterPolation(iMomType, dPsi, iPsi1, iPsi2, dPsiRat);
	BOOL bGetCoeffData = Get_CoeffDataForInterPolation(iMomType, dCoeff, iCoeff1, iCoeff2, dCoeffRat);

	double dC4_LT = 0.0, dC4_RT = 0.0, dC4_LB = 0.0, dC4_RB = 0.0;
	double dDistRatioFromLeft = 0.0, dDistRatioFromBot = 0.0;
	switch (iMomType)
	{
	case 1:
	case 2:
	{
		if (bGetPsiData && bGetCoeffData)
		{
			dC4_LT = dC4List[iCoeff1][iPsi1];
			dC4_RT = dC4List[iCoeff1][iPsi2];
			dC4_LB = dC4List[iCoeff2][iPsi1];
			dC4_RB = dC4List[iCoeff2][iPsi2];
			dDistRatioFromLeft = dPsiRat;
			dDistRatioFromBot = dCoeffRat;
			dC4 = CMathFunc::mathInterpolate(dC4_LB, dC4_RB, dC4_LT, dC4_RT, dDistRatioFromLeft, dDistRatioFromBot);
		}
		else if (!bGetPsiData && bGetCoeffData)
		{
			if (dPsi < 0.5)
			{
				dC4_LT = dC4List[iCoeff1][0];
				dC4_LB = dC4List[iCoeff2][0];
			}
			else if (dPsi > 2.5)
			{
				dC4_LT = dC4List[iCoeff1][8];
				dC4_LB = dC4List[iCoeff2][8];
			}
			dDistRatioFromLeft = dCoeffRat;
			dC4 = CMathFunc::mathInterpolate(dC4_LB, dC4_LT, dDistRatioFromLeft); // 함수 설명 참고.CMathFunc::mathInterpolate 
		}
		else
		{
			ASSERT(0);
			return false;
		}

		break;
	}
	case 3:
	case 4:
	{
		if (bGetPsiData && bGetCoeffData)
		{
			dC4_LT = dC4List[4][iPsi1];
			dC4_RT = dC4List[4][iPsi2];
			dC4_LB = dC4List[5][iPsi1];
			dC4_RB = dC4List[5][iPsi2];
			dDistRatioFromLeft = dPsiRat;
			dDistRatioFromBot = dCoeffRat;
			dC4 = CMathFunc::mathInterpolate(dC4_LB, dC4_RB, dC4_LT, dC4_RT, dDistRatioFromLeft, dDistRatioFromBot);
		}
		else if (!bGetPsiData && bGetCoeffData)
		{
			if (dPsi < 0.5)
			{
				dC4_LT = dC4List[4][0];
				dC4_LB = dC4List[5][0];
			}
			else if (dPsi > 2.5)
			{
				dC4_LT = dC4List[4][8];
				dC4_LB = dC4List[5][8];
			}
			dDistRatioFromLeft = dCoeffRat;
			dC4 = CMathFunc::mathInterpolate(dC4_LB, dC4_LT, dDistRatioFromLeft); // 함수 설명 참고.CMathFunc::mathInterpolate 
		}
		else
		{
			ASSERT(0);
			return false;
		}

		break;
	}
	case 5:
	{
		double dC4_type5[5] = { 11.1,  9.5,  8.2,  7.1,  6.2, };
		if (bGetPsiData)
		{
			dC4_LT = dC4_type5[iPsi1];
			dC4_RT = dC4_type5[iPsi2];
			dDistRatioFromLeft = dPsiRat;
			dC4 = CMathFunc::mathInterpolate(dC4_LT, dC4_RT, dDistRatioFromLeft); // 함수 설명 참고.CMathFunc::mathInterpolate 
		}
		else
		{
			if (dPsi < 0.0)
			{
				dC4 = dC4_type5[0];
			}
			else if (dPsi > 1.0)
			{
				dC4 = dC4_type5[4];
			}
		}
		break;
	}
	case 6:
	{
		double dC4_type6[5] = { 11.1, 12.8, 14.6, 16.3, 18.1, };
		if (bGetPsiData)
		{
			dC4_LT = dC4_type6[iPsi1];
			dC4_RT = dC4_type6[iPsi2];
			dDistRatioFromLeft = dPsiRat;
			dC4 = CMathFunc::mathInterpolate(dC4_LT, dC4_RT, dDistRatioFromLeft);
		}
		else
		{
			if (dPsi < 0.0)
			{
				dC4 = dC4_type6[0];
			}
			else if (dPsi > 1.0)
			{
				dC4 = dC4_type6[4];
			}
		}
		break;
	}
	case 7:
	{
		double dC4_type71[4] = { 47.6, 33.8, 26.6, 22.1, };
		double dC4_type72[4] = { 12.5, 11.0, 10.2,  9.3, };
		double dC4_type73[4] = { 9.2,  8.8,  8.6,  8.4, };
		double dC4_type74[4] = { 7.9,  7.8,  7.7,  7.6, };
		//
		double dC4_type7[4][4];
		for (int i = 0; i < 4; ++i)
		{
			dC4_type7[0][i] = dC4_type71[i];
			dC4_type7[1][i] = dC4_type72[i];
			dC4_type7[2][i] = dC4_type73[i];
			dC4_type7[3][i] = dC4_type74[i];
		}

		if (bGetPsiData && bGetCoeffData)
		{
			dC4_LT = dC4_type7[iCoeff1][iPsi1];
			dC4_RT = dC4_type7[iCoeff1][iPsi2];
			dC4_LB = dC4_type7[iCoeff2][iPsi1];
			dC4_RB = dC4_type7[iCoeff2][iPsi2];
			dDistRatioFromLeft = dPsiRat;
			dDistRatioFromBot = dCoeffRat;
			dC4 = CMathFunc::mathInterpolate(dC4_LB, dC4_RB, dC4_LT, dC4_RT, dDistRatioFromLeft, dDistRatioFromBot);
		}
		else if (!bGetPsiData && bGetCoeffData)
		{
			if (dPsi < 0.0)
			{
				dC4_LT = dC4List[iCoeff1][0];
				dC4_LB = dC4List[iCoeff2][0];
			}
			else if (dPsi > 1.0)
			{
				dC4_LT = dC4List[iCoeff1][3];
				dC4_LB = dC4List[iCoeff2][3];
			}
			dDistRatioFromLeft = dCoeffRat;
			dC4 = CMathFunc::mathInterpolate(dC4_LB, dC4_LT, dDistRatioFromLeft); // 함수 설명 참고.CMathFunc::mathInterpolate 
		}
		else
		{
			ASSERT(0);
			return false;
		}
		break;
	}

	default:
	{
		ASSERT(0);
		return false;
		//break;
	}
	}

	return true;
}

BOOL CCRCDataCtrl::Get_PsiDataForInterPolation(int iMomType, double dPsi, int& iPsi1, int& iPsi2, double& dPsiRat) const
{
	switch (iMomType)
	{
	case 1:
	case 2:
	case 3:
	case 4:
	{
		if (!Get_PsiDataForInterPolation14(dPsi, iPsi1, iPsi2, dPsiRat))
			return false;
		break;
	}
	case 5:
	case 6:
	{
		if (!Get_PsiDataForInterPolation56(dPsi, iPsi1, iPsi2, dPsiRat))
			return false;
		break;
	}
	case 7:
	{
		if (!Get_PsiDataForInterPolation7(dPsi, iPsi1, iPsi2, dPsiRat))
			return false;
		break;
	}
	default:
	{
		ASSERT(0);
		return false;
	}
	}

	return true;
}

BOOL CCRCDataCtrl::Get_PsiDataForInterPolation14(double dPsi, int& iPsi1, int& iPsi2, double& dPsiRat) const
{
	if (dPsi<0.5 || dPsi>2.5)
		return false;

	double dPsi1 = 0.0, dPsi2 = 0.0;
	if (0.5 - m_dZero < dPsi && dPsi < 0.75)
	{
		iPsi1 = 0, iPsi2 = 1;
		dPsiRat = (0.5 - dPsi) / (0.50 - 0.75);
	}
	else if (0.75 - m_dZero < dPsi && dPsi < 1.00)
	{
		iPsi1 = 1, iPsi2 = 2;
		dPsiRat = (0.75 - dPsi) / (0.75 - 1.00);
	}
	else if (1.00 - m_dZero < dPsi && dPsi < 1.25)
	{
		iPsi1 = 2, iPsi2 = 3;
		dPsiRat = (1.00 - dPsi) / (1.00 - 1.25);
	}
	else if (1.25 - m_dZero < dPsi && dPsi < 1.50)
	{
		iPsi1 = 3, iPsi2 = 4;
		dPsiRat = (1.25 - dPsi) / (1.25 - 1.50);
	}
	else if (1.50 - m_dZero < dPsi && dPsi < 1.75)
	{
		iPsi1 = 4, iPsi2 = 5;
		dPsiRat = (1.50 - dPsi) / (1.50 - 1.75);
	}
	else if (1.75 - m_dZero < dPsi && dPsi < 2.00)
	{
		iPsi1 = 5, iPsi2 = 6;
		dPsiRat = (1.75 - dPsi) / (1.75 - 2.00);
	}
	else if (2.00 - m_dZero < dPsi && dPsi < 2.25)
	{
		iPsi1 = 6, iPsi2 = 7;
		dPsiRat = (2.00 - dPsi) / (2.00 - 2.25);
	}
	else if (2.25 - m_dZero < dPsi && dPsi < 2.50 + m_dZero)
	{
		iPsi1 = 7, iPsi2 = 8;
		dPsiRat = (2.25 - dPsi) / (2.25 - 2.50);
	}
	else
		ASSERT(0);

	return true;
}

BOOL CCRCDataCtrl::Get_PsiDataForInterPolation56(double dPsi, int& iPsi1, int& iPsi2, double& dPsiRat) const
{
	if (dPsi<0.0 || dPsi>1.0)
		return false;

	double dPsi1 = 0.0, dPsi2 = 0.0;
	if (0.0 <= dPsi && dPsi < 0.25)
	{
		iPsi1 = 0, iPsi2 = 1;
		dPsiRat = (0.0 - dPsi) / (0.0 - 0.25);
	}
	else if (0.25 - m_dZero < dPsi && dPsi < 0.50)
	{
		iPsi1 = 1, iPsi2 = 2;
		dPsiRat = (0.25 - dPsi) / (0.25 - 0.50);
	}
	else if (0.50 - m_dZero < dPsi && dPsi < 0.75)
	{
		iPsi1 = 2, iPsi2 = 3;
		dPsiRat = (0.50 - dPsi) / (0.50 - 0.75);
	}
	else if (0.75 - m_dZero < dPsi && dPsi < 1.00 + m_dZero)
	{
		iPsi1 = 3, iPsi2 = 4;
		dPsiRat = (0.75 - dPsi) / (0.75 - 1.00);
	}
	else
		ASSERT(0);

	return true;
}

