BOOL CCRCDataCtrl::Get_RigidLength(ElemPairK ElemK, int iPosi, double& dLy, double& dLz, double& dLu)
{
	if (iPosi < 1 || iPosi>2) return false;

	CDgnDataCtrl DataCtrl;

	int iPosiNo = 0;
	if (iPosi == 1)      iPosiNo = 0;
	else if (iPosi == 2) iPosiNo = 4;
	// Get Length.
	T_LENG_D LengData;
	LengData.Initialize();
	double dLength = 0.0;
	//!!/ 
	if (ElemK.second == EN_EL_BEAM)
	{
		DataCtrl.Get_DgnGenLeng(ElemK.first, iPosiNo, LengData, dLength);
	}
	else if (ElemK.second == EN_EL_VBEAM)
	{
		T_LENV_D LenvD; LenvD.Initialize();
		if (m_pDoc->m_pAttrCtrl->GetLenv(ElemK.first, LenvD))
		{
			LengData.BLy = LenvD.BLy;
			LengData.BLz = LenvD.BLz;
			LengData.BLu = LenvD.BLu;
		}
		else
		{
			double dElemLength = m_pDoc->calcLenthVbem(ElemK.first);
			LengData.BLy = dElemLength;
			LengData.BLz = dElemLength;
			LengData.BLu = dElemLength;
		}
	}
	else ASSERT(0);
	//
	dLy = LengData.BLy;
	dLz = LengData.BLz;
	dLu = LengData.BLu;
	//m_bAutoCalcLe = LengData.bAutoCalcLe;

	return true;
}

BOOL CCRCDataCtrl::MakeStlOrthDeckDesignData()
{
	CCurUnitSaver Save(TRUE);

	T_UNIT_INDEX CodeUnit = Get_CodeUnitIndex();
	m_pDoc->m_pUnitCtrl->SetUnitIndexCurrent(CodeUnit);

	// Initailize
	InitialStlOrthDeck();

	// Flexural Buckling Check하는 경우, Write 5Position Design Force Data
	if (m_pDoc->m_pAttrCtrl2->GetCountFlbk() > 0) { m_ForceCtrl.Set_Write5PositionDgnForce(true); }

	//  Make Design Force & Stress
	if (!Cal_LcomDataForDesignAll())	return FALSE;
	//
	if (!ExecuteStlOrthDeckDesign()) return FALSE;

	// recursive 
	if (m_pDoc->m_pAttrCtrl2->GetCountFlbk() > 0) { m_ForceCtrl.Set_Write5PositionDgnForce(false); }

	return TRUE;
}

void CCRCDataCtrl::InitialStlOrthDeck()
{
	m_ForceCtrl.Set_LcomDataForDesign();
	m_iDgnLcomNum = m_ForceCtrl.Get_LcomDataCount();
}

BOOL CCRCDataCtrl::Get_ElemListForStlOrthDeck(BOOL bShowMsg, CArray<T_ELEM_K, T_ELEM_K>& arElemK)
{
	arElemK.RemoveAll();

	CArray<T_ELEM_K, T_ELEM_K> aChkElemKey;
	CMap<T_ELEM_K, T_ELEM_K, T_ELEM_K, T_ELEM_K> mChkElemKey; mChkElemKey.RemoveAll();
	m_pDoc->m_pAttrCtrl2->GetSddpKeyList(aChkElemKey);

	for (int i = 0; i < aChkElemKey.GetSize(); ++i)
	{
		T_ELEM_K ElemK = aChkElemKey.GetAt(i);
		BOOL bpErr[4] = { FALSE };
		CString strErr = _T("");
		if (!CDBLib::IsStlOrthDeckDgnElem(ElemK, bpErr))
		{
			if (bShowMsg)
			{
				if (bpErr[0]) { strErr.Format(_LS(IDS_RCSC_SKIP_ELEM_TYPE), ElemK); GSaveHistoryFormatNF(strErr); }
				if (bpErr[1]) { strErr.Format(_LS(IDS_RCSC_SKIP_MEMB_TYPE), ElemK); GSaveHistoryFormatNF(strErr); }
				if (bpErr[2]) { strErr.Format(_LS(IDS_RCSC_SKIP_MATL_TYPE), ElemK); GSaveHistoryFormatNF(strErr); }
				if (bpErr[3]) { strErr.Format(_LS(IDS_RCSC_SKIP_SECT_TYPE), ElemK); GSaveHistoryFormatNF(strErr); }
			}
			continue;
		}
		mChkElemKey.SetAt(ElemK, ElemK);
	}

	// Member's Element for Force write 5 Position (for flexural buckling check)
	for (int i = 0; i < aChkElemKey.GetSize(); ++i)
	{
		T_ELEM_K ElemK = aChkElemKey[i];
		if (m_pDoc->m_pAttrCtrl2->ExistFlbk(ElemK))
		{
			T_MEMB_K MembK;
			if (m_pDoc->m_pAttrCtrl->GetMembAssigned(ElemK, MembK))
			{
				T_MEMB_D MembD;
				if (m_pDoc->m_pAttrCtrl->GetMemb(MembK, MembD))
				{
					for (int j = 0; j < MembD.aElemList.GetSize(); ++j)
					{
						T_ELEM_K ElemSubK = MembD.aElemList[j];
						T_ELEM_K ElemSubKeyD;
						if (!mChkElemKey.Lookup(ElemSubK, ElemSubKeyD)) { mChkElemKey.SetAt(ElemSubK, ElemSubK); }
					}
				}
			}
		}
		else
		{
			T_ELEM_K ElemSubKeyD;
			if (!mChkElemKey.Lookup(ElemK, ElemSubKeyD)) { mChkElemKey.SetAt(ElemK, ElemK); }
		}
	}

	// Save Output Data
	POSITION pos = mChkElemKey.GetStartPosition();
	while (pos)
	{
		T_ELEM_K ElemK, ElemKeyD;
		mChkElemKey.GetNextAssoc(pos, ElemK, ElemKeyD);
		arElemK.Add(ElemKeyD);
	}

	if (bShowMsg)	GSaveHistoryFormatNF(_T(""));
	if (arElemK.GetSize() <= 0)	return FALSE;

	return TRUE;
}

