BOOL CCRCDataCtrl::ExecuteRUSStlCompDesign()
{
	MakeRUSStlCompDesignData();

	m_ForceStageMap.clear();

	CArray<T_ELEM_K, T_ELEM_K> arPgdElemKey;  arPgdElemKey.RemoveAll();
	if (!CDBLib::GetElemforStlCompGirderGirder(arPgdElemKey)) return FALSE;

	int CheckElemKNum = arPgdElemKey.GetSize();
	m_pPostCtrl->GetRUSStlCompGirderDesign()->WriteStlCompGirderSeq(CheckElemKNum);

	LONGLONG iCount = 0;
	for (int i = 0; i < CheckElemKNum; ++i)
	{
		iCount++;
		T_ELEM_K ElemK = arPgdElemKey[i];
		if (!m_pPostCtrl->GetRUSStlCompGirderDesign()->WriteStlCompGirderElement(ElemK, iCount)) continue;
	}

	T_CPGD_D CpgdD;   CpgdD.Initialize();
	m_pAttrCtrl2->GetDgnCpgd(CpgdD);

	BOOL bExecuteDgn = FALSE;
	switch (CpgdD.iDgnCode)
	{
	case SNiP_20503_84_CSG:
	case SP_35_13330_11_CSG:
		bExecuteDgn = m_pRusStlCompDataCtrl->ExcuteStlCompGirderDesign();
		break;
	default: ASSERT(0); break;
	}

	return bExecuteDgn;
}

