double CCRCDataCtrl::GetDgnMoment(double dMu)
{
	if (m_CodeUnit.nBase_Force == D_UNITSYS_FORCE_INDEX_N && m_CodeUnit.nBase_Length == D_UNITSYS_LENGTH_INDEX_MM)
	{
		double dMuDgn = fabs(dMu);
		if (dMuDgn < 0.1) // 0.1 N-mm 보다 작으면 0 처리
		{
			return 0.0;
		}
	}
	return dMu;
}

