void CCRCDataCtrl::GetElemKeyList4ElemPair(UINT nType, const ArrElemPairKey& aElemPairK, CArray<T_ELEM_K, T_ELEM_K>& aElemK)
{
	aElemK.RemoveAll();
	for (int i = 0; i < aElemPairK.GetSize(); ++i)
	{
		ElemPairK PairK = aElemPairK[i];
		if (nType == EN_EL_BEAM && PairK.second == EN_EL_BEAM) // Element
		{
			aElemK.Add(PairK.first);
		}
		else if (nType == EN_EL_VBEAM && PairK.second == EN_EL_VBEAM) // VB Element
		{
			aElemK.Add(PairK.first);
		}
	}
}

