SectPairK CCRCDataCtrl::GetSectPairKey(ElemPairK EPairK)
{
	SectPairK SPairK;
	if (EPairK.second == EN_EL_BEAM)
	{
		T_ELEM_D ElemD;
		if (m_pPostCtrl->GetElemPost(EPairK.first, ElemD))
		{
			SPairK.first = ElemD.elpro;
			SPairK.second = EN_EL_BEAM;
		}
		else ASSERT(0);
	}
	else if (EPairK.second == EN_EL_VBEAM)
	{
		T_VBEM_D VbemD;
		if (m_pDoc->m_pAttrCtrl2->GetVbem(EPairK.first, VbemD)) // T_SECV_K = T_VBEM_K
		{
			SPairK.first = EPairK.first;
			SPairK.second = EN_EL_VBEAM;
		}
		else ASSERT(0);
	}
	else ASSERT(0);

	return SPairK;
}


