int CCRCDataCtrl::GetMaterialKey4ElemPairK(ElemPairK EPairK)
{
	int nMatlK = 0;
	T_ELEM_D ElemD; ElemD.Initialize();
	if (EPairK.second == EN_EL_BEAM)
	{
		if (!m_pDoc->m_pPostCtrl->GetElemPost(EPairK.first, ElemD)) return 0;
		nMatlK = ElemD.elmat;
	}
	else if (EPairK.second == EN_EL_VBEAM)
	{
		T_VBEM_D VbemD; VbemD.Initialize();
		if (m_pDoc->m_pAttrCtrl2->GetVbem(EPairK.first, VbemD))
		{
			T_MATL_K SlabMatlK = 0, GirderMatlK = 0;
			m_pDoc->m_pAttrCtrl2->GetSecvMatlK(EPairK.first, SlabMatlK, GirderMatlK);
			nMatlK = GirderMatlK;
		}
	}
	else ASSERT(0);

	return nMatlK;
}

BOOL CCRCDataCtrl::MakeJointData4Segment()
{
	int iElemNum = m_arCheckElemK.GetSize();
	m_mapJoint.clear();

	for (int i = 0; i < iElemNum; ++i)
	{
		auto ElemK = m_arCheckElemK[i];
		DGN_JOINT_D JointD;
		if (!Make_JointData4Element(ElemK, JointD)) continue;
		m_mapJoint[ElemK] = JointD;
	}

	return TRUE;
}

BOOL CCRCDataCtrl::Get_JointData4Segment()
{
	return  MakeJointData4Segment();
}

BOOL CCRCDataCtrl::Make_JointData4Element(ElemPairK ElemK, DGN_JOINT_D& rData)
{
	rData.Initialize();
	if (m_pAttrCtrl->ExistPsegAssigned(ElemK.first))
	{
		T_PSEG_K PsegK = 0;
		if (m_pAttrCtrl->GetPsegAssigned(ElemK.first, PsegK))
		{
			T_PSEG_D PsegD;
			if (m_pAttrCtrl->GetPseg(PsegK, PsegD))
			{
				int iElemNumOfSegment = PsegD.aElemList.GetSize();
				if (iElemNumOfSegment == 1)
				{
					CArray<T_ELEM_K, T_ELEM_K> aElemI;
					CArray<T_ELEM_K, T_ELEM_K> aElemJ;

					T_ELEM_D ElemD;
					if (!m_pAttrCtrl->GetElem(PsegD.aElemList[0], ElemD)) return FALSE;
					m_pAttrCtrl->GetConnectedElem(ElemD.elnod[0], aElemI);
					m_pAttrCtrl->GetConnectedElem(ElemD.elnod[1], aElemJ);

					rData.iI_joint = rData.iJ_joint = 1;

					if (aElemI.GetSize() == 1) rData.iI_joint = 0;
					if (aElemJ.GetSize() == 1) rData.iJ_joint = 0;
				}
				else if (iElemNumOfSegment > 1)
				{
					CArray<T_ELEM_K, T_ELEM_K> aElem1I;
					CArray<T_ELEM_K, T_ELEM_K> aElem2J;

					T_ELEM_D ElemD1, ElemD2;
					if (ElemK.first == PsegD.aElemList[0]) // Segment의 첫번째 요소이면 
					{
						if (!m_pAttrCtrl->GetElem(PsegD.aElemList[0], ElemD1)) return FALSE;
						m_pAttrCtrl->GetConnectedElem(ElemD1.elnod[0], aElem1I);

						if (!m_pAttrCtrl->GetElem(PsegD.aElemList[1], ElemD2)) return FALSE;

						// 첫번째 요소의 I단이 근접요소의 I단 또는 J단이라면 I단은 joint가 아니다. 
						if (ElemD1.elnod[0] == ElemD2.elnod[0] || ElemD1.elnod[0] == ElemD2.elnod[1]) { rData.iI_joint = 0, rData.iJ_joint = 1; }
						// 첫번째 요소의 J단이 근접요소의 I단 또는 J단이라면 J단은 joint가 아니다. 
						else if (ElemD1.elnod[1] == ElemD2.elnod[0] || ElemD1.elnod[1] == ElemD2.elnod[1]) { rData.iI_joint = 1, rData.iJ_joint = 0; }
						else ASSERT(0);

						if (aElem1I.GetSize() == 1) rData.iI_joint = 0;
					}
					else if (ElemK.first == PsegD.aElemList[iElemNumOfSegment - 1]) // Segment의 마지막 요소이면 
					{
						if (!m_pAttrCtrl->GetElem(PsegD.aElemList[iElemNumOfSegment - 2], ElemD2)) return FALSE;

						if (!m_pAttrCtrl->GetElem(PsegD.aElemList[iElemNumOfSegment - 1], ElemD1)) return FALSE;
						m_pAttrCtrl->GetConnectedElem(ElemD1.elnod[1], aElem2J);


						// 마지막 요소의 I단이 근접요소의 I단 또는 J단이라면 I단은 joint가 아니다. 
						if (ElemD1.elnod[0] == ElemD2.elnod[0] || ElemD1.elnod[0] == ElemD2.elnod[1]) { rData.iI_joint = 0, rData.iJ_joint = 1; }
						// 마지막 요소의 J단이 근접요소의 I단 또는 J단이라면 J단은 joint가 아니다. 
						else if (ElemD1.elnod[1] == ElemD2.elnod[0] || ElemD1.elnod[1] == ElemD2.elnod[1]) { rData.iI_joint = 1, rData.iJ_joint = 0; }
						else ASSERT(0);

						if (aElem2J.GetSize() == 1) rData.iJ_joint = 0;
					}
					else
					{
						// Segment의 내부 Node이면 0.
						rData.iI_joint = 0;
						rData.iJ_joint = 0;
					}
				}
				rData.iJointType = PsegD.nJointType;
			}
		}
		else return FALSE;
	}
	else return FALSE;

	return TRUE;
}

BOOL CCRCDataCtrl::Get_JointData4Element(ElemPairK ElemK, DGN_JOINT_D& rData)
{
	const auto& it = m_mapJoint.find(ElemK);
	if (it == m_mapJoint.end()) return FALSE;
	rData = it->second;
	
	return TRUE;
}

