BOOL CCRCDataCtrl::Get_Day4fci(ElemPairK ElemK, BOOL bIsCpt, BOOL bIsPart1, T_STAG_K StagK, int nSerialStep, double& dDay)
{
	double dAgeGr = 0.0;
	double dAgeSl = 0.0;

	CArray<T_STAG_K, T_STAG_K> aStagK;
	m_pStageInfo->GetResultSavedStagKeyList(aStagK);
	if ( aStagK.GetSize() == 0 )	return FALSE;

	int nStepGr = 0;
	double dFirstStep_Day = 0.0;
	double dStartStepSlab = 0.0;

	if ( bIsCpt == TRUE )
	{
		T_CONC_AGE_D AgeD;
		if(!GetInitAgesOfConcrete(ElemK, AgeD)) ASSERT(0);
		dAgeGr = AgeD.dAgeGr;
		dAgeSl = AgeD.dAgeSl;;

		for ( int i = 0; i < aStagK.GetSize(); ++i )
		{
			T_STAG_K StagK = aStagK.GetAt(i);
			if ( !m_pStageInfo->IsActiveElemInTgtStag(StagK, ElemK) ) continue;

			T_STAG_STEP_INFO StageInfo; StageInfo.Initialize();
			m_pAttrCtrl->GetStagStepInfo(StagK, StageInfo);
			int nStepSize = StageInfo.aInfo.GetSize();
			int nStepArr = nStepSize == 0 ? 1 : nStepSize;
			int iSerialStep = 0;

			T_CSCS_D CscsD; CscsD.Initialize();
			int nCompositeType = m_pAttrCtrl->GetElemSectCompositeInfoDgn(ElemK, StagK, CscsD);
			if ( bIsCpt == TRUE )
			{
				if ( nCompositeType == 0 || nCompositeType == 1 ) continue;
			}

			for ( int jj = 0; jj < nStepArr; ++jj )
			{
				int nCurStep = jj + 1;

				double dStep_Day = 0.0;
				m_pStageInfo->GetStagStepDay(StagK, nCurStep, dStep_Day); // Stage에서 각 step의 날짜

				nStepGr++;
				if(nStepGr == 1) dFirstStep_Day = dStep_Day;

				if ( nStepSize > 0 )
				{
					// 유효하지 않은 Step은 Skip
					int nTempSerialStep = 0;
					if ( !m_pStageInfo->GetStepSerialKey(StagK, nCurStep, nTempSerialStep) ) continue;
				}

				if ( nCompositeType >= 3 )
				{
					dStartStepSlab = dStep_Day;
					break;
				}
			}
			if ( nCompositeType >= 3 ) break;
		}
	}

	// 0:오류 또는 시공 합성 단면 아님
	// 1:시공 합성 단면 : 합성 전 (Active Stage 이전)
	// 2:시공 합성 단면 : 합성 중 (Active되고 모든 Part가 합성되기 전)
	// 3:시공 합성 단면 : 합성 후 (모든 Part가 합성된 후)
	T_CSCS_D CscsD; CscsD.Initialize();
	int nCompositeType = m_pAttrCtrl->GetElemSectCompositeInfoDgn(ElemK, StagK, CscsD);
	if ( bIsCpt == TRUE )
	{
		if ( nCompositeType == 0 || nCompositeType == 1 ) return FALSE;
	}

	T_ELFM_D DayActive; DayActive.Initialize();
	m_pPostCtrl->GetElfmDgn(StagK, ElemK, DayActive);

	T_STAG_STEP_INFO StageInfo; StageInfo.Initialize();
	m_pAttrCtrl->GetStagStepInfo(StagK, StageInfo);

	int nStepSize = StageInfo.aInfo.GetSize();
	int nStepArr = nStepSize == 0 ? 1 : nStepSize;

	double dStep_Day = 0.0;
	if ( m_pStageInfo->GetStagStepDay(nSerialStep, dStep_Day) )
	{
		if ( bIsCpt )
		{
			if ( bIsPart1 )
			{
				dDay = dAgeGr + dStep_Day - dFirstStep_Day; //??//
			}
			else
			{
				if ( nCompositeType >= 3 )
				{
					dDay = dStep_Day - dStartStepSlab + dAgeSl;
				}
			}
		}
		else
		{
			dDay = dAgeGr + dStep_Day;
		}
	}

	return TRUE;
}

BOOL CCRCDataCtrl::Get_InitCompressStrength(T_TDME_K TdmeK, double dt, double& dfci)
{
	T_TDME_D TdmeD; TdmeD.Initialize();
	if (!m_pAttrCtrl->GetTdme(TdmeK, TdmeD)) return FALSE;
	
	if ( dt < 0.0 )
		dt = 0.0;

	if (TdmeD.nMatlType == 1) // Code:1, User:2
	{
		int ncode = CDBLib::GetHmtpCodeID(TdmeD.strCode);
		int nCement = TdmeD.nCementType - 1;

		if (ncode == 1 /*|| ncode == 11*/) 	// korea standard, KCI-USD12
		{
			double S91 = TdmeD.dCompStrength;
			double a = TdmeD.dFactorA;
			double b = TdmeD.dFactorB;
			dfci = a + b * dt == 0.0 ? 0.0 : S91 * (dt / (a + b * dt));
		}
		else if (ncode == 2)  // ACI
		{
			double S28 = TdmeD.dCompStrength;
			double a = TdmeD.dFactorA;
			double b = TdmeD.dFactorB;
			dfci = a + b * dt == 0.0 ? 0.0 : S28 * (dt / (a + b * dt));
		}
		else if (ncode == 3 || ncode == 27)  // CEB-FIP
		{
			double a[3] = { 0.2, 0.25, 0.38 };
			double S28 = TdmeD.dCompStrength;
			if (nCement < 0 || nCement > 2) nCement = 0;
			dfci = dt == 0.0 ? 0.0 : S28 * exp(a[nCement] * (1.0 - pow((28.0 / dt), 0.5)));
		}
		else if (ncode == 4)  // Ohzagi
		{
			double S28 = TdmeD.dCompStrength;
			if (nCement < 0 || nCement > 3) nCement = 0;
			dfci = S28 * OhzagiY(nCement, dt);
		}
		else if (ncode == 5)  // China
		{
			double S28 = TdmeD.dCompStrength;
			dfci = S28 * log10(dt) / log10(28);
		}
		else if (ncode == 6)    //Japan
		{
			double fck = TdmeD.dCompStrength;
			double a = TdmeD.dFactorA;
			double b = TdmeD.dFactorB;
			double d = TdmeD.dFactorD;
			double tensile = TdmeD.dTensileStrengthFactor;
			dfci = a + b * dt == 0.0 ? 0.0 : fck * d * (dt / (a + b * dt));
		}
		else if (ncode == 7)    //Japan(Elastic Modulus)
		{
			double dTimeRapid[] = { 1.52, 2., 4., 5., 10., 20., 28., 50., 80.35 };
			double dKeRapid[] = { 0.7, 0.752, 0.836, 0.873, 0.939, 0.985, 1.0, 1.0, 1.0 };  // 28일 이후부터는 1.0으로 변경

			double dTimeNormal[] = { 2., 4., 5., 7.938, 10., 20., 28., 50., 75.858 };
			double dKeNormal[] = { 0.632, 0.764, 0.821, 0.884, 0.909, 0.976, 1.0, 1.0, 1.0 };  // 28일 이후부터는 1.0으로 변경
			int nLoop = sizeof(dTimeRapid) / sizeof(double);

			// 보간해야한다.

			ASSERT(0);

			int nSel = TdmeD.nJpElaCementType;
			double fck = TdmeD.dCompStrength;

			double* dTime;
			double* dVal;
			if (nSel == 0)
			{
				dTime = dTimeNormal;
				dVal = dKeNormal;
			}
			else
			{
				dTime = dTimeRapid;
				dVal = dKeRapid;
			}

			double dReFactor = 1.0;
			for (int i = 0; i < nLoop; ++i)
			{
				if (dt < dTime[i])
				{
					double dPreTime = 0.0, dNextTime = 0.0;
					if (i == 0)
					{
						dPreTime = 0.0;
						dNextTime = dTime[i];
					}
					else
					{
						dPreTime = dTime[i - 1];
						dNextTime = dTime[i];
					}
					double dDistFromLeft = dt - dPreTime;
					double dTotalDist = dNextTime - dPreTime;
					double dDistRatioFromLeft = dTotalDist == 0.0 ? 0.0 : dDistFromLeft / dTotalDist;
					dReFactor = CMathFunc::mathInterpolate(dVal[i - 1], dVal[i], dDistRatioFromLeft);
					break;
				}
			}

			dfci = fck * dReFactor;
		}
		else if (ncode == 8) 	// INDIA standard
		{
			double S28 = TdmeD.dCompStrength;
			if (dt < 3.0) dt = 3.0;
			dfci = S28 * (2.008 - (1.2134 / (pow(log10(dt), 0.5))));
		}
		else if (ncode == 25||ncode==35) //INDIA(IRC:112-2011)
		{
			double S28 = TdmeD.dCompStrength;
			double a[3] = { 0.38, 0.25, 0.2 };
			double dfcm = S28;
			//nCement = TdmeD.nCementType;
			//IRC112 6.4.2.2 and A-2.3 page 237
			dfci = dt == 0.0 ? 0.0 : dfcm * exp(a[nCement] * (1.0 - pow((28. / dt), 0.5)));
		}
		else if (ncode == 9) // European
		{
			double a[3] = { 0.2, 0.25, 0.38 };
			double S28 = TdmeD.dCompStrength;
			if (nCement < 0 || nCement > 2) nCement = 0;
			dfci = dt == 0.0 ? 0.0 : S28 * exp(a[nCement] * (1.0 - pow((28.0 / dt), 0.5)));
		}
		else if (ncode == 10) // CEB-FIP(1978)
		{
			double S28 = TdmeD.dCompStrength;
			double dTmp1 = dt / (dt + 47.0);
			double dTmp2 = 1.0 / 2.45;
			dfci = pow(dTmp1, dTmp2)*S28;
		}
		else if (ncode == 11 || ncode == 33)  // KCI-USD12, KDS-2016
		{
			double a[5] = { 0.35, 0.15, 0.25, 0.12, 0.40 };
			double S28 = TdmeD.dCompStrength;
			if (nCement < 0 || nCement > 5) nCement = 0;
			dfci = S28 * exp(a[nCement] * (1 - pow((28 / dt), 0.5)));
		}
		else if (ncode == 22 || ncode == 24 || ncode == 29 || ncode == 31 ||
			ncode == TDMT_CODE_AUSTRALIA_2018_AMD_2021) 	// AS 3600-2009, AS/RTA 5100.5-2011, AS 5100.5-2016, AS 5100.5-2017  : 호주시간의존 재질 개발명세서 참고
		{ // INDIA standard와 대화창 모양이 같다.
			double S28 = TdmeD.dCompStrength;
			dfci = 1.451849874*pow(dt, 0.75)*S28 / (pow(dt, 0.75) + 5.5);
		}
		else if (ncode == 26) // Russian
		{
			double dB28 = TdmeD.dCompStrength;
			if (nCement < 0 || nCement > 3) nCement = 0;
			double da = 0.0, dc = 0.0, dd = 0.0;
			if (nCement == 0) // 0:Normal
			{
				da = 23.0;
				dc = 55.0;
				dd = 11.0;
			}
			else if (nCement == 1) // 1:Fast Hardened 
			{
				da = 9.0;
				dc = 31.0;
				dd = 6.0;
			}
			else if (nCement == 2) // 2:Slag
			{
				da = 39.0;
				dc = 62.0;
				dd = 15.0;
			}
			else if (nCement == 3) // 3:Pozzolan
			{
				da = 35.0;
				dc = 93.0;
				dd = 8.0;
			}
			dfci = (1.0 + ((da / (dc + dB28))*((dt - 28.0) / (dt + dd)))) * dB28;
		}
		else ASSERT(0);
	}
	else if (TdmeD.nMatlType == 2)
	{
		int nDataSize = TdmeD.aFuncData.GetSize();
		if (nDataSize == 0) return FALSE;
		for (int ii = 0; ii < nDataSize; ++ii)
		{
			T_TDME_BASE TdmeBase = TdmeD.aFuncData[ii];
			if (fabs(TdmeBase.dTime - dt) < m_dZero)
			{
				dfci = TdmeBase.dComp;
				break;
			}
			else
			{
				if (dt < TdmeBase.dTime)
				{
					double dPreTime = 0.0, dNextTime = 0.0;
					if (ii == 0)
					{
						dPreTime = 0.0;
						dNextTime = TdmeD.aFuncData[ii].dTime;
					}
					else
					{
						dPreTime = TdmeD.aFuncData[ii - 1].dTime;
						dNextTime = TdmeBase.dTime;
					}
					double dDistFromLeft = dt - dPreTime;
					double dTotalDist = dNextTime - dPreTime;
					double dDistRatioFromLeft = dTotalDist == 0.0 ? 0.0 : dDistFromLeft / dTotalDist;
					double dPreComp = ii == 0.0 ? 0.0 : TdmeD.aFuncData[ii - 1].dComp;
					dfci = CMathFunc::mathInterpolate(dPreComp, TdmeBase.dComp, dDistRatioFromLeft);
				}
			}
		}
		if (dfci == 0.0 && dt > TdmeD.aFuncData[nDataSize - 1].dTime) dfci = TdmeD.aFuncData[nDataSize - 1].dComp;
	}
	else
	{
		ASSERT(0);
		return FALSE;
	}

	return TRUE;
}

double CCRCDataCtrl::OhzagiY(int nCement, double m)
{
	double a = 0.0, b = 0.0, c = 0.0;
	double retY = 0.0, x = 0.0;

	if (nCement == 0)
	{
		if (m <= 30) a = 0.024, b = -0.028, c = 0.01;
		else				a = -0.005, b = 0.162, c = -0.286;
		if (m <= 6.626) return 1e-10;
	}
	else if (nCement == 1)
	{
		if (m <= 30) a = 0.012, b = -0.028, c = 0.02;
		else				a = 0.000, b = 0.112, c = -0.347;
		if (m <= 8.488) return 1e-10;
	}
	else if (nCement == 2)
	{
		if (m <= 30) a = 0.01, b = -0.027, c = 0.02;
		else				a = 0.006, b = 0.014, c = -0.077;
		if (m <= 9.477) return 1e-10;
	}
	else if (nCement == 3)
	{
		if (m <= 30) a = 0.012, b = -0.034, c = 0.028;
		else				a = 0.002, b = 0.074, c = -0.251;
		if (m <= 9.456) return 1e-10;
	}

	x = 2.389 * log(m / 3.5) - 1.0;
	retY = a * pow(x, 2) + b * x + c;

	return retY;
}

BOOL CCRCDataCtrl::GetCentroidAngleOfSectoffset(int nOffsetPoint, double dLength,
	double dCypI, double dCymI, double dCzpI, double dCzmI,
	double dCypJ, double dCymJ, double dCzpJ, double dCzmJ,
	double &dAngY, double &dAngZ)
{
	switch (nOffsetPoint)
	{
	case 1: // Left-Top
	case 2: // Center-Top
	case 3: // Right-Top
	{
		double dtanAng = (dLength == 0.0) ? 0.0 : (dCzpI - dCzpJ) / dLength;
		dAngZ = atan(dtanAng);

		break;
	}
	case 4:
	case 5:
	case 6:
	{
		break;
	}
	case 7:
	case 8:
	case 9:
	{
		break;
	}

	break;
	default: ASSERT(0); break;
	}
	return TRUE;
}

